_DATE_RE = re.compile(
    r"(?<!\d)((?:19|20)\d{2})\s*[.年/-]\s*(\d{1,2})"
    r"(?:\s*[.月/-]\s*(\d{1,2})\s*日?)?(?!\d)"
)
_FULL_DATE_RE = re.compile(
    r"(?<!\d)((?:19|20)\d{2})\s*[.年/-]\s*(\d{1,2})"
    r"\s*[.月/-]\s*(\d{1,2})\s*日?(?!\d)"
)
_CANONICAL_FULL_DATE_RE = re.compile(
    r"(?<!\d)((?:19|20)\d{2})\s*[.,年/-]\s*(\d{1,2})"
    r"\s*[.,月/-]\s*(\d{1,2})\s*日?(?!\d)"
)
_RAW_INQUIRY_PHYSICAL_DATE_SHAPE_RE = re.compile(
    r"(?<!\d)((?:19|20)\d{2})\D{0,3}(\d{2})\D{0,3}(\d{2})(?!\d)"
)
_MONTH_RE = re.compile(
    r"(?<!\d)((?:19|20)\d{2})\s*[.年/-]\s*(\d{1,2})(?:\s*月)?"
    r"(?!\s*[.月/-]\s*\d)(?!\d)"
)
_AS_OF_RE = re.compile(r"截至\s*((?:19|20)\d{2})\s*年\s*(\d{1,2})\s*月\s*(\d{1,2})\s*日")
_STATUS_CODES = frozenset({"*", "/", "N", "1", "2", "3", "4", "5", "6", "7", "A", "B", "C", "D", "G", "M", "Z", "#"})
_INQUIRY_REASONS = tuple(sorted(PBOC_INQUIRY_REASON_ROOTS, key=len, reverse=True))
# Flattened OCR lines do not preserve the reason-cell boundary.  The generic
# official value ``其他`` is therefore admissible only in an exact schema-owned
# reason cell; it is not a safe suffix delimiter for an institution name.
_INQUIRY_LINE_SUFFIX_REASONS = tuple(reason for reason in _INQUIRY_REASONS if reason != "其他")
_SELF_INQUIRY_REASON_CHANNELS = PBOC_SELF_INQUIRY_CHANNELS
