def _pboc_layout_profile(parse_result: Any) -> PBOCLayoutProfile:
    """Return one cached evidence profile without requiring the full context."""

    cached = getattr(parse_result, "_pboc_layout_profile_cache", None)
    if isinstance(cached, PBOCLayoutProfile):
        return cached
    loader = getattr(parse_result, "pboc_layout_profile", None)
    if callable(loader):
        profile = loader()
    else:
        profile = detect_pboc_layout_profile(getattr(parse_result, "pages", ()) or ())
        try:
            setattr(parse_result, "_pboc_layout_profile_cache", profile)
        except (AttributeError, TypeError):
            pass
    return profile


def _pboc_layout_allows(parse_result: Any, capability: LayoutCapability) -> bool:
    return _pboc_layout_profile(parse_result).allows(capability)

