def _report_collapsed_cluster_fields(
    parse_result: Any,
    record: dict[str, Any],
    *,
    dataset: str,
    target_record_id: str,
    raw: str,
    source_ref: dict[str, Any],
    unresolved_fields: Iterable[str],
    parser_stage: str,
) -> None:
    """Retain every unresolved canonical role from one collapsed source cell."""

    for field_name in dict.fromkeys(str(value) for value in unresolved_fields if value):
        if record.get(field_name) not in (None, ""):
            continue
        _reject_exact_observation(
            parse_result,
            record,
            dataset=dataset,
            target_record_id=target_record_id,
            field_name=field_name,
            raw=raw,
            source_ref=source_ref,
            parser_stage=parser_stage,
        )


def _native_table_geometry(table: Any) -> Mapping[str, Any] | None:
    metadata = getattr(table, "metadata", None)
    if not isinstance(metadata, Mapping):
        return None
    geometry = metadata.get("geometry")
    return geometry if isinstance(geometry, Mapping) else None


def _indexed_geometry_bands(
    geometry: Mapping[str, Any],
    key: str,
    *,
    lower_key: str,
    upper_key: str,
) -> dict[int, tuple[float, float]] | None:
    raw_bands = geometry.get(key)
    if not isinstance(raw_bands, list):
        return None
    bands: dict[int, tuple[float, float]] = {}
    for raw_band in raw_bands:
        if not isinstance(raw_band, Mapping):
            return None
        index = raw_band.get("index")
        if not isinstance(index, int) or isinstance(index, bool) or index < 0:
            return None
        try:
            lower = float(raw_band.get(lower_key))
            upper = float(raw_band.get(upper_key))
        except (TypeError, ValueError):
            return None
        if not math.isfinite(lower) or not math.isfinite(upper) or upper <= lower:
            return None
        if index in bands:
            return None
        bands[index] = (lower, upper)
    return bands


def _exact_native_table_cell(
    table: Any,
    *,
    row: int,
    column: int,
) -> tuple[tuple[float, float, float, float], tuple[str, ...]] | None:
    """Return one exact, unspanned cell on an indexed native lattice."""

    geometry = _native_table_geometry(table)
    if geometry is None:
        return None
    row_bands = _indexed_geometry_bands(
        geometry,
        "row_bands",
        lower_key="y0",
        upper_key="y1",
    )
    column_bands = _indexed_geometry_bands(
        geometry,
        "col_bands",
        lower_key="x0",
        upper_key="x1",
    )
    if row_bands is None or column_bands is None:
        return None
    if row not in row_bands or column not in column_bands:
        return None
    cell_bboxes = geometry.get("cell_bboxes")
    cell_status = geometry.get("cell_geometry_status")
    cell_evidence_ids = geometry.get("cell_evidence_ids")
    if not all(isinstance(value, list) for value in (cell_bboxes, cell_status, cell_evidence_ids)):
        return None
    if any(
        row >= len(grid) or not isinstance(grid[row], list) or column >= len(grid[row])
        for grid in (cell_bboxes, cell_status, cell_evidence_ids)
    ):
        return None
    if str(cell_status[row][column] or "") != "exact":
        return None
    bbox = _exact_geometry_bbox(cell_bboxes[row][column])
    evidence_ids = cell_evidence_ids[row][column]
    if bbox is None or not isinstance(evidence_ids, list):
        return None
    normalized_evidence = tuple(dict.fromkeys(str(value) for value in evidence_ids if str(value or "")))
    if not normalized_evidence:
        return None
    expected = (
        column_bands[column][0],
        row_bands[row][0],
        column_bands[column][1],
        row_bands[row][1],
    )
    if any(abs(left - right) > 1.0 for left, right in zip(bbox, expected, strict=True)):
        return None
    spans = geometry.get("cell_spans")
    if spans is not None:
        if not isinstance(spans, list):
            return None
        for span in spans:
            if not isinstance(span, Mapping):
                return None
            try:
                span_row = int(span.get("row"))
                span_column = int(span.get("col"))
                row_span = int(span.get("row_span"))
                column_span = int(span.get("col_span"))
            except (TypeError, ValueError):
                return None
            if span_row <= row < span_row + row_span and span_column <= column < span_column + column_span:
                return None
    return bbox, normalized_evidence


def _bounded_account_guarantee_period_header_residue(
    table: Any,
    rows: list[list[str]],
    *,
    header_row: int,
    header_column: int,
    physical_header_row: int | None,
    physical_value_row: int | None,
) -> dict[str, Any] | None:
    """Recover one exact guarantee/period header with one isolated Han glyph.

    This exception is deliberately physical.  Both source cells must be exact,
    unspanned, consecutive cells in the same native column; their evidence must
    also be independent.  The general closed-header parser therefore remains
    residue-free and cannot promote a text-only or projected candidate.
    """

    if (
        not isinstance(physical_header_row, int)
        or isinstance(physical_header_row, bool)
        or not isinstance(physical_value_row, int)
        or isinstance(physical_value_row, bool)
        or physical_header_row < 0
        or physical_value_row != physical_header_row + 1
        or not (0 <= header_row < len(rows) - 1)
        or not (0 <= header_column < len(rows[header_row]))
        or header_column >= len(rows[header_row + 1])
    ):
        return None

    raw_header = _clean(rows[header_row][header_column])
    match = re.fullmatch(
        r"担保方式\s+还款期数\s+([\u3400-\u9fff])",
        raw_header,
    )
    if match is None:
        return None
    raw_value = _clean(rows[header_row + 1][header_column])

    native_rows = _table_rows(table)
    if (
        physical_value_row >= len(native_rows)
        or header_column >= len(native_rows[physical_header_row])
        or header_column >= len(native_rows[physical_value_row])
        or _clean(native_rows[physical_header_row][header_column]) != raw_header
        or _clean(native_rows[physical_value_row][header_column]) != raw_value
    ):
        return None

    header_cell = _exact_native_table_cell(
        table,
        row=physical_header_row,
        column=header_column,
    )
    value_cell = _exact_native_table_cell(
        table,
        row=physical_value_row,
        column=header_column,
    )
    if header_cell is None or value_cell is None:
        return None
    header_bbox, header_evidence_ids = header_cell
    value_bbox, value_evidence_ids = value_cell
    if (
        abs(header_bbox[0] - value_bbox[0]) > 1.0
        or abs(header_bbox[2] - value_bbox[2]) > 1.0
        or abs(header_bbox[3] - value_bbox[1]) > 1.0
        or set(header_evidence_ids) & set(value_evidence_ids)
    ):
        return None

    return {
        "labels": _ACCOUNT_CELL_GUARANTEE_PERIODS,
        "raw_header": raw_header,
        "residue": match.group(1),
        "header_row": physical_header_row,
        "value_row": physical_value_row,
        "column": header_column,
        "header_bbox": header_bbox,
        "header_evidence_ids": header_evidence_ids,
        "value_bbox": value_bbox,
        "value_evidence_ids": value_evidence_ids,
    }


_EXACT_TWO_CELL_CARD_HEADERS = (
    "发卡机构账户标识开立日期账户授信额度",
    "共享授信额度币种业务种类担保方式",
)


def _exact_two_cell_card_cluster_values(
    table: Any,
    rows: list[list[str]],
) -> dict[str, Any] | None:
    """Decode a closed two-wide-cell PBOC account-card identity layout."""

    if (
        len(rows) < 2
        or len(rows[0]) != 2
        or len(rows[1]) != 2
        or tuple(_compact(value) for value in rows[0]) != _EXACT_TWO_CELL_CARD_HEADERS
    ):
        return None
    geometry = _native_table_geometry(table)
    if geometry is None:
        return None
    column_bands = _indexed_geometry_bands(
        geometry,
        "col_bands",
        lower_key="x0",
        upper_key="x1",
    )
    if column_bands is None or set(column_bands) != {0, 1}:
        return None
    cell_geometry = {
        (row, column): _exact_native_table_cell(table, row=row, column=column) for row in (0, 1) for column in (0, 1)
    }
    if any(value is None for value in cell_geometry.values()):
        return None

    left_raw = _clean(rows[1][0])
    left = left_raw.split()
    if (
        len(left) != 7
        or re.fullmatch(r"[A-Z]\d{8}[A-Z]", left[0], re.I) is None
        or re.fullmatch(r"[\u3400-\u9fff]+", left[1]) is None
        or re.fullmatch(r"\d{4,20}", left[2]) is None
        or _date(left[3]) is None
        or re.fullmatch(r"\d{1,3}(?:,\d{3})+", left[4]) is None
        or re.fullmatch(r"[\u3400-\u9fff]+", left[5]) is None
        or re.fullmatch(r"\d{4,20}", left[6]) is None
    ):
        return None
    institution = _exact_source_account_institution(f"{left[1]}{left[5]}")
    identifier = _canonical_pboc_account_identifier(f"{left[0]}{left[2]}{left[6]}")
    open_date = _date(left[3])
    credit_limit = _number(left[4])
    if (
        not institution
        or not identifier
        or open_date is None
        or not isinstance(credit_limit, int)
        or isinstance(credit_limit, bool)
        or credit_limit < 0
    ):
        return None

    right_raw = _clean(rows[1][1])
    right = right_raw.split()
    if len(right) not in {3, 4}:
        return None
    currency, currency_residue, currency_resolution = _currency_token(right[0])
    business_type = normalize_pboc_field(
        _business_text(right[1]),
        "account_business_type",
    )
    guarantee_type = normalize_pboc_field(
        _business_text(right[2]),
        "guarantee_type",
    )
    residue = "".join(right[3:])
    if (
        currency is None
        or currency_resolution != "exact"
        or currency_residue
        or not validate_pboc_field(business_type, "account_business_type").valid
        or not validate_pboc_field(guarantee_type, "guarantee_type").valid
        or (residue and re.fullmatch(r"[\u3400-\u9fff]", residue) is None)
    ):
        return None
    return {
        "values": {
            "management_institution": institution,
            "account_identifier": identifier,
            "open_date": open_date,
            "credit_limit": credit_limit,
            "currency": currency,
            "business_type": business_type,
            "guarantee_type": guarantee_type,
        },
        "raw_by_field": {
            "management_institution": left_raw,
            "account_identifier": left_raw,
            "open_date": left_raw,
            "credit_limit": left_raw,
            "currency": right_raw,
            "business_type": right_raw,
            "guarantee_type": right_raw,
        },
        "column_by_field": {
            "management_institution": 0,
            "account_identifier": 0,
            "open_date": 0,
            "credit_limit": 0,
            "currency": 1,
            "business_type": 1,
            "guarantee_type": 1,
        },
        "residue": residue,
    }


def _capture_exact_two_cell_card_cluster(
    page: Any,
    table: Any,
    rows: list[list[str]],
) -> dict[str, Any] | None:
    """Retain exact card cells internally without choosing credit vs quasi."""

    decoded = _exact_two_cell_card_cluster_values(table, rows)
    if decoded is None:
        return None
    observations: dict[str, dict[str, Any]] = {}
    for field_name, value in decoded["values"].items():
        column = int(decoded["column_by_field"][field_name])
        ref = _source_ref(page, table, row=1, column=column)
        ref.update(
            binding="closed_exact_two_cell_card_cluster",
            binding_quality="closed_exact_two_cell_card_cluster",
        )
        observations[field_name] = {
            "value": value,
            "raw": str(decoded["raw_by_field"][field_name]),
            "source_ref": ref,
        }
    unresolved_ref = _source_ref(page, table, row=1, column=1)
    unresolved_ref.update(
        binding="closed_exact_two_cell_card_cluster",
        binding_quality="closed_exact_two_cell_card_cluster",
    )
    return {
        "observations": observations,
        "shared_limit_raw": str(rows[1][1]),
        "shared_limit_source_ref": unresolved_ref,
        "residue": str(decoded.get("residue") or ""),
    }


def _release_exact_two_cell_card_cluster(
    parse_result: Any,
    account: dict[str, Any],
) -> None:
    """Publish retained observations only after an exact heading owns subtype."""

    capsule = account.pop("_pending_exact_two_cell_card_cluster", None)
    if (
        not isinstance(capsule, Mapping)
        or account.get("account_type") not in {"credit_card", "quasi_credit_card"}
        or account.get("_table_account_family_resolution")
        != "exact_printed_card_heading_owned_interval"
    ):
        return
    target_record_id = str(account.get("account_id") or "")
    for field_name, observation in (capsule.get("observations") or {}).items():
        if not isinstance(observation, Mapping):
            continue
        for target_field in (str(field_name), "account_currency") if field_name == "currency" else (str(field_name),):
            _merge_exact_observation(
                parse_result,
                account,
                dataset="credit_accounts",
                target_record_id=target_record_id,
                field_name=target_field,
                value=observation.get("value"),
                raw=str(observation.get("raw") or ""),
                source_ref=observation.get("source_ref") or {},
                parser_stage="candidate_b_account_closed_cluster",
            )
    shared_ref = capsule.get("shared_limit_source_ref") or {}
    _report_account_cell_cluster_unresolved(
        parse_result,
        account,
        target_record_id=target_record_id,
        field_names=("shared_credit_limit",),
        raw=str(capsule.get("shared_limit_raw") or ""),
        source_ref=shared_ref,
    )
    residue = str(capsule.get("residue") or "")
    if residue:
        _report_account_cluster_residue(
            parse_result,
            account,
            target_record_id=target_record_id,
            field_names=("currency", "business_type", "guarantee_type"),
            raw=str(capsule.get("shared_limit_raw") or ""),
            residue=residue,
            source_ref=shared_ref,
        )


def _apply_collapsed_account_clusters(
    parse_result: Any,
    account: dict[str, Any],
    rows: list[list[str]],
    *,
    page: Any,
    table: Any,
    physical_row_indices: list[int | None] | None,
) -> None:
    """Decode only closed PBOC clusters whose role assignment is unique."""

    target_record_id = str(account.get("account_id") or "")

    def physical(index: int) -> int | None:
        if physical_row_indices is None:
            return index
        return physical_row_indices[index] if 0 <= index < len(physical_row_indices) else None

    def bind(
        field_name: str,
        value: Any,
        raw: str,
        row_index: int,
        column: int,
        *,
        binding: str = "closed_canonical_account_cluster",
        exact_bbox: tuple[float, float, float, float] | None = None,
        exact_evidence_ids: tuple[str, ...] = (),
    ) -> None:
        source_row = physical(row_index)
        if source_row is None:
            return
        ref = _source_ref(page, table, row=source_row, column=column)
        if exact_bbox is not None and exact_evidence_ids:
            ref.update(
                {
                    "source": "native_detail_table_cell",
                    "geometry_scope": "cell",
                    "bbox": list(exact_bbox),
                    "evidence_ids": list(exact_evidence_ids),
                }
            )
        ref["binding"] = binding
        ref["binding_quality"] = binding
        _merge_exact_observation(
            parse_result,
            account,
            dataset="credit_accounts",
            target_record_id=target_record_id,
            field_name=field_name,
            value=value,
            raw=raw,
            source_ref=ref,
            parser_stage="candidate_b_account_closed_cluster",
        )

    def bind_status(raw: str, row_index: int, column: int) -> None:
        status_values = _status_fields(raw)
        if (
            status_values.get("account_status_resolution") == "unresolved"
            or "account_status" in account.get("_invalid_observation_fields", ())
        ):
            source_row = physical(row_index)
            if source_row is None:
                return
            ref = _source_ref(page, table, row=source_row, column=column)
            ref["binding"] = "closed_canonical_account_cluster"
            _reject_exact_observation(
                parse_result,
                account,
                dataset="credit_accounts",
                target_record_id=target_record_id,
                field_name="account_status",
                raw=raw,
                source_ref=ref,
                parser_stage="candidate_b_account_closed_cluster",
            )
            _withhold_account_status_fields(account)
            return
        for field_name, value in status_values.items():
            bind(field_name, value, raw, row_index, column)

    exact_two_cell_card = (
        _exact_two_cell_card_cluster_values(table, rows)
        if str(account.get("account_type") or "") in {"credit_card", "quasi_credit_card"}
        else None
    )
    if exact_two_cell_card is not None:
        for field_name, value in exact_two_cell_card["values"].items():
            column = int(exact_two_cell_card["column_by_field"][field_name])
            raw = str(exact_two_cell_card["raw_by_field"][field_name])
            bind(
                field_name,
                value,
                raw,
                1,
                column,
                binding="closed_exact_two_cell_card_cluster",
            )
            if field_name == "currency":
                bind(
                    "account_currency",
                    value,
                    raw,
                    1,
                    column,
                    binding="closed_exact_two_cell_card_cluster",
                )
        shared_limit_ref = _source_ref(
            page,
            table,
            row=physical(1),
            column=1,
        )
        shared_limit_ref["binding"] = "closed_exact_two_cell_card_cluster"
        shared_limit_ref["binding_quality"] = "closed_exact_two_cell_card_cluster"
        _report_account_cell_cluster_unresolved(
            parse_result,
            account,
            target_record_id=target_record_id,
            field_names=("shared_credit_limit",),
            raw=str(rows[1][1]),
            source_ref=shared_limit_ref,
        )
        residue = str(exact_two_cell_card.get("residue") or "")
        if residue:
            residue_ref = _source_ref(page, table, row=physical(1), column=1)
            residue_ref["binding"] = "closed_exact_two_cell_card_cluster"
            residue_ref["binding_quality"] = "closed_exact_two_cell_card_cluster"
            _report_account_cluster_residue(
                parse_result,
                account,
                target_record_id=target_record_id,
                field_names=("currency", "business_type", "guarantee_type"),
                raw=str(rows[1][1]),
                residue=residue,
                source_ref=residue_ref,
            )

    for header_index in range(len(rows) - 1):
        for value_column, raw_header in enumerate(rows[header_index]):
            if exact_two_cell_card is not None and header_index == 0 and value_column in {0, 1}:
                continue
            header_raw = _clean(raw_header)
            if not header_raw:
                continue
            value_raw = _clean(
                rows[header_index + 1][value_column] if value_column < len(rows[header_index + 1]) else ""
            )

            suffix_institution = _account_header_suffix_institution(header_raw)
            if suffix_institution is not None:
                _label, institution = suffix_institution
                if institution is not None:
                    bind(
                        "management_institution",
                        institution,
                        header_raw,
                        header_index,
                        value_column,
                        binding="closed_canonical_account_header_suffix",
                    )
                else:
                    cluster_ref = _source_ref(
                        page,
                        table,
                        row=physical(header_index),
                        column=value_column,
                    )
                    _report_collapsed_cluster_fields(
                        parse_result,
                        account,
                        dataset="credit_accounts",
                        target_record_id=target_record_id,
                        raw=header_raw,
                        source_ref=cluster_ref,
                        unresolved_fields=("management_institution",),
                        parser_stage="candidate_b_account_header_suffix",
                    )
                continue

            header_residue_observation = None
            labels = _exact_account_cell_header_labels(header_raw)
            if labels is None and str(account.get("account_type") or "") in {
                "non_revolving_loan",
                "revolving_loan_subaccount",
                "revolving_loan_account",
            }:
                header_residue_observation = _bounded_account_guarantee_period_header_residue(
                    table,
                    rows,
                    header_row=header_index,
                    header_column=value_column,
                    physical_header_row=physical(header_index),
                    physical_value_row=physical(header_index + 1),
                )
                if header_residue_observation is not None:
                    labels = header_residue_observation["labels"]
            if labels is not None:
                geometry_status, geometry_values = _account_merged_header_geometry_values(
                    table,
                    rows,
                    header_row=header_index,
                    header_column=value_column,
                    labels=labels,
                )
                if geometry_status == "rejected":
                    cluster_ref = _source_ref(
                        page,
                        table,
                        row=physical(header_index),
                        column=value_column,
                    )
                    cluster_ref["binding"] = "closed_canonical_account_merged_header_geometry"
                    cluster_ref["binding_quality"] = "closed_canonical_account_merged_header_geometry_rejected"
                    _report_account_cell_cluster_unresolved(
                        parse_result,
                        account,
                        target_record_id=target_record_id,
                        raw=_clean(" ".join(rows[header_index + 1])),
                        source_ref=cluster_ref,
                        field_names=(_ACCOUNT_CELL_LABEL_FIELDS[label] for label in labels),
                    )
                    continue
                if geometry_status == "resolved":
                    source_row = physical(header_index + 1)
                    if source_row is None:
                        continue
                    for item in geometry_values:
                        field_name = str(item["field_name"])
                        raw = str(item["raw"])
                        source_ref = _source_ref(
                            page,
                            table,
                            row=source_row,
                            column=int(item["column"]),
                        )
                        source_ref.update(
                            {
                                "source": "native_detail_table_cell",
                                "geometry_scope": "cell",
                                "bbox": list(item["bbox"]),
                                "evidence_ids": list(item["evidence_ids"]),
                                "binding": ("closed_canonical_account_merged_header_geometry"),
                                "binding_quality": ("closed_canonical_account_merged_header_geometry"),
                                "header_row": physical(header_index),
                                "header_column": value_column,
                            }
                        )
                        value = _decode_account_geometry_field_value(
                            field_name,
                            raw,
                        )
                        if value is None:
                            _reject_exact_observation(
                                parse_result,
                                account,
                                dataset="credit_accounts",
                                target_record_id=target_record_id,
                                field_name=field_name,
                                raw=raw,
                                source_ref=source_ref,
                                parser_stage=("candidate_b_account_merged_header_geometry"),
                            )
                            continue
                        if field_name == "management_institution":
                            _merge_account_institution_observation(
                                parse_result,
                                account,
                                raw=raw,
                                source_ref=source_ref,
                                parser_stage=("candidate_b_account_merged_header_geometry"),
                            )
                            continue
                        if field_name in {"open_date", "due_date"}:
                            _merge_canonical_date_observation(
                                parse_result,
                                account,
                                dataset="credit_accounts",
                                target_record_id=target_record_id,
                                field_name=field_name,
                                raw=raw,
                                source_ref=source_ref,
                                parser_stage=("candidate_b_account_merged_header_geometry"),
                            )
                            continue
                        _merge_exact_observation(
                            parse_result,
                            account,
                            dataset="credit_accounts",
                            target_record_id=target_record_id,
                            field_name=field_name,
                            value=value,
                            raw=raw,
                            source_ref=source_ref,
                            parser_stage=("candidate_b_account_merged_header_geometry"),
                        )
                        if field_name == "currency":
                            _merge_exact_observation(
                                parse_result,
                                account,
                                dataset="credit_accounts",
                                target_record_id=target_record_id,
                                field_name="account_currency",
                                value=value,
                                raw=raw,
                                source_ref=source_ref,
                                parser_stage=("candidate_b_account_merged_header_geometry"),
                            )
                    continue
                fields, unresolved_fields, residue = _decode_account_cell_cluster(
                    labels,
                    value_raw,
                )
                cluster_row_index = header_index + 1 if value_raw else header_index
                cluster_ref = _source_ref(
                    page,
                    table,
                    row=(
                        int(header_residue_observation["value_row"])
                        if header_residue_observation is not None
                        else physical(cluster_row_index)
                    ),
                    column=value_column,
                )
                cluster_binding = (
                    "bounded_canonical_account_header_residue_cluster"
                    if header_residue_observation is not None
                    else "closed_canonical_account_cell_cluster"
                )
                cluster_ref["binding"] = cluster_binding
                cluster_ref["binding_quality"] = cluster_binding
                if header_residue_observation is not None:
                    cluster_ref.update(
                        {
                            "source": "native_detail_table_cell",
                            "geometry_scope": "cell",
                            "bbox": list(header_residue_observation["value_bbox"]),
                            "evidence_ids": list(header_residue_observation["value_evidence_ids"]),
                        }
                    )
                for field_name, (value, _source_token) in fields.items():
                    bind(
                        field_name,
                        value,
                        value_raw,
                        header_index + 1,
                        value_column,
                        binding=cluster_binding,
                        exact_bbox=(
                            header_residue_observation["value_bbox"] if header_residue_observation is not None else None
                        ),
                        exact_evidence_ids=(
                            header_residue_observation["value_evidence_ids"]
                            if header_residue_observation is not None
                            else ()
                        ),
                    )
                    if field_name == "currency":
                        bind(
                            "account_currency",
                            value,
                            value_raw,
                            header_index + 1,
                            value_column,
                            binding=cluster_binding,
                            exact_bbox=(
                                header_residue_observation["value_bbox"]
                                if header_residue_observation is not None
                                else None
                            ),
                            exact_evidence_ids=(
                                header_residue_observation["value_evidence_ids"]
                                if header_residue_observation is not None
                                else ()
                            ),
                        )
                _report_account_cell_cluster_unresolved(
                    parse_result,
                    account,
                    target_record_id=target_record_id,
                    raw=value_raw,
                    source_ref=cluster_ref,
                    field_names=unresolved_fields,
                )
                if residue and fields:
                    _report_account_cluster_residue(
                        parse_result,
                        account,
                        target_record_id=target_record_id,
                        field_names=fields,
                        raw=value_raw,
                        residue=residue,
                        source_ref=cluster_ref,
                    )
                if header_residue_observation is not None:
                    header_ref = _source_ref(
                        page,
                        table,
                        row=int(header_residue_observation["header_row"]),
                        column=value_column,
                    )
                    header_ref.update(
                        {
                            "source": "native_detail_table_cell",
                            "geometry_scope": "cell",
                            "bbox": list(header_residue_observation["header_bbox"]),
                            "evidence_ids": list(header_residue_observation["header_evidence_ids"]),
                            "binding": cluster_binding,
                            "binding_quality": cluster_binding,
                        }
                    )
                    _report_account_header_han_residue_corrected(
                        parse_result,
                        target_record_id=target_record_id,
                        raw_header=str(header_residue_observation["raw_header"]),
                        residue=str(header_residue_observation["residue"]),
                        header_ref=header_ref,
                        value_ref=cluster_ref,
                    )
                continue

            header = _compact(header_raw)
            tokens = _ACCOUNT_CLUSTER_TOKEN_RE.findall(value_raw)

            # Non-revolving status block.  Two identical finite statuses and
            # two shape-distinct numbers make every role unique even when OCR
            # merged the physical columns into one cell.
            if all(marker in header for marker in ("五级分类", "账户状态", "余额", "剩余还款期数")):
                status_tokens = [token for token in tokens if token in {"正常", "逾期", "呆账", "结清", "销户", "转出"}]
                number_tokens = [
                    token
                    for token in tokens
                    if isinstance(_number(token), int) and not isinstance(_number(token), bool)
                ]
                balance_tokens = [token for token in number_tokens if "," in token or int(_number(token) or 0) >= 1000]
                remaining_tokens = [
                    token
                    for token in number_tokens
                    if 0 <= int(_number(token) or 0) <= 600 and token not in balance_tokens
                ]
                if len(status_tokens) == 2 and len(set(status_tokens)) == 1:
                    bind(
                        "five_tier_class",
                        status_tokens[0],
                        status_tokens[0],
                        header_index + 1,
                        value_column,
                    )
                    bind_status(status_tokens[0], header_index + 1, value_column)
                if len(balance_tokens) == 1 and len(remaining_tokens) == 1:
                    bind(
                        "balance",
                        int(_number(balance_tokens[0]) or 0),
                        balance_tokens[0],
                        header_index + 1,
                        value_column,
                    )
                    bind(
                        "remaining_periods",
                        int(_number(remaining_tokens[0]) or 0),
                        remaining_tokens[0],
                        header_index + 1,
                        value_column,
                    )
                continue

            # Known merged card summary traversal.  The signature is the
            # canonical seven-column PBOC block; other token counts/orders are
            # withheld.
            card_signature = (
                "未出单的大额" in header
                and "最近6个月" in header
                and "剩余分期期数" in header
                and "最大使用额度" in header
                and "账户状态" in header
                and "余额" in header
                and "已用额度" in header
                and "平均使用额度" in header
                and "专项分期余额" in header
            )
            if card_signature and len(tokens) == 7:
                numeric = [_number(token) for token in tokens]
                if (
                    isinstance(numeric[0], int)
                    and 0 <= numeric[0] <= 600
                    and all(isinstance(numeric[index], int) for index in (1, 2, 3, 5))
                    and tokens[4]
                    in {
                        "正常",
                        "逾期",
                        "呆账",
                        "结清",
                        "销户",
                        "转出",
                        "未激活",
                        "冻结",
                        "止付",
                    }
                    and numeric[3] >= max(int(numeric[1]), int(numeric[2]))
                    and re.fullmatch(r"[-*#]+", tokens[6]) is not None
                ):
                    for field_name, index in (
                        ("remaining_periods", 0),
                        ("used_amount", 1),
                        ("recent_6_month_average_used_amount", 2),
                        ("maximum_used_amount", 3),
                        ("balance", 5),
                    ):
                        bind(
                            field_name,
                            int(numeric[index]),
                            tokens[index],
                            header_index + 1,
                            value_column,
                        )
                    bind_status(tokens[4], header_index + 1, value_column)
                continue

            # Non-revolving payment row: value shapes alternate exactly with
            # the four canonical roles after the split label is restored.
            if all(
                marker in header
                for marker in (
                    "最近一次",
                    "本月应还款",
                    "应还款日",
                    "本月实还款",
                    "还款日期",
                )
            ):
                if len(tokens) == 4:
                    first_date, first_amount, second_date, second_amount = tokens
                    parsed = (
                        _date(first_date),
                        _number(first_amount),
                        _date(second_date),
                        _number(second_amount),
                    )
                    if isinstance(parsed[1], int) and isinstance(parsed[3], int) and parsed[0] and parsed[2]:
                        for field_name, value, raw in (
                            ("last_repayment_date", parsed[0], first_date),
                            ("scheduled_payment", parsed[1], first_amount),
                            ("scheduled_payment_date", parsed[2], second_date),
                            ("actual_payment", parsed[3], second_amount),
                        ):
                            bind(
                                field_name,
                                value,
                                raw,
                                header_index + 1,
                                value_column,
                            )
                continue

            # Card payment rows can be merged in a different traversal.  The
            # dates are distinguished by the source-visible snapshot date.
            if all(
                marker in header
                for marker in (
                    "当前逾期期数",
                    "最近一次还款日期",
                    "当前逾期总额",
                    "账单日",
                    "本月应还款",
                    "本月实还款",
                )
            ):
                dates = [(token, _date(token)) for token in tokens if _date(token)]
                numbers = [(token, _number(token)) for token in tokens if isinstance(_number(token), int)]
                snapshot = str(account.get("snapshot_date") or "")
                billing = [item for item in dates if item[1] == snapshot]
                prior_dates = [item for item in dates if item[1] != snapshot]
                nonzero = [item for item in numbers if int(item[1]) > 0]
                zeros = [item for item in numbers if int(item[1]) == 0]
                if (
                    len(billing) == 1
                    and len(prior_dates) == 1
                    and len(nonzero) == 2
                    and nonzero[0][1] == nonzero[1][1]
                    and len(zeros) == 2
                ):
                    for field_name, value, raw in (
                        ("billing_date", billing[0][1], billing[0][0]),
                        ("last_repayment_date", prior_dates[0][1], prior_dates[0][0]),
                        ("scheduled_payment", int(nonzero[0][1]), nonzero[0][0]),
                        ("actual_payment", int(nonzero[1][1]), nonzero[1][0]),
                        ("current_overdue_periods", 0, zeros[0][0]),
                        ("current_overdue_amount", 0, zeros[1][0]),
                    ):
                        bind(
                            field_name,
                            value,
                            raw,
                            header_index + 1,
                            value_column,
                        )


def _apply_account_facts(
    parse_result: Any,
    account: dict[str, Any],
    rows: list[list[str]],
    *,
    page: Any,
    table: Any,
    physical_row_indices: list[int | None] | None = None,
    defer_trailing_labels: bool = True,
) -> None:
    observations, unresolved = _exact_label_observations(rows)
    mappings: tuple[tuple[str, tuple[str, ...], Any], ...] = (
        ("management_institution", ("管理机构", "发卡机构"), _account_institution),
        ("account_identifier", ("账户标识",), _identifier),
        ("open_date", ("开立日期",), _date),
        ("due_date", ("到期日期",), _date),
        ("loan_amount", ("借款金额",), _number),
        ("credit_limit", ("账户授信额度", "账户授信额度"), _number),
        ("shared_credit_limit", ("共享授信额度",), _number),
        ("business_type", ("业务种类",), _business_text),
        ("guarantee_type", ("担保方式",), _business_text),
        ("repayment_periods", ("还款期数",), _number),
        ("repayment_frequency", ("还款频率",), _business_text),
        ("repayment_method", ("还款方式",), _business_text),
        ("co_borrower_flag", ("共同借款标志",), _business_text),
        ("balance", ("余额", "透支余额"), _number),
        ("remaining_periods", ("剩余还款期数", "剩余分期期数"), _number),
        ("scheduled_payment", ("本月应还款",), _number),
        ("actual_payment", ("本月实还款",), _number),
        ("scheduled_payment_date", ("应还款日",), _date),
        ("billing_date", ("账单日",), _date),
        ("last_repayment_date", ("最近一次还款日期",), _date),
        ("current_overdue_periods", ("当前逾期期数",), _number),
        ("current_overdue_amount", ("当前逾期总额",), _number),
        ("overdue_principal_31_60", ("逾期31—60天未还本金", "逾期31－60天未还本金"), _number),
        ("overdue_principal_61_90", ("逾期61—90天未还本金", "逾期61－90天未还本金"), _number),
        ("overdue_principal_91_180", ("逾期91—180天未还本金", "逾期91－180天未还本金"), _number),
        ("overdue_principal_over_180", ("逾期180天以上未还本金", "透支180天以上未付余额"), _number),
        ("used_amount", ("已用额度",), _number),
        ("recent_6_month_average_used_amount", ("最近6个月平均使用额度",), _number),
        ("maximum_used_amount", ("最大使用额度",), _number),
        ("recent_6_month_average_overdraft_balance", ("最近6个月平均透支余额",), _number),
        ("maximum_overdraft_balance", ("最大透支余额",), _number),
        ("unbilled_installment_balance", ("未出单的大额专项分期余额",), _number),
        ("five_tier_class", ("五级分类",), _clean),
        ("close_date", ("账户关闭日期", "销户日期"), _date),
        ("transfer_out_date", ("转出月份",), _date),
    )
    dataset = "credit_accounts"
    target_record_id = str(account.get("account_id") or "")
    parser_stage = "candidate_b_account_canonical_slots"

    def physical_row(row_index: int) -> int | None:
        if physical_row_indices is None:
            return row_index
        if 0 <= row_index < len(physical_row_indices):
            return physical_row_indices[row_index]
        return None

    for target, labels, converter in mappings:
        values = [item for label in labels for item in observations.get(_compact(label), ())]
        for raw, value_row_index, column in values:
            source_row = physical_row(value_row_index)
            if source_row is None:
                continue
            ref = _source_ref(page, table, row=source_row, column=column)
            if is_explicit_source_absence(raw):
                _mark_source_absent(account, target, raw)
                continue
            if target == "management_institution":
                _merge_account_institution_observation(
                    parse_result,
                    account,
                    raw=raw,
                    source_ref=ref,
                    parser_stage=parser_stage,
                )
                continue
            if converter is _date:
                _merge_canonical_date_observation(
                    parse_result,
                    account,
                    dataset=dataset,
                    target_record_id=target_record_id,
                    field_name=target,
                    raw=raw,
                    source_ref=ref,
                    parser_stage=parser_stage,
                )
                continue
            value = converter(raw)
            valid = value not in (None, "")
            if converter is _number:
                valid = isinstance(value, int) and not isinstance(value, bool)
            elif converter in {_business_text, _account_institution}:
                compact_value = _compact(value)
                valid = bool(value) and not any(label in compact_value for label in _ACCOUNT_LABELS)
                if target == "management_institution":
                    valid = valid and not bool(
                        _DATE_RE.search(compact_value)
                        or re.search(r"[A-Z][A-Z0-9-]{7,}\d", compact_value, re.IGNORECASE)
                    )
                contract_role = _ACCOUNT_SCALAR_CONTRACT_ROLES.get(target)
                if contract_role:
                    value = normalize_pboc_field(str(value), contract_role)
                    valid = valid and validate_pboc_field(str(value), contract_role).valid
            elif target == "account_identifier":
                typed_value = _typed_identifier(value)
                valid = typed_value is not None
                value = typed_value
            if not valid:
                _reject_exact_observation(
                    parse_result,
                    account,
                    dataset=dataset,
                    target_record_id=target_record_id,
                    field_name=target,
                    raw=raw,
                    source_ref=ref,
                    parser_stage=parser_stage,
                )
                continue
            _merge_exact_observation(
                parse_result,
                account,
                dataset=dataset,
                target_record_id=target_record_id,
                field_name=target,
                value=value,
                raw=raw,
                source_ref=ref,
                parser_stage=parser_stage,
            )

    for raw_currency, value_row_index, column in [
        item for label in ("账户币种", "币种") for item in observations.get(label, ())
    ]:
        source_row = physical_row(value_row_index)
        if source_row is None:
            continue
        ref = _source_ref(page, table, row=source_row, column=column)
        if _compact(raw_currency) in {"-", "--"}:
            _mark_source_absent(account, "currency", raw_currency)
            _mark_source_absent(account, "account_currency", raw_currency)
            continue
        currency, _residue, _resolution = _currency_token(raw_currency)
        if not currency:
            _reject_exact_observation(
                parse_result,
                account,
                dataset=dataset,
                target_record_id=target_record_id,
                field_name="currency",
                raw=raw_currency,
                source_ref=ref,
                parser_stage=parser_stage,
            )
            continue
        for field_name in ("currency", "account_currency"):
            _merge_exact_observation(
                parse_result,
                account,
                dataset=dataset,
                target_record_id=target_record_id,
                field_name=field_name,
                value=currency,
                raw=raw_currency,
                source_ref=ref,
                parser_stage=parser_stage,
            )

    for raw_status, value_row_index, column in [
        item for label in ("账户状态", "状态") for item in observations.get(label, ())
    ]:
        source_row = physical_row(value_row_index)
        if source_row is None:
            continue
        ref = _source_ref(page, table, row=source_row, column=column)
        if _compact(raw_status) in {"-", "--"}:
            _mark_source_absent(account, "account_status", raw_status)
            continue
        status_values = _status_fields(raw_status)
        if (
            status_values.get("account_status_resolution") == "unresolved"
            or "account_status" in account.get("_invalid_observation_fields", ())
        ):
            _reject_exact_observation(
                parse_result,
                account,
                dataset=dataset,
                target_record_id=target_record_id,
                field_name="account_status",
                raw=raw_status,
                source_ref=ref,
                parser_stage=parser_stage,
            )
            _withhold_account_status_fields(account)
            continue
        for field_name, value in status_values.items():
            _merge_exact_observation(
                parse_result,
                account,
                dataset=dataset,
                target_record_id=target_record_id,
                field_name=field_name,
                value=value,
                raw=raw_status,
                source_ref=ref,
                parser_stage=parser_stage,
            )

    terminal_block = _canonical_account_terminal_subtable(rows)
    if terminal_block is not None:
        status_source_row = physical_row(int(terminal_block["status_row"]))
        close_source_row = physical_row(int(terminal_block["close_row"]))
        if status_source_row is not None and close_source_row is not None:
            status_ref = _source_ref(
                page,
                table,
                row=status_source_row,
                column=int(terminal_block["status_column"]),
            )
            close_ref = _source_ref(
                page,
                table,
                row=close_source_row,
                column=int(terminal_block["close_column"]),
            )
            for ref in (status_ref, close_ref):
                ref["binding"] = "canonical_account_terminal_subtable"
                ref["binding_quality"] = "canonical_account_terminal_subtable"
            if "account_status" in account.get("_invalid_observation_fields", ()):
                _reject_exact_observation(
                    parse_result,
                    account,
                    dataset=dataset,
                    target_record_id=target_record_id,
                    field_name="account_status",
                    raw=str(terminal_block["status_raw"]),
                    source_ref=status_ref,
                    parser_stage="candidate_b_account_terminal_subtable",
                )
                _withhold_account_status_fields(account)
            else:
                for field_name, value in terminal_block["status_values"].items():
                    _merge_exact_observation(
                        parse_result,
                        account,
                        dataset=dataset,
                        target_record_id=target_record_id,
                        field_name=field_name,
                        value=value,
                        raw=str(terminal_block["status_raw"]),
                        source_ref=status_ref,
                        parser_stage="candidate_b_account_terminal_subtable",
                    )
            _merge_canonical_date_observation(
                parse_result,
                account,
                dataset=dataset,
                target_record_id=target_record_id,
                field_name="close_date",
                raw=str(terminal_block["close_raw"]),
                source_ref=close_ref,
                parser_stage="candidate_b_account_terminal_subtable",
            )

    # Do not report the final label row yet: it may be a verified continuation
    # whose value row begins the next logical page.  Internal missing cells are
    # immediately repair-eligible.
    for label, label_row_index, column in unresolved:
        if defer_trailing_labels and label_row_index == len(rows) - 1:
            continue
        target = next((field for field, labels, _converter in mappings if label in labels), None)
        if target is None:
            target = {
                "账户币种": "currency",
                "币种": "currency",
                "账户状态": "account_status",
                "状态": "account_status",
            }.get(label)
        label_source_row = physical_row(label_row_index)
        source_row = physical_row(label_row_index + 1)
        if not target or label_source_row is None:
            continue
        if source_row is None:
            ref = _source_ref(
                page,
                table,
                row=label_source_row,
                column=column,
            )
            ref.update(
                {
                    "field_slot_role": "label_without_value_row",
                    "canonical_label_row": label_source_row,
                    "canonical_value_row": None,
                }
            )
            _report_unreadable_exact_slot(
                parse_result,
                account,
                dataset=dataset,
                target_record_id=target_record_id,
                field_name=target,
                source_ref=ref,
                parser_stage=parser_stage,
                issue_code="candidate_b_exact_slot_value_row_missing",
                slot_state="value_row_missing",
                message=(
                    "The canonical label had no physically owned next value row; no value was guessed or published."
                ),
            )
            continue
        ref = _source_ref(page, table, row=source_row, column=column)
        ref.update(
            {
                "field_slot_role": "value",
                "canonical_label_row": label_source_row,
                "canonical_value_row": source_row,
            }
        )
        _report_unreadable_exact_slot(
            parse_result,
            account,
            dataset=dataset,
            target_record_id=target_record_id,
            field_name=target,
            source_ref=ref,
            parser_stage=parser_stage,
        )

    for row_index, row in enumerate(rows):
        text = _clean(" ".join(row))
        as_of = _AS_OF_RE.search(text)
        if as_of:
            account["snapshot_date"] = f"{int(as_of.group(1)):04d}-{int(as_of.group(2)):02d}-{int(as_of.group(3)):02d}"
        inactive = re.search(r"账户状态为[“\"]([^”\"]+)", text)
        if inactive:
            raw_status = inactive.group(1)
            status_values = _status_fields(raw_status)
            source_row = physical_row(row_index)
            if source_row is None:
                continue
            ref = _source_ref(page, table, row=source_row)
            ref["binding"] = "canonical_account_status_sentence"
            if (
                status_values.get("account_status_resolution") == "unresolved"
                or "account_status" in account.get("_invalid_observation_fields", ())
            ):
                _reject_exact_observation(
                    parse_result,
                    account,
                    dataset=dataset,
                    target_record_id=target_record_id,
                    field_name="account_status",
                    raw=raw_status,
                    source_ref=ref,
                    parser_stage=parser_stage,
                )
                _withhold_account_status_fields(account)
                continue
            for field_name, value in status_values.items():
                _merge_exact_observation(
                    parse_result,
                    account,
                    dataset=dataset,
                    target_record_id=target_record_id,
                    field_name=field_name,
                    value=value,
                    raw=raw_status,
                    source_ref=ref,
                    parser_stage=parser_stage,
                )

    _apply_collapsed_account_clusters(
        parse_result,
        account,
        rows,
        page=page,
        table=table,
        physical_row_indices=physical_row_indices,
    )

    if account.get("due_date"):
        account["contract_maturity_date"] = account["due_date"]
    if account.get("currency"):
        account["reporting_amount_currency"] = account["currency"]
    account.setdefault("amount_unit", "yuan")
    account.setdefault("reporting_amount_unit", "yuan")
    account.setdefault("reporting_amount_precision", 0)


def _repayment_records(
    page: Any,
    table: Any,
    rows: list[list[str]],
    account: dict[str, Any],
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    context = account.setdefault("_repayment_context", {})
    observed_months = _month_centers(table, rows)
    if observed_months:
        context["month_centers"] = observed_months
    months = dict(context.get("month_centers") or {})
    width = max((len(row) for row in rows), default=0)
    centers = _column_centers(table, width)

    def amount_values(row: list[str]) -> dict[int, str]:
        values: dict[int, str] = {}
        for column, cell in enumerate(row):
            raw = _compact(cell)
            if not raw or not re.fullmatch(r"(?:--|-?\d[\d,]*)", raw):
                continue
            month = _nearest_month(column, centers, months)
            if month is not None:
                values[month] = raw
        return values

    def make_record(
        *,
        year: int,
        month: int,
        status: str,
        amount_raw: str = "",
        row_index: int,
        source_refs: list[dict[str, Any]] | None = None,
        confidence: float = 1.0,
        inferred: bool = False,
    ) -> dict[str, Any]:
        account_id = str(account["account_id"])
        return {
            "repayment_id": stable_record_id("credit_repayment", account_id, year, month),
            "account_id": account_id,
            "_table_observation_instance_id": account.get("_table_observation_instance_id"),
            "account_identifier": account.get("account_identifier"),
            "grid_id": str(getattr(table, "table_id", "") or ""),
            "year": year,
            "month": month,
            "status": status,
            "overdue_amount": (
                None if amount_raw in {"", "--"} else _number(amount_raw)
            ),
            "source": "native_detail_repayment_grid_gap_recovery" if inferred else "native_detail_repayment_grid",
            "source_refs": source_refs or [_source_ref(page, table, row=row_index)],
            "confidence": confidence,
            **({"status_inferred_from_adjacent_months": True} if inferred else {}),
        }

    records: list[dict[str, Any]] = []
    pending = context.pop("pending_status", None)
    if isinstance(pending, dict) and rows and months:
        first_values = amount_values(rows[0])
        if first_values:
            for month, status in pending.get("statuses", {}).items():
                records.append(
                    make_record(
                        year=int(pending["year"]),
                        month=int(month),
                        status=str(status),
                        amount_raw=first_values.get(int(month), ""),
                        row_index=0,
                        source_refs=[
                            *list(pending.get("source_refs") or []),
                            _source_ref(page, table, row=0),
                        ],
                    )
                )

    for row_index, row in enumerate(rows):
        year_cell = next(
            ((index, _compact(cell)) for index, cell in enumerate(row) if re.fullmatch(r"20\d{2}", _compact(cell))),
            None,
        )
        if year_cell is None:
            continue
        year_col, year_raw = year_cell
        status_cells = [
            (index, _compact(cell))
            for index, cell in enumerate(row)
            if index != year_col and _compact(cell) in _STATUS_CODES
        ]
        if not status_cells:
            continue
        statuses: dict[int, str] = {}
        for column, status in status_cells:
            month = _nearest_month(column, centers, months)
            if month is not None:
                statuses[month] = status
        if not statuses:
            continue

        amount_row_index = row_index + 1
        amounts = (
            amount_values(rows[amount_row_index])
            if amount_row_index < len(rows)
            and not any(re.fullmatch(r"20\d{2}", _compact(cell)) for cell in rows[amount_row_index])
            else {}
        )
        # A native grid can occasionally omit one status glyph while keeping
        # the paired amount. Recover only a sandwiched value whose two adjacent
        # statuses agree; this is deterministic and intentionally conservative.
        inferred_months: set[int] = set()
        for month in sorted(amounts):
            if month in statuses or month <= 1 or month >= 12:
                continue
            previous = statuses.get(month - 1)
            following = statuses.get(month + 1)
            if previous == following and previous in {"1", "2", "3", "4", "5", "6", "7"}:
                statuses[month] = str(previous)
                inferred_months.add(month)

        if amounts or amount_row_index < len(rows):
            for month, status in sorted(statuses.items()):
                records.append(
                    make_record(
                        year=int(year_raw),
                        month=month,
                        status=status,
                        amount_raw=amounts.get(month, ""),
                        row_index=row_index,
                        confidence=0.8 if month in inferred_months else 1.0,
                        inferred=month in inferred_months,
                    )
                )
        else:
            context["pending_status"] = {
                "year": int(year_raw),
                "statuses": statuses,
                "source_refs": [_source_ref(page, table, row=row_index)],
            }
    return records, context


def _account_base(rows: list[list[str]]) -> bool:
    compact = _compact(" ".join(cell for row in rows[:4] for cell in row))
    return "账户标识" in compact and ("管理机构" in compact or "发卡机构" in compact) and not _other_entity_table(rows)


def _other_entity_table(rows: list[list[str]]) -> bool:
    compact = _compact(" ".join(cell for row in rows[:4] for cell in row))
    return any(
        marker in compact
        for marker in (
            "保证合同编号",
            "授信协议标识",
            "机构名称业务类型业务开通日期",
            "主管税务机关",
            "立案法院",
            "执行法院",
            "处罚机构",
            "查询日期查询机构查询原因",
        )
    )


def _account_heading_fields(value: Any) -> dict[str, str]:
    """Decode business identifiers printed in one canonical account anchor."""

    text = _compact(value)
    tail = re.search(r"卡片尾号[：:]?([0-9]{4})", text)
    agreement = re.search(r"授信协议标识[：:]?([A-Z0-9]{8,80})", text, re.IGNORECASE)
    return {
        **({"card_tail": tail.group(1)} if tail else {}),
        **({"credit_agreement_identifier": agreement.group(1).upper()} if agreement else {}),
    }


def _account_heading_for_table(page: Any, table: Any) -> dict[str, str]:
    bbox = getattr(table, "bbox", None) or []
    table_top = float(bbox[1]) if len(bbox) == 4 else float("inf")
    candidates: list[tuple[float, str]] = []
    for text_block in getattr(page, "texts", None) or []:
        text = _clean(getattr(text_block, "content", "") or getattr(text_block, "text", "") or "")
        compact_text = _compact(text)
        if not re.match(r"^(?:账户|业务)\s*\d{1,3}", compact_text):
            continue
        text_bbox = getattr(text_block, "bbox", None) or []
        bottom = float(text_bbox[3]) if len(text_bbox) == 4 else 0.0
        if bottom <= table_top + 1.0:
            candidates.append((bottom, text))
    if not candidates:
        return {}
    bottom, raw_text = max(candidates, key=lambda item: item[0])
    page_height = float(getattr(page, "height", 0.0) or 0.0)
    maximum_gap = max(72.0, page_height * 0.10) if page_height else 72.0
    if table_top != float("inf") and table_top - bottom > maximum_gap:
        return {}
    return _account_heading_fields(raw_text)


_ACCOUNT_CONTINUATION_LABELS = frozenset(
    {
        "账户状态",
        "状态",
        "五级分类",
        "余额",
        "透支余额",
        "剩余还款期数",
        "剩余分期期数",
        "本月应还款",
        "本月实还款",
        "应还款日",
        "账单日",
        "最近一次还款日期",
        "当前逾期期数",
        "当前逾期总额",
        "逾期31—60天未还本金",
        "逾期31－60天未还本金",
        "逾期61—90天未还本金",
        "逾期61－90天未还本金",
        "逾期91—180天未还本金",
        "逾期91－180天未还本金",
        "逾期180天以上未还本金",
        "透支180天以上未付余额",
        "已用额度",
        "最近6个月平均使用额度",
        "最大使用额度",
        "未出单的大额专项分期余额",
        "大额专项分期额度",
        "分期额度生效日期",
        "分期额度到期日期",
        "已用分期金额",
        "还款日期",
        "还款金额",
        "当前还款状态",
        "特殊交易类型",
        "特殊事件说明",
    }
)


def _account_continuation_fragment(rows: list[list[str]], pending_labels: list[str] | None = None) -> bool:
    """Recognize a canonical account-detail fragment, not another account body."""

    compact = _compact(" ".join(cell for row in rows for cell in row))
    if not compact:
        return False
    if any(_compact(label) in compact for label in _ACCOUNT_CONTINUATION_LABELS):
        return True
    if "还款记录" in compact or "逾期金额" in compact:
        return True
    # A value-only table is eligible only when the immediately preceding
    # account fragment ended with an exact canonical label row.
    return bool(pending_labels and _label_row(pending_labels))


def _table_top_value(table: Any) -> float | None:
    bbox = getattr(table, "bbox", None)
    if not isinstance(bbox, (list, tuple)) or len(bbox) != 4:
        return None
    try:
        top = float(bbox[1])
    except (TypeError, ValueError):
        return None
    return top if math.isfinite(top) else None


def _account_reading_order_resolution(
    parse_result: Any,
    pages: Iterable[Any],
) -> tuple[dict[int, int], list[int], list[int], list[int], bool]:
    """Validate the registered order for this exact account-page population."""

    materialized = list(pages)
    raw_order = getattr(parse_result, "reading_order_by_logical", None)
    registered_resolution = getattr(parse_result, "reading_order_resolution", None)
    legacy_sealed = not hasattr(parse_result, "reading_order_by_logical") and not hasattr(
        parse_result, "reading_order_resolution"
    )
    provenance_resolved = (
        legacy_sealed
        or not hasattr(parse_result, "reading_order_resolution")
        or bool(
            isinstance(registered_resolution, Mapping)
            and registered_resolution.get("resolved") is True
            and registered_resolution.get("authoritative") is True
        )
    )
    normalized_order: dict[int, int] = {}
    if isinstance(raw_order, Mapping):
        for raw_logical, raw_position in raw_order.items():
            try:
                logical = int(raw_logical)
                position = int(raw_position)
            except (TypeError, ValueError):
                continue
            if logical > 0 and position > 0:
                normalized_order[logical] = position

    logical_pages: list[int] = []
    for page in materialized:
        raw_logical = page.get("page") if isinstance(page, Mapping) else getattr(page, "page_number", 0)
        try:
            logical_pages.append(int(raw_logical or 0))
        except (TypeError, ValueError):
            logical_pages.append(0)
    missing = sorted({logical for logical in logical_pages if logical <= 0 or logical not in normalized_order})
    observed_positions = [
        normalized_order[logical] for logical in logical_pages if logical > 0 and logical in normalized_order
    ]
    duplicate_positions = sorted(position for position, count in Counter(observed_positions).items() if count > 1)
    registered_pages = list(getattr(parse_result, "pages", None) or [])
    if registered_pages and registered_pages is not materialized:
        registered_logicals: list[int] = []
        for page in registered_pages:
            try:
                registered_logicals.append(int(getattr(page, "page_number", 0) or 0))
            except (TypeError, ValueError):
                registered_logicals.append(0)
        missing = sorted(
            set(missing)
            | {logical for logical in registered_logicals if logical <= 0 or logical not in normalized_order}
        )
        registered_positions = [
            normalized_order[logical] for logical in registered_logicals if logical > 0 and logical in normalized_order
        ]
        duplicate_positions = sorted(
            set(duplicate_positions)
            | {position for position, count in Counter(registered_positions).items() if count > 1}
        )
    # Contexts created before the reading-order plane existed have always
    # treated their sealed page list as authoritative.  Preserve that explicit
    # legacy contract.  Once a context exposes the plane, however, empty,
    # partial, or non-unique registration is unresolved and must fail closed.
    resolved = legacy_sealed or bool(
        isinstance(raw_order, Mapping)
        and normalized_order
        and not missing
        and not duplicate_positions
        and provenance_resolved
    )
    return normalized_order, logical_pages, missing, duplicate_positions, resolved


def _account_ordered_pages(parse_result: Any, pages: Iterable[Any]) -> list[Any]:
    """Return pages in the document's registered reading order.

    Logical page numbers remain the provenance coordinate.  Account-family
    state, however, must follow the already-registered printed reading order:
    some scanned PDFs store two physical halves in a different logical order.
    A partial or non-unique order is not repaired here; that case falls back to
    the sealed input order and is reported once for downstream review.
    """

    materialized = list(pages)
    if len(materialized) < 2:
        return materialized

    raw_order = getattr(parse_result, "reading_order_by_logical", None)
    registered_resolution = getattr(parse_result, "reading_order_resolution", None)
    # Small unit/legacy contexts created before the reading-order plane existed
    # retain their sealed order without manufacturing a diagnostic.  A real
    # context that exposes an empty/invalid plane is explicitly auditable.
    if (
        raw_order is None
        and not hasattr(parse_result, "reading_order_by_logical")
        and not hasattr(parse_result, "reading_order_resolution")
    ):
        return materialized
    (
        normalized_order,
        logical_pages,
        missing,
        duplicate_positions,
        resolved,
    ) = _account_reading_order_resolution(parse_result, materialized)
    if not resolved:
        if not getattr(parse_result, "_candidate_b_account_reading_order_issue", False):
            try:
                setattr(parse_result, "_candidate_b_account_reading_order_issue", True)
            except (AttributeError, TypeError):
                pass
            from docmirror.plugins.credit_report.personal_detail_scanned.extraction_issues import (
                make_issue,
                record_issue,
            )

            record_issue(
                parse_result,
                make_issue(
                    category="ocr_structure_correction",
                    issue_code="candidate_b_account_reading_order_unresolved",
                    message=(
                        "The document-local account reading-order plane was missing or non-unique; "
                        "sealed page order was retained and no cross-page ownership was inferred from it."
                    ),
                    parser_stage="candidate_b_account_page_ownership",
                    target_dataset="credit_accounts",
                    observed_value={
                        "logical_pages": logical_pages,
                        "registered_reading_order": normalized_order,
                        "reading_order_resolution": (
                            dict(registered_resolution) if isinstance(registered_resolution, Mapping) else None
                        ),
                        "missing_logical_pages": missing,
                        "duplicate_reading_positions": duplicate_positions,
                    },
                    source_refs=tuple(
                        {
                            "source": "candidate_b_account_page_order",
                            "logical_page": logical,
                        }
                        for logical in logical_pages
                        if logical > 0
                    ),
                    reason_codes=(
                        "document_local_reading_order_unresolved",
                        "sealed_page_order_retained",
                        "cross_page_account_ownership_not_inferred",
                    ),
                ),
            )
        return materialized

    return [
        page
        for _index, page in sorted(
            enumerate(materialized),
            key=lambda item: (
                normalized_order[logical_pages[item[0]]],
                item[0],
            ),
        )
    ]


def _exact_account_anchor_boundary_between(
    parse_result: Any,
    *,
    current_logical_page: int,
    current_table_top: float,
    candidate_logical_page: int,
    candidate_table_top: float,
) -> bool:
    """Return whether one exact printed account anchor separates two tables.

    Native table OCR can damage one required base-table label (for example,
    ``管理机构`` or ``账户标识``) while the independently reconstructed text
    plane still contains the exact ``账户 N`` boundary.  Such a table is a new
    account body, never a continuation of the preceding account.  This helper
    is deliberately veto-only: absent or malformed geometry preserves the
    existing fail-closed ownership path and never manufactures an owner.
    """

    evidence_loader = getattr(parse_result, "corrected_evidence_pages", None)
    if not callable(evidence_loader):
        return False
    if (
        current_logical_page <= 0
        or candidate_logical_page <= 0
        or candidate_logical_page < current_logical_page
        or not math.isfinite(current_table_top)
        or not math.isfinite(candidate_table_top)
    ):
        return False

    for evidence_page in evidence_loader():
        if not isinstance(evidence_page, Mapping):
            continue
        logical_page = int(evidence_page.get("page") or 0)
        if logical_page not in {current_logical_page, candidate_logical_page}:
            continue
        for line in evidence_page.get("lines") or ():
            if not isinstance(line, Mapping):
                continue
            raw_text = str(line.get("text") or line.get("content") or "")
            match = _ACCOUNT_ANCHOR_RE.search(raw_text)
            if match is None or not (match.group(1) or _account_heading_fields(raw_text)):
                continue
            bbox = _account_evidence_bbox(line)
            if bbox is None:
                continue
            anchor_top = bbox[1]
            if current_logical_page == candidate_logical_page:
                if current_table_top + 1.0 < anchor_top <= candidate_table_top + 1.0:
                    return True
                continue
            if (logical_page == current_logical_page and anchor_top > current_table_top + 1.0) or (
                logical_page == candidate_logical_page and anchor_top <= candidate_table_top + 1.0
            ):
                return True
    return False


def _geometric_prior_account_continuation(
    *,
    parse_result: Any,
    page: Any,
    table: Any,
    page_tables: list[Any],
    current_logical_page: int,
    current_table_top: float | None,
    rows: list[list[str]],
    pending_labels: list[str] | None,
    cross_page_order_resolved: bool,
) -> bool:
    """Authorize the unique prior-account interval around a split table.

    On the same logical page, a secondary account table below the current body
    remains inside that body's interval.  At a logical-page boundary, a
    secondary table can belong to the prior account only when it is
    geometrically above the next canonical account body.  Page adjacency or a
    footer alone is never sufficient.
    """

    if not _account_continuation_fragment(rows, pending_labels):
        return False
    top = _table_top_value(table)
    logical_page = int(getattr(page, "page_number", 0) or 0)
    if top is None or not logical_page or not current_logical_page:
        return False
    if _exact_account_anchor_boundary_between(
        parse_result,
        current_logical_page=current_logical_page,
        current_table_top=current_table_top if current_table_top is not None else top,
        candidate_logical_page=logical_page,
        candidate_table_top=top,
    ):
        return False
    if logical_page == current_logical_page:
        return current_table_top is not None and top + 1.0 >= current_table_top
    if not (
        cross_page_order_resolved
        and _registered_account_pages_are_adjacent(
            parse_result,
            current_logical_page,
            logical_page,
        )
    ):
        return False
    next_body_tops = [
        candidate_top
        for candidate in page_tables
        if candidate is not table
        and _account_base(_table_rows(candidate))
        and (candidate_top := _table_top_value(candidate)) is not None
        and candidate_top > top
    ]
    return bool(next_body_tops and top < min(next_body_tops))


_ACCOUNT_EVENT_DATASETS = {
    "special_transaction": "credit_account_special_transactions",
    "large_installment": "credit_card_large_installments",
    "latest_repayment": "credit_account_latest_repayments",
    "special_event_note": "credit_account_special_events",
}


def _account_event_type(row: list[str]) -> str | None:
    compact = _compact("".join(row))
    if "特殊交易类型" in compact:
        return "special_transaction"
    if "大额专项分期额度" in compact:
        return "large_installment"
    if "还款日期" in compact and "还款金额" in compact and "当前还款状态" in compact:
        return "latest_repayment"
    if "特殊事件说明" in compact:
        return "special_event_note"
    return None


def _large_installment_tail_header(row: list[str]) -> bool:
    compact = _compact("".join(row))
    return all(label in compact for label in ("分期额度到期日期", "已用分期金额"))


def _account_event_continuation_value_index(rows: list[list[str]]) -> int | None:
    """Return the first value row that can consume a pending typed event header."""

    for row_index, row in enumerate(rows):
        if not _nonempty(row):
            continue
        if _account_event_type(row) is not None or _label_row(row):
            return None
        return row_index
    return None


def _report_pending_account_event_unresolved(
    issue_owner: Any,
    pending: Mapping[str, Any],
    *,
    boundary: str,
    candidate_table: Any | None = None,
) -> None:
    from docmirror.plugins.credit_report.personal_detail_scanned.extraction_issues import (
        make_issue,
        record_issue,
    )

    event_type = str(pending.get("event_type") or "")
    account_id = str(pending.get("account_id") or "")
    page = pending.get("page")
    table = pending.get("table")
    row_index = int(pending.get("row_index") or 0)
    record_issue(
        issue_owner,
        make_issue(
            category="page_continuation",
            issue_code="candidate_b_account_event_continuation_unresolved",
            message=(
                "A canonical account-event header ended an account fragment, but no affirmatively owned "
                "continuation supplied its value row; the event was withheld."
            ),
            parser_stage="candidate_b_account_event_continuation",
            target_dataset=_ACCOUNT_EVENT_DATASETS.get(event_type, "personal_detail_account_events"),
            target_record_id=str(
                (pending.get("target_event") or {}).get("account_event_id")
                or stable_record_id(
                    "personal_detail_account_event",
                    account_id,
                    event_type,
                    int(getattr(page, "page_number", 0) or 0),
                    row_index,
                )
            ),
            observed_value={
                "event_type": event_type,
                "header": list(pending.get("row") or ()),
                "boundary": boundary,
                **(
                    {"candidate_table_id": str(getattr(candidate_table, "table_id", "") or "")}
                    if candidate_table is not None
                    else {}
                ),
            },
            source_refs=(_source_ref(page, table, row=row_index),),
            reason_codes=(
                "canonical_event_header_at_fragment_end",
                "continuation_value_not_affirmatively_owned",
                "event_record_withheld",
                "dataset_incomplete",
            ),
        ),
    )


_SPECIAL_TRANSACTION_TYPE_RE = re.compile(
    r"^(?:"
    r"提前结清|"
    r"提前还款(?:[（(](?:全部|部分)[)）])?|"
    r"展期(?:[（(]延期[)）])?|"
    r"延期|"
    r"担保人代还|"
    r"以资抵债|"
    r"其他"
    r")(?:[,，]变更月数[-－—]?\d+个月)?$"
)


def _special_transaction_type(raw: Any) -> str | None:
    """Return a source-observed value only when it matches the finite PBOC grammar.

    Unknown text stays unresolved and is reported from its exact source cell.
    This is intentionally a positive contract: accepting every value except a
    previously observed OCR typo would merely move the silent error to the next
    document that contains a different typo.
    """

    value = _clean(raw)
    compact = _compact(value)
    if not compact or _SPECIAL_TRANSACTION_TYPE_RE.fullmatch(compact) is None:
        return None
    return value


def _account_events(
    issue_owner: Any,
    account: dict[str, Any],
    page: Any,
    table: Any,
    rows: list[list[str]],
    *,
    leading_header: Mapping[str, Any] | None = None,
    leading_value_row_index: int = 0,
    defer_trailing_large_installment_tail: bool = False,
) -> list[dict[str, Any]]:
    from docmirror.plugins.credit_report.personal_detail_scanned.extraction_issues import (
        make_issue,
        record_issue,
    )

    scoped_rows: list[tuple[list[str], Any, Any, int]] = []
    if leading_header is not None:
        scoped_rows.append(
            (
                list(leading_header.get("row") or ()),
                leading_header.get("page"),
                leading_header.get("table"),
                int(leading_header.get("row_index") or 0),
            )
        )
    scoped_rows.extend(
        (row, page, table, row_index)
        for row_index, row in enumerate(rows)
        if leading_header is None or row_index >= leading_value_row_index
    )

    def scoped_ref(index: int, column: int | None = None) -> dict[str, Any]:
        _row, source_page, source_table, source_row = scoped_rows[index]
        return _source_ref(source_page, source_table, row=source_row, column=column)

    events: list[dict[str, Any]] = []
    for row_index, (row, header_page, header_table, header_row_index) in enumerate(scoped_rows):
        event_type = _account_event_type(row)
        if event_type is None or row_index + 1 >= len(scoped_rows):
            continue
        target_dataset = _ACCOUNT_EVENT_DATASETS[event_type]
        value_row = scoped_rows[row_index + 1][0]
        page_number = int(getattr(header_page, "page_number", 0) or 0)
        event_id = stable_record_id(
            "personal_detail_account_event",
            account.get("account_id"),
            event_type,
            page_number,
            header_row_index,
        )
        record: dict[str, Any] = {
            "record_id": event_id,
            "account_event_id": event_id,
            "account_id": account.get("account_id"),
            "_table_observation_instance_id": account.get("_table_observation_instance_id"),
            "event_type": event_type,
            "source": "native_personal_detail_account_event",
            "source_refs": [scoped_ref(row_index)],
            "source_refs_by_field": {},
            "canonical_raw": {},
            "confidence": min(
                float(getattr(header_table, "confidence", None) or 0.9),
                float(getattr(scoped_rows[row_index + 1][2], "confidence", None) or 0.9),
            ),
        }
        observations, unresolved_slots = _exact_label_observations([row, value_row])
        cluster_decoded = None
        cluster_raw = ""
        cluster_value_rows: dict[str, tuple[int, int | None]] = {}
        if event_type in {"special_transaction", "large_installment"}:
            kind = event_type
            fragments = [f"{_clean(' '.join(row))} {_clean(' '.join(value_row))}"]
            first_value_cell = _single_business_cell(value_row)
            for field_name in (
                ("transaction_type", "event_date", "changed_months", "amount", "details")
                if event_type == "special_transaction"
                else ("installment_limit", "effective_date")
            ):
                cluster_value_rows[field_name] = (
                    row_index + 1,
                    first_value_cell[0] if first_value_cell is not None else None,
                )
            if event_type == "large_installment" and row_index + 3 < len(scoped_rows):
                second_header = _compact("".join(scoped_rows[row_index + 2][0]))
                if all(label in second_header for label in ("分期额度到期日期", "已用分期金额")):
                    second_value = scoped_rows[row_index + 3][0]
                    fragments.append(
                        f"{_clean(' '.join(scoped_rows[row_index + 2][0]))} {_clean(' '.join(second_value))}"
                    )
                    second_value_cell = _single_business_cell(second_value)
                    for field_name in ("expiry_date", "used_installment_amount"):
                        cluster_value_rows[field_name] = (
                            row_index + 3,
                            second_value_cell[0] if second_value_cell is not None else None,
                        )
            cluster_decoded = decode_labeled_cluster(
                tuple(fragments),
                kind=kind,
            )
            cluster_raw = " | ".join(fragments)

        def bind_cluster(field_name: str) -> bool:
            if cluster_decoded is None or field_name not in cluster_decoded.fields:
                return False
            value = cluster_decoded.fields[field_name]
            if field_name == "transaction_type":
                value = _special_transaction_type(value)
                if value is None:
                    return False
            source_row, source_column = cluster_value_rows.get(field_name, (row_index + 1, None))
            source_ref = scoped_ref(source_row, source_column)
            source_ref["binding"] = "closed_canonical_account_event_cluster"
            source_ref["binding_quality"] = "closed_canonical_account_event_cluster"
            record[field_name] = value
            record["canonical_raw"][field_name] = cluster_raw
            record["source_refs_by_field"].setdefault(field_name, []).append({**source_ref, "field_name": field_name})
            return True

        def bind_exact(field_name: str, label: str, converter: Any) -> None:
            candidates = observations.get(label) or []
            distinct = {_compact(raw) for raw, _physical_row, _column in candidates if _compact(raw)}
            if len(distinct) != 1:
                if bind_cluster(field_name):
                    return
                record_issue(
                    issue_owner,
                    make_issue(
                        category="ocr_structure_correction",
                        issue_code="candidate_b_account_event_slot_unresolved",
                        message=(
                            "A canonical account-event field was missing or ambiguous; no adjacent value "
                            "was shifted into the slot."
                        ),
                        parser_stage="candidate_b_account_event_canonical_slots",
                        target_dataset=target_dataset,
                        target_record_id=event_id,
                        field_name=field_name,
                        observed_value={
                            "label": label,
                            "candidate_values": [raw for raw, _physical_row, _column in candidates],
                        },
                        source_refs=(scoped_ref(row_index),),
                        reason_codes=(
                            "canonical_event_label_observed",
                            "exact_value_slot_unresolved",
                            "positional_fallback_forbidden",
                            "normalized_value_withheld",
                        ),
                    ),
                )
                _append_internal_field(record, "_unresolved_fields", field_name)
                return
            raw, physical_row, column = candidates[0]
            source_ref = scoped_ref(row_index + physical_row, column)
            if _compact(raw) in {"-", "--"}:
                _mark_source_absent(record, field_name, raw)
                record["source_refs_by_field"].setdefault(field_name, []).append(
                    {**source_ref, "field_name": field_name}
                )
                return
            value = converter(raw)
            if value in (None, ""):
                # An exact transaction-type cell that fails the bounded field
                # contract must not be replaced from the same OCR cluster.  The
                # exact cell is the authoritative observation and is retained as
                # localized issue evidence below.
                if field_name != "transaction_type" and bind_cluster(field_name):
                    return
                _reject_exact_observation(
                    issue_owner,
                    record,
                    dataset=target_dataset,
                    target_record_id=event_id,
                    field_name=field_name,
                    raw=raw,
                    source_ref=source_ref,
                    parser_stage="candidate_b_account_event_canonical_slots",
                )
                return
            record[field_name] = value
            record["canonical_raw"][field_name] = raw
            record["source_refs_by_field"].setdefault(field_name, []).append({**source_ref, "field_name": field_name})

        field_contracts: dict[str, tuple[tuple[str, str, Any], ...]] = {
            "special_transaction": (
                ("transaction_type", "特殊交易类型", _special_transaction_type),
                ("event_date", "发生日期", _date),
                ("changed_months", "变更月数", _number),
                ("amount", "发生金额", _number),
                ("details", "明细记录", _clean),
            ),
            "large_installment": (
                ("installment_limit", "大额专项分期额度", _number),
                ("effective_date", "分期额度生效日期", _date),
                ("expiry_date", "分期额度到期日期", _date),
                ("used_installment_amount", "已用分期金额", _number),
            ),
            "latest_repayment": (
                ("five_tier_class", "五级分类", _clean),
                ("balance", "余额", _number),
                ("repayment_date", "还款日期", _date),
                ("repayment_amount", "还款金额", _number),
                ("repayment_status", "当前还款状态", _clean),
            ),
            "special_event_note": (("details", "特殊事件说明", _clean),),
        }
        for field_name, label, converter in field_contracts[event_type]:
            if (
                defer_trailing_large_installment_tail
                and event_type == "large_installment"
                and field_name in {"expiry_date", "used_installment_amount"}
                and _large_installment_tail_header(scoped_rows[-1][0])
            ):
                continue
            bind_exact(field_name, label, converter)
        # Keep the observed row even when one slot failed: the normalized
        # omissions are linked to explicit issues and the source record count
        # remains conserved.
        if unresolved_slots:
            record.setdefault("_unresolved_source_slots", []).extend(
                sorted({label for label, _row, _column in unresolved_slots})
            )
        events.append(record)
    return events


def _consume_pending_large_installment_tail(
    issue_owner: Any,
    pending: Mapping[str, Any],
    *,
    page: Any,
    table: Any,
    rows: list[list[str]],
    value_row_index: int,
) -> None:
    """Bind the second large-installment pair to its already materialized event."""

    event = pending.get("target_event")
    if not isinstance(event, dict):
        _report_pending_account_event_unresolved(
            issue_owner,
            pending,
            boundary="large_installment_tail_without_primary_event",
            candidate_table=table,
        )
        return
    header = list(pending.get("row") or ())
    value_row = rows[value_row_index]
    observations, _unresolved = _exact_label_observations([header, value_row])
    event_id = str(event.get("account_event_id") or event.get("record_id") or "")
    target_dataset = _ACCOUNT_EVENT_DATASETS["large_installment"]
    for field_name, label, converter in (
        ("expiry_date", "分期额度到期日期", _date),
        ("used_installment_amount", "已用分期金额", _number),
    ):
        candidates = observations.get(label) or []
        distinct = {_compact(raw) for raw, _row, _column in candidates if _compact(raw)}
        if len(distinct) != 1:
            _reject_exact_observation(
                issue_owner,
                event,
                dataset=target_dataset,
                target_record_id=event_id,
                field_name=field_name,
                raw="",
                source_ref=_source_ref(
                    pending.get("page"),
                    pending.get("table"),
                    row=int(pending.get("row_index") or 0),
                ),
                parser_stage="candidate_b_account_event_continuation",
            )
            continue
        raw, _physical_row, column = candidates[0]
        value = converter(raw)
        valid = value not in (None, "")
        if converter is _number:
            valid = isinstance(value, int) and not isinstance(value, bool)
        if not valid:
            _reject_exact_observation(
                issue_owner,
                event,
                dataset=target_dataset,
                target_record_id=event_id,
                field_name=field_name,
                raw=raw,
                source_ref=_source_ref(page, table, row=value_row_index, column=column),
                parser_stage="candidate_b_account_event_continuation",
            )
            continue
        event[field_name] = value
        event.setdefault("canonical_raw", {})[field_name] = raw
        value_ref = _source_ref(page, table, row=value_row_index, column=column)
        event.setdefault("source_refs_by_field", {}).setdefault(field_name, []).append(
            {**value_ref, "field_name": field_name}
        )
    for ref in (
        _source_ref(
            pending.get("page"),
            pending.get("table"),
            row=int(pending.get("row_index") or 0),
        ),
        _source_ref(page, table, row=value_row_index),
    ):
        if ref not in event.setdefault("source_refs", []):
            event["source_refs"].append(ref)


def _registered_account_pages_are_adjacent(
    parse_result: Any,
    left_logical_page: int,
    right_logical_page: int,
) -> bool:
    """Require exact adjacency in the already-validated reading-order plane."""

    registered_resolution = getattr(parse_result, "reading_order_resolution", None)
    if hasattr(parse_result, "reading_order_resolution") and not (
        isinstance(registered_resolution, Mapping)
        and registered_resolution.get("resolved") is True
        and registered_resolution.get("authoritative") is True
    ):
        return False
    raw_order = getattr(parse_result, "reading_order_by_logical", None)
    if raw_order is None:
        # Sealed unit/legacy contexts predate the document order plane.  Their
        # only cross-page contract is the immediate logical edge; an explicit
        # plane below always takes the stricter complete/unique path.
        return bool(
            not hasattr(parse_result, "reading_order_by_logical")
            and not hasattr(parse_result, "reading_order_resolution")
            and int(left_logical_page or 0) > 0
            and int(right_logical_page or 0) == int(left_logical_page or 0) + 1
        )
    if not isinstance(raw_order, Mapping):
        return False
    normalized: dict[int, int] = {}
    for raw_logical, raw_position in raw_order.items():
        try:
            logical = int(raw_logical)
            position = int(raw_position)
        except (TypeError, ValueError):
            return False
        if logical <= 0 or position <= 0:
            return False
        normalized[logical] = position
    positions = list(normalized.values())
    if len(positions) != len(set(positions)):
        return False
    left = normalized.get(int(left_logical_page or 0))
    right = normalized.get(int(right_logical_page or 0))
    return bool(left is not None and right == left + 1)


def _bounded_card_credit_limit(value: Any) -> tuple[int, str] | None:
    """Return one money token with at most one trailing Han OCR glyph."""

    raw = _clean(value)
    tokens = list(dict.fromkeys(re.findall(r"(?<![A-Za-z0-9])\d[\d,]*(?![A-Za-z0-9])", raw)))
    if len(tokens) != 1:
        return None
    parsed = _number(tokens[0])
    if not isinstance(parsed, int) or isinstance(parsed, bool) or parsed < 0:
        return None
    residue = _account_cluster_residue(raw, (tokens[0],))
    if residue and re.fullmatch(r"[\u3400-\u9fff]", residue) is None:
        return None
    return parsed, residue


def _bounded_headerless_card_values(
    pending_labels: list[str] | None,
    rows: list[list[str]],
) -> dict[str, Any] | None:
    """Decode the one complete card header followed by one exact value row.

    This is an ownership proof, not a general account decoder. All canonical
    card-header labels must be present once and in template order, and the six
    identity-bearing cells used below must independently satisfy their finite
    contracts. Weak, collapsed, or repayment-only rows therefore fail closed.
    """

    if not pending_labels or not rows:
        return None
    nonempty_columns: list[tuple[int, str]] = [
        (column, _compact(cell)) for column, cell in enumerate(pending_labels) if _compact(cell)
    ]
    roles = [_ACCOUNT_BASIC_HEADER_ROLES.get(label) for _column, label in nonempty_columns]
    if any(role is None for role in roles):
        return None
    if tuple(roles) != _ACCOUNT_BASIC_CARD_TEMPLATE:
        return None
    columns = {str(role): column for (column, _label), role in zip(nonempty_columns, roles, strict=True)}
    body = rows[0]
    if max(columns.values(), default=-1) >= len(body):
        return None

    raw_institution = _clean(body[columns["management_institution"]])
    raw_identifier = _clean(body[columns["account_identifier"]])
    raw_open_date = _clean(body[columns["open_date"]])
    raw_limit = _clean(body[columns["credit_limit"]])
    raw_currency = _clean(body[columns["currency"]])
    raw_business_type = _clean(body[columns["business_type"]])
    raw_guarantee_type = _clean(body[columns["guarantee_type"]])
    institution = _exact_source_account_institution(raw_institution)
    identifier = _canonical_pboc_account_identifier(raw_identifier)
    open_date = _date(raw_open_date)
    bounded_limit = _bounded_card_credit_limit(raw_limit)
    credit_limit = bounded_limit[0] if bounded_limit is not None else None
    credit_limit_residue = bounded_limit[1] if bounded_limit is not None else ""
    currency, _currency_residue, currency_resolution = _currency_token(raw_currency)
    business_type = normalize_pboc_field(
        _business_text(raw_business_type),
        "account_business_type",
    )
    guarantee_type = normalize_pboc_field(
        _business_text(raw_guarantee_type),
        "guarantee_type",
    )
    guarantee_valid = (
        bool(guarantee_type)
        and validate_pboc_field(
            guarantee_type,
            "guarantee_type",
        ).valid
    )
    if (
        not institution
        or not identifier
        or open_date is None
        or not isinstance(credit_limit, int)
        or isinstance(credit_limit, bool)
        or credit_limit < 0
        or currency is None
        or currency_resolution != "exact"
        or not business_type
        or not validate_pboc_field(business_type, "account_business_type").valid
    ):
        return None
    result = {
        "management_institution": institution,
        "account_identifier": identifier,
        "open_date": open_date,
        "credit_limit": credit_limit,
        "currency": currency,
        "business_type": business_type,
        "_credit_limit_residue": credit_limit_residue,
    }
    if guarantee_valid:
        result["guarantee_type"] = guarantee_type
    return result


_EXACT_CARD_HEADER_COLUMNS = (0, 2, 4, 5, 7, 8, 10, 12)


def _card_header_template_labels(labels: list[str] | None) -> list[str] | None:
    if not labels:
        return None
    nonempty = [(column, _compact(value)) for column, value in enumerate(labels) if _compact(value)]
    roles = [_ACCOUNT_BASIC_HEADER_ROLES.get(value) for _column, value in nonempty]
    if tuple(roles) != _ACCOUNT_BASIC_CARD_TEMPLATE:
        return None
    return list(labels)


def _strict_pdf_card_lattice(
    table: Any,
) -> dict[str, Any] | None:
    """Return one complete 13-column PDF lattice bounded by its table box."""

    geometry = _native_table_geometry(table)
    table_bbox = _exact_geometry_bbox(getattr(table, "bbox", None))
    if geometry is None or geometry.get("coordinate_system") != "pdf_points_top_left" or table_bbox is None:
        return None
    column_bands = _indexed_geometry_bands(
        geometry,
        "col_bands",
        lower_key="x0",
        upper_key="x1",
    )
    row_bands = _indexed_geometry_bands(
        geometry,
        "row_bands",
        lower_key="y0",
        upper_key="y1",
    )
    if (
        column_bands is None
        or set(column_bands) != set(range(13))
        or row_bands is None
        or set(row_bands) != set(range(len(row_bands)))
        or not row_bands
    ):
        return None
    if any(abs(column_bands[index][1] - column_bands[index + 1][0]) > 1e-6 for index in range(12)) or any(
        abs(row_bands[index][1] - row_bands[index + 1][0]) > 1e-6 for index in range(len(row_bands) - 1)
    ):
        return None
    lattice_bbox = (
        column_bands[0][0],
        row_bands[0][0],
        column_bands[12][1],
        row_bands[len(row_bands) - 1][1],
    )
    if any(abs(observed - expected) > 1.0 for observed, expected in zip(table_bbox, lattice_bbox, strict=True)):
        return None
    cell_bboxes = geometry.get("cell_bboxes")
    cell_status = geometry.get("cell_geometry_status")
    cell_evidence_ids = geometry.get("cell_evidence_ids")
    if not all(
        isinstance(grid, list) and len(grid) == len(row_bands) for grid in (cell_bboxes, cell_status, cell_evidence_ids)
    ):
        return None
    if any(
        not isinstance(grid[row], list) or len(grid[row]) != 13
        for grid in (cell_bboxes, cell_status, cell_evidence_ids)
        for row in range(len(row_bands))
    ):
        return None
    raw_spans = geometry.get("cell_spans")
    if not isinstance(raw_spans, list):
        return None
    spans: list[tuple[int, int, int, int]] = []
    for raw_span in raw_spans:
        if not isinstance(raw_span, Mapping):
            return None
        values = tuple(raw_span.get(key) for key in ("row", "col", "row_span", "col_span"))
        if any(not isinstance(value, int) or isinstance(value, bool) for value in values):
            return None
        span_row, span_column, row_span, column_span = values
        if (
            span_row < 0
            or span_column < 0
            or row_span <= 0
            or column_span <= 0
            or span_row + row_span > len(row_bands)
            or span_column + column_span > 13
        ):
            return None
        declared_bbox = _exact_geometry_bbox(raw_span.get("bbox"))
        if raw_span.get("bbox") is not None:
            expected_bbox = (
                column_bands[span_column][0],
                row_bands[span_row][0],
                column_bands[span_column + column_span - 1][1],
                row_bands[span_row + row_span - 1][1],
            )
            if declared_bbox is None or any(
                abs(observed - expected) > 1.0 for observed, expected in zip(declared_bbox, expected_bbox, strict=True)
            ):
                return None
        spans.append((span_row, span_column, row_span, column_span))
    return {
        "geometry": geometry,
        "table_bbox": table_bbox,
        "column_bands": column_bands,
        "row_bands": row_bands,
        "cell_bboxes": cell_bboxes,
        "cell_status": cell_status,
        "cell_evidence_ids": cell_evidence_ids,
        "spans": tuple(spans),
    }


def _strict_card_lattice_cell(
    lattice: Mapping[str, Any],
    *,
    row: int,
    column: int,
    evidence_required: bool,
) -> tuple[tuple[float, float, float, float], tuple[str, ...]] | None:
    row_bands = lattice["row_bands"]
    column_bands = lattice["column_bands"]
    if row not in row_bands or column not in column_bands:
        return None
    for span_row, span_column, row_span, column_span in lattice["spans"]:
        if span_row <= row < span_row + row_span and span_column <= column < span_column + column_span:
            return None
    status = lattice["cell_status"][row][column]
    bbox = _exact_geometry_bbox(lattice["cell_bboxes"][row][column])
    evidence_ids = lattice["cell_evidence_ids"][row][column]
    if status != "exact" or bbox is None or not isinstance(evidence_ids, list):
        return None
    expected_bbox = (
        column_bands[column][0],
        row_bands[row][0],
        column_bands[column][1],
        row_bands[row][1],
    )
    if any(abs(observed - expected) > 1.0 for observed, expected in zip(bbox, expected_bbox, strict=True)):
        return None
    normalized_evidence = tuple(dict.fromkeys(str(value) for value in evidence_ids if str(value or "")))
    if evidence_required and not normalized_evidence:
        return None
    return bbox, normalized_evidence


def _card_lattice_physical_signature(
    lattice: Mapping[str, Any],
) -> tuple[Any, ...]:
    geometry = lattice["geometry"]
    return (
        tuple(lattice["table_bbox"]),
        tuple(sorted(lattice["column_bands"].items())),
        tuple(sorted(lattice["row_bands"].items())),
        json.dumps(
            {
                "cell_bboxes": geometry.get("cell_bboxes"),
                "cell_geometry_status": geometry.get("cell_geometry_status"),
                # The strict parser has already normalized and validated every
                # span.  Raw scanner order and an optional redundant span bbox
                # must not let the same physical table evade duplicate
                # detection.
                "cell_spans": tuple(sorted(tuple(span) for span in lattice["spans"])),
            },
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        ),
    )


def _card_lattice_regions_compete(
    left: Mapping[str, Any],
    right: Mapping[str, Any],
) -> bool:
    """Reject two strict table claims occupying the same physical region."""

    left_bbox = left["table_bbox"]
    right_bbox = right["table_bbox"]
    overlap_width = max(
        0.0,
        min(left_bbox[2], right_bbox[2]) - max(left_bbox[0], right_bbox[0]),
    )
    overlap_height = max(
        0.0,
        min(left_bbox[3], right_bbox[3]) - max(left_bbox[1], right_bbox[1]),
    )
    overlap_area = overlap_width * overlap_height
    left_area = (left_bbox[2] - left_bbox[0]) * (left_bbox[3] - left_bbox[1])
    right_area = (right_bbox[2] - right_bbox[0]) * (right_bbox[3] - right_bbox[1])
    return overlap_area >= 0.9 * min(left_area, right_area)


def _card_lattices_are_translation_compatible(
    prior: Mapping[str, Any],
    candidate: Mapping[str, Any],
) -> bool:
    """Prove the two 13-column partitions differ only by scan translation."""

    prior_bands = prior["column_bands"]
    candidate_bands = candidate["column_bands"]
    if tuple(prior_bands) != tuple(candidate_bands):
        return False
    prior_edges = [prior_bands[0][0], *(prior_bands[index][1] for index in range(13))]
    candidate_edges = [
        candidate_bands[0][0],
        *(candidate_bands[index][1] for index in range(13)),
    ]
    widths = [right - left for bands in (prior_bands, candidate_bands) for left, right in bands.values()]
    median_width = sorted(widths)[len(widths) // 2]
    tolerance = min(1.5, max(0.75, 0.06 * median_width))
    prior_origin = prior_edges[0]
    candidate_origin = candidate_edges[0]
    return all(
        abs((prior_edge - prior_origin) - (candidate_edge - candidate_origin)) <= tolerance
        for prior_edge, candidate_edge in zip(
            prior_edges,
            candidate_edges,
            strict=True,
        )
    )


def _unique_strict_card_table_on_page(
    parse_result: Any,
    *,
    logical_page: int,
    table_id: str,
    table: Any,
) -> dict[str, Any] | None:
    if not table_id or str(getattr(table, "table_id", "") or "") != table_id:
        return None
    pages = [
        page
        for page in getattr(parse_result, "pages", None) or ()
        if int(getattr(page, "page_number", 0) or 0) == logical_page
    ]
    if len(pages) != 1:
        return None
    page_tables = list(getattr(pages[0], "tables", None) or ())
    target_lattice = _strict_pdf_card_lattice(table)
    if target_lattice is None:
        return None
    target_signature = _card_lattice_physical_signature(target_lattice)
    id_matches = [candidate for candidate in page_tables if str(getattr(candidate, "table_id", "") or "") == table_id]
    physical_matches = []
    for candidate in page_tables:
        candidate_lattice = _strict_pdf_card_lattice(candidate)
        if candidate_lattice is not None and (
            _card_lattice_physical_signature(candidate_lattice) == target_signature
            or _card_lattice_regions_compete(candidate_lattice, target_lattice)
        ):
            physical_matches.append(candidate)
    if len(id_matches) != 1 or len(physical_matches) != 1 or id_matches[0] is not physical_matches[0]:
        return None
    return target_lattice


def _skeleton_has_exact_card_header_role(
    skeleton: Mapping[str, Any],
) -> bool:
    """Return whether the corrected-evidence plane contains any exact role."""

    for raw_line in skeleton.get("raw_detail_lines") or ():
        if not isinstance(raw_line, Mapping):
            continue
        role = _ACCOUNT_BASIC_HEADER_ROLES.get(_compact(raw_line.get("text") or ""))
        if role in _ACCOUNT_BASIC_CARD_TEMPLATE:
            return True
    return False


def _sealed_native_text_block_card_header_lines(
    parse_result: Any,
    *,
    skeleton: Mapping[str, Any],
    prior_logical_page: int,
) -> list[dict[str, Any]] | None:
    """Return one complete card header from one sealed native TextBlock plane.

    This is a bounded fallback for scans whose corrected-evidence segment has
    merged the eight independently sealed TextBlocks into non-role lines.  It
    never combines the two planes: callers may use it only when the skeleton
    contains zero exact card-header roles, and every returned role comes from
    the single registered prior-page object.
    """

    missing_sealed_owner = object()
    sealed_owner = getattr(parse_result, "parse_result", missing_sealed_owner)
    if sealed_owner is missing_sealed_owner:
        page_owner = parse_result
    elif sealed_owner is None or sealed_owner is parse_result:
        return None
    else:
        page_owner = sealed_owner
    pages = [
        page
        for page in getattr(page_owner, "pages", None) or ()
        if int(getattr(page, "page_number", 0) or 0) == int(prior_logical_page or 0)
    ]
    if len(pages) != 1:
        return None
    page = pages[0]
    source_page = getattr(page, "source_page_number", None)
    skeleton_source_page = skeleton.get("source_page")
    if (
        not isinstance(source_page, int)
        or isinstance(source_page, bool)
        or source_page <= 0
        or not isinstance(skeleton_source_page, int)
        or isinstance(skeleton_source_page, bool)
        or skeleton_source_page != source_page
    ):
        return None
    anchor_bbox = _exact_geometry_bbox(skeleton.get("bbox"))
    if anchor_bbox is None:
        return None

    candidates: list[dict[str, Any]] = []
    for block in getattr(page, "texts", None) or ():
        if isinstance(block, Mapping):
            text = str(block.get("content") or block.get("text") or "")
            raw_bbox = block.get("bbox")
            raw_evidence_ids = block.get("evidence_ids")
        else:
            text = str(getattr(block, "content", "") or getattr(block, "text", "") or "")
            raw_bbox = getattr(block, "bbox", None)
            raw_evidence_ids = getattr(block, "evidence_ids", None)
        role = _ACCOUNT_BASIC_HEADER_ROLES.get(_compact(text))
        if role not in _ACCOUNT_BASIC_CARD_TEMPLATE:
            continue
        bbox = _exact_geometry_bbox(raw_bbox)
        if bbox is None or bbox[1] + 1.0 < anchor_bbox[3] or bbox[1] > anchor_bbox[3] + 36.0:
            continue
        if not isinstance(raw_evidence_ids, (list, tuple)):
            return None
        evidence_ids = tuple(dict.fromkeys(str(value) for value in raw_evidence_ids if str(value or "")))
        if not evidence_ids:
            return None
        candidates.append(
            {
                "logical_page": int(prior_logical_page or 0),
                "source_page": source_page,
                "text": text,
                "bbox": list(bbox),
                "evidence_ids": list(evidence_ids),
                "_role": str(role),
            }
        )

    roles = [candidate["_role"] for candidate in candidates]
    if (
        len(candidates) != len(_ACCOUNT_BASIC_CARD_TEMPLATE)
        or tuple(sorted(roles)) != tuple(sorted(_ACCOUNT_BASIC_CARD_TEMPLATE))
        or any(roles.count(role) != 1 for role in _ACCOUNT_BASIC_CARD_TEMPLATE)
    ):
        return None
    seen_evidence: set[str] = set()
    for candidate in candidates:
        evidence_ids = set(candidate["evidence_ids"])
        if seen_evidence.intersection(evidence_ids):
            return None
        seen_evidence.update(evidence_ids)
        candidate.pop("_role", None)
    return candidates


def _exact_anchor_evidence_card_header(
    skeleton: Mapping[str, Any],
    *,
    prior_lattice: Mapping[str, Any],
    candidate_lattice: Mapping[str, Any],
    rows: list[list[str]],
    prior_logical_page: int,
) -> tuple[list[str], list[dict[str, Any]]] | None:
    """Carry exact header ordinals from the immediately preceding table lattice.

    A facing-page scan can translate the next table horizontally. Header labels
    printed beneath the pending anchor therefore bind to the exact preceding
    table's primitive column ordinals; only those ordinals are projected into
    the candidate value row. No value comparison or estimated translation is
    used to align the two lattices.
    """

    if (
        not rows
        or len(rows[0]) != 13
        or not _card_lattices_are_translation_compatible(
            prior_lattice,
            candidate_lattice,
        )
    ):
        return None
    anchor_bbox = _exact_geometry_bbox(skeleton.get("bbox"))
    if anchor_bbox is None:
        return None
    header_lines: list[tuple[dict[str, Any], str, tuple[float, float, float, float]]] = []
    for raw_line in skeleton.get("raw_detail_lines") or ():
        if not isinstance(raw_line, Mapping):
            continue
        if int(raw_line.get("logical_page") or 0) != int(prior_logical_page or 0):
            continue
        role = _ACCOUNT_BASIC_HEADER_ROLES.get(_compact(raw_line.get("text") or ""))
        bbox = _exact_geometry_bbox(raw_line.get("bbox"))
        evidence_ids = tuple(
            dict.fromkeys(str(value) for value in raw_line.get("evidence_ids") or () if str(value or ""))
        )
        if (
            role not in _ACCOUNT_BASIC_CARD_TEMPLATE
            or bbox is None
            or not evidence_ids
            or bbox[1] + 1.0 < anchor_bbox[3]
            or bbox[1] > anchor_bbox[3] + 36.0
        ):
            continue
        header_lines.append((dict(raw_line), str(role), bbox))
    roles = [role for _line, role, _bbox in header_lines]
    if (
        len(header_lines) != len(_ACCOUNT_BASIC_CARD_TEMPLATE)
        or tuple(sorted(roles)) != tuple(sorted(_ACCOUNT_BASIC_CARD_TEMPLATE))
        or any(roles.count(role) != 1 for role in _ACCOUNT_BASIC_CARD_TEMPLATE)
    ):
        return None
    ordered = sorted(header_lines, key=lambda item: (item[2][0] + item[2][2]) / 2.0)
    if tuple(item[1] for item in ordered) != _ACCOUNT_BASIC_CARD_TEMPLATE:
        return None
    centers_y = [(item[2][1] + item[2][3]) / 2.0 for item in ordered]
    if max(centers_y) - min(centers_y) > 18.0:
        return None

    prior_column_bands = prior_lattice["column_bands"]
    labels = ["" for _column in range(13)]
    refs: list[dict[str, Any]] = []
    projected_columns: list[int] = []
    for line, role, bbox in ordered:
        center = (bbox[0] + bbox[2]) / 2.0
        matching_columns = [column for column, (left, right) in prior_column_bands.items() if left <= center <= right]
        if len(matching_columns) != 1:
            return None
        column = matching_columns[0]
        if labels[column]:
            return None
        labels[column] = _compact(line.get("text") or "")
        projected_columns.append(column)
        if (
            _strict_card_lattice_cell(
                prior_lattice,
                row=0,
                column=column,
                # The separately printed boundary label carries the evidence
                # and binds its own centre to this exact primitive band.  The
                # preceding account table may place its unrelated header text
                # in a neighbouring primitive column,
                # so requiring prior-cell text evidence would make values from
                # the old account control ownership of the new one.
                evidence_required=False,
            )
            is None
            or _strict_card_lattice_cell(
                candidate_lattice,
                row=0,
                column=column,
                # A projected shared-limit cell may be physically exact but
                # legitimately empty.  Missing evidence is therefore allowed
                # only for that empty primitive; a populated value must carry
                # the same exact evidence proof as every other projected field.
                evidence_required=(role != "shared_credit_limit" or bool(str(rows[0][column] or "").strip())),
            )
            is None
        ):
            return None
        refs.append(
            {
                "source": "candidate_b_account_anchor_header",
                "logical_page": int(prior_logical_page or 0),
                "source_page": int(line.get("source_page") or 0),
                "bbox": list(bbox),
                "evidence_ids": list(line.get("evidence_ids") or ()),
                "field_name": role,
                "binding": "printed_anchor_exact_card_header_lattice",
            }
        )
    if tuple(projected_columns) != _EXACT_CARD_HEADER_COLUMNS:
        return None
    return labels, refs


def _printed_unique_card_anchor_skeletons(
    parse_result: Any,
    *,
    prior_logical_page: int,
) -> list[dict[str, Any]]:
    return [
        dict(skeleton)
        for skeleton in _account_anchor_skeletons(parse_result)
        if (
            str(skeleton.get("account_type") or "") in {"credit_card", "quasi_credit_card"}
            and skeleton.get("_printed_ordinal_status") == "printed_unique"
            and int(skeleton.get("page") or 0) == int(prior_logical_page or 0)
        )
    ]


def _pending_headerless_card_anchor_skeletons(
    parse_result: Any,
    *,
    current: Mapping[str, Any],
    prior_logical_page: int,
    prior_table_top: float | None,
    prior_table_bbox: tuple[float, float, float, float] | None,
) -> list[dict[str, Any]]:
    """Return printed card anchors that form a hard boundary after a table."""

    if (
        str(current.get("account_type") or "")
        not in {"credit_card", "quasi_credit_card", "card_account_unresolved"}
        or prior_table_top is None
        or prior_table_bbox is None
    ):
        return []
    candidates: list[dict[str, Any]] = []
    for skeleton in _printed_unique_card_anchor_skeletons(
        parse_result,
        prior_logical_page=prior_logical_page,
    ):
        bbox = _exact_geometry_bbox(skeleton.get("bbox"))
        if bbox is None:
            continue
        anchor_top = bbox[1]
        if anchor_top <= prior_table_top + 1.0 or anchor_top + 1.0 < prior_table_bbox[3]:
            continue
        candidates.append(dict(skeleton))
    return candidates


def _malformed_card_anchor_in_exact_family_page(
    parse_result: Any,
    *,
    logical_page: int,
) -> bool:
    """Treat an unsealed account-looking line inside an exact card section as a veto."""

    loader = getattr(parse_result, "corrected_evidence_pages", None)
    if not callable(loader):
        return False
    matching_pages = [
        page
        for page in loader()
        if isinstance(page, Mapping) and int(page.get("page") or 0) == logical_page
    ]
    if len(matching_pages) != 1:
        return bool(matching_pages)
    active_card_family = False
    for line in matching_pages[0].get("lines") or ():
        if not isinstance(line, Mapping):
            continue
        exact_family = _exact_account_detail_section_heading(line)
        if exact_family is not None:
            active_card_family = exact_family[0] in {"credit_card", "quasi_credit_card"}
            continue
        text = str(line.get("text") or line.get("content") or "")
        if _account_detail_section_end(text):
            active_card_family = False
            continue
        anchor = _ACCOUNT_ANCHOR_RE.search(text)
        if anchor is None or not active_card_family:
            continue
        if (
            not anchor.group(1)
            or _account_evidence_bbox(line) is None
            or not any(item for item in line.get("evidence_ids") or () if item)
        ):
            return True
    return False


def _bounded_headerless_card_owner(
    parse_result: Any,
    *,
    current: Mapping[str, Any],
    prior_logical_page: int,
    prior_table_top: float | None,
    prior_table_id: str,
    prior_table: Any,
    candidate_page: Any,
    candidate_table: Any,
    source_table_index: int,
    pending_labels: list[str] | None,
    rows: list[list[str]],
    prior_accounts: Iterable[Mapping[str, Any]],
    cross_page_order_resolved: bool,
) -> dict[str, Any] | None:
    """Resolve a headerless top-of-page card only from a pending exact anchor."""

    if not cross_page_order_resolved:
        return None
    if str(current.get("account_type") or "") not in {
        "credit_card",
        "quasi_credit_card",
        "card_account_unresolved",
    }:
        return None
    prior_table_bbox = _exact_geometry_bbox(getattr(prior_table, "bbox", None))
    if source_table_index != 0 or prior_table_top is None or prior_table_bbox is None:
        return None
    candidate_logical_page = int(getattr(candidate_page, "page_number", 0) or 0)
    if not _registered_account_pages_are_adjacent(
        parse_result,
        prior_logical_page,
        candidate_logical_page,
    ):
        return None
    prior_identifiers = {
        identifier
        for record in prior_accounts
        if (identifier := _canonical_pboc_account_identifier(record.get("account_identifier")))
    }
    pending_header = _card_header_template_labels(pending_labels)
    projected_lattices: tuple[dict[str, Any], dict[str, Any]] | None = None
    if pending_header is None:
        prior_owner_identifier = _canonical_pboc_account_identifier(current.get("account_identifier"))
        candidate_table_id = str(getattr(candidate_table, "table_id", "") or "")
        prior_lattice = _unique_strict_card_table_on_page(
            parse_result,
            logical_page=prior_logical_page,
            table_id=prior_table_id,
            table=prior_table,
        )
        candidate_lattice = _unique_strict_card_table_on_page(
            parse_result,
            logical_page=candidate_logical_page,
            table_id=candidate_table_id,
            table=candidate_table,
        )
        if not prior_owner_identifier or prior_lattice is None or candidate_lattice is None:
            return None
        projected_lattices = (prior_lattice, candidate_lattice)

    ownership_candidates: list[dict[str, Any]] = []
    for skeleton in _pending_headerless_card_anchor_skeletons(
        parse_result,
        current=current,
        prior_logical_page=prior_logical_page,
        prior_table_top=prior_table_top,
        prior_table_bbox=prior_table_bbox,
    ):
        header_labels = list(pending_header) if pending_header is not None else None
        header_refs: list[dict[str, Any]] = []
        ownership_basis = "pending_table_header_row"
        if header_labels is None:
            if projected_lattices is None:
                continue
            projected = _exact_anchor_evidence_card_header(
                skeleton,
                prior_lattice=projected_lattices[0],
                candidate_lattice=projected_lattices[1],
                rows=rows,
                prior_logical_page=prior_logical_page,
            )
            native_text_projection = False
            if projected is None and not _skeleton_has_exact_card_header_role(skeleton):
                native_header_lines = _sealed_native_text_block_card_header_lines(
                    parse_result,
                    skeleton=skeleton,
                    prior_logical_page=prior_logical_page,
                )
                if native_header_lines is not None:
                    projected = _exact_anchor_evidence_card_header(
                        {**skeleton, "raw_detail_lines": native_header_lines},
                        prior_lattice=projected_lattices[0],
                        candidate_lattice=projected_lattices[1],
                        rows=rows,
                        prior_logical_page=prior_logical_page,
                    )
                    native_text_projection = projected is not None
            if projected is None:
                continue
            header_labels, header_refs = projected
            if native_text_projection:
                header_refs = [
                    {
                        **ref,
                        "source": "candidate_b_account_anchor_header_native_text",
                        "binding": ("sealed_native_text_block_exact_card_header_lattice"),
                    }
                    for ref in header_refs
                ]
            ownership_basis = "printed_anchor_header_lattice"
        ownership_candidates.append(
            {
                "skeleton": skeleton,
                "header_labels": header_labels,
                "header_refs": header_refs,
                "ownership_basis": ownership_basis,
            }
        )
    if len(ownership_candidates) != 1:
        return None
    selected = ownership_candidates[0]
    strong_values = _bounded_headerless_card_values(selected["header_labels"], rows)
    if strong_values is None:
        return {
            **selected,
            "ownership_status": "values_unresolved",
            "ownership_reason": "card_value_contract_invalid",
            "strong_values": None,
        }
    strong_identifier = _canonical_pboc_account_identifier(strong_values.get("account_identifier"))
    if not strong_identifier:
        return {
            **selected,
            "ownership_status": "values_unresolved",
            "ownership_reason": "account_identifier_invalid",
            "strong_values": None,
        }
    if strong_identifier in prior_identifiers:
        return {
            **selected,
            "ownership_status": "values_conflict",
            "ownership_reason": "account_identifier_replay",
            "strong_values": None,
        }
    anchor_identifier = _account_card_identifier(selected["skeleton"])
    if anchor_identifier and anchor_identifier != strong_identifier:
        return {
            **selected,
            "ownership_status": "values_conflict",
            "ownership_reason": "anchor_identifier_conflict",
            "strong_values": None,
        }
    return {
        **selected,
        "ownership_status": "resolved",
        "strong_values": strong_values,
    }


def _extract_table_accounts(
    parse_result: Any,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]], list[dict[str, Any]]]:
    accounts: list[dict[str, Any]] = []
    repayments: list[dict[str, Any]] = []
    account_events: list[dict[str, Any]] = []
    phase = "non_revolving_loan"
    current: dict[str, Any] | None = None
    pending_labels: list[str] | None = None
    pending_label_source: tuple[Any, Any, int] | None = None
    pending_event: dict[str, Any] | None = None
    current_table_id = ""
    current_logical_page = 0
    current_table_top: float | None = None
    current_source_table: Any | None = None
    quarantined_card_boundary: dict[str, Any] | None = None
    phase_logical_page = 0
    continuation_check = getattr(parse_result, "tables_continue", None)

    def withhold_headerless_card_boundary_table(
        boundary: Mapping[str, Any],
        *,
        page: Any,
        table: Any,
        continuation: bool | None,
        ownership_status: str,
        ownership_reason: str,
    ) -> None:
        from docmirror.plugins.credit_report.personal_detail_scanned.extraction_issues import (
            make_issue,
            record_issue,
        )

        source_refs = [
            *(dict(ref) for ref in boundary.get("header_refs") or () if isinstance(ref, Mapping)),
            _source_ref(page, table),
        ]
        record_issue(
            parse_result,
            make_issue(
                category="ocr_structure_correction",
                issue_code=(
                    "candidate_b_headerless_account_value_contract_unresolved"
                    if ownership_status in {"values_unresolved", "values_conflict"}
                    else "candidate_b_headerless_account_owner_unresolved"
                ),
                message=(
                    "A table after an exact printed new-card boundary was withheld. "
                    "It was not attached to the preceding card because the new "
                    "account ownership or value contract was unresolved."
                ),
                parser_stage="candidate_b_account_table_ownership",
                target_dataset="credit_accounts",
                target_record_id=str(boundary.get("target_record_id") or "") or None,
                observed_value={
                    "prior_account_observation_id": boundary.get("prior_account_id"),
                    "prior_table_id": boundary.get("prior_table_id"),
                    "candidate_table_id": str(getattr(table, "table_id", "") or ""),
                    "continuation_decision": continuation,
                    "ownership_status": ownership_status,
                    "ownership_reason": ownership_reason,
                },
                source_refs=tuple(source_refs),
                reason_codes=(
                    "printed_new_card_boundary",
                    "prior_account_continuation_vetoed",
                    "candidate_table_withheld",
                    ownership_reason,
                ),
            ),
        )

    def flush_pending_fact_labels(boundary: str) -> None:
        nonlocal pending_labels, pending_label_source
        if current is None or pending_labels is None or pending_label_source is None:
            pending_labels = None
            pending_label_source = None
            return
        source_page, source_table, source_row_index = pending_label_source
        _apply_account_facts(
            parse_result,
            current,
            [pending_labels, []],
            page=source_page,
            table=source_table,
            physical_row_indices=[source_row_index, None],
            defer_trailing_labels=False,
        )
        current.setdefault("_terminal_unresolved_fact_boundaries", []).append(boundary)
        pending_labels = None
        pending_label_source = None

    def flush_pending_event(
        boundary: str,
        *,
        candidate_table: Any | None = None,
    ) -> None:
        nonlocal pending_event
        if pending_event is None:
            return
        _report_pending_account_event_unresolved(
            parse_result,
            pending_event,
            boundary=boundary,
            candidate_table=candidate_table,
        )
        pending_event = None

    def flush_pending_institution(boundary: str) -> None:
        if current is not None:
            _flush_pending_account_institution_observations(
                parse_result,
                current,
                boundary=boundary,
            )

    def set_trailing_pending_state(page: Any, table: Any, rows: list[list[str]]) -> None:
        nonlocal pending_labels, pending_label_source, pending_event
        trailing_event_type = _account_event_type(rows[-1]) if rows else None
        if trailing_event_type is not None:
            pending_event = {
                "event_type": trailing_event_type,
                "account_id": str(current.get("account_id") or "") if current is not None else "",
                "page": page,
                "table": table,
                "row_index": len(rows) - 1,
                "row": list(rows[-1]),
            }
            # Event headers are typed structures.  They must never also act as
            # generic account-fact headers (latest-repayment includes 余额).
            pending_labels = None
            pending_label_source = None
            return
        if rows and _large_installment_tail_header(rows[-1]):
            target_event = next(
                (
                    event
                    for event in reversed(account_events)
                    if event.get("account_id") == (current or {}).get("account_id")
                    and event.get("event_type") == "large_installment"
                    and not {
                        "expiry_date",
                        "used_installment_amount",
                    }.issubset(event)
                ),
                None,
            )
            pending_event = {
                "event_type": "large_installment",
                "event_part": "tail",
                "target_event": target_event,
                "account_id": str(current.get("account_id") or "") if current is not None else "",
                "page": page,
                "table": table,
                "row_index": len(rows) - 1,
                "row": list(rows[-1]),
            }
            pending_labels = None
            pending_label_source = None
            return
        pending_event = None
        pending_labels = rows[-1] if rows and _label_row(rows[-1]) else None
        pending_label_source = (page, table, len(rows) - 1) if pending_labels is not None else None

    account_pages = list(getattr(parse_result, "pages", None) or [])
    cross_page_order_resolved = _account_reading_order_resolution(parse_result, account_pages)[-1]
    for page_offset, page in enumerate(_account_ordered_pages(parse_result, account_pages)):
        if page_offset > 0 and not cross_page_order_resolved:
            # The sealed input order remains usable inside each page, but it
            # cannot carry entity state across a page boundary without a
            # complete, unique registered reading-order plane.
            flush_pending_event("unresolved_reading_order_page_boundary")
            flush_pending_fact_labels("unresolved_reading_order_page_boundary")
            flush_pending_institution("unresolved_reading_order_page_boundary")
            current = None
            pending_labels = None
            pending_label_source = None
            current_table_id = ""
            current_logical_page = 0
            current_table_top = None
            current_source_table = None
            phase = "non_revolving_loan"
            phase_logical_page = 0
        page_tables = list(getattr(page, "tables", None) or [])
        page_tables.sort(
            key=lambda candidate: (
                _table_top_value(candidate) is None,
                _table_top_value(candidate) or 0.0,
            )
        )
        for source_table_index, table in enumerate(page_tables):
            rows = _table_rows(table)
            if not rows:
                continue
            logical_page = int(getattr(page, "page_number", 0) or 0)
            if quarantined_card_boundary is not None:
                if logical_page != int(quarantined_card_boundary.get("candidate_logical_page") or 0):
                    quarantined_card_boundary = None
                elif _account_base(rows):
                    quarantined_card_boundary = None
                elif _other_entity_table(rows):
                    quarantined_card_boundary = None
                else:
                    withhold_headerless_card_boundary_table(
                        quarantined_card_boundary,
                        page=page,
                        table=table,
                        continuation=None,
                        ownership_status="ownership_unresolved",
                        ownership_reason="pending_new_account_table_still_unresolved",
                    )
                    continue
            compact = _compact(" ".join(cell for row in rows[:6] for cell in row))
            if _account_base(rows):
                if current is not None:
                    flush_pending_event("next_account", candidate_table=table)
                    flush_pending_fact_labels("next_account")
                    flush_pending_institution("next_account")
                if "发卡机构" in compact:
                    # Card columns prove only the shared PBOC account-card
                    # schema. They do not distinguish 贷记卡 from 准贷记卡:
                    # revisions may add, remove, or reorder columns such as
                    # 业务种类 without changing the printed account family.
                    # Keep an internal superfamily observation; an exact
                    # printed heading/typed source value must own the subtype.
                    account_type = "card_account_unresolved"
                    account_family_basis = "shared_card_table_signature"
                    phase = ""
                    phase_logical_page = 0
                elif "账户授信额度" in compact:
                    account_type = "revolving_loan_subaccount"
                    # R1 and R2 share this canonical first-row label.  The
                    # table shape therefore proves a revolving-loan account,
                    # but it does not distinguish the printed family variant.
                    account_family_basis = "shared_revolving_credit_limit_signature"
                    phase = account_type
                    phase_logical_page = int(getattr(page, "page_number", 0) or 0)
                elif phase in {"revolving_loan_subaccount", "revolving_loan_account"} and (
                    int(getattr(page, "page_number", 0) or 0) == phase_logical_page
                    or (
                        cross_page_order_resolved
                        and _registered_account_pages_are_adjacent(
                            parse_result,
                            phase_logical_page,
                            int(getattr(page, "page_number", 0) or 0),
                        )
                    )
                ):
                    account_type = "revolving_loan_account"
                    account_family_basis = "revolving_table_phase_carry"
                    phase = account_type
                    phase_logical_page = int(getattr(page, "page_number", 0) or 0)
                else:
                    account_type = "non_revolving_loan"
                    account_family_basis = "non_revolving_table_signature"
                    phase = account_type
                    phase_logical_page = int(getattr(page, "page_number", 0) or 0)

                table_ref = _source_ref(page, table)
                table_observation_id = stable_record_id(
                    "credit_account_table_observation",
                    account_type,
                    table_ref.get("logical_page"),
                    table_ref.get("source_page"),
                    table_ref.get("table_id"),
                    table_ref.get("bbox"),
                    source_table_index,
                )
                current = {
                    # A table is an observation, not an account identity.  Only
                    # a printed anchor can contribute the family ordinal.  The
                    # source-position digest stays stable when the ordinal is
                    # unreadable and cannot silently masquerade as one.
                    "account_id": table_observation_id,
                    "_table_observation_id": table_observation_id,
                    "_table_observation_instance_id": stable_record_id(
                        "credit_account_table_observation_instance",
                        table_observation_id,
                        len(accounts),
                    ),
                    "sequence": len(accounts) + 1,
                    "account_type": account_type,
                    "_table_account_family_basis": account_family_basis,
                    "source": "native_detail_account_table",
                    "source_refs": [table_ref],
                    "confidence": 1.0,
                    "canonical_raw": {},
                }
                if account_type == "card_account_unresolved":
                    capsule = _capture_exact_two_cell_card_cluster(page, table, rows)
                    if capsule is not None:
                        current["_pending_exact_two_cell_card_cluster"] = capsule
                if account_type in {"credit_card", "quasi_credit_card"}:
                    current["credit_card_type"] = account_type
                _apply_account_facts(
                    parse_result,
                    current,
                    rows,
                    page=page,
                    table=table,
                    physical_row_indices=list(range(len(rows))),
                )
                accounts.append(current)
                repayment_rows, _context = _repayment_records(page, table, rows, current)
                repayments.extend(repayment_rows)
                account_events.extend(
                    _account_events(
                        parse_result,
                        current,
                        page,
                        table,
                        rows,
                        defer_trailing_large_installment_tail=True,
                    )
                )
                set_trailing_pending_state(page, table, rows)
                current_table_id = str(getattr(table, "table_id", "") or "")
                current_logical_page = int(getattr(page, "page_number", 0) or 0)
                current_table_top = _table_top_value(table)
                current_source_table = table
                continue

            candidate_table_id = str(getattr(table, "table_id", "") or "")
            continuation = None
            if current is not None and callable(continuation_check) and current_table_id and candidate_table_id:
                continuation = continuation_check(current_table_id, candidate_table_id)

            printed_card_anchor_candidates = (
                _printed_unique_card_anchor_skeletons(
                    parse_result,
                    prior_logical_page=current_logical_page,
                )
                if (
                    current is not None
                    and str(current.get("account_type") or "")
                    in {"credit_card", "quasi_credit_card", "card_account_unresolved"}
                    and cross_page_order_resolved
                    and _registered_account_pages_are_adjacent(
                        parse_result,
                        current_logical_page,
                        logical_page,
                    )
                )
                else []
            )
            pending_headerless_card_anchors = (
                _pending_headerless_card_anchor_skeletons(
                    parse_result,
                    current=current,
                    prior_logical_page=current_logical_page,
                    prior_table_top=current_table_top,
                    prior_table_bbox=_exact_geometry_bbox(getattr(current_source_table, "bbox", None)),
                )
                if (
                    current is not None
                    and cross_page_order_resolved
                    and _registered_account_pages_are_adjacent(
                        parse_result,
                        current_logical_page,
                        logical_page,
                    )
                )
                else []
            )
            malformed_card_boundary_geometry = bool(
                (
                    printed_card_anchor_candidates
                    or _malformed_card_anchor_in_exact_family_page(
                        parse_result,
                        logical_page=current_logical_page,
                    )
                )
                and (
                    _malformed_card_anchor_in_exact_family_page(
                        parse_result,
                        logical_page=current_logical_page,
                    )
                    or
                    current_table_top is None
                    or _exact_geometry_bbox(getattr(current_source_table, "bbox", None)) is None
                    or any(
                        _exact_geometry_bbox(skeleton.get("bbox")) is None
                        for skeleton in printed_card_anchor_candidates
                    )
                )
            )
            pending_headerless_card_boundary = bool(pending_headerless_card_anchors or malformed_card_boundary_geometry)
            headerless_owner = (
                _bounded_headerless_card_owner(
                    parse_result,
                    current=current,
                    prior_logical_page=current_logical_page,
                    prior_table_top=current_table_top,
                    prior_table_id=current_table_id,
                    prior_table=current_source_table,
                    candidate_page=page,
                    candidate_table=table,
                    source_table_index=source_table_index,
                    pending_labels=pending_labels,
                    rows=rows,
                    prior_accounts=accounts,
                    cross_page_order_resolved=cross_page_order_resolved,
                )
                if current is not None and not _other_entity_table(rows)
                else None
            )
            if pending_headerless_card_boundary and (
                malformed_card_boundary_geometry
                or headerless_owner is None
                or headerless_owner.get("ownership_status") != "resolved"
            ):
                selected_skeleton = (
                    (
                        pending_headerless_card_anchors[0]
                        if (not malformed_card_boundary_geometry and len(pending_headerless_card_anchors) == 1)
                        else (
                            printed_card_anchor_candidates[0]
                            if (not malformed_card_boundary_geometry and len(printed_card_anchor_candidates) == 1)
                            else {}
                        )
                    )
                    if headerless_owner is None or malformed_card_boundary_geometry
                    else headerless_owner.get("skeleton")
                )
                boundary = {
                    "candidate_logical_page": logical_page,
                    "target_record_id": (
                        selected_skeleton.get("account_id") if isinstance(selected_skeleton, Mapping) else None
                    ),
                    "prior_account_id": current.get("account_id"),
                    "prior_table_id": current_table_id,
                    "header_refs": (
                        headerless_owner.get("header_refs") or ()
                        if (headerless_owner is not None and not malformed_card_boundary_geometry)
                        else ()
                    ),
                }
                ownership_status = str(
                    "ownership_unresolved"
                    if malformed_card_boundary_geometry
                    else ((headerless_owner or {}).get("ownership_status") or "ownership_unresolved")
                )
                ownership_reason = str(
                    "malformed_new_account_boundary_geometry"
                    if malformed_card_boundary_geometry
                    else (
                        (headerless_owner or {}).get("ownership_reason") or "new_account_geometry_contract_unresolved"
                    )
                )
                withhold_headerless_card_boundary_table(
                    boundary,
                    page=page,
                    table=table,
                    continuation=continuation,
                    ownership_status=ownership_status,
                    ownership_reason=ownership_reason,
                )
                flush_pending_event(
                    "unresolved_headerless_card_boundary",
                    candidate_table=table,
                )
                flush_pending_fact_labels("unresolved_headerless_card_boundary")
                flush_pending_institution("unresolved_headerless_card_boundary")
                current = None
                current_table_id = ""
                current_logical_page = 0
                current_table_top = None
                current_source_table = None
                quarantined_card_boundary = boundary
                continue

            if headerless_owner is not None:
                owner_skeleton = dict(headerless_owner["skeleton"])
                strong_values = dict(headerless_owner["strong_values"])
                header_labels = list(headerless_owner["header_labels"])
                header_refs = [dict(ref) for ref in headerless_owner.get("header_refs") or ()]
                ownership_basis = str(headerless_owner.get("ownership_basis") or "")
                prior_account_id = str(current.get("account_id") or "")
                header_source = pending_label_source if ownership_basis == "pending_table_header_row" else None
                flush_pending_event("next_account", candidate_table=table)
                flush_pending_institution("next_account")
                pending_labels = None
                pending_label_source = None

                account_type = str(owner_skeleton.get("account_type") or "credit_card")
                table_ref = _source_ref(page, table)
                table_observation_id = stable_record_id(
                    "credit_account_table_observation",
                    account_type,
                    table_ref.get("logical_page"),
                    table_ref.get("source_page"),
                    table_ref.get("table_id"),
                    table_ref.get("bbox"),
                    source_table_index,
                )
                current = {
                    "account_id": table_observation_id,
                    "_table_observation_id": table_observation_id,
                    "_table_observation_instance_id": stable_record_id(
                        "credit_account_table_observation_instance",
                        table_observation_id,
                        len(accounts),
                    ),
                    "_pending_anchor_account_id": str(owner_skeleton.get("account_id") or ""),
                    "sequence": len(accounts) + 1,
                    "account_type": account_type,
                    "credit_card_type": account_type,
                    "_table_account_family_basis": ("printed_card_anchor_exact_header_lattice"),
                    "source": "native_detail_account_table",
                    "source_refs": [
                        table_ref,
                        *(dict(ref) for ref in owner_skeleton.get("source_refs") or () if isinstance(ref, Mapping)),
                    ],
                    "confidence": 1.0,
                    "canonical_raw": {},
                }
                fact_rows = [list(row) for row in rows]
                credit_limit_residue = str(strong_values.pop("_credit_limit_residue", "") or "")
                credit_limit_column = next(
                    (
                        column
                        for column, label in enumerate(header_labels)
                        if _ACCOUNT_BASIC_HEADER_ROLES.get(_compact(label)) == "credit_limit"
                    ),
                    None,
                )
                raw_credit_limit = ""
                if (
                    credit_limit_residue
                    and credit_limit_column is not None
                    and fact_rows
                    and credit_limit_column < len(fact_rows[0])
                ):
                    raw_credit_limit = str(fact_rows[0][credit_limit_column])
                    fact_rows[0][credit_limit_column] = str(strong_values["credit_limit"])
                _apply_account_facts(
                    parse_result,
                    current,
                    [header_labels, *fact_rows],
                    page=page,
                    table=table,
                    physical_row_indices=[None, *range(len(rows))],
                )
                if raw_credit_limit:
                    current.setdefault("canonical_raw", {})["credit_limit"] = raw_credit_limit
                    residue_ref = _source_ref(
                        page,
                        table,
                        row=0,
                        column=int(credit_limit_column),
                    )
                    residue_ref["binding"] = "printed_anchor_exact_card_header_lattice"
                    _report_account_cluster_residue(
                        parse_result,
                        current,
                        target_record_id=table_observation_id,
                        field_names=("credit_limit",),
                        raw=raw_credit_limit,
                        residue=credit_limit_residue,
                        source_ref=residue_ref,
                    )
                accounts.append(current)
                repayment_rows, _context = _repayment_records(page, table, rows, current)
                repayments.extend(repayment_rows)
                account_events.extend(
                    _account_events(
                        parse_result,
                        current,
                        page,
                        table,
                        rows,
                        defer_trailing_large_installment_tail=True,
                    )
                )
                from docmirror.plugins.credit_report.personal_detail_scanned.extraction_issues import (
                    make_issue,
                    record_issue,
                )

                issue_refs = [
                    *(dict(ref) for ref in owner_skeleton.get("source_refs") or () if isinstance(ref, Mapping)),
                    *(
                        (
                            _source_ref(
                                header_source[0],
                                header_source[1],
                                row=int(header_source[2]),
                            ),
                        )
                        if header_source is not None
                        else ()
                    ),
                    *header_refs,
                    table_ref,
                ]
                record_issue(
                    parse_result,
                    make_issue(
                        category="ocr_structure_correction",
                        issue_code="candidate_b_headerless_account_owner_resolved",
                        message=(
                            "A complete exact card header and printed anchor assigned the "
                            "adjacent page's headerless value table to a new account."
                        ),
                        severity="info",
                        status="resolved",
                        parser_stage="candidate_b_account_table_ownership",
                        target_dataset="credit_accounts",
                        target_record_id=str(owner_skeleton.get("account_id") or "") or table_observation_id,
                        observed_value={
                            "prior_account_observation_id": prior_account_id,
                            "pending_anchor_account_id": owner_skeleton.get("account_id"),
                            "candidate_table_id": candidate_table_id,
                            "strong_identity": strong_values,
                            "ownership_basis": ownership_basis,
                        },
                        candidate_value={
                            "account_type": account_type,
                            "category_sequence": owner_skeleton.get("category_sequence"),
                        },
                        source_refs=issue_refs,
                        reason_codes=(
                            "registered_printed_pages_adjacent",
                            "complete_card_header_in_template_order",
                            "finite_card_identity_contracts",
                            "distinct_account_identifier",
                            "unique_printed_anchor",
                            ownership_basis,
                        ),
                    ),
                )
                set_trailing_pending_state(page, table, rows)
                current_table_id = candidate_table_id
                current_logical_page = logical_page
                current_table_top = _table_top_value(table)
                current_source_table = table
                continue

            geometric_prior_owner = bool(
                current is not None
                and not pending_headerless_card_boundary
                and not _other_entity_table(rows)
                and _geometric_prior_account_continuation(
                    parse_result=parse_result,
                    page=page,
                    table=table,
                    page_tables=page_tables,
                    current_logical_page=current_logical_page,
                    current_table_top=current_table_top,
                    rows=rows,
                    pending_labels=pending_labels,
                    cross_page_order_resolved=cross_page_order_resolved,
                )
            )

            # Ownership comes either from the entity graph or from the unique
            # static interval around a canonical secondary account table.  The
            # geometric path never relies on a footer or page adjacency alone.
            if (
                current is not None
                and not pending_headerless_card_boundary
                and (continuation is True or geometric_prior_owner)
                and not _other_entity_table(rows)
            ):
                continuation_values = [value for row in rows for value in _nonempty(row)]
                if (
                    len(continuation_values) == 1
                    and continuation_values[0] == "期"
                    and account_events
                    and account_events[-1].get("account_id") == current.get("account_id")
                    and str(account_events[-1].get("transaction_type") or "").endswith("分")
                ):
                    account_events[-1]["transaction_type"] = (
                        str(account_events[-1]["transaction_type"]) + continuation_values[0]
                    )
                fact_rows = ([pending_labels] if pending_labels else []) + rows
                _apply_account_facts(
                    parse_result,
                    current,
                    fact_rows,
                    page=page,
                    table=table,
                    physical_row_indices=([None] if pending_labels else []) + list(range(len(rows))),
                )
                repayment_rows, _context = _repayment_records(page, table, rows, current)
                repayments.extend(repayment_rows)
                if pending_event is not None:
                    value_row_index = _account_event_continuation_value_index(rows)
                    if value_row_index is None:
                        flush_pending_event(
                            "affirmed_continuation_without_value_row",
                            candidate_table=table,
                        )
                        account_events.extend(
                            _account_events(
                                parse_result,
                                current,
                                page,
                                table,
                                rows,
                                defer_trailing_large_installment_tail=True,
                            )
                        )
                    else:
                        if pending_event.get("event_part") == "tail":
                            _consume_pending_large_installment_tail(
                                parse_result,
                                pending_event,
                                page=page,
                                table=table,
                                rows=rows,
                                value_row_index=value_row_index,
                            )
                            account_events.extend(
                                _account_events(
                                    parse_result,
                                    current,
                                    page,
                                    table,
                                    rows,
                                    defer_trailing_large_installment_tail=True,
                                )
                            )
                        else:
                            account_events.extend(
                                _account_events(
                                    parse_result,
                                    current,
                                    page,
                                    table,
                                    rows,
                                    leading_header=pending_event,
                                    leading_value_row_index=value_row_index,
                                    defer_trailing_large_installment_tail=True,
                                )
                            )
                        pending_event = None
                else:
                    account_events.extend(
                        _account_events(
                            parse_result,
                            current,
                            page,
                            table,
                            rows,
                            defer_trailing_large_installment_tail=True,
                        )
                    )
                continuation_ref = _source_ref(page, table)
                if continuation_ref not in current.setdefault("source_refs", []):
                    current["source_refs"].append(continuation_ref)
                set_trailing_pending_state(page, table, rows)
                # These four values describe one physical table and must move
                # atomically.  Falling back member-by-member can pair a new
                # table object with the previous table's ID or top (including
                # the valid top coordinate 0.0), reopening stale ownership.
                current_table_id = candidate_table_id
                current_logical_page = logical_page
                current_table_top = _table_top_value(table)
                current_source_table = table
                continue

            if current is not None:
                compact_values = _compact(" ".join(cell for row in rows for cell in row))
                looks_like_account_fragment = (
                    any(label in compact_values for label in _ACCOUNT_LABELS)
                    or "还款记录" in compact_values
                    or "逾期金额" in compact_values
                )
                if looks_like_account_fragment and not _other_entity_table(rows):
                    from docmirror.plugins.credit_report.personal_detail_scanned.extraction_issues import (
                        make_issue,
                        record_issue,
                    )

                    record_issue(
                        parse_result,
                        make_issue(
                            category="ocr_structure_correction",
                            issue_code="candidate_b_account_table_fragment_owner_unresolved",
                            message=(
                                "An account-like table fragment was not joined because canonical continuation "
                                "ownership was not affirmatively established."
                            ),
                            parser_stage="candidate_b_account_table_ownership",
                            target_dataset="credit_accounts",
                            target_record_id=str(current.get("account_id") or "") or None,
                            source_refs=(_source_ref(page, table),),
                            observed_value={
                                "left_table_id": current_table_id,
                                "candidate_table_id": candidate_table_id,
                                "left_logical_page": current_logical_page,
                                "candidate_logical_page": logical_page,
                                "continuation_decision": continuation,
                            },
                            reason_codes=(
                                "canonical_continuation_not_verified",
                                "table_fragment_withheld",
                                "neighbour_order_not_used",
                            ),
                        ),
                    )
                    flush_pending_event("unowned_account_fragment", candidate_table=table)
                    flush_pending_fact_labels("unowned_account_fragment")
                    flush_pending_institution("unowned_account_fragment")
                    current = None
                    current_table_id = ""
                    current_logical_page = 0
                    current_table_top = None
                    current_source_table = None
                elif _other_entity_table(rows):
                    flush_pending_event("next_section", candidate_table=table)
                    flush_pending_fact_labels("next_section")
                    flush_pending_institution("next_section")
                    current = None
                    current_table_id = ""
                    current_logical_page = 0
                    current_table_top = None
                    current_source_table = None

    flush_pending_event("end_of_document")
    flush_pending_fact_labels("end_of_document")
    flush_pending_institution("end_of_document")

    account_identifiers = {str(account["account_id"]): account.get("account_identifier") for account in accounts}
    deduped: dict[tuple[str, str, int, int], dict[str, Any]] = {}
    for record in repayments:
        if not record.get("account_identifier"):
            record["account_identifier"] = account_identifiers.get(str(record["account_id"]))
        key = (
            str(record.get("_table_observation_instance_id") or ""),
            str(record["account_id"]),
            int(record["year"]),
            int(record["month"]),
        )
        deduped[key] = record
    for account in accounts:
        account.pop("_repayment_context", None)
    return accounts, list(deduped.values()), account_events


