_PUBLIC_LAYOUT_LABELS = frozenset(
    str(alias)
    for layout in _PUBLIC_CANONICAL_LAYOUTS
    for aliases in layout["aliases"].values()
    for alias in aliases
    if alias
)
_PUBLIC_TYPED_INSTITUTION_RE = re.compile(
    r"(?:人民法院|法院|税务局|管理局|监管局|管理中心|"
    r"住房公积金管理中心|银行(?:股份)?有限公司|有限公司)"
)
_PUBLIC_TYPED_AMOUNT_RE = re.compile(
    r"(?:[\uffe5¥] *-?\d[\d,]*(?:\.\d{1,2})?|"
    r"-?\d[\d,]*(?:\.\d{1,2})? *(?:元|%))"
)
_PUBLIC_ISSUE_ONLY_SECTION_HEADERS: Mapping[str, str] = {
    "社会救助记录": "social_assistance_records",
    "低保救助记录": "social_assistance_records",
    "低收入家庭救助记录": "social_assistance_records",
}
_PUBLIC_LEGAL_IDENTIFIER_RE = re.compile(
    r"[A-Za-z0-9\u3400-\u9fff（）()〔〕【】\[\]{}〈〉《》._/\-—]+"
)
_PUBLIC_YEAR_BRACKET = (
    r"(?:\((?:19|20)\d{2}\)|（(?:19|20)\d{2}）|"
    r"〔(?:19|20)\d{2}〕|【(?:19|20)\d{2}】|\[(?:19|20)\d{2}\])"
)
_PUBLIC_CASE_NUMBER_RE = re.compile(
    rf"{_PUBLIC_YEAR_BRACKET}[A-Za-z0-9\u3400-\u9fff._/\-—]{{2,60}}号"
)
_PUBLIC_CASE_TYPE_MARKERS = frozenset(
    {
        "民初",
        "民终",
        "民申",
        "民再",
        "刑初",
        "刑终",
        "行初",
        "行终",
        "执",
        "执恢",
        "执保",
        "破",
        "清申",
        "赔",
        "知民初",
        "知民终",
    }
)
_PUBLIC_DOCUMENT_NUMBER_RE = re.compile(
    rf"[A-Za-z0-9\u3400-\u9fff._/\-—]{{1,40}}{_PUBLIC_YEAR_BRACKET}"
    r"[A-Za-z0-9\u3400-\u9fff._/\-—]{1,40}号"
)


def _public_text_slot_is_unambiguous(raw: str) -> bool:
    """Reject text cells that visibly contain another canonical slot."""

    compact = _compact(raw)
    if not compact:
        return False
    if any(label in compact for label in _PUBLIC_LAYOUT_LABELS):
        return False
    typed_markers = len(_valid_date_spans(compact))
    typed_markers += len(_PUBLIC_TYPED_INSTITUTION_RE.findall(compact))
    typed_markers += len(_PUBLIC_TYPED_AMOUNT_RE.findall(compact))
    return typed_markers < 2


def _strict_public_integer(raw: str) -> int | None:
    """Parse one complete integer cell without concatenating malformed groups."""

    text = str(raw or "").strip()
    if re.fullmatch(r"-?\d+", text):
        return int(text)
    if re.fullmatch(r"-?\d{1,3}(?:,\d{3})+", text):
        return int(text.replace(",", ""))
    return None


def _strict_whole_cell_business_name(raw: str, role: str) -> str | None:
    """Validate a complete business-name cell without deleting source glyphs."""

    from docmirror.plugins.credit_report.personal_detail_scanned.ocr_correction import (
        institution_name_has_separated_leading_han,
        normalize_role_candidate,
        role_candidate_is_valid,
    )

    cleaned = _clean(raw)
    compact = _compact(cleaned)
    if not compact or institution_name_has_separated_leading_han(cleaned):
        return None
    normalized = _compact(normalize_role_candidate(cleaned, role))
    if normalized != compact:
        # A deterministic normalizer may identify likely acquisition debris,
        # but text alone cannot prove which glyphs should be deleted.  Keep the
        # full observation in an issue rather than publishing a shorter name.
        return None
    return compact if role_candidate_is_valid(compact, role) else None


def _strict_public_identifier(raw: str, kind: str) -> str | None:
    """Validate one complete printed identifier without mining a substring."""

    cleaned = _clean(raw)
    compact = _compact(cleaned)
    if not compact or cleaned != compact:
        return None
    if any(label in compact for label in _PUBLIC_LAYOUT_LABELS):
        return None
    if kind == "taxpayer_identifier":
        return (
            compact
            if re.fullmatch(r"[0-9A-Z]{12,25}", compact)
            and any(character.isdigit() for character in compact)
            and len(set(compact)) > 1
            else None
        )
    if kind == "case_number":
        return (
            compact
            if _PUBLIC_CASE_NUMBER_RE.fullmatch(compact)
            and any(marker in compact for marker in _PUBLIC_CASE_TYPE_MARKERS)
            else None
        )
    if kind == "document_number":
        return compact if _PUBLIC_DOCUMENT_NUMBER_RE.fullmatch(compact) else None
    return None


def _public_value(raw: str, kind: str) -> Any:
    if kind == "number":
        return _strict_public_integer(raw)
    if kind == "date":
        return _date(raw)
    if kind == "employer_name":
        return _strict_whole_cell_business_name(raw, "employer_name")
    if kind in {"taxpayer_identifier", "case_number", "document_number"}:
        return _strict_public_identifier(raw, kind)
    return _clean(raw) if _public_text_slot_is_unambiguous(raw) else None


def _strict_native_evidence_ids(value: Any) -> tuple[str, ...] | None:
    """Return an immutable exact evidence list without normalizing its members."""

    if not isinstance(value, (list, tuple)) or not value:
        return None
    if any(not isinstance(item, str) or not item or item.strip() != item for item in value):
        return None
    if len(value) != len(set(value)):
        return None
    return tuple(value)


def _native_evidence_id_counts(
    parse_result: Any,
    *,
    roles: frozenset[str] | None = None,
) -> Counter[str] | None:
    """Inventory exact cell owners and reject malformed/replayed source IDs.

    ``roles`` identifies the tables that require a geometry plane; it is not
    an evidence namespace.  Evidence IDs are document-global, so every other
    well-formed native geometry plane must also participate in the replay
    count.  Otherwise the same acquisition atom could independently authorize
    a public row and a postpaid row.
    """

    counts: Counter[str] = Counter()
    cell_owners: defaultdict[
        str,
        list[tuple[int, tuple[float, float, float, float]]],
    ] = defaultdict(list)
    geometry_pages: set[int] = set()
    for page in getattr(parse_result, "pages", None) or ():
        page_number = int(getattr(page, "page_number", 0) or 0)
        for table in getattr(page, "tables", None) or ():
            required = not roles or any(
                canonical_table_owned_by(parse_result, page, table, role) for role in roles
            )
            geometry = _native_table_geometry(table)
            if geometry is None:
                if required:
                    return None
                continue
            grid = geometry.get("cell_evidence_ids")
            boxes = geometry.get("cell_bboxes")
            if not isinstance(grid, list) or not isinstance(boxes, list) or len(grid) != len(boxes):
                return None
            geometry_pages.add(page_number)
            for row_index, raw_row in enumerate(grid):
                if (
                    not isinstance(raw_row, list)
                    or row_index >= len(boxes)
                    or not isinstance(boxes[row_index], list)
                    or len(raw_row) != len(boxes[row_index])
                ):
                    return None
                for column, raw_cell in enumerate(raw_row):
                    strict_ids = _strict_native_evidence_ids(raw_cell)
                    bbox = _exact_geometry_bbox(boxes[row_index][column])
                    if strict_ids is None or bbox is None:
                        return None
                    counts.update(strict_ids)
                    for evidence_id in strict_ids:
                        cell_owners[evidence_id].append((page_number, bbox))

    evidence_loader = getattr(parse_result, "corrected_evidence_pages", None)
    corrected_pages = evidence_loader() if callable(evidence_loader) else ()
    if not isinstance(corrected_pages, (list, tuple)):
        return None
    for raw_page in corrected_pages:
        if not isinstance(raw_page, Mapping):
            return None
        page_number = raw_page.get("page")
        if not isinstance(page_number, int) or isinstance(page_number, bool) or page_number <= 0:
            return None
        raw_lines = raw_page.get("lines")
        if raw_lines is None:
            raw_lines = ()
        if not isinstance(raw_lines, (list, tuple)):
            return None
        for line in raw_lines:
            if not isinstance(line, Mapping):
                return None
            raw_ids = line.get("evidence_ids")
            if raw_ids in (None, (), []):
                continue
            line_ids = _strict_native_evidence_ids(raw_ids)
            if line_ids is None:
                return None
            if page_number not in geometry_pages:
                continue
            shared_ids = [evidence_id for evidence_id in line_ids if evidence_id in cell_owners]
            if not shared_ids:
                continue
            line_bbox = _exact_geometry_bbox(line.get("source_bbox") or line.get("bbox"))
            for evidence_id in shared_ids:
                owners = cell_owners[evidence_id]
                contained_alias = bool(
                    line_bbox is not None
                    and len(owners) == 1
                    and owners[0][0] == page_number
                    and owners[0][1][0] - 1.0 <= line_bbox[0]
                    and owners[0][1][1] - 1.0 <= line_bbox[1]
                    and line_bbox[2] <= owners[0][1][2] + 1.0
                    and line_bbox[3] <= owners[0][1][3] + 1.0
                )
                if not contained_alias:
                    counts[evidence_id] += 1
    return counts


def _sealed_exact_native_cell(
    table: Any,
    *,
    row: int,
    column: int,
    evidence_counts: Mapping[str, int] | None,
) -> tuple[tuple[float, float, float, float], tuple[str, ...]] | None:
    """Require exact geometry and globally unique provenance for one cell."""

    if evidence_counts is None:
        return None
    exact = _exact_native_table_cell(table, row=row, column=column)
    geometry = _native_table_geometry(table)
    grid = geometry.get("cell_evidence_ids") if isinstance(geometry, Mapping) else None
    raw_ids = (
        grid[row][column]
        if isinstance(grid, list)
        and row < len(grid)
        and isinstance(grid[row], list)
        and column < len(grid[row])
        else None
    )
    strict_ids = _strict_native_evidence_ids(raw_ids)
    if exact is None or strict_ids is None or exact[1] != strict_ids:
        return None
    if any(evidence_counts.get(evidence_id, 0) != 1 for evidence_id in strict_ids):
        return None
    return exact


def _exact_public_header_slots(
    row: tuple[str, ...],
    layout: Mapping[str, Any],
) -> dict[str, int] | None:
    """Match one of the finite public headers by whole physical cells only."""

    aliases = layout["aliases"]
    label_roles = {
        _compact(alias): role
        for role, labels in aliases.items()
        for alias in labels
    }
    roles = tuple(label_roles.get(_compact(cell), "") for cell in row)
    if not roles or not all(roles) or len(set(roles)) != len(roles):
        return None
    observed = set(roles)
    optional = set(layout.get("optional_header_roles") or ())
    required = set(aliases) - optional
    if not required.issubset(observed) or not observed.issubset(set(aliases)):
        return None
    return {role: column for column, role in enumerate(roles)}


def _public_header_lattice_is_sealed(
    table: Any,
    *,
    row_index: int,
    width: int,
    evidence_counts: Mapping[str, int],
) -> bool:
    return all(
        _sealed_exact_native_cell(
            table,
            row=row_index,
            column=column,
            evidence_counts=evidence_counts,
        )
        is not None
        for column in range(width)
    )


def _public_data_lattice_is_sealed(
    table: Any,
    *,
    row_index: int,
    row: tuple[str, ...],
    width: int,
    evidence_counts: Mapping[str, int],
) -> bool:
    return len(row) == width and _public_header_lattice_is_sealed(
        table,
        row_index=row_index,
        width=width,
        evidence_counts=evidence_counts,
    )


_PUBLIC_FINAL_DATASETS = {
    "tax_arrears": "tax_arrears_records",
    "civil_judgment": "civil_judgment_records",
    "enforcement": "enforcement_records",
    "administrative_penalty": "administrative_penalty_records",
    "housing_fund": "housing_fund_records",
    "professional_qualification": "professional_qualification_records",
    "award": "administrative_award_records",
}


def _consume_public_canonical_row(
    parse_result: Any,
    working: dict[tuple[Any, ...], dict[str, Any]],
    *,
    page: Any,
    table: Any,
    layout: Mapping[str, Any],
    slots: Mapping[str, int],
    data_row: tuple[str, ...],
    row_index: int,
    sequence: int,
    record_key: tuple[Any, ...] | None = None,
    target_id: str | None = None,
) -> None:
    record_type = str(layout["record_type"])
    target_dataset = _PUBLIC_FINAL_DATASETS[record_type]
    record_key = record_key or (record_type, sequence)
    target_id = target_id or stable_record_id("public_record", record_type, sequence)
    item = working.setdefault(
        record_key,
        {
            "public_record_id": target_id,
            "sequence": sequence,
            "record_type": record_type,
            "source": "native_detail_public_table",
            "source_refs": [],
            "confidence": 1.0,
        },
    )
    row_ref = _source_ref(page, table, row=row_index)
    if row_ref not in item["source_refs"]:
        item["source_refs"].append(row_ref)
    for role, (field_name, kind) in layout["fields"].items():
        if role not in slots:
            continue
        raw = _slot_value(data_row, slots, role)
        ref = _source_ref(page, table, row=row_index, column=slots[role])
        if not raw:
            _report_required_row_failure(
                parse_result,
                issue_code="candidate_b_public_record_cell_unresolved",
                dataset=target_dataset,
                sequence=sequence,
                field_name=field_name,
                row=data_row,
                page=page,
                table=table,
                row_index=row_index,
                target_record_id=target_id,
            )
            _append_internal_field(item, "_unresolved_fields", field_name)
            continue
        if _compact(raw) in {"-", "--", "---"}:
            _mark_source_absent(item, field_name, raw)
            continue
        value = _public_value(raw, kind)
        if value in (None, ""):
            _reject_exact_observation(
                parse_result,
                item,
                dataset=target_dataset,
                target_record_id=target_id,
                field_name=field_name,
                raw=raw,
                source_ref=ref,
                parser_stage="candidate_b_public_canonical_slots",
            )
            continue
        _merge_exact_observation(
            parse_result,
            item,
            dataset=target_dataset,
            target_record_id=target_id,
            field_name=field_name,
            value=value,
            raw=raw,
            source_ref=ref,
            parser_stage="candidate_b_public_canonical_slots",
        )


def _public_record_continuation_allowed(
    parse_result: Any,
    left_logical_page: int,
    right_logical_page: int,
) -> bool:
    """Bind a split public record only across one proven page edge."""

    return _document_page_carry_allowed(
        parse_result,
        left_logical_page,
        right_logical_page,
    )


def _bounded_compound_housing_fund_records(
    parse_result: Any,
) -> tuple[dict[tuple[str, int], dict[str, Any]], set[str]]:
    """Recover one exact PBOC housing-fund role graph without shifting.

    Physical columns and row counts are scanner output, not report semantics.
    The finite PBOC labels establish roles; immutable token geometry establishes
    each role's value region.  Ambiguous or novel graphs are left to ordinary
    extraction instead of being consumed by this bounded repair.
    """

    working: dict[tuple[str, int], dict[str, Any]] = {}
    consumed: set[str] = set()
    pages_by_number = {
        int(page.get("page") or 0): page
        for page in (
            parse_result.corrected_evidence_pages()
            if callable(getattr(parse_result, "corrected_evidence_pages", None))
            else ()
        )
        if isinstance(page, Mapping)
    }
    exact_month_re = re.compile(r"(?:19|20)\d{2}[./-](?:0?[1-9]|1[0-2])")
    exact_ratio_re = re.compile(r"(?:0|[1-9]\d?|100)(?:\.\d+)?%")

    for page in getattr(parse_result, "pages", None) or ():
        logical_page = int(getattr(page, "page_number", 0) or 0)
        for table in getattr(page, "tables", None) or ():
            rows = _table_rows(table)
            geometry = _native_table_geometry(table)
            row_bands = (
                _indexed_geometry_bands(geometry, "row_bands", lower_key="y0", upper_key="y1")
                if geometry is not None
                else None
            )
            column_bands = (
                _indexed_geometry_bands(geometry, "col_bands", lower_key="x0", upper_key="x1")
                if geometry is not None
                else None
            )
            if row_bands is None or column_bands is None or not rows:
                continue
            if set(row_bands) != set(range(len(row_bands))) or set(column_bands) != set(range(len(column_bands))):
                continue
            if any(
                row_bands[index][1] > row_bands[index + 1][0]
                for index in range(len(row_bands) - 1)
            ) or any(
                column_bands[index][1] > column_bands[index + 1][0]
                for index in range(len(column_bands) - 1)
            ):
                continue

            base_roles = (
                "参缴地",
                "参缴日期",
                "初缴月份",
                "缴至月份",
                "缴费状态",
                "月缴存额",
                "个人缴存比例",
                "单位缴存比例",
            )
            provider_roles = ("缴费单位", "信息更新日期")
            all_roles = (*base_roles, *provider_roles)

            def exact_cell_tokens(
                row: int,
                column: int,
                *,
                registered_header_roles: tuple[str, ...] = (),
            ) -> tuple[tuple[str, tuple[float, float, float, float], str], ...] | None:
                span = _native_table_cell_span(table, row=row, column=column)
                tokens = _exact_native_table_cell_tokens(
                    parse_result,
                    table,
                    row=row,
                    column=column,
                    allowed_span=span if span not in (None, (1, 1)) else None,
                    logical_page=logical_page,
                )
                if tokens is not None or len(registered_header_roles) < 2:
                    return tokens

                # A scanner may assign one exact atom containing adjacent PBOC
                # labels to either physical grid cell even though the printed
                # atom crosses their divider.  This is not permission to relax
                # ordinary value ownership: accept the spill only for a cell
                # whose complete text is a registered multi-role header, whose
                # token/evidence sets agree exactly, and whose token geometry is
                # contained by this exact table and centred in this header row.
                # These topological checks scale with the source lattice; no PDF
                # point or sample-column threshold participates.
                if span is not None:
                    return None
                exact_cell = _exact_native_table_cell(table, row=row, column=column)
                if exact_cell is None:
                    return None
                _cell_bbox, evidence_ids = exact_cell
                metadata = getattr(table, "metadata", None)
                token_grid = (
                    metadata.get("cell_token_ids")
                    if isinstance(metadata, Mapping)
                    else None
                ) or geometry.get("cell_token_ids")
                if (
                    not isinstance(token_grid, list)
                    or row >= len(token_grid)
                    or not isinstance(token_grid[row], list)
                    or column >= len(token_grid[row])
                    or not isinstance(token_grid[row][column], list)
                ):
                    return None
                token_ids = tuple(
                    str(value) for value in token_grid[row][column] if str(value or "")
                )
                if (
                    not token_ids
                    or len(token_ids) != len(set(token_ids))
                    or set(token_ids) != set(evidence_ids)
                ):
                    return None
                resolved = resolve_exact_page_token_atoms(
                    parse_result,
                    token_ids,
                    logical_page=logical_page,
                )
                if resolved is None:
                    return None
                table_left = min(left for left, _right in column_bands.values())
                table_right = max(right for _left, right in column_bands.values())
                row_top, row_bottom = row_bands[row]
                row_height = row_bottom - row_top
                if any(
                    bbox[0] < table_left
                    or bbox[2] > table_right
                    or bbox[3] - bbox[1] > row_height
                    or not row_top <= (bbox[1] + bbox[3]) / 2.0 <= row_bottom
                    for _text, bbox, _token_id in resolved
                ):
                    return None
                return tuple(
                    sorted(resolved, key=lambda item: (item[1][1], item[1][0], item[2]))
                )

            def ordered_roles(text: str, vocabulary: tuple[str, ...]) -> tuple[str, ...] | None:
                residue = _compact(text)
                roles: list[tuple[int, str]] = []
                for role in vocabulary:
                    if residue.count(role) != 1:
                        continue
                    roles.append((residue.index(role), role))
                if not roles:
                    return None
                roles.sort()
                cursor = 0
                for position, role in roles:
                    if position != cursor:
                        return None
                    cursor += len(role)
                return tuple(role for _position, role in roles) if cursor == len(residue) else None

            header_cells: list[
                tuple[int, int, tuple[str, ...], tuple[tuple[str, tuple[float, float, float, float], str], ...]]
            ] = []
            used_header_ids: set[str] = set()
            for row_index, row in enumerate(rows):
                for column, raw in enumerate(row):
                    roles = ordered_roles(raw, all_roles)
                    if roles is None:
                        continue
                    tokens = exact_cell_tokens(
                        row_index,
                        column,
                        registered_header_roles=roles,
                    )
                    if tokens is None:
                        header_cells = []
                        break
                    token_ids = {token[2] for token in tokens}
                    if token_ids & used_header_ids:
                        header_cells = []
                        break
                    token_text = _compact("".join(token[0] for token in sorted(tokens, key=lambda token: token[1][0])))
                    if token_text != _compact(raw):
                        header_cells = []
                        break
                    used_header_ids.update(token_ids)
                    header_cells.append((row_index, column, roles, tokens))
                else:
                    continue
                break
            role_cells: dict[str, tuple[int, int, tuple[float, float, float, float]]] = {}
            for row_index, column, roles, tokens in header_cells:
                left_to_right = tuple(sorted(tokens, key=lambda token: (token[1][0], token[1][1], token[2])))
                compact_tokens = tuple((token, _compact(token[0])) for token in left_to_right)
                if (
                    any(not text for _token, text in compact_tokens)
                    or any(
                        left[0][1][2] > right[0][1][0]
                        for left, right in zip(compact_tokens, compact_tokens[1:])
                    )
                    or min(token[1][3] for token, _text in compact_tokens)
                    <= max(token[1][1] for token, _text in compact_tokens)
                ):
                    role_cells = {}
                    break

                # OCR may preserve two adjacent official labels as one exact
                # atom. Split only a registered PBOC-role concatenation, and
                # derive its role regions from character offsets inside the
                # immutable atom bbox. No value text or report-specific x
                # coordinate participates.
                token_segments: list[
                    tuple[int, int, tuple[str, tuple[float, float, float, float], str]]
                ] = []
                character_cursor = 0
                for token, compact_token in compact_tokens:
                    token_segments.append(
                        (character_cursor, character_cursor + len(compact_token), token)
                    )
                    character_cursor += len(compact_token)
                if character_cursor != sum(len(role) for role in roles):
                    role_cells = {}
                    break

                role_cursor = 0
                for role in roles:
                    role_end = role_cursor + len(role)
                    pieces: list[tuple[float, float, float, float]] = []
                    for segment_start, segment_end, token in token_segments:
                        overlap_start = max(role_cursor, segment_start)
                        overlap_end = min(role_end, segment_end)
                        if overlap_end <= overlap_start:
                            continue
                        bbox = token[1]
                        width = bbox[2] - bbox[0]
                        segment_length = segment_end - segment_start
                        pieces.append(
                            (
                                bbox[0]
                                + width * (overlap_start - segment_start) / segment_length,
                                bbox[1],
                                bbox[0]
                                + width * (overlap_end - segment_start) / segment_length,
                                bbox[3],
                            )
                        )
                    if not pieces or role in role_cells:
                        role_cells = {}
                        break
                    role_cells[role] = (
                        row_index,
                        column,
                        (
                            min(piece[0] for piece in pieces),
                            min(piece[1] for piece in pieces),
                            max(piece[2] for piece in pieces),
                            max(piece[3] for piece in pieces),
                        ),
                    )
                    role_cursor = role_end
                if not role_cells:
                    break
            if set(role_cells) != set(all_roles):
                continue
            base_rows = {role_cells[role][0] for role in base_roles}
            provider_rows = {role_cells[role][0] for role in provider_roles}
            if len(base_rows) != 1 or len(provider_rows) != 1:
                continue
            provider_header_boxes = [role_cells[role][2] for role in provider_roles]
            if provider_header_boxes[0][2] > provider_header_boxes[1][0]:
                continue
            base_header_row = next(iter(base_rows))
            provider_header_row = next(iter(provider_rows))
            if provider_header_row <= base_header_row:
                continue
            value_row = base_header_row + 1
            if value_row >= len(rows) or value_row >= provider_header_row:
                continue
            def row_has_only_registered_cells(
                row_index: int,
                vocabulary: tuple[str, ...],
            ) -> bool:
                registered_cells = {
                    column
                    for header_row, column, roles, _tokens in header_cells
                    if header_row == row_index and all(role in vocabulary for role in roles)
                }
                return all(
                    not _compact(raw) or column in registered_cells
                    for column, raw in enumerate(rows[row_index])
                )

            if any(
                len(rows[row_index]) != len(column_bands)
                for row_index in (base_header_row, value_row, provider_header_row)
            ):
                continue
            if not row_has_only_registered_cells(
                base_header_row,
                base_roles,
            ) or not row_has_only_registered_cells(provider_header_row, provider_roles):
                # An unknown/new official field is not evidence for this
                # finite schema and must remain available to ordinary parsing.
                continue
            if any(any(_compact(cell) for cell in row) for row in rows[value_row + 1 : provider_header_row]):
                continue

            # Scanner columns may merge several adjacent printed fields. Exact
            # header atoms therefore define role regions across the whole
            # printed row, independent of the reconstructed column count.
            regions: dict[str, tuple[float, float]] = {}
            ordered_base_roles = sorted(base_roles, key=lambda role: role_cells[role][2][0])
            if tuple(ordered_base_roles) != base_roles:
                continue
            header_boxes = [role_cells[role][2] for role in ordered_base_roles]
            if any(left[2] > right[0] for left, right in zip(header_boxes, header_boxes[1:])):
                continue
            table_left = min(left for left, _right in column_bands.values())
            table_right = max(right for _left, right in column_bands.values())
            boundaries = [table_left]
            boundaries.extend(
                (
                    (left_bbox[0] + left_bbox[2]) / 2.0
                    + (right_bbox[0] + right_bbox[2]) / 2.0
                )
                / 2.0
                for left_bbox, right_bbox in zip(header_boxes, header_boxes[1:])
            )
            boundaries.append(table_right)
            if any(left >= right for left, right in zip(boundaries, boundaries[1:])):
                continue
            for index, role in enumerate(ordered_base_roles):
                regions[role] = boundaries[index], boundaries[index + 1]
            if set(regions) != set(base_roles):
                continue

            value_tokens_by_column: dict[
                int,
                tuple[tuple[str, tuple[float, float, float, float], str], ...],
            ] = {}
            value_ids: set[str] = set()
            value_graph_valid = True
            for column in column_bands:
                tokens = exact_cell_tokens(value_row, column)
                raw_cell = _compact(rows[value_row][column])
                if tokens is None and not raw_cell:
                    continue
                if tokens is None or not raw_cell:
                    value_graph_valid = False
                    break
                token_text = _compact(
                    "".join(
                        token[0]
                        for token in sorted(tokens, key=lambda token: (token[1][0], token[1][1], token[2]))
                    )
                )
                if token_text != raw_cell or any(
                    token[2] in used_header_ids or token[2] in value_ids for token in tokens
                ):
                    value_graph_valid = False
                    break
                value_tokens_by_column[column] = tokens
                value_ids.update(token[2] for token in tokens)
            if not value_graph_valid or not value_tokens_by_column:
                continue

            role_tokens: dict[str, list[tuple[str, tuple[float, float, float, float], str]]] = {}
            all_value_tokens = tuple(token for tokens in value_tokens_by_column.values() for token in tokens)
            for role in base_roles:
                left, right = regions[role]
                role_tokens[role] = [
                    token
                    for token in all_value_tokens
                    if left <= token[1][0] and token[1][2] <= right
                ]
            token_role_counts = {
                token[2]: sum(token in tokens for tokens in role_tokens.values())
                for token in all_value_tokens
            }
            # Every sealed value token must belong to exactly one registered
            # role. Explicitly blank roles remain field-level uncertainty, but
            # an unassigned/cross-band token cannot silently become one.
            if any(count != 1 for count in token_role_counts.values()):
                continue

            token_columns = {
                token[2]: column
                for column, tokens in value_tokens_by_column.items()
                for token in tokens
            }

            def value_ref(
                role: str,
                *,
                binding_quality: str = "exact_token_in_header_derived_role_region",
            ) -> dict[str, Any]:
                tokens = role_tokens[role]
                columns = {token_columns[token[2]] for token in tokens}
                ref = (
                    _source_ref(page, table, row=value_row, column=next(iter(columns)))
                    if len(columns) == 1
                    else _source_ref(page, table)
                )
                if tokens:
                    ref.update(
                        {
                            "source": "native_detail_table_token"
                            if len(tokens) == 1
                            else "native_detail_table_tokens",
                            "bbox": [
                                min(token[1][0] for token in tokens),
                                min(token[1][1] for token in tokens),
                                max(token[1][2] for token in tokens),
                                max(token[1][3] for token in tokens),
                            ],
                            "evidence_ids": [token[2] for token in tokens],
                            "geometry_scope": "token" if len(tokens) == 1 else "tokens",
                            "binding": "canonical_field_token",
                            "binding_quality": binding_quality,
                        }
                    )
                return ref

            first_month_left, first_month_right = regions["初缴月份"]
            first_month_columns = [
                column
                for column, (left, right) in column_bands.items()
                if left <= first_month_left < first_month_right <= right
            ]
            if len(first_month_columns) != 1:
                continue
            first_month_column = first_month_columns[0]
            first_month_cell_left, first_month_cell_right = column_bands[first_month_column]
            first_month_cell_width = first_month_cell_right - first_month_cell_left
            first_month_fraction = (
                (first_month_left - first_month_cell_left) / first_month_cell_width,
                (first_month_right - first_month_cell_left) / first_month_cell_width,
            )
            if not 0.0 <= first_month_fraction[0] < first_month_fraction[1] <= 1.0:
                continue

            table_id = str(getattr(table, "table_id", "") or "")
            sequence = len(working) + 1
            target_id = stable_record_id("public_record", "housing_fund", sequence)
            item: dict[str, Any] = {
                "public_record_id": target_id,
                "sequence": sequence,
                "record_type": "housing_fund",
                "source": "native_detail_public_compound_table",
                "source_refs": [_source_ref(page, table)],
                "confidence": 1.0,
            }
            working[("housing_fund", sequence)] = item
            consumed.add(table_id)

            observations: tuple[tuple[str, str, str], ...] = (
                ("contribution_location", "参缴地", "text"),
                ("participation_date", "参缴日期", "date"),
                ("paid_through_month", "缴至月份", "date"),
            )
            for field_name, role, kind in observations:
                tokens = role_tokens[role]
                raw = _clean("".join(token[0] for token in tokens))
                value = _public_value(raw, kind)
                ref = value_ref(role)
                if value in (None, ""):
                    _reject_exact_observation(
                        parse_result,
                        item,
                        dataset="housing_fund_records",
                        target_record_id=target_id,
                        field_name=field_name,
                        raw=raw,
                        source_ref=ref,
                        parser_stage="candidate_b_public_compound_housing_fund",
                    )
                    continue
                _merge_exact_observation(
                    parse_result,
                    item,
                    dataset="housing_fund_records",
                    target_record_id=target_id,
                    field_name=field_name,
                    value=value,
                    raw=raw,
                    source_ref=ref,
                    parser_stage="candidate_b_public_compound_housing_fund",
                )

            payment_tokens = role_tokens["缴费状态"]
            payment_raw = _compact("".join(token[0] for token in payment_tokens))
            payment_ref = value_ref("缴费状态")
            if len(payment_tokens) == 1 and payment_raw in {
                "正常",
                "缴交",
                "缴存",
                "正常缴存",
                "封存",
                "停缴",
                "销户",
            }:
                _merge_exact_observation(
                    parse_result,
                    item,
                    dataset="housing_fund_records",
                    target_record_id=target_id,
                    field_name="payment_status",
                    value=payment_raw,
                    raw=payment_raw,
                    source_ref=payment_ref,
                    parser_stage="candidate_b_public_compound_housing_fund",
                )
            else:
                _reject_exact_observation(
                    parse_result,
                    item,
                    dataset="housing_fund_records",
                    target_record_id=target_id,
                    field_name="payment_status",
                    raw=payment_raw,
                    source_ref=payment_ref,
                    parser_stage="candidate_b_public_compound_housing_fund",
                )

            for field_name, role, pattern, kind in (
                ("monthly_contribution", "月缴存额", _STRICT_REGISTERED_SUMMARY_NUMBER_RE, "number"),
                (
                    "personal_contribution_ratio",
                    "个人缴存比例",
                    exact_ratio_re,
                    "text",
                ),
                (
                    "employer_contribution_ratio",
                    "单位缴存比例",
                    exact_ratio_re,
                    "text",
                ),
            ):
                tokens = role_tokens[role]
                raw = _compact("".join(token[0] for token in tokens))
                token_ref = value_ref(
                    role,
                    binding_quality="exact_typed_token_in_header_derived_role_region",
                )
                if not tokens or pattern.fullmatch(raw) is None:
                    _reject_exact_observation(
                        parse_result,
                        item,
                        dataset="housing_fund_records",
                        target_record_id=target_id,
                        field_name=field_name,
                        raw=raw,
                        source_ref=token_ref,
                        parser_stage="candidate_b_public_compound_housing_fund",
                    )
                    continue
                _merge_exact_observation(
                    parse_result,
                    item,
                    dataset="housing_fund_records",
                    target_record_id=target_id,
                    field_name=field_name,
                    value=_public_value(raw, kind),
                    raw=raw,
                    source_ref=token_ref,
                    parser_stage="candidate_b_public_compound_housing_fund",
                )

            # The first-contribution month has its own printed header but no
            # exact typed value in the shared physical cell. Never reinterpret
            # the participation date as both fields. A visual dash proof may
            # establish explicit absence; otherwise preserve uncertainty.
            first_month_ref = _source_ref(page, table, row=value_row, column=first_month_column)
            visual_cell = None
            source_cells = getattr(table, "source_cell_objects", None)
            if (
                isinstance(source_cells, list)
                and len(source_cells) > value_row
                and isinstance(source_cells[value_row], list)
                and len(source_cells[value_row]) > first_month_column
            ):
                visual_cell = source_cells[value_row][first_month_column]
            first_month_values = role_tokens["初缴月份"]
            first_month_raw = _compact("".join(token[0] for token in first_month_values))
            first_month_value = _date(first_month_raw) if first_month_raw else None
            if first_month_value is not None and first_month_values:
                first_month_token_ref = value_ref(
                    "初缴月份",
                    binding_quality="exact_date_token_in_header_derived_role_region",
                )
                _merge_exact_observation(
                    parse_result,
                    item,
                    dataset="housing_fund_records",
                    target_record_id=target_id,
                    field_name="first_contribution_month",
                    value=first_month_value,
                    raw=first_month_raw,
                    source_ref=first_month_token_ref,
                    parser_stage="candidate_b_public_compound_housing_fund",
                )
            elif not first_month_values and visual_cell is not None and exact_cell_visually_contains_dash_pair(
                parse_result,
                visual_cell,
                logical_page=logical_page,
                horizontal_fraction=first_month_fraction,
            ):
                _mark_source_absent(item, "first_contribution_month")
                absence_ref = {
                    **first_month_ref,
                    "source": "native_detail_visual_subcell",
                    "geometry_scope": "visual_subcell",
                    "binding": "canonical_explicit_absence_slot",
                    "binding_quality": "exact_dash_pair_visual_shape",
                    "field_name": "first_contribution_month",
                    "observed_value": "--",
                    "horizontal_fraction": list(first_month_fraction),
                    "visual_proof": "dash_pair_only",
                }
                # The cell's OCR evidence belongs to the participation date on
                # the left; never relabel that token as evidence for the dash.
                absence_ref.pop("evidence_ids", None)
                if (absence_bbox := _exact_geometry_bbox(first_month_ref.get("bbox"))) is not None:
                    width = absence_bbox[2] - absence_bbox[0]
                    absence_ref["bbox"] = [
                        absence_bbox[0] + width * first_month_fraction[0],
                        absence_bbox[1],
                        absence_bbox[0] + width * first_month_fraction[1],
                        absence_bbox[3],
                    ]
                item.setdefault("source_refs", []).append(absence_ref)
                item.setdefault("source_refs_by_field", {}).setdefault(
                    "first_contribution_month",
                    [],
                ).append(absence_ref)
            else:
                _reject_exact_observation(
                    parse_result,
                    item,
                    dataset="housing_fund_records",
                    target_record_id=target_id,
                    field_name="first_contribution_month",
                    raw="",
                    source_ref=first_month_ref,
                    parser_stage="candidate_b_public_compound_housing_fund",
                )

            evidence_page = pages_by_number.get(logical_page, {})
            lines = [line for line in evidence_page.get("lines") or () if isinstance(line, Mapping)]
            employer_header = role_cells["缴费单位"][2]
            month_header = role_cells["信息更新日期"][2]
            provider_boundary = (employer_header[2] + month_header[0]) / 2.0
            provider_header_bottom = max(employer_header[3], month_header[3])
            provider_candidates: list[
                tuple[str, str, str, str, dict[str, Any], dict[str, Any]]
            ] = []
            provider_tokens: list[
                tuple[int, str, tuple[float, float, float, float], str, dict[str, Any]]
            ] = []
            provider_ids: set[str] = set()
            provider_graph_valid = True
            for line_index, line in enumerate(lines):
                raw_line = _clean(line.get("text") or line.get("content") or "")
                ref = _corrected_text_source_ref(evidence_page, line, line_index)
                line_bbox = _exact_geometry_bbox(ref.get("bbox"))
                evidence_ids = tuple(str(value) for value in ref.get("evidence_ids") or () if value)
                if not raw_line or line_bbox is None or line_bbox[1] < provider_header_bottom:
                    continue
                atoms = resolve_exact_page_token_atoms(
                    parse_result,
                    evidence_ids,
                    logical_page=logical_page,
                )
                if atoms is None:
                    continue
                sorted_atoms = tuple(sorted(atoms, key=lambda atom: (atom[1][0], atom[1][1], atom[2])))
                if _compact("".join(atom[0] for atom in sorted_atoms)) != _compact(raw_line):
                    continue
                candidate_atoms = tuple(
                    atom
                    for atom in sorted_atoms
                    if atom[1][1] >= provider_header_bottom
                    and table_left <= atom[1][0] < atom[1][2] <= table_right
                )
                if not candidate_atoms:
                    continue
                candidate_ids = {atom[2] for atom in candidate_atoms}
                if (
                    len(candidate_ids) != len(candidate_atoms)
                    or candidate_ids & (used_header_ids | value_ids | provider_ids)
                ):
                    provider_graph_valid = False
                    break
                provider_ids.update(candidate_ids)
                for text, bbox, token_id in candidate_atoms:
                    token_ref = {
                        **ref,
                        "source": "candidate_b_corrected_page_token",
                        "bbox": list(bbox),
                        "evidence_ids": [token_id],
                        "geometry_scope": "token",
                        "binding": "canonical_provider_field_token",
                        "binding_quality": "exact_token_in_header_derived_provider_region",
                    }
                    provider_tokens.append((line_index, text, bbox, token_id, token_ref))
            y_groups: list[
                list[tuple[int, str, tuple[float, float, float, float], str, dict[str, Any]]]
            ] = []
            for entry in sorted(provider_tokens, key=lambda value: (value[2][1], value[2][0], value[0])):
                matching = [
                    group
                    for group in y_groups
                    if all(
                        min(member[2][3], entry[2][3]) > max(member[2][1], entry[2][1])
                        for member in group
                    )
                ]
                if len(matching) == 1:
                    matching[0].append(entry)
                elif not matching:
                    y_groups.append([entry])
                else:
                    provider_graph_valid = False
                    break
            for group in y_groups if provider_graph_valid else ():
                employer_entries = [entry for entry in group if entry[2][2] <= provider_boundary]
                month_entries = [entry for entry in group if entry[2][0] >= provider_boundary]
                if (
                    not employer_entries
                    or not month_entries
                    or len(employer_entries) + len(month_entries) != len(group)
                ):
                    # Provider values form the contiguous geometric row sequence
                    # immediately below their exact header.  The first unrelated
                    # row closes that local schema; a later typed line elsewhere
                    # on the page cannot be recruited as provider evidence.
                    break
                employer_entries.sort(key=lambda entry: (entry[2][0], entry[0], entry[3]))
                month_entries.sort(key=lambda entry: (entry[2][0], entry[0], entry[3]))
                employer_raw = _clean("".join(entry[1] for entry in employer_entries))
                month_raw = _compact("".join(entry[1] for entry in month_entries))
                employer = _public_value(employer_raw, "employer_name")
                update_month = _date(month_raw) if exact_month_re.fullmatch(month_raw) else None
                if employer and update_month:
                    employer_ref = {
                        **employer_entries[0][4],
                        "source": "candidate_b_corrected_page_token"
                        if len(employer_entries) == 1
                        else "candidate_b_corrected_page_tokens",
                        "bbox": [
                            min(entry[2][0] for entry in employer_entries),
                            min(entry[2][1] for entry in employer_entries),
                            max(entry[2][2] for entry in employer_entries),
                            max(entry[2][3] for entry in employer_entries),
                        ],
                        "evidence_ids": [entry[3] for entry in employer_entries],
                        "geometry_scope": "token" if len(employer_entries) == 1 else "tokens",
                    }
                    month_ref = {
                        **month_entries[0][4],
                        "source": "candidate_b_corrected_page_token"
                        if len(month_entries) == 1
                        else "candidate_b_corrected_page_tokens",
                        "bbox": [
                            min(entry[2][0] for entry in month_entries),
                            min(entry[2][1] for entry in month_entries),
                            max(entry[2][2] for entry in month_entries),
                            max(entry[2][3] for entry in month_entries),
                        ],
                        "evidence_ids": [entry[3] for entry in month_entries],
                        "geometry_scope": "token" if len(month_entries) == 1 else "tokens",
                    }
                    provider_candidates.append(
                        (
                            str(employer),
                            update_month,
                            employer_raw,
                            month_raw,
                            employer_ref,
                            month_ref,
                        )
                    )
            if len(provider_candidates) == 1:
                employer, update_month, employer_raw, month_raw, employer_ref, month_ref = provider_candidates[0]
                for field_name, value, raw, ref in (
                    ("employer", employer, employer_raw, employer_ref),
                    ("information_updated_month", update_month, month_raw, month_ref),
                ):
                    _merge_exact_observation(
                        parse_result,
                        item,
                        dataset="housing_fund_records",
                        target_record_id=target_id,
                        field_name=field_name,
                        value=value,
                        raw=raw,
                        source_ref=ref,
                        parser_stage="candidate_b_public_compound_housing_fund",
                    )
            else:
                for field_name, role in (
                    ("employer", "缴费单位"),
                    ("information_updated_month", "信息更新日期"),
                ):
                    header_row, column, _bbox = role_cells[role]
                    _reject_exact_observation(
                        parse_result,
                        item,
                        dataset="housing_fund_records",
                        target_record_id=target_id,
                        field_name=field_name,
                        raw="",
                        source_ref=_source_ref(page, table, row=header_row, column=column),
                        parser_stage="candidate_b_public_compound_housing_fund",
                    )
    return working, consumed


def _report_public_lattice_row_failure(
    parse_result: Any,
    *,
    layout: Mapping[str, Any],
    page: Any,
    table: Any,
    row_index: int,
    row: tuple[str, ...],
    slots: Mapping[str, int] | None = None,
) -> None:
    """Conserve every business role from one unsealed public row as issues."""

    dataset = _PUBLIC_FINAL_DATASETS[str(layout["record_type"])]
    target_id = stable_record_id(
        "public_lattice_unresolved",
        dataset,
        int(getattr(page, "page_number", 0) or 0),
        str(getattr(table, "table_id", "") or ""),
        row_index,
    )
    for role, (field_name, _kind) in layout["fields"].items():
        if slots is not None and role not in slots:
            continue
        _report_required_row_failure(
            parse_result,
            issue_code="candidate_b_public_lattice_row_unresolved",
            dataset=dataset,
            sequence=0,
            field_name=field_name,
            row=row,
            page=page,
            table=table,
            row_index=row_index,
            target_record_id=target_id,
        )


def _report_public_join_failure(
    parse_result: Any,
    *,
    layout: Mapping[str, Any],
    page: Any,
    table: Any,
    row_index: int,
    row: tuple[str, ...],
    sequence: int,
    target_record_id: str,
) -> None:
    from docmirror.plugins.credit_report.personal_detail_scanned.extraction_issues import make_issue, record_issue

    record_issue(
        parse_result,
        make_issue(
            category="schema_incompleteness",
            issue_code="candidate_b_public_record_join_unresolved",
            message=(
                "A canonical civil/enforcement detail row had no unique same-instance or approved adjacent base; "
                "it was retained as a separate partial record."
            ),
            parser_stage="candidate_b_public_instance_join",
            target_dataset=_PUBLIC_FINAL_DATASETS[str(layout["record_type"])],
            target_record_id=target_record_id,
            field_name="sequence",
            observed_value={"sequence": sequence, "physical_cells": list(row)},
            source_refs=(_source_ref(page, table, row=row_index),),
            reason_codes=(
                "same_table_section_instance_required",
                "unique_adjacent_continuation_required",
                "global_sequence_merge_forbidden",
            ),
        ),
    )


def _report_public_duplicate_sequence_row(
    parse_result: Any,
    *,
    layout: Mapping[str, Any],
    slots: Mapping[str, int],
    page: Any,
    table: Any,
    row_index: int,
    row: tuple[str, ...],
    sequence: int,
    physical_table_index: int,
) -> None:
    """Localize a second physical row without assigning it a new ordinal."""

    target_id = stable_record_id(
        "public_duplicate_sequence_unresolved",
        str(layout["record_type"]),
        int(getattr(page, "page_number", 0) or 0),
        str(getattr(table, "table_id", "") or ""),
        physical_table_index,
        row_index,
        sequence,
    )
    for role, (field_name, _kind) in layout["fields"].items():
        if role not in slots:
            continue
        _report_required_row_failure(
            parse_result,
            issue_code="candidate_b_public_duplicate_sequence_owner_unresolved",
            dataset=_PUBLIC_FINAL_DATASETS[str(layout["record_type"])],
            sequence=sequence,
            field_name=field_name,
            row=row,
            page=page,
            table=table,
            row_index=row_index,
            target_record_id=target_id,
        )


def _conserve_issue_only_public_table(
    parse_result: Any,
    *,
    page: Any,
    table: Any,
    rows: tuple[tuple[str, ...], ...],
    evidence_counts: Mapping[str, int],
) -> bool:
    """Retain visible social-assistance cells without inventing an unproved schema."""

    from docmirror.plugins.credit_report.personal_detail_scanned.extraction_issues import make_issue, record_issue

    marker_positions = [
        (row_index, column, _PUBLIC_ISSUE_ONLY_SECTION_HEADERS[_compact(cell)])
        for row_index, row in enumerate(rows)
        for column, cell in enumerate(row)
        if _compact(cell) in _PUBLIC_ISSUE_ONLY_SECTION_HEADERS
    ]
    if not marker_positions:
        return False
    datasets = {dataset for _row, _column, dataset in marker_positions}
    if len(datasets) != 1:
        return False
    dataset = next(iter(datasets))
    marker_cells = {(row_index, column) for row_index, column, _dataset in marker_positions}
    for marker_row, marker_column, _dataset in marker_positions:
        if (
            _sealed_exact_native_cell(
                table,
                row=marker_row,
                column=marker_column,
                evidence_counts=evidence_counts,
            )
            is None
        ):
            _report_header_graph_failure(
                parse_result,
                dataset=dataset,
                page=page,
                table=table,
                row_index=marker_row,
                row=rows[marker_row],
            )

    # A pure section-title row carries no business fields.  Every other visible
    # row in an issue-only table must terminate in its own physical-row issue,
    # including rows beside/before a repeated marker and rows following an
    # unsealed marker.  This prevents a malformed title from disabling terminal
    # conservation for the rest of the table.
    for row_index, row in enumerate(rows):
        nonempty_columns = [column for column, raw in enumerate(row) if _clean(raw)]
        if not nonempty_columns:
            continue
        if (
            len(nonempty_columns) == 1
            and (row_index, nonempty_columns[0]) in marker_cells
        ):
            continue
        refs: list[dict[str, Any]] = []
        exact_row = True
        for column in nonempty_columns:
            if _sealed_exact_native_cell(
                table,
                row=row_index,
                column=column,
                evidence_counts=evidence_counts,
            ) is None:
                exact_row = False
                break
            refs.append(_source_ref(page, table, row=row_index, column=column))
        if not exact_row:
            refs = [_source_ref(page, table, row=row_index)]
        record_issue(
            parse_result,
            make_issue(
                category="schema_incompleteness",
                issue_code="candidate_b_social_assistance_source_row_unresolved",
                message=(
                    "A visible social-assistance source row has no proved finite PBOC business-field layout; "
                    "the exact source row was retained without inventing fields."
                ),
                parser_stage="candidate_b_public_issue_only_social_assistance",
                target_dataset=dataset,
                target_record_id=stable_record_id(
                    "social_assistance_unresolved",
                    int(getattr(page, "page_number", 0) or 0),
                    str(getattr(table, "table_id", "") or ""),
                    row_index,
                ),
                observed_value={"physical_cells": list(row)},
                source_refs=refs,
                reason_codes=(
                    "visible_owned_source_row",
                    "finite_business_layout_unproved",
                    "business_fields_not_invented",
                    "silent_drop_prevented",
                ),
            ),
        )
    return True


def _extract_public_records(parse_result: Any) -> list[dict[str, Any]]:
    # Every published scalar is bound to one sealed exact physical lattice.
    # Near-canonical, short, extra, or unsealed rows terminate in localized
    # issues and never enter the business record map.
    working, compound_housing_tables = _bounded_compound_housing_fund_records(parse_result)
    evidence_counts = _native_evidence_id_counts(
        parse_result,
        roles=frozenset({"public_information"}),
    )
    optional_sequence_counters: defaultdict[str, int] = defaultdict(
        int,
        {
            "housing_fund": sum(
                item.get("record_type") == "housing_fund" for item in working.values()
            )
        },
    )
    pending_optional_sequences: dict[str, dict[str, int]] = {}
    physical_tables = [
        (page, table)
        for page in getattr(parse_result, "pages", None) or ()
        for table in getattr(page, "tables", None) or ()
    ]
    continuation_check = getattr(parse_result, "tables_continue", None)
    terminal_public_headers: dict[int, int] = {}
    seen_public_sequence_rows: set[tuple[str, int, int, int]] = set()

    def report_pending(record_type: str) -> None:
        pending = pending_optional_sequences.pop(record_type, None)
        if pending is None:
            return
        sequence = int(pending["sequence"])
        _report_optional_public_continuation_missing(
            parse_result,
            dataset=_PUBLIC_FINAL_DATASETS[record_type],
            target_record_id=stable_record_id("public_record", record_type, sequence),
            sequence=sequence,
            source_refs=working.get((record_type, sequence), {}).get("source_refs", []),
        )

    def header_match(
        row: tuple[str, ...],
    ) -> tuple[Mapping[str, Any] | None, dict[str, int], Mapping[str, Any] | None]:
        exact = [
            (layout, slots)
            for layout in _PUBLIC_CANONICAL_LAYOUTS
            if (slots := _exact_public_header_slots(row, layout)) is not None
        ]
        diagnostic = next(
            (
                layout
                for layout in _PUBLIC_CANONICAL_LAYOUTS
                if all(
                    role in _canonical_header_slots(row, layout["aliases"])
                    for role in layout["signature"]
                )
            ),
            None,
        )
        if len(exact) != 1:
            return None, {}, diagnostic
        return exact[0][0], exact[0][1], diagnostic

    for physical_index, (page, table) in enumerate(physical_tables):
        if not canonical_table_owned_by(
            parse_result,
            page,
            table,
            "public_information",
        ):
            continue
        table_id = str(getattr(table, "table_id", "") or "")
        if table_id in compound_housing_tables:
            continue
        rows = tuple(tuple(row) for row in _table_rows(table))
        if not rows:
            continue
        if _conserve_issue_only_public_table(
            parse_result,
            page=page,
            table=table,
            rows=rows,
            evidence_counts=evidence_counts,
        ):
            continue

        last_header_index: int | None = None
        cursor = 0
        while cursor < len(rows):
            header_index = cursor
            header = rows[header_index]
            matched, slots, diagnostic = header_match(header)
            if matched is None:
                if diagnostic is None:
                    cursor += 1
                    continue
                _report_header_graph_failure(
                    parse_result,
                    dataset=_PUBLIC_FINAL_DATASETS[str(diagnostic["record_type"])],
                    page=page,
                    table=table,
                    row_index=header_index,
                    row=header,
                )
                if header_index + 1 < len(rows):
                    _report_public_lattice_row_failure(
                        parse_result,
                        layout=diagnostic,
                        page=page,
                        table=table,
                        row_index=header_index + 1,
                        row=rows[header_index + 1],
                        slots=_canonical_header_slots(header, diagnostic["aliases"]),
                    )
                    cursor += 2
                else:
                    cursor += 1
                last_header_index = header_index
                terminal_public_headers[physical_index] = header_index
                continue

            matched_record_type = str(matched["record_type"])
            matched_boundary = str(matched.get("record_boundary") or "standalone")
            for pending_record_type in tuple(pending_optional_sequences):
                if not (
                    matched_record_type == pending_record_type
                    and matched_boundary == "continuation"
                ):
                    report_pending(pending_record_type)
            header_sealed = _public_header_lattice_is_sealed(
                table,
                row_index=header_index,
                width=len(header),
                evidence_counts=evidence_counts,
            )
            if not header_sealed or header_index + 1 >= len(rows):
                _report_header_graph_failure(
                    parse_result,
                    dataset=_PUBLIC_FINAL_DATASETS[matched_record_type],
                    page=page,
                    table=table,
                    row_index=header_index,
                    row=header,
                )
                if header_index + 1 < len(rows):
                    _report_public_lattice_row_failure(
                        parse_result,
                        layout=matched,
                        page=page,
                        table=table,
                        row_index=header_index + 1,
                        row=rows[header_index + 1],
                        slots=slots,
                    )
                    cursor += 2
                else:
                    cursor += 1
                last_header_index = header_index
                terminal_public_headers[physical_index] = header_index
                continue

            data_index = header_index + 1
            while data_index < len(rows):
                data_row = rows[data_index]
                next_exact, _next_slots, next_diagnostic = header_match(data_row)
                if next_exact is not None or next_diagnostic is not None:
                    break
                if not any(_clean(cell) for cell in data_row):
                    data_index += 1
                    continue
                if not _public_data_lattice_is_sealed(
                    table,
                    row_index=data_index,
                    row=data_row,
                    width=len(header),
                    evidence_counts=evidence_counts,
                ):
                    _report_public_lattice_row_failure(
                        parse_result,
                        layout=matched,
                        page=page,
                        table=table,
                        row_index=data_index,
                        row=data_row,
                        slots=slots,
                    )
                    data_index += 1
                    if matched.get("sequence_optional"):
                        break
                    continue

                if matched.get("sequence_optional"):
                    record_type = matched_record_type
                    boundary = matched_boundary
                    if boundary == "start":
                        optional_sequence_counters[record_type] += 1
                        sequence = optional_sequence_counters[record_type]
                        pending_optional_sequences[record_type] = {
                            "sequence": sequence,
                            "logical_page": int(getattr(page, "page_number", 0) or 0),
                        }
                    elif boundary == "continuation":
                        pending = pending_optional_sequences.get(record_type)
                        if pending is None:
                            _report_unowned_optional_public_fragment(
                                parse_result,
                                dataset=_PUBLIC_FINAL_DATASETS[record_type],
                                row=data_row,
                                page=page,
                                table=table,
                                row_index=data_index,
                            )
                            break
                        logical_page = int(getattr(page, "page_number", 0) or 0)
                        if not _public_record_continuation_allowed(
                            parse_result,
                            int(pending["logical_page"]),
                            logical_page,
                        ):
                            report_pending(record_type)
                            _report_unowned_optional_public_fragment(
                                parse_result,
                                dataset=_PUBLIC_FINAL_DATASETS[record_type],
                                row=data_row,
                                page=page,
                                table=table,
                                row_index=data_index,
                            )
                            break
                        sequence = int(pending["sequence"])
                    else:
                        optional_sequence_counters[record_type] += 1
                        sequence = optional_sequence_counters[record_type]
                    record_key: tuple[Any, ...] = (record_type, sequence)
                    target_id = stable_record_id("public_record", record_type, sequence)
                else:
                    raw_sequence = _slot_value(data_row, slots, "sequence")
                    sequence_match = re.fullmatch(r"[1-9]\d{0,2}", _clean(raw_sequence))
                    if sequence_match is None:
                        _report_unkeyed_business_row(
                            parse_result,
                            dataset=_PUBLIC_FINAL_DATASETS[matched_record_type],
                            row=data_row,
                            page=page,
                            table=table,
                            row_index=data_index,
                        )
                        data_index += 1
                        continue
                    sequence = int(sequence_match.group(0))
                    owner_header = header_index
                    record_part = str(matched.get("record_part") or "")
                    physical_row_owner = (
                        matched_record_type,
                        physical_index,
                        owner_header,
                        sequence,
                    )
                    if physical_row_owner in seen_public_sequence_rows:
                        _report_public_duplicate_sequence_row(
                            parse_result,
                            layout=matched,
                            slots=slots,
                            page=page,
                            table=table,
                            row_index=data_index,
                            row=data_row,
                            sequence=sequence,
                            physical_table_index=physical_index,
                        )
                        data_index += 1
                        continue
                    seen_public_sequence_rows.add(physical_row_owner)
                    record_key = (
                        matched_record_type,
                        int(getattr(page, "page_number", 0) or 0),
                        table_id,
                        physical_index,
                        owner_header,
                        sequence,
                    )
                    target_id = stable_record_id("public_record", *record_key)
                    if record_part == "detail":
                        same_table_candidates = [
                            key
                            for key, item in working.items()
                            if item.get("record_type") == matched_record_type
                            and item.get("sequence") == sequence
                            and item.get("_public_instance_table_id") == table_id
                            and item.get("_public_instance_physical_index") == physical_index
                            and item.get("_public_instance_page")
                            == int(getattr(page, "page_number", 0) or 0)
                            and item.get("_public_instance_header_index") == last_header_index
                            and "base" in (item.get("_public_record_parts") or ())
                        ]
                        candidates = same_table_candidates
                        if not candidates and physical_index > 0:
                            previous_page, previous_table = physical_tables[physical_index - 1]
                            previous_table_id = str(getattr(previous_table, "table_id", "") or "")
                            previous_page_number = int(
                                getattr(previous_page, "page_number", 0) or 0
                            )
                            current_page_number = int(getattr(page, "page_number", 0) or 0)
                            approved = bool(
                                canonical_table_owned_by(
                                    parse_result,
                                    previous_page,
                                    previous_table,
                                    "public_information",
                                )
                                and callable(continuation_check)
                                and continuation_check(previous_table_id, table_id) is True
                                and _public_record_continuation_allowed(
                                    parse_result,
                                    previous_page_number,
                                    current_page_number,
                                )
                            )
                            if approved:
                                terminal_header = terminal_public_headers.get(physical_index - 1, -1)
                                candidates = [
                                    key
                                    for key, item in working.items()
                                    if item.get("record_type") == matched_record_type
                                    and item.get("sequence") == sequence
                                    and item.get("_public_instance_table_id") == previous_table_id
                                    and item.get("_public_instance_physical_index") == physical_index - 1
                                    and item.get("_public_instance_page") == previous_page_number
                                    and item.get("_public_instance_header_index") == terminal_header
                                    and "base" in (item.get("_public_record_parts") or ())
                                ]
                        if len(candidates) == 1:
                            record_key = candidates[0]
                            target_id = str(working[record_key]["public_record_id"])
                        else:
                            _report_public_join_failure(
                                parse_result,
                                layout=matched,
                                page=page,
                                table=table,
                                row_index=data_index,
                                row=data_row,
                                sequence=sequence,
                                target_record_id=target_id,
                            )

                _consume_public_canonical_row(
                    parse_result,
                    working,
                    page=page,
                    table=table,
                    layout=matched,
                    slots=slots,
                    data_row=data_row,
                    row_index=data_index,
                    sequence=sequence,
                    record_key=record_key,
                    target_id=target_id,
                )
                item = working[record_key]
                if not matched.get("sequence_optional"):
                    item.setdefault(
                        "_public_instance_page",
                        int(getattr(page, "page_number", 0) or 0),
                    )
                    item.setdefault("_public_instance_table_id", table_id)
                    item.setdefault("_public_instance_physical_index", physical_index)
                    item.setdefault("_public_instance_header_index", header_index)
                    part = str(matched.get("record_part") or "standalone")
                    parts = item.setdefault("_public_record_parts", [])
                    if part not in parts:
                        parts.append(part)
                if matched.get("sequence_optional") and matched.get("record_boundary") == "continuation":
                    pending_optional_sequences.pop(matched_record_type, None)
                data_index += 1
                if matched.get("sequence_optional"):
                    break

            last_header_index = header_index
            terminal_public_headers[physical_index] = header_index
            cursor = max(data_index, header_index + 1)

    for record_type in tuple(pending_optional_sequences):
        report_pending(record_type)

    records: list[dict[str, Any]] = []
    authority_fields = {
        "tax_arrears": "tax_authority",
        "civil_judgment": "filing_court",
        "enforcement": "court",
        "administrative_penalty": "authority",
        "housing_fund": "employer",
        "professional_qualification": "issuing_authority",
        "award": "authority",
    }
    internal = {
        "public_record_id",
        "sequence",
        "record_type",
        "source",
        "source_refs",
        "source_refs_by_field",
        "confidence",
    }
    ordered_items = sorted(
        working.values(),
        key=lambda item: (
            str(item.get("record_type") or ""),
            int(item.get("sequence") or 0),
            str(item.get("public_record_id") or ""),
        ),
    )
    for item in ordered_items:
        record_type = str(item["record_type"])
        content = {
            key: value
            for key, value in item.items()
            if key not in internal and not key.startswith("_") and key != "canonical_raw"
        }
        for field_name in item.get("_source_absent_fields", []):
            content.setdefault(field_name, None)
        if record_type in {"tax_arrears", "civil_judgment", "enforcement", "administrative_penalty", "housing_fund"}:
            content["reporting_amount_currency"] = "CNY"
            content["reporting_amount_unit"] = "yuan"
        if "cause" in item:
            content["cause_status"] = "reported"
        elif "cause" in item.get("_source_absent_fields", []):
            content["cause_status"] = "not_reported"
        if "administrative_review_result" in item:
            content["administrative_review_result_status"] = "reported"
        elif "administrative_review_result" in item.get("_source_absent_fields", []):
            content["administrative_review_result_status"] = "not_reported"
        published_item = {
            key: value
            for key, value in item.items()
            if not key.startswith("_public_instance") and key != "_public_record_parts"
        }
        record = {
            **published_item,
            "authority": item.get(authority_fields[record_type]),
            "start_date": item.get("filing_date") or item.get("effective_date"),
            "end_date": item.get("closure_date") or item.get("end_date"),
            "content": json.dumps(content, ensure_ascii=False, sort_keys=True),
        }
        records.append(record)
    return records


# Employment cells use finite PBOC code-list descriptions.  These are used
# only to disambiguate OCR cells whose printed column boundaries collapsed;
# arbitrary text is never coerced into one of these values.
_EMPLOYER_TYPES = (
    "机关事业单位",
    "国有企业",
    "集体企业",
    "外资企业",
    "私营企业",
    "民营企业",
    "个体工商户",
    "个体、私营企业",
    "其他（包括三资企业、民营企业、民间团体等）",
    "未知",
)
_EMPLOYMENT_INDUSTRIES = (
    "农、林、牧、渔业",
    "采矿业",
    "制造业",
    "电力、燃气及水的生产和供应业",
    "建筑业",
    "交通运输、仓储和邮政业",
    "信息传输、计算机服务和软件业",
    "批发和零售业",
    "住宿和餐饮业",
    "金融业",
    "房地产业",
    "租赁和商务服务业",
    "科学研究、技术服务和地质勘查业",
    "水利、环境和公共设施管理业",
    "居民服务和其他服务业",
    "教育",
    "卫生、社会保障和社会福利业",
    "文化、体育和娱乐业",
    "公共管理和社会组织",
    "国际组织",
    "未知",
)
_EMPLOYMENT_OCCUPATIONS = (
    "国家机关、党群组织、企业、事业单位负责人",
    "专业技术人员",
    "办事人员和有关人员",
    "商业、服务业人员",
    "农、林、牧、渔、水利业生产人员",
    "生产、运输设备操作人员及有关人员",
    "军人",
    "不便分类的其他从业人员",
    "未知",
)
_EMPLOYMENT_POSITIONS = ("高级领导", "中级领导", "一般员工", "其他", "未知")
_EMPLOYMENT_TITLES = ("高级", "中级", "初级", "无", "未知")
_EMPLOYMENT_DETAIL_VOCABULARIES = {
    "industry": _EMPLOYMENT_INDUSTRIES,
    "occupation": _EMPLOYMENT_OCCUPATIONS,
    "position": _EMPLOYMENT_POSITIONS,
    "professional_title": _EMPLOYMENT_TITLES,
}


def _canonical_header_slots(row: tuple[str, ...], aliases: Mapping[str, tuple[str, ...]]) -> dict[str, int]:
    """Map semantic roles to distinct physical columns in a printed header."""
    candidates: dict[str, int] = {}
    by_column: defaultdict[int, list[str]] = defaultdict(list)
    for role, labels in aliases.items():
        for column, cell in enumerate(row):
            text = _compact(cell)
            if text and any(_compact(label) in text for label in labels):
                candidates[role] = column
                by_column[column].append(role)
                break
    # A single OCR blob containing several labels is not a column graph.
    duplicate_columns = {column for column, roles in by_column.items() if len(roles) > 1}
    return {role: column for role, column in candidates.items() if column not in duplicate_columns}


def _header_role_columns(row: tuple[str, ...], aliases: Mapping[str, tuple[str, ...]]) -> dict[str, int]:
    """Return observed role columns without pretending merged columns are distinct."""

    columns: dict[str, int] = {}
    for role, labels in aliases.items():
        for column, cell in enumerate(row):
            text = _compact(cell)
            if text and any(_compact(label) in text for label in labels):
                columns[role] = column
                break
    return columns


def _employment_signature(value: Any) -> str:
    """Ignore presentation whitespace when matching one finite employment value."""

    return re.sub(r"\s+", "", str(value or ""))


def _finite_employment_value(value: Any, vocabulary: Iterable[str]) -> str | None:
    """Return a canonical finite value only for a unique exact glyph signature."""

    marker = _employment_signature(value)
    if not marker:
        return None
    matches = [candidate for candidate in vocabulary if _employment_signature(candidate) == marker]
    return matches[0] if len(matches) == 1 else None


def _employment_address_has_cross_field_contamination(record: Mapping[str, Any]) -> bool:
    """Detect exact business-field spans copied into an employer address.

    The address is withheld as a whole.  Removing the matching span would
    invent a cell boundary which the OCR evidence did not preserve.
    """

    address = str(record.get("employer_address") or "")
    address_marker = _employment_signature(address)
    if not address_marker:
        return False
    employer_marker = _employment_signature(record.get("employer"))
    department_suffixes = (
        "销售部",
        "营业部",
        "门市部",
        "办公室",
        "办事处",
        "项目部",
    )
    # A printed workplace address may legitimately end with the full employer
    # name and one exact department suffix.  Keep that source value only when
    # an address-shaped prefix precedes the employer; a bare organization name
    # is not promoted into an address by this exception.
    employer_is_address_suffix = bool(
        employer_marker
        and any(
            address_marker.endswith(employer_marker + suffix)
            and len(address_marker[: -len(employer_marker + suffix)]) >= 3
            and re.search(
                r"(?:省|市|区|县|镇|乡|街|路|道|巷|弄|号|楼|村|社区)",
                address_marker[: -len(employer_marker + suffix)],
            )
            for suffix in department_suffixes
        )
    )
    if len(employer_marker) >= 3 and employer_marker in address_marker and not employer_is_address_suffix:
        return True

    # A merged/truncated cell can end part-way through the same record's legal
    # employer name.  Require a long prefix owned by this exact record; short
    # generic fragments such as a district or ``公司`` are never sufficient.
    minimum_prefix = max(6, (len(employer_marker) + 1) // 2)
    if len(employer_marker) >= 8 and len(address_marker) > minimum_prefix:
        if any(
            address_marker.endswith(employer_marker[:prefix_length])
            for prefix_length in range(len(employer_marker) - 1, minimum_prefix - 1, -1)
        ):
            return True

    # Position and title values are short, so require an exact suffix token;
    # an interior occurrence such as ``中级人民法院`` may be legitimate address
    # text.  Include both extracted values and the finite printed vocabulary
    # so contamination is still recognized when the corresponding detail cell
    # was itself unreadable.
    role_tokens = {
        str(record.get("position") or ""),
        str(record.get("professional_title") or ""),
        *_EMPLOYMENT_POSITIONS,
        *_EMPLOYMENT_TITLES,
    }
    return any(
        token_marker and address_marker != token_marker and address_marker.endswith(token_marker)
        for token in role_tokens
        if (token_marker := _employment_signature(token))
    )


def _enforce_employment_record_contracts(
    parse_result: Any,
    records: Iterable[dict[str, Any]],
) -> None:
    """Apply cross-field contracts after any employment record merge plane."""

    for record in records:
        if not _employment_address_has_cross_field_contamination(record):
            continue
        address = str(record.get("employer_address") or "")
        refs = record.get("source_refs_by_field", {}).get("employer_address") or ()
        source_ref = next(
            (dict(ref) for ref in refs if isinstance(ref, Mapping)),
            dict((record.get("source_refs") or [{}])[0]),
        )
        target_record_id = str(
            record.get("employment_record_id") or record.get("record_id") or "employment_record:unresolved"
        )
        _reject_exact_observation(
            parse_result,
            record,
            dataset="employment_records",
            target_record_id=target_record_id,
            field_name="employer_address",
            raw=address,
            source_ref=source_ref,
            parser_stage="candidate_b_employment_record_contract",
        )


def _finite_values_in_cluster(
    value: Any,
    vocabularies: Mapping[str, Iterable[str]],
) -> dict[str, str]:
    """Find uniquely owned finite values inside one OCR-merged business cell.

    A glyph sequence shared by multiple logical roles (for example ``未知``)
    is intentionally left unresolved.  For a role with nested candidates, the
    longest observed candidate wins only when it is unique.
    """

    marker = _employment_signature(value)
    if not marker:
        return {}
    candidates: dict[str, list[tuple[str, str]]] = {}
    for role, vocabulary in vocabularies.items():
        observed = [
            (candidate, _employment_signature(candidate))
            for candidate in vocabulary
            if _employment_signature(candidate) in marker
        ]
        if not observed:
            continue
        longest = max(len(signature) for _candidate, signature in observed)
        maximal = [item for item in observed if len(item[1]) == longest]
        if len(maximal) == 1:
            candidates[role] = maximal
    signatures_to_roles: defaultdict[str, list[str]] = defaultdict(list)
    for role, ((_, signature),) in candidates.items():
        signatures_to_roles[signature].append(role)
    return {
        role: candidate
        for role, ((candidate, signature),) in candidates.items()
        if len(signatures_to_roles[signature]) == 1
        and not any(
            signature != other_signature
            and signature in other_signature
            and marker.count(signature) <= marker.count(other_signature)
            for other_role, ((_, other_signature),) in candidates.items()
            if other_role != role
        )
    }


def _employment_cluster_residue(value: Any, owned_values: Iterable[Any]) -> str:
    """Return glyphs in one cluster not owned by selected exact values."""

    residue = _employment_signature(value)
    for owned_value in owned_values:
        signature = _employment_signature(owned_value)
        if signature and signature in residue:
            residue = residue.replace(signature, "", 1)
    return residue


_EMPLOYMENT_SECTION_HEADING_RE = re.compile(
    r"^(?:(?:[（(][〇零一二三四五六七八九十百]{1,5}[）)])|"
    r"[〇零一二三四五六七八九十百]{1,5})?职业信息$"
)


def _employment_source_owner(page: Any, table: Any) -> tuple[int, int] | None:
    """Return one canonical source owner for a PBOC employment table.

    Employment is a subsection of the PBOC personal-information section, but
    it may finish on the physical page whose next top-level owner is
    ``信息概要``.  Page number and encounter order are therefore not authority.
    A detached canonical profile page owns the table directly; a registered
    summary-transition page owns it only when one sealed ``职业信息`` heading is
    immediately above the table and the sealed summary heading is below it.
    """

    metadata = getattr(table, "metadata", None)
    table_id = str(getattr(table, "table_id", "") or "")
    page_template = str(getattr(page, "canonical_template_id", "") or "")
    if not isinstance(metadata, Mapping) or not table_id:
        return None
    table_template = str(metadata.get("canonical_template_id") or "")
    if page_template != table_template or page_template not in {
        "report_header_and_identity",
        "information_summary",
    }:
        return None
    source_logical_page = metadata.get("source_logical_page")
    source_page = metadata.get("source_page")
    if (
        not isinstance(source_logical_page, int)
        or isinstance(source_logical_page, bool)
        or source_logical_page <= 0
        or not isinstance(source_page, int)
        or isinstance(source_page, bool)
        or source_page <= 0
    ):
        return None
    fragment_pages = getattr(page, "canonical_fragment_logical_pages", None)
    transform = getattr(page, "coordinate_transform", None)
    source_pages = transform.get("source_page_numbers") if isinstance(transform, Mapping) else None
    if (
        not isinstance(fragment_pages, (list, tuple))
        or not fragment_pages
        or len(set(fragment_pages)) != len(fragment_pages)
        or source_logical_page not in fragment_pages
        or not isinstance(source_pages, (list, tuple))
        or not source_pages
        or len(set(source_pages)) != len(source_pages)
        or source_page not in source_pages
    ):
        return None
    if page_template == "report_header_and_identity":
        return source_logical_page, source_page

    table_bbox = _exact_geometry_bbox(getattr(table, "bbox", None))
    if table_bbox is None:
        return None
    employment_headings: list[tuple[float, tuple[str, ...]]] = []
    summary_headings: list[float] = []
    for text_block in getattr(page, "texts", None) or ():
        content = _compact(
            getattr(text_block, "content", "")
            or getattr(text_block, "text", "")
            or ""
        )
        bbox = _exact_geometry_bbox(getattr(text_block, "bbox", None))
        evidence_ids = tuple(
            dict.fromkeys(
                str(value)
                for value in (getattr(text_block, "evidence_ids", None) or ())
                if str(value or "")
            )
        )
        block_logical_page = int(
            getattr(text_block, "source_logical_page", 0) or source_logical_page
        )
        if bbox is None or not evidence_ids or block_logical_page != source_logical_page:
            continue
        if _EMPLOYMENT_SECTION_HEADING_RE.fullmatch(content):
            employment_headings.append((bbox[3], evidence_ids))
        if canonical_registered_section_heading(content) == "信息概要":
            summary_headings.append(bbox[1])
    owners = [
        (bottom, evidence_ids)
        for bottom, evidence_ids in employment_headings
        if bottom <= table_bbox[1]
        and any(summary_top >= table_bbox[3] for summary_top in summary_headings)
    ]
    if len(owners) != 1 or len(summary_headings) != 1:
        return None
    owner_evidence = owners[0][1]
    if len(owner_evidence) != len(set(owner_evidence)):
        return None
    return source_logical_page, source_page


def _employment_geometry_bands(
    geometry: Mapping[str, Any],
    key: str,
) -> dict[int, tuple[float, float]] | None:
    """Read indexed bands from runtime mappings or sealed bbox arrays."""

    raw_bands = geometry.get(key)
    if not isinstance(raw_bands, list) or not raw_bands:
        return None
    output: dict[int, tuple[float, float]] = {}
    for ordinal, raw_band in enumerate(raw_bands):
        if isinstance(raw_band, Mapping):
            index = raw_band.get("index")
            lower = raw_band.get("y0" if key == "row_bands" else "x0")
            upper = raw_band.get("y1" if key == "row_bands" else "x1")
        else:
            bbox = _exact_geometry_bbox(raw_band)
            if bbox is None:
                return None
            index = ordinal
            lower, upper = (bbox[1], bbox[3]) if key == "row_bands" else (bbox[0], bbox[2])
        if not isinstance(index, int) or isinstance(index, bool) or index < 0:
            return None
        try:
            lower_value = float(lower)
            upper_value = float(upper)
        except (TypeError, ValueError):
            return None
        if (
            not math.isfinite(lower_value)
            or not math.isfinite(upper_value)
            or upper_value <= lower_value
            or index in output
        ):
            return None
        output[index] = (lower_value, upper_value)
    if set(output) != set(range(len(output))):
        return None
    ordered = [output[index] for index in range(len(output))]
    if any(left[1] > right[0] for left, right in zip(ordered, ordered[1:], strict=False)):
        return None
    return output


def _employment_bbox_matches(
    observed: tuple[float, float, float, float],
    expected: tuple[float, float, float, float],
) -> bool:
    """Compare two source boxes with scale-relative serialization tolerance."""

    return all(
        math.isclose(left, right, rel_tol=1e-5, abs_tol=max(abs(left), abs(right), 1.0) * 1e-7)
        for left, right in zip(observed, expected, strict=True)
    )


def _employment_exact_lattice_owner(
    table: Any,
    *,
    row: int,
    column: int,
) -> tuple[tuple[float, float, float, float], tuple[str, ...]] | None:
    """Return one exact employment cell or declared merged-cell owner."""

    geometry = _native_table_geometry(table)
    if geometry is None:
        return None
    row_bands = _employment_geometry_bands(geometry, "row_bands")
    column_bands = _employment_geometry_bands(geometry, "col_bands")
    grids = tuple(
        geometry.get(key)
        for key in (
            "cell_bboxes",
            "cell_geometry_status",
            "cell_evidence_ids",
            "cell_token_ids",
        )
    )
    if (
        row_bands is None
        or column_bands is None
        or row not in row_bands
        or column not in column_bands
        or any(
            not isinstance(grid, list)
            or row >= len(grid)
            or not isinstance(grid[row], list)
            or column >= len(grid[row])
            for grid in grids
        )
    ):
        return None
    bboxes, statuses, evidence_grid, token_grid = grids
    spans = geometry.get("cell_spans")
    if not isinstance(spans, list):
        return None
    matching_spans = [
        span
        for span in spans
        if isinstance(span, Mapping)
        and span.get("row") == row
        and span.get("col") == column
    ]
    covering_spans = [
        span
        for span in spans
        if isinstance(span, Mapping)
        and isinstance(span.get("row"), int)
        and isinstance(span.get("col"), int)
        and isinstance(span.get("row_span"), int)
        and isinstance(span.get("col_span"), int)
        and span["row"] <= row < span["row"] + span["row_span"]
        and span["col"] <= column < span["col"] + span["col_span"]
    ]
    if len(matching_spans) > 1 or len(covering_spans) > 1:
        return None
    last_row = row
    last_column = column
    if matching_spans:
        span = matching_spans[0]
        row_span = span.get("row_span")
        column_span = span.get("col_span")
        if (
            not isinstance(row_span, int)
            or isinstance(row_span, bool)
            or not isinstance(column_span, int)
            or isinstance(column_span, bool)
            or row_span < 1
            or column_span < 1
        ):
            return None
        last_row = row + row_span - 1
        last_column = column + column_span - 1
        if last_row not in row_bands or last_column not in column_bands:
            return None
    elif covering_spans:
        # This is a derived covered slot, not an independent owner.
        return None
    observed_bbox = _exact_geometry_bbox(bboxes[row][column])
    raw_evidence = evidence_grid[row][column]
    raw_tokens = token_grid[row][column]
    expected_bbox = (
        column_bands[column][0],
        row_bands[row][0],
        column_bands[last_column][1],
        row_bands[last_row][1],
    )
    evidence_ids = tuple(
        dict.fromkeys(
            str(value)
            for value in raw_evidence
            if str(value or "")
        )
    ) if isinstance(raw_evidence, list) else ()
    token_ids = tuple(
        dict.fromkeys(
            str(value)
            for value in raw_tokens
            if str(value or "")
        )
    ) if isinstance(raw_tokens, list) else ()
    if (
        observed_bbox is None
        or not _employment_bbox_matches(observed_bbox, expected_bbox)
        or str(statuses[row][column] or "") != "exact"
        or not evidence_ids
        or len(evidence_ids) != len(token_ids)
        or set(evidence_ids) != set(token_ids)
    ):
        return None
    for covered_row in range(row, last_row + 1):
        for covered_column in range(column, last_column + 1):
            if (covered_row, covered_column) == (row, column):
                continue
            if any(
                covered_row >= len(grid)
                or not isinstance(grid[covered_row], list)
                or covered_column >= len(grid[covered_row])
                for grid in grids
            ):
                return None
            if (
                bboxes[covered_row][covered_column] is not None
                or str(statuses[covered_row][covered_column] or "") != "derived"
                or evidence_grid[covered_row][covered_column] not in ([], None)
                or token_grid[covered_row][covered_column] not in ([], None)
            ):
                return None
    return observed_bbox, evidence_ids


def _employment_exact_covered_lattice_owner(
    table: Any,
    *,
    row: int,
    column: int,
) -> tuple[tuple[float, float, float, float], tuple[str, ...]] | None:
    """Return the unique exact span owner for one derived covered slot."""

    geometry = _native_table_geometry(table)
    spans = geometry.get("cell_spans") if geometry is not None else None
    if not isinstance(spans, list):
        return None
    covering: list[tuple[int, int]] = []
    for span in spans:
        if not isinstance(span, Mapping):
            continue
        span_row = span.get("row")
        span_column = span.get("col")
        row_span = span.get("row_span")
        column_span = span.get("col_span")
        if (
            not isinstance(span_row, int)
            or isinstance(span_row, bool)
            or not isinstance(span_column, int)
            or isinstance(span_column, bool)
            or not isinstance(row_span, int)
            or isinstance(row_span, bool)
            or not isinstance(column_span, int)
            or isinstance(column_span, bool)
            or row_span < 1
            or column_span < 1
        ):
            return None
        if (
            span_row <= row < span_row + row_span
            and span_column <= column < span_column + column_span
            and (span_row, span_column) != (row, column)
        ):
            covering.append((span_row, span_column))
    if len(covering) != 1:
        return None
    return _employment_exact_lattice_owner(
        table,
        row=covering[0][0],
        column=covering[0][1],
    )


def _employment_exact_empty_lattice_slot(
    table: Any,
    *,
    row: int,
    column: int,
) -> bool:
    """Authenticate one exact empty ordinal slot without inventing evidence."""

    geometry = _native_table_geometry(table)
    if geometry is None:
        return False
    row_bands = _employment_geometry_bands(geometry, "row_bands")
    column_bands = _employment_geometry_bands(geometry, "col_bands")
    grids = tuple(
        geometry.get(key)
        for key in (
            "cell_bboxes",
            "cell_geometry_status",
            "cell_evidence_ids",
            "cell_token_ids",
        )
    )
    if (
        row_bands is None
        or column_bands is None
        or row not in row_bands
        or column not in column_bands
        or any(
            not isinstance(grid, list)
            or row >= len(grid)
            or not isinstance(grid[row], list)
            or column >= len(grid[row])
            for grid in grids
        )
    ):
        return False
    bboxes, statuses, evidence_grid, token_grid = grids
    bbox = _exact_geometry_bbox(bboxes[row][column])
    expected = (
        column_bands[column][0],
        row_bands[row][0],
        column_bands[column][1],
        row_bands[row][1],
    )
    spans = geometry.get("cell_spans")
    return bool(
        bbox is not None
        and _employment_bbox_matches(bbox, expected)
        and str(statuses[row][column] or "") == "exact"
        and evidence_grid[row][column] in ([], None)
        and token_grid[row][column] in ([], None)
        and isinstance(spans, list)
        and not any(
            isinstance(span, Mapping)
            and isinstance(span.get("row"), int)
            and isinstance(span.get("col"), int)
            and isinstance(span.get("row_span"), int)
            and isinstance(span.get("col_span"), int)
            and span["row"] <= row < span["row"] + span["row_span"]
            and span["col"] <= column < span["col"] + span["col_span"]
            for span in spans
        )
    )


def _employment_inferred_sequence_row_owned(
    table: Any,
    *,
    row_index: int,
    row: tuple[str, ...],
    sequence_column: int,
    cluster_column: int | None,
) -> bool:
    """Prove one inferred ordinal from its exact local row, never its values."""

    raw_sequence = _clean(row[sequence_column] if sequence_column < len(row) else "")
    sequence_owner = _employment_exact_lattice_owner(
        table,
        row=row_index,
        column=sequence_column,
    )
    covered_sequence_owner = _employment_exact_covered_lattice_owner(
        table,
        row=row_index,
        column=sequence_column,
    )
    if sequence_owner is None and not (
        covered_sequence_owner is not None
        or (
            not raw_sequence
            and _employment_exact_empty_lattice_slot(
                table,
                row=row_index,
                column=sequence_column,
            )
        )
    ):
        return False
    business_columns = {
        column
        for column, value in enumerate(row)
        if column != sequence_column and _clean(value)
    }
    if cluster_column is not None and cluster_column != sequence_column and _clean(
        row[cluster_column] if cluster_column < len(row) else ""
    ):
        business_columns.add(cluster_column)
    if not business_columns:
        return False
    business_owners = [
        _employment_exact_lattice_owner(
            table,
            row=row_index,
            column=column,
        )
        for column in sorted(business_columns)
    ]
    if any(owner is None for owner in business_owners):
        return False
    evidence_ids = [
        evidence_id
        for owner in business_owners
        if owner is not None
        for evidence_id in owner[1]
    ]
    if sequence_owner is not None:
        evidence_ids.extend(sequence_owner[1])
    elif covered_sequence_owner is not None:
        evidence_ids.extend(covered_sequence_owner[1])
    return len(evidence_ids) == len(set(evidence_ids))


def _employment_exact_header_owners(
    table: Any,
    *,
    row_index: int,
    slots: Mapping[str, int],
) -> dict[int, tuple[tuple[float, float, float, float], tuple[str, ...]]] | None:
    """Authenticate distinct header columns and exact declared merged spans."""

    columns = set(slots.values())
    if not columns:
        return None
    owners: dict[int, tuple[tuple[float, float, float, float], tuple[str, ...]]] = {}
    for column in columns:
        owner = _employment_exact_lattice_owner(
            table,
            row=row_index,
            column=column,
        )
        if owner is None:
            return None
        owners[column] = owner
    evidence_ids = [
        evidence_id
        for _bbox, owner_evidence in owners.values()
        for evidence_id in owner_evidence
    ]
    if len(evidence_ids) != len(set(evidence_ids)):
        return None
    return owners


def _employment_exact_header_slots(
    page: Any,
    table: Any,
    *,
    row_index: int,
    slots: Mapping[str, int],
) -> dict[str, int] | None:
    """Return a semantic employment header only from one owned exact lattice."""

    if _employment_source_owner(page, table) is None:
        return None
    return dict(slots) if _employment_exact_header_owners(
        table,
        row_index=row_index,
        slots=slots,
    ) is not None else None


def _employment_recovered_basic_header_slots(
    page: Any,
    table: Any,
    rows: list[list[str]],
    *,
    row_index: int,
    recovered: tuple[dict[str, int], dict[str, str]] | None,
) -> tuple[dict[str, int], dict[str, str]] | None:
    """Bind a damaged/blank ordinal header through exact local row ownership."""

    if recovered is None or _employment_source_owner(page, table) is None:
        return None
    slots, overflow = recovered
    business_slots = {role: column for role, column in slots.items() if role != "sequence"}
    owners = _employment_exact_header_owners(
        table,
        row_index=row_index,
        slots=business_slots,
    )
    if owners is None:
        return None
    sequence_column = slots.get("sequence")
    if not isinstance(sequence_column, int):
        return None
    # A damaged or blank ordinal label is not itself evidence.  Its lattice
    # column is authorized only when the local run contains at least two exact,
    # distinct, positive printed ordinals in that same column.
    ordinal_owners: list[tuple[int, tuple[str, ...]]] = []
    for candidate_row in range(row_index + 1, _employment_run_end(rows, row_index + 1)):
        sequence = _employment_row_sequence(
            tuple(rows[candidate_row]),
            sequence_column=sequence_column,
        )
        owner = _employment_exact_lattice_owner(
            table,
            row=candidate_row,
            column=sequence_column,
        )
        if sequence is not None and sequence > 0 and owner is not None:
            ordinal_owners.append((sequence, owner[1]))
    ordinals = [sequence for sequence, _evidence in ordinal_owners]
    ordinal_evidence = [
        evidence_id
        for _sequence, evidence in ordinal_owners
        for evidence_id in evidence
    ]
    if (
        len(ordinal_owners) < 2
        or len(ordinals) != len(set(ordinals))
        or len(ordinal_evidence) != len(set(ordinal_evidence))
        or set(ordinal_evidence)
        & {
            evidence_id
            for _bbox, evidence in owners.values()
            for evidence_id in evidence
        }
    ):
        return None
    return dict(slots), dict(overflow)


def _employment_collapsed_basic_header_slots(
    page: Any,
    table: Any,
    *,
    row_index: int,
    collapsed: tuple[int, int] | None,
) -> tuple[int, int] | None:
    """Bind a fully collapsed basic header to exact, disjoint source owners."""

    if collapsed is None or _employment_source_owner(page, table) is None:
        return None
    sequence_column, cluster_column = collapsed
    owners = _employment_exact_header_owners(
        table,
        row_index=row_index,
        slots={"sequence": sequence_column, "cluster": cluster_column},
    )
    return collapsed if owners is not None else None


def _recovered_employment_basic_header(
    row: tuple[str, ...], aliases: Mapping[str, tuple[str, ...]]
) -> tuple[dict[str, int], dict[str, str]] | None:
    """Recover only the canonical five-column header with a damaged ordinal label."""

    columns = _header_role_columns(row, aliases)
    business_roles = ("employer", "employer_type", "employer_address", "employer_phone")
    if not all(role in columns for role in business_roles):
        return None
    if [columns[role] for role in business_roles] != [1, 2, 3, 4]:
        return None
    sequence_header = _compact(row[0] if row else "")
    if sequence_header and "编" not in sequence_header and "号" not in sequence_header:
        return None
    columns["sequence"] = 0
    overflow: dict[str, str] = {}
    for role in business_roles:
        cell = _clean(row[columns[role]])
        residue = cell
        for label in aliases[role]:
            residue = residue.replace(label, " ")
        residue = _clean(residue)
        if residue:
            overflow[role] = residue
    return columns, overflow


def _collapsed_employment_basic_header(row: tuple[str, ...]) -> tuple[int, int] | None:
    """Recognize the closed five-role header after OCR collapsed its columns.

    The four business labels may appear in the OCR traversal order rather than
    their visual left-to-right order.  Recognition therefore depends on the
    exact finite label set and rejects every extra glyph; values are assigned
    later by their field contracts, never by this traversal order.
    """

    labels = ("工作单位", "单位性质", "单位地址", "单位电话")
    populated = [(index, _compact(value)) for index, value in enumerate(row) if _compact(value)]
    if not populated:
        return None
    sequence_columns = [index for index, value in populated if value == "编号"]
    cluster_candidates: list[tuple[int, str]] = []
    for index, value in populated:
        residue = value
        if residue.startswith("编号"):
            residue = residue.removeprefix("编号")
        if all(residue.count(label) == 1 for label in labels):
            for label in labels:
                residue = residue.replace(label, "", 1)
            if not residue:
                cluster_candidates.append((index, value))
    if len(cluster_candidates) != 1:
        return None
    cluster_column, cluster_value = cluster_candidates[0]
    if cluster_value.startswith("编号"):
        if len(populated) != 1:
            return None
        return cluster_column, cluster_column
    if len(sequence_columns) != 1 or len(populated) != 2:
        return None
    return sequence_columns[0], cluster_column


def _clustered_employment_detail_header(
    row: tuple[str, ...], aliases: Mapping[str, tuple[str, ...]]
) -> dict[str, int] | None:
    """Recognize the canonical detail layout after OCR merged its role columns."""

    columns = _header_role_columns(row, aliases)
    if not {
        "sequence",
        "industry",
        "occupation",
        "entry_year",
        "professional_title",
        "information_updated_date",
    } <= set(columns):
        return None
    if columns["sequence"] != 0:
        return None
    main_column = columns["industry"]
    secondary_column = columns["entry_year"]
    updated_column = columns["information_updated_date"]
    if columns["occupation"] != main_column or columns["professional_title"] != secondary_column:
        return None
    if not (0 < main_column < secondary_column < updated_column):
        return None
    # The position label is frequently the only damaged label in this exact
    # three-role cluster.  Infer its slot, never its value.
    position_column = columns.get("position")
    if position_column not in (None, secondary_column):
        return None
    return {
        "sequence": 0,
        "industry": main_column,
        "occupation": main_column,
        "entry_year": secondary_column,
        "professional_title": secondary_column,
        "position": secondary_column,
        "information_updated_date": updated_column,
    }


def _exact_fully_clustered_employment_detail_header(
    table: Any,
    *,
    row_index: int,
    row: tuple[str, ...],
    aliases: Mapping[str, tuple[str, ...]],
) -> dict[str, int] | None:
    """Recognize a complete detail header sealed in one exact merged cell.

    This is a physical-table exception, not a text fallback.  The ordinal
    header must remain an independent exact cell, every other canonical label
    must occur exactly once in one residue-free span, and that span must cover
    every remaining lattice column.  A partial, duplicate, or text-only header
    therefore stays unresolved.
    """

    if not row or _employment_signature(row[0]) != "编号":
        return None
    sequence_owner = _exact_native_table_cell(table, row=row_index, column=0)
    if sequence_owner is None:
        return None
    columns = _header_role_columns(row, aliases)
    required_roles = tuple(aliases)
    if set(columns) != set(required_roles) or columns.get("sequence") != 0:
        return None
    business_roles = tuple(role for role in required_roles if role != "sequence")
    cluster_columns = {columns[role] for role in business_roles}
    if len(cluster_columns) != 1:
        return None
    cluster_column = cluster_columns.pop()
    geometry = _native_table_geometry(table)
    column_bands = (
        _indexed_geometry_bands(
            geometry,
            "col_bands",
            lower_key="x0",
            upper_key="x1",
        )
        if geometry is not None
        else None
    )
    if column_bands is None or cluster_column <= 0:
        return None
    last_column = max(column_bands)
    if set(column_bands) != set(range(last_column + 1)) or cluster_column != 1:
        return None
    span = (1, last_column - cluster_column + 1)
    if _exact_native_table_span_owner(
        table,
        row=row_index,
        column=cluster_column,
        span=span,
    ) is None:
        return None
    residue = _employment_signature(row[cluster_column])
    for role in business_roles:
        label_signatures = {
            _employment_signature(label)
            for label in aliases[role]
            if _employment_signature(label)
        }
        matches = [label for label in label_signatures if residue.count(label) == 1]
        if len(matches) != 1:
            return None
        residue = residue.replace(matches[0], "", 1)
    if residue:
        return None
    return {
        role: 0 if role == "sequence" else cluster_column
        for role in aliases
    }


def _slot_value(row: tuple[str, ...], slots: Mapping[str, int], role: str) -> str:
    column = slots.get(role)
    return _clean(row[column]) if column is not None and column < len(row) else ""


def _sequence_value(row: tuple[str, ...], slots: Mapping[str, int]) -> int | None:
    value = _slot_value(row, slots, "sequence")
    match = re.fullmatch(r"\D*(\d{1,3})\D*", value)
    return int(match.group(1)) if match else None


def _employment_sequence_value(row: tuple[str, ...], slots: Mapping[str, int]) -> int | None:
    """Accept an exact ordinal or a watermark-duplicated identical ordinal."""

    sequence = _sequence_value(row, slots)
    if sequence is not None:
        return sequence
    value = _slot_value(row, slots, "sequence")
    tokens = re.findall(r"\d{1,3}", value)
    if len(tokens) >= 2 and len(set(tokens)) == 1:
        return int(tokens[0])
    return None


_PHONE_PRESENTATION_TRANSLATION = str.maketrans({"（": "(", "）": ")", "－": "-"})


def _canonical_nonmobile_phone(value: Any) -> str | None:
    """Return digits only for one complete, registered phone presentation.

    Separators are presentation syntax, not generic characters to delete.  A
    value must therefore match one finite layout before any punctuation is
    removed.  This prevents duplicate separators, unmatched parentheses, and
    arbitrary digit segmentation from manufacturing a plausible phone number.
    """

    raw = _clean(value).translate(_PHONE_PRESENTATION_TRANSLATION)
    if not raw or re.search(r"[A-Za-z\u3400-\u9fff]", raw):
        return None

    plain = re.fullmatch(r"\d{7,16}", raw)
    if plain is not None:
        # A leading zero denotes a mainland fixed-line area code.  Such values
        # need an area-code-plus-subscriber shape; a shorter OCR blob (for
        # example ``06927225``) is not a complete canonical phone.
        return None if raw.startswith("0") and len(raw) < 10 else raw

    layouts = (
        # Mainland fixed line, with an optional country prefix and paired area
        # code parentheses.  Every separator position is explicit and singular.
        r"(?:(?:\+?86|0086)[ -]?)?(?:\(0\d{2,3}\)|0\d{2,3})[ -]?\d{7,8}",
        # Mainland mobile presentation in the printed 3-4-4 grouping.
        r"(?:(?:\+?86|0086)[ -]?)?1[3-9]\d[ -]?\d{4}[ -]?\d{4}",
        # A plus-prefixed international number may use two to four bounded
        # digit groups, but never repeated separators or one-digit fragments.
        r"\+\d{1,3}(?:[ -]\d{2,4}){2,4}",
        # Ungrouped E.164-style presentation.
        r"\+\d{7,15}",
    )
    if not any(re.fullmatch(layout, raw) for layout in layouts):
        return None
    digits = re.sub(r"\D", "", raw)
    return digits if 7 <= len(digits) <= 16 else None


def _canonical_employer_phone(value: Any) -> str | None:
    """Return a canonical phone from one exact employment slot."""

    return _canonical_nonmobile_phone(value)


def _canonical_employer_name(value: Any) -> str | None:
    """Return one complete employer name, withholding truncated legal suffixes."""

    raw = _clean(value)
    if (
        not raw
        or not validate_pboc_field(raw, "employer_name").valid
        or re.search(r"(?:有限公|股份有限公)$", _employment_signature(raw)) is not None
    ):
        return None
    return raw


def _employment_sequence_cell_has_multirow_span(
    table: Any,
    *,
    row: int,
    column: int,
) -> bool:
    """Return whether any declared multi-row span covers this ordinal cell.

    This predicate is intentionally broader than the proof used for repair.
    An ambiguous or duplicate span must suppress a raw ordinal even though it
    cannot authorize a replacement ordinal.
    """

    geometry = _native_table_geometry(table)
    spans = geometry.get("cell_spans") if geometry is not None else None
    if not isinstance(spans, list):
        return False
    for span in spans:
        if not isinstance(span, Mapping):
            continue
        span_row = span.get("row")
        span_column = span.get("col")
        row_span = span.get("row_span")
        column_span = span.get("col_span")
        if (
            isinstance(span_row, int)
            and not isinstance(span_row, bool)
            and isinstance(span_column, int)
            and not isinstance(span_column, bool)
            and isinstance(row_span, int)
            and not isinstance(row_span, bool)
            and isinstance(column_span, int)
            and not isinstance(column_span, bool)
            and row_span > 1
            and column_span > 0
            and span_row <= row < span_row + row_span
            and span_column <= column < span_column + column_span
        ):
            return True
    return False


def _exact_employment_detail_population(
    table: Any,
    rows: list[list[str]],
    *,
    start: int,
    aliases: Mapping[str, tuple[str, ...]],
) -> tuple[int, ...] | None:
    """Return one exact, dense downstream employment-detail population.

    A population proof accepts either a fully distinct exact header or the
    exact fully merged header topology.  Every populated row in the detail run
    must retain an independent exact ordinal cell, and duplicate or sparse
    ordinals invalidate the proof.
    """

    candidates: list[tuple[int, ...]] = []
    for header_index in range(start, len(rows)):
        header = tuple(rows[header_index])
        slots = _exact_fully_clustered_employment_detail_header(
            table,
            row_index=header_index,
            row=header,
            aliases=aliases,
        )
        if slots is None:
            distinct_slots = _canonical_header_slots(header, aliases)
            if set(distinct_slots) != set(aliases) or any(
                _exact_native_table_cell(table, row=header_index, column=column) is None
                for column in distinct_slots.values()
            ):
                continue
            slots = distinct_slots
        end = _employment_run_end(rows, header_index + 1)
        sequences: list[int] = []
        valid = True
        for row_index in range(header_index + 1, end):
            if not _nonempty(rows[row_index]):
                continue
            sequence_column = slots["sequence"]
            if _exact_native_table_cell(table, row=row_index, column=sequence_column) is None:
                valid = False
                break
            sequence = _employment_sequence_value(tuple(rows[row_index]), slots)
            if sequence is None or sequence <= 0 or sequence in sequences:
                valid = False
                break
            sequences.append(sequence)
        if valid and sequences and sequences == list(range(1, sequences[-1] + 1)):
            candidates.append(tuple(sequences))
    return candidates[0] if len(candidates) == 1 else None


def _exact_employment_covered_sequence_cell(
    table: Any,
    *,
    row: int,
    column: int,
) -> bool:
    """Authenticate the empty derived ordinal slot below a merged owner."""

    geometry = _native_table_geometry(table)
    if geometry is None:
        return False
    grids = tuple(
        geometry.get(key)
        for key in (
            "cell_bboxes",
            "cell_geometry_status",
            "cell_evidence_ids",
            "cell_token_ids",
        )
    )
    if any(
        not isinstance(grid, list)
        or row >= len(grid)
        or not isinstance(grid[row], list)
        or column >= len(grid[row])
        for grid in grids
    ):
        return False
    bboxes, statuses, evidence_ids, token_ids = grids
    return bool(
        bboxes[row][column] is None
        and str(statuses[row][column] or "") == "derived"
        and evidence_ids[row][column] in ([], None)
        and token_ids[row][column] in ([], None)
    )


def _employment_basic_merged_sequence_repairs(
    table: Any,
    rows: list[list[str]],
    *,
    start: int,
    sequence_column: int,
    detail_aliases: Mapping[str, tuple[str, ...]],
) -> dict[int, int]:
    """Recover two ordinals hidden by one exact two-row sequence merge.

    The repair is structural: an exact owner whose OCR value is the second
    ordinal must follow an exact predecessor, cover one empty derived ordinal
    cell, and align with an exact dense downstream detail population.  The
    second business row must also preserve an exact employer cell and one exact
    type/address/phone span whose address and phone decode independently.
    """

    metadata = getattr(table, "metadata", None)
    if not isinstance(metadata, Mapping):
        return {}
    geometry = metadata.get("geometry") if isinstance(metadata.get("geometry"), Mapping) else metadata
    spans = geometry.get("cell_spans") if isinstance(geometry, Mapping) else None
    if not isinstance(spans, list):
        return {}
    end = _employment_run_end(rows, start)
    detail_population = _exact_employment_detail_population(
        table,
        rows,
        start=end,
        aliases=detail_aliases,
    )
    if detail_population is None:
        return {}
    repairs: dict[int, int] = {}
    for span in spans:
        if not isinstance(span, Mapping):
            continue
        row = span.get("row")
        column = span.get("col")
        row_span = span.get("row_span")
        column_span = span.get("col_span")
        if (
            not isinstance(row, int)
            or isinstance(row, bool)
            or column != sequence_column
            or row_span != 2
            or column_span != 1
            or not start <= row < row + 1 < end
        ):
            continue
        observed = _employment_row_sequence(tuple(rows[row]), sequence_column=sequence_column)
        following = row + 2
        prior = row - 1
        prior_sequence = (
            _employment_row_sequence(tuple(rows[prior]), sequence_column=sequence_column)
            if prior >= start
            else None
        )
        merged_value = _exact_employment_basic_merged_cell(table, row=row + 1)
        merged_decoded = (
            _decode_exact_employment_basic_merged_value(merged_value[1])
            if merged_value is not None
            else None
        )
        employer_raw = _clean(rows[row + 1][1] if len(rows[row + 1]) > 1 else "")
        if (
            prior_sequence is None
            or prior < start
            or _exact_native_table_cell(table, row=prior, column=sequence_column) is None
            or _exact_native_table_span_owner(
                table,
                row=row,
                column=sequence_column,
                span=(2, 1),
            )
            is None
            or not _exact_employment_covered_sequence_cell(
                table,
                row=row + 1,
                column=sequence_column,
            )
            or observed != prior_sequence + 2
            or _clean(rows[row + 1][sequence_column] if sequence_column < len(rows[row + 1]) else "")
            or not _nonempty(rows[row + 1])
            or _exact_native_table_cell(table, row=row + 1, column=1) is None
            or _canonical_employer_name(employer_raw) is None
            or merged_decoded is None
            or not {prior_sequence, prior_sequence + 1, prior_sequence + 2} <= set(detail_population)
        ):
            continue
        if following < end and (
            _exact_native_table_cell(table, row=following, column=sequence_column) is None
            or _employment_row_sequence(
                tuple(rows[following]),
                sequence_column=sequence_column,
            )
            != prior_sequence + 3
        ):
            continue
        proposed = {row: prior_sequence + 1, row + 1: prior_sequence + 2}
        if any(index in repairs and repairs[index] != sequence for index, sequence in proposed.items()):
            return {}
        repairs.update(proposed)
    return repairs


def _exact_employment_basic_merged_cell(
    table: Any,
    *,
    row: int,
) -> tuple[int, str] | None:
    """Return one exact basic value cell spanning type/address/phone columns."""

    if _exact_native_table_span_owner(table, row=row, column=2, span=(1, 3)) is None:
        return None
    rows = _table_rows(table)
    raw = _clean(rows[row][2] if row < len(rows) and len(rows[row]) > 2 else "")
    return (2, raw) if raw else None


def _decode_exact_employment_basic_merged_value(value: Any) -> dict[str, str] | None:
    """Decode only independently typed address and phone from a three-slot cell."""

    raw = _clean(value)
    phone_matches = list(re.finditer(r"(?<!\d)0\d{9,11}(?!\d)", raw))
    if len(phone_matches) != 1:
        return None
    phone_match = phone_matches[0]
    phone = _canonical_employer_phone(phone_match.group(0))
    if phone is None:
        return None
    address = _clean(raw[: phone_match.start()] + " " + raw[phone_match.end() :])
    address_signature = _employment_signature(address)
    if (
        not address
        or not validate_pboc_field(address, "address").valid
        or re.match(r"^[A-Za-z](?:\s|(?=[\u3400-\u9fff]))", address) is not None
        # This physical cell spans employer type, address, and phone.  A
        # registered type term left after removing the exact phone proves that
        # the remaining glyphs are not owned by the address field alone.
        or any(
            type_signature
            and type_signature in address_signature
            for employer_type in _EMPLOYER_TYPES
            if (type_signature := _employment_signature(employer_type))
        )
    ):
        return None
    # The merged cell includes the employer-type slot.  It is safe to publish
    # address and phone only when the remaining glyphs are completely owned by
    # those two typed values; the absent type remains locally unresolved.
    raw_signature = _employment_signature(raw)
    phone_signature = _employment_signature(phone)
    if (
        raw_signature.count(phone_signature) != 1
        or raw_signature.replace(phone_signature, "", 1) != address_signature
    ):
        return None
    return {"employer_address": address, "employer_phone": phone}


def _employment_run_end(rows: list[list[str]], start: int) -> int:
    """Return the exclusive end of one canonical employment data run."""

    header_labels = (
        "编号",
        "工作单位",
        "单位性质",
        "单位地址",
        "单位电话",
        "职业",
        "行业",
        "职务",
        "职称",
        "进入本单位年份",
        "信息更新日期",
        "数据发生机构名称",
    )
    for row_index in range(start, len(rows)):
        compact = _compact("".join(rows[row_index]))
        if sum(label in compact for label in header_labels) >= 2:
            return row_index
    return len(rows)


def _employment_row_sequence(
    row: tuple[str, ...],
    *,
    sequence_column: int,
    cluster_column: int | None = None,
) -> int | None:
    """Read a sequence from one row without using any business value."""

    sequence = _employment_sequence_value(row, {"sequence": sequence_column})
    if sequence is not None or cluster_column != sequence_column:
        return sequence
    cluster_raw = _clean(row[cluster_column] if cluster_column < len(row) else "")
    match = re.fullmatch(r"\s*(\d{1,3})\s+.+", cluster_raw)
    return int(match.group(1)) if match is not None else None


def _employment_sequence_repairs(
    rows: list[list[str]],
    *,
    start: int,
    sequence_column: int,
    mode: str,
    known_basic_population: Iterable[int] = (),
    cluster_column: int | None = None,
) -> dict[int, int]:
    """Recover unreadable ordinals only from a closed canonical row run.

    Basic-table repairs must sit between globally consistent printed anchors.
    Detail-table repairs additionally require a unique alignment to the dense
    basic-table population.  Printed dash sentinels are never replaced.
    """

    end = _employment_run_end(rows, start)
    run_indices = [index for index in range(start, end) if _nonempty(rows[index])]
    if not run_indices or mode not in {"basic", "detail"}:
        return {}
    observed = [
        _employment_row_sequence(
            tuple(rows[index]),
            sequence_column=sequence_column,
            cluster_column=cluster_column,
        )
        for index in run_indices
    ]
    inferred: dict[int, int] = {}
    if mode == "basic":
        anchors = [(position, sequence) for position, sequence in enumerate(observed) if sequence is not None]
        if len(anchors) < 2:
            return {}
        offsets = {sequence - position for position, sequence in anchors}
        if len(offsets) != 1:
            return {}
        offset = offsets.pop()
        first_anchor = anchors[0][0]
        last_anchor = anchors[-1][0]
        for position in range(first_anchor + 1, last_anchor):
            if observed[position] is not None:
                continue
            row_index = run_indices[position]
            raw_sequence = rows[row_index][sequence_column] if sequence_column < len(rows[row_index]) else ""
            if is_explicit_source_absence(raw_sequence):
                continue
            expected = position + offset
            if expected > 0:
                inferred[row_index] = expected
        return inferred

    population = sorted(set(int(value) for value in known_basic_population))
    if not population or population != list(range(1, population[-1] + 1)):
        return {}
    if len(run_indices) > len(population):
        return {}
    alignments: list[list[int]] = []
    for population_start in range(len(population) - len(run_indices) + 1):
        candidate = population[population_start : population_start + len(run_indices)]
        if all(sequence is None or sequence == candidate[position] for position, sequence in enumerate(observed)):
            alignments.append(candidate)
    if len(alignments) != 1:
        return {}
    for position, expected in enumerate(alignments[0]):
        if observed[position] is not None:
            continue
        row_index = run_indices[position]
        raw_sequence = rows[row_index][sequence_column] if sequence_column < len(rows[row_index]) else ""
        if not is_explicit_source_absence(raw_sequence):
            inferred[row_index] = expected
    return inferred


_EMPLOYMENT_PROVIDER_ANCHOR_RE = re.compile(
    r"(?:银行|信用社|信用合作联社|消费金融|汽车金融|财务|"
    r"信托|小额贷款|融资担保|征信|公积金管理)"
)
_EMPLOYMENT_PROVIDER_END_RE = re.compile(r"(?:有限公司|中心|分行|支行|营业部|银行|信托|信用社|联社)$")


def _strict_employment_provider_span(value: Any) -> str | None:
    """Return one complete institution value without deleting source glyphs.

    OCR may insert whitespace inside a printed institution name, so the whole
    cell is compacted before applying the finite PBOC institution contract.
    Substring selection is deliberately forbidden: an edge glyph may be part
    of a legitimate name, and geometry-free deletion would silently change a
    business value.
    """

    tokens = [token for token in re.split(r"\s+", _clean(value)) if token]
    if not tokens:
        return None

    def valid(candidate_tokens: list[str]) -> str | None:
        candidate = _compact(" ".join(candidate_tokens))
        if not 5 <= len(candidate) <= 96:
            return None
        if any(label in candidate for label in ("数据发生机构名称", "编号", "信息更新日期")):
            return None
        if re.search(r"(?:19|20)\d{2}", candidate):
            return None
        if _EMPLOYMENT_PROVIDER_ANCHOR_RE.search(candidate) is None:
            return None
        if _EMPLOYMENT_PROVIDER_END_RE.search(candidate) is None:
            return None
        if len(re.findall(r"[\u3400-\u9fff]", candidate)) < 4:
            return None
        return candidate

    if sum(valid([token]) is not None for token in tokens) > 1:
        return None
    return valid(tokens)


def _bounded_provider_header_cell(value: Any) -> bool:
    """Accept only the complete canonical provider label."""

    return _employment_signature(value) == "数据发生机构名称"


def _employment_provider_header(row: tuple[str, ...]) -> dict[str, int] | None:
    """Recognize the two-label provider header with bounded label debris."""

    populated = [(column, value) for column, value in enumerate(row) if _employment_signature(value)]
    if len(populated) != 2:
        return None
    sequence_columns = [column for column, value in populated if _employment_signature(value) == "编号"]
    provider_columns = [column for column, value in populated if _bounded_provider_header_cell(value)]
    if len(sequence_columns) != 1 or len(provider_columns) != 1:
        return None
    sequence_column = sequence_columns[0]
    provider_column = provider_columns[0]
    if sequence_column == provider_column:
        return None
    return {"sequence": sequence_column, "data_provider": provider_column}


def _employment_provider_observation(
    row: tuple[str, ...], *, sequence_column: int
) -> tuple[str | None, int | None, str]:
    """Select the one institution-shaped non-sequence cell in a provider row."""

    candidates: list[tuple[str, int]] = []
    explicit_absence: list[tuple[str, int]] = []
    for column, raw in enumerate(row):
        if column == sequence_column:
            continue
        value = _clean(raw)
        if not value:
            continue
        if is_explicit_source_absence(value):
            explicit_absence.append((value, column))
            continue
        provider = _strict_employment_provider_span(value)
        if provider is not None:
            candidates.append((provider, column))
    unique = list(dict.fromkeys(candidates))
    if len(unique) == 1:
        return unique[0][0], unique[0][1], "exact"
    if not unique and len(explicit_absence) == 1:
        return explicit_absence[0][0], explicit_absence[0][1], "source_absent"
    return None, None, "ambiguous" if unique else "missing"


def _continuation_rows_are_provider_shaped(
    rows: list[list[str]],
    *,
    known_sequences: set[int],
) -> tuple[bool, int | None]:
    """Recognize a headerless provider tail without consuming business rows.

    A provider tail has exactly two populated columns, institution-shaped
    values, and either repeats already observed sequence numbers or contains
    at least two consistently unreadable sequence glyphs.  A new numbered
    residence/employment row therefore stays in its current canonical mode.
    """

    if not rows or not known_sequences:
        return False, None
    nonempty_columns = [[index for index, value in enumerate(row) if _clean(value)] for row in rows]
    if not all(len(columns) == 2 and columns[0] == 0 for columns in nonempty_columns):
        return False, None
    provider_column = nonempty_columns[0][1]
    if any(columns[1] != provider_column for columns in nonempty_columns):
        return False, None
    provider_pattern = re.compile(
        r"(?:银行(?:股份)?有限公司|银行|信用社|消费金融(?:股份)?有限公司|财务有限公司|管理中心|征信中心)$"
    )
    if not all(provider_pattern.search(_clean(row[provider_column])) for row in rows):
        return False, None
    parsed_sequences: list[int] = []
    unreadable_sequences = 0
    for row in rows:
        first = _clean(row[0] if row else "")
        if first.isdigit():
            parsed_sequences.append(int(first))
        else:
            unreadable_sequences += 1
    if parsed_sequences:
        return (
            unreadable_sequences == 0 and set(parsed_sequences) <= known_sequences,
            provider_column,
        )
    return unreadable_sequences >= 2, provider_column


def _employment_provider_tail_lattice_owned(
    table: Any,
    rows: list[list[str]],
    *,
    provider_column: int,
) -> bool:
    """Require independent exact ordinal/provider cells in a headerless tail."""

    owners: list[tuple[tuple[float, float, float, float], tuple[str, ...]]] = []
    for row_index, row in enumerate(rows):
        if not _nonempty(row):
            continue
        for column in (0, provider_column):
            owner = _employment_exact_lattice_owner(
                table,
                row=row_index,
                column=column,
            )
            if owner is None:
                return False
            owners.append(owner)
    evidence_ids = [
        evidence_id
        for _bbox, owner_evidence in owners
        for evidence_id in owner_evidence
    ]
    return bool(owners) and len(evidence_ids) == len(set(evidence_ids))


