def _bounded_residence_combined_status_date_header(
    table: Any,
    row: tuple[str, ...],
    *,
    row_index: int,
) -> dict[str, int] | None:
    """Recognize the four-column PBOC residence header with one combined slot.

    Some renderers print ``居住状况`` and ``信息更新日期`` inside one physical
    column.  The ordinary header graph correctly rejects two roles sharing a
    column, but discarding the whole table loses the independently exact
    record identity, address, phone and provider rows.  This exception is
    limited to the canonical first row of an exact four-column native lattice;
    every header cell must be evidence-sealed and the combined cell must own
    exactly the two expected labels.
    """

    if row_index != 0 or len(row) != 4:
        return None
    expected = {
        0: "编号",
        1: "居住地址",
        2: "住宅电话",
    }
    if any(_compact(row[column]) != marker for column, marker in expected.items()):
        return None
    combined = _compact(row[3])
    if combined not in {"居住状况信息更新日期", "信息更新日期居住状况"}:
        return None
    if not all(_exact_residence_cell_owner(table, row=0, column=column) for column in range(4)):
        return None
    evidence_ids = [
        evidence_id
        for column in range(4)
        for evidence_id in (_exact_residence_cell_owner(table, row=0, column=column) or ((), ()))[1]
    ]
    if len(evidence_ids) != len(set(evidence_ids)):
        return None
    return {
        "sequence": 0,
        "address": 1,
        "residential_phone": 2,
        "residence_status": 3,
        "information_updated_date": 3,
    }


def _bounded_residence_combined_phone_status_date_header(
    table: Any,
    row: tuple[str, ...],
    *,
    row_index: int,
) -> dict[str, int] | None:
    """Recognize an exact three-column residence lattice with three merged roles.

    This is narrower than the four-column exception above: the final physical
    column must own exactly ``住宅电话``, ``居住状况`` and ``信息更新日期``.  Exact
    per-token geometry is then required before any value inside that column is
    assigned to one of the three roles.
    """

    if row_index != 0 or len(row) != 3:
        return None
    if _compact(row[0]) != "编号" or _compact(row[1]) != "居住地址":
        return None
    combined = _compact(row[2])
    if combined != "住宅电话居住状况信息更新日期":
        return None
    owners = [
        _exact_residence_cell_owner(table, row=0, column=column)
        for column in range(3)
    ]
    if any(owner is None for owner in owners):
        return None
    evidence_ids = [
        evidence_id
        for owner in owners
        if owner is not None
        for evidence_id in owner[1]
    ]
    if len(evidence_ids) != len(set(evidence_ids)):
        return None
    return {
        "sequence": 0,
        "address": 1,
        "residential_phone": 2,
        "residence_status": 2,
        "information_updated_date": 2,
    }


def _exact_residence_cell_owner(
    table: Any,
    *,
    row: int,
    column: int,
) -> tuple[tuple[float, float, float, float], tuple[str, ...]] | None:
    """Return one exact unspanned residence cell from native or projected metadata."""

    owner = _exact_native_table_cell(table, row=row, column=column)
    if owner is not None:
        return owner
    metadata = getattr(table, "metadata", None)
    if not isinstance(metadata, Mapping):
        return None
    boxes = metadata.get("source_cell_bboxes") or metadata.get("cell_bboxes")
    statuses = metadata.get("cell_geometry_status")
    evidence = metadata.get("cell_evidence_ids")
    if any(
        not isinstance(grid, list) or row >= len(grid) or not isinstance(grid[row], list) or column >= len(grid[row])
        for grid in (boxes, statuses, evidence)
    ):
        return None
    bbox = _exact_geometry_bbox(boxes[row][column])
    evidence_ids = evidence[row][column]
    if bbox is None or str(statuses[row][column] or "") != "exact" or not isinstance(evidence_ids, list):
        return None
    normalized = tuple(dict.fromkeys(str(value) for value in evidence_ids if str(value or "")))
    return (bbox, normalized) if normalized else None


def _split_residence_status_date_slot(value: Any) -> tuple[str, str]:
    """Separate one combined residence-status/date value without guessing."""

    raw = _clean(value)
    matches = list(_FULL_DATE_RE.finditer(raw))
    if len(matches) != 1:
        return "", ""
    date_raw = matches[0].group(0)
    status = re.sub(
        r"^[\s\"“”'*#=—–-]+|[\s\"“”'*#=—–-]+$",
        "",
        raw[: matches[0].start()] + " " + raw[matches[0].end() :],
    ).strip()
    # The current PBOC form prints ``自有`` while older forms use the
    # semantically equivalent controlled value ``自置``.  This is a finite,
    # exact renderer alias—not fuzzy vocabulary repair.
    normalized_status = (
        "自置" if status == "自有" else normalize_pboc_field(status, "residence_status") if status else ""
    )
    if status and not validate_pboc_field(normalized_status, "residence_status").valid:
        normalized_status = ""
    return normalized_status, date_raw


def _exact_residence_combined_cell_components(
    parse_result: Any,
    table: Any,
    *,
    row: int,
    column: int,
) -> tuple[str, str, str] | None:
    """Decode phone/status/date only from exact, uniquely owned cell tokens."""

    tokens = _exact_native_table_cell_tokens(
        parse_result,
        table,
        row=row,
        column=column,
    )
    if tokens is None:
        exact_owner = _exact_residence_cell_owner(table, row=row, column=column)
        loader = getattr(parse_result, "corrected_evidence_pages", None)
        if exact_owner is None or not callable(loader):
            return None
        cell_bbox, cell_evidence_ids = exact_owner
        source_logical_page = int(
            (getattr(table, "metadata", None) or {}).get("source_logical_page")
            or 0
        )
        evidence_pages = [
            page
            for page in loader()
            if isinstance(page, Mapping)
            and int(page.get("page") or 0) == source_logical_page
        ]
        if len(evidence_pages) != 1:
            return None
        candidates: dict[str, tuple[str, tuple[float, float, float, float], str]] = {}
        for line in evidence_pages[0].get("lines") or ():
            if not isinstance(line, Mapping):
                continue
            bbox = _exact_geometry_bbox(line.get("source_bbox") or line.get("bbox"))
            evidence_ids = tuple(
                dict.fromkeys(
                    str(value)
                    for value in line.get("evidence_ids") or ()
                    if str(value or "")
                )
            )
            if (
                bbox is None
                or len(evidence_ids) != 1
                or evidence_ids[0] not in cell_evidence_ids
            ):
                continue
            token_id = evidence_ids[0]
            text = _clean(line.get("text") or line.get("content"))
            if (
                not text
                or bbox[0] < cell_bbox[0] - 1.0
                or bbox[1] < cell_bbox[1] - 1.0
                or bbox[2] > cell_bbox[2] + 1.0
                or bbox[3] > cell_bbox[3] + 1.0
                or token_id in candidates
            ):
                continue
            candidates[token_id] = (text, bbox, token_id)
        if set(candidates) != set(cell_evidence_ids):
            return None
        tokens = tuple(
            sorted(candidates.values(), key=lambda item: (item[1][1], item[1][0], item[2]))
        )

    dates: list[str] = []
    statuses: list[str] = []
    phones: list[str] = []
    unknown: list[str] = []
    for text, _bbox, _token_id in tokens:
        if is_explicit_source_absence(text):
            continue
        if _FULL_DATE_RE.fullmatch(text):
            dates.append(text)
            continue
        normalized_status = normalize_pboc_field(text, "residence_status")
        if validate_pboc_field(normalized_status, "residence_status").valid:
            statuses.append(normalized_status)
            continue
        if _canonical_exact_phone(text, mobile=False) is not None:
            phones.append(text)
            continue
        if re.sub(r'[\s"“”\'*#=—–-]+', "", text):
            unknown.append(text)
    if (
        len(dates) != 1
        or len(statuses) > 1
        or len(phones) > 1
        or unknown
    ):
        return None
    return (
        phones[0] if phones else "",
        statuses[0] if statuses else "",
        dates[0],
    )


def _exact_residence_address_date_components(
    parse_result: Any,
    table: Any,
    *,
    row: int,
    column: int,
    date_column: int,
    raw: str,
) -> tuple[
    str,
    str,
    tuple[str, tuple[float, float, float, float], str],
    tuple[str, tuple[float, float, float, float], str],
] | None:
    """Split an address/date cell only from two independently owned tokens."""

    metadata = getattr(table, "metadata", None)
    header_candidates: list[tuple[int, set[str]]] = []
    labels = {
        "sequence": "编号",
        "address": "居住地址",
        "residential_phone": "住宅电话",
        "residence_status": "居住状况",
        "information_updated_date": "信息更新日期",
    }
    for header_row, header in enumerate(_table_rows(table)):
        slots: dict[str, int] = {}
        for role, label in labels.items():
            columns = [index for index, value in enumerate(header) if _compact(value) == label]
            if len(columns) != 1:
                slots = {}
                break
            slots[role] = columns[0]
        if (
            set(slots) != set(labels)
            or len(set(slots.values())) != len(slots)
            or slots["address"] != column
            or slots["information_updated_date"] != date_column
        ):
            continue
        owners = [
            _exact_residence_cell_owner(table, row=header_row, column=slots[role])
            for role in labels
        ]
        if any(owner is None for owner in owners):
            continue
        evidence_ids = {
            evidence_id
            for owner in owners
            if owner is not None
            for evidence_id in owner[1]
        }
        if sum(len(owner[1]) for owner in owners if owner is not None) != len(evidence_ids):
            continue
        header_candidates.append((header_row, evidence_ids))
    if len(header_candidates) != 1 or header_candidates[0][0] >= row:
        return None
    logical_page = (
        int(metadata.get("source_logical_page") or 0)
        if isinstance(metadata, Mapping)
        else 0
    )
    tokens = _exact_native_table_cell_tokens(
        parse_result,
        table,
        row=row,
        column=column,
        logical_page=logical_page or None,
    )
    if tokens is None or len(tokens) != 2:
        return None
    geometry = _native_table_geometry(table)
    metadata_token_grid = metadata.get("cell_token_ids") if isinstance(metadata, Mapping) else None
    evidence_grid = geometry.get("cell_evidence_ids") if isinstance(geometry, Mapping) else None
    token_grid = metadata_token_grid or (
        geometry.get("cell_token_ids") if isinstance(geometry, Mapping) else None
    )
    requested_ids = {token[2] for token in tokens}
    for grid in (evidence_grid, token_grid):
        if not isinstance(grid, list):
            return None
        ownership_counts = Counter(
            str(evidence_id)
            for grid_row in grid
            if isinstance(grid_row, list)
            for cell in grid_row
            if isinstance(cell, list)
            for evidence_id in cell
            if str(evidence_id or "") in requested_ids
        )
        if any(ownership_counts[token_id] != 1 for token_id in requested_ids):
            return None
    date_tokens = [token for token in tokens if _FULL_DATE_RE.fullmatch(_clean(token[0]))]
    address_tokens = [token for token in tokens if token not in date_tokens]
    if len(date_tokens) != 1 or len(address_tokens) != 1:
        return None
    date_raw = _clean(date_tokens[0][0])
    address = _clean(address_tokens[0][0])
    if (
        _date(date_raw) is None
        or len(_compact(address)) < 4
        or _DATE_RE.search(address)
        or _compact(raw) != _compact("".join(token[0] for token in tokens))
    ):
        return None
    date_box = date_tokens[0][1]
    address_box = address_tokens[0][1]
    separated = (
        date_box[2] <= address_box[0]
        or address_box[2] <= date_box[0]
        or date_box[3] <= address_box[1]
        or address_box[3] <= date_box[1]
    )
    if not separated:
        return None
    return address, date_raw, address_tokens[0], date_tokens[0]


def _exact_residence_provider_header_slots(row: tuple[str, ...]) -> dict[str, int] | None:
    """Bind provider roles only to two unique, exact PBOC header labels."""

    labels = {"sequence": "编号", "data_provider": "数据发生机构名称"}
    slots: dict[str, int] = {}
    for role, label in labels.items():
        columns = [column for column, value in enumerate(row) if _compact(value) == label]
        if len(columns) != 1:
            return None
        slots[role] = columns[0]
    return slots if len(set(slots.values())) == len(slots) else None


def _exact_residence_provider_continuation_slots(
    table: Any,
    rows: list[list[str]],
    records: Mapping[int, Mapping[str, Any]],
) -> dict[str, int] | None:
    """Bind a headerless provider tail only through exact same-record proof.

    The provider value's spelling is deliberately irrelevant.  Every row must
    own exactly one printed ordinal for a known, otherwise complete residence
    record and one other exact cell.  Unique cell evidence and a registered
    table-continuation edge then leave ``data_provider`` as the sole unresolved
    semantic role; row count and row order never participate.
    """

    if not rows or not records:
        return None
    required_roles = {
        "address",
        "residential_phone",
        "residence_status",
        "information_updated_date",
    }
    observed_columns: set[tuple[int, int]] = set()
    evidence_owners: set[str] = set()
    observed_sequences: set[int] = set()
    for row_index, row in enumerate(rows):
        nonempty_columns = [column for column, value in enumerate(row) if _clean(value)]
        if len(nonempty_columns) != 2:
            return None
        sequence_candidates = [
            column
            for column in nonempty_columns
            if _clean(row[column]).isdigit() and int(_clean(row[column])) in records
        ]
        if len(sequence_candidates) != 1:
            return None
        sequence_column = sequence_candidates[0]
        provider_column = next(column for column in nonempty_columns if column != sequence_column)
        sequence = int(_clean(row[sequence_column]))
        record = records[sequence]
        source_absent = set(record.get("_source_absent_fields") or ())
        if (
            sequence in observed_sequences
            or record.get("data_provider")
            or "data_provider" in source_absent
            or any(role not in record and role not in source_absent for role in required_roles)
        ):
            return None
        owners = [
            _exact_residence_cell_owner(table, row=row_index, column=column)
            for column in (sequence_column, provider_column)
        ]
        if any(owner is None for owner in owners):
            return None
        row_evidence = {
            evidence_id
            for owner in owners
            if owner is not None
            for evidence_id in owner[1]
        }
        if (
            not row_evidence
            or evidence_owners.intersection(row_evidence)
            or sum(len(owner[1]) for owner in owners if owner is not None) != len(row_evidence)
        ):
            return None
        evidence_owners.update(row_evidence)
        observed_sequences.add(sequence)
        observed_columns.add((sequence_column, provider_column))
    if len(observed_columns) != 1:
        return None
    sequence_column, provider_column = next(iter(observed_columns))
    return {"sequence": sequence_column, "data_provider": provider_column}


def _residence_token_source_ref(
    page: Any,
    table: Any,
    *,
    row: int,
    column: int,
    token: tuple[str, tuple[float, float, float, float], str],
) -> dict[str, Any]:
    ref = _source_ref(page, table, row=row, column=column)
    ref.update(
        {
            "source": "native_detail_table_token",
            "bbox": list(token[1]),
            "evidence_ids": [token[2]],
            "geometry_scope": "token",
            "binding": "canonical_field_token",
            "binding_quality": "exact_token_in_residence_cell",
        }
    )
    return ref


def _extract_residence_records(parse_result: Any) -> list[dict[str, Any]]:
    aliases = {
        "sequence": ("编号",),
        "address": ("居住地址",),
        "residential_phone": ("住宅电话",),
        "residence_status": ("居住状况",),
        "information_updated_date": ("信息更新日期",),
    }
    records: dict[int, dict[str, Any]] = {}
    providers: defaultdict[int, list[tuple[str, dict[str, Any]]]] = defaultdict(list)
    provider_source_absent: set[int] = set()
    active_slots: dict[str, int] = {}
    mode = ""
    provider_header_table_id = ""
    provider_header_slots: dict[str, int] = {}
    provider_continuation_table_id = ""
    previous_table_id = ""
    previous_table_owned = False
    continuation_check = getattr(parse_result, "tables_continue", None)
    for page in getattr(parse_result, "pages", None) or []:
        page_number = int(getattr(page, "page_number", 0) or 0)
        source_page = int(getattr(page, "source_page_number", 0) or page_number)
        for table in getattr(page, "tables", None) or []:
            rows = _table_rows(table)
            table_id = str(getattr(table, "table_id", "") or "")
            table_owned = canonical_table_owned_by(
                parse_result,
                page,
                table,
                "report_header_and_identity",
            )
            if not table_owned:
                active_slots = {}
                mode = ""
                provider_header_table_id = ""
                provider_header_slots = {}
                provider_continuation_table_id = ""
                previous_table_id = table_id or previous_table_id
                previous_table_owned = False
                continue
            table_text = _compact(" ".join(cell for row in rows for cell in row))
            continues = bool(
                previous_table_id
                and previous_table_owned
                and table_id
                and callable(continuation_check)
                and continuation_check(previous_table_id, table_id) is True
            )
            residence_schema_markers = ("居住地址", "住宅电话", "居住状况")
            other_section_markers = ("学历", "学位", "电子邮箱", "通讯地址", "户籍地址", "工作单位", "职业")
            if (
                mode in {"residence", "provider"}
                and not any(marker in table_text for marker in residence_schema_markers)
                and any(marker in table_text for marker in other_section_markers)
            ):
                continues = False
            if not continues:
                active_slots = {}
                mode = ""
                provider_header_table_id = ""
                provider_header_slots = {}
                provider_continuation_table_id = ""
            if not continues and not any(marker in table_text for marker in residence_schema_markers):
                previous_table_id = table_id or previous_table_id
                previous_table_owned = table_owned
                continue
            if continues and mode == "residence" and rows:
                provider_slots = _exact_residence_provider_continuation_slots(
                    table,
                    rows,
                    records,
                )
                if provider_slots is not None:
                    active_slots = provider_slots
                    mode = "provider"
                    provider_continuation_table_id = table_id
            for row_index, row in enumerate(rows):
                residence_slots = _canonical_header_slots(row, aliases)
                combined_status_date_slots = _bounded_residence_combined_status_date_header(
                    table,
                    row,
                    row_index=row_index,
                )
                if combined_status_date_slots is not None:
                    residence_slots = combined_status_date_slots
                combined_phone_status_date_slots = (
                    _bounded_residence_combined_phone_status_date_header(
                        table,
                        row,
                        row_index=row_index,
                    )
                )
                if combined_phone_status_date_slots is not None:
                    residence_slots = combined_phone_status_date_slots
                compact_header = _compact("".join(row))
                header_anchor = len(residence_slots) >= 2
                if (
                    all(marker in compact_header for marker in ("编号", "居住地址", "信息更新日期"))
                    and not set(aliases) <= set(residence_slots)
                ) or (header_anchor and not set(aliases) <= set(residence_slots)):
                    _report_header_graph_failure(
                        parse_result,
                        dataset="residence_records",
                        page=page,
                        table=table,
                        row_index=row_index,
                        row=row,
                    )
                    active_slots = {}
                    mode = ""
                    continue
                if set(aliases) <= set(residence_slots):
                    active_slots = residence_slots
                    mode = "residence"
                    provider_header_table_id = ""
                    provider_header_slots = {}
                    provider_continuation_table_id = ""
                    continue
                if "数据发生机构名称" in _compact("".join(row)) and mode in {"residence", "provider"}:
                    provider_slots = _exact_residence_provider_header_slots(tuple(row))
                    if provider_slots is None:
                        _report_header_graph_failure(
                            parse_result,
                            dataset="residence_records",
                            page=page,
                            table=table,
                            row_index=row_index,
                            row=row,
                        )
                        active_slots = {}
                        mode = ""
                        provider_header_table_id = ""
                        provider_header_slots = {}
                        provider_continuation_table_id = ""
                        continue
                    active_slots = provider_slots
                    mode = "provider"
                    provider_header_table_id = table_id
                    provider_header_slots = dict(provider_slots)
                    provider_continuation_table_id = ""
                    continue
                if not active_slots or mode not in {"residence", "provider"}:
                    continue
                if mode == "provider":
                    sequence_raw = _slot_value(row, active_slots, "sequence")
                    sequence = (
                        int(sequence_raw)
                        if re.fullmatch(r"\d{1,3}", sequence_raw)
                        and int(sequence_raw) in records
                        else None
                    )
                else:
                    sequence = _sequence_value(row, active_slots)
                if sequence is None:
                    nonempty = _nonempty(row)
                    if mode == "provider" and nonempty:
                        _report_unkeyed_fragment(
                            parse_result,
                            dataset="residence_records",
                            row=row,
                            page=page,
                            table=table,
                            row_index=row_index,
                        )
                    elif mode == "residence" and nonempty:
                        _report_unkeyed_business_row(
                            parse_result,
                            dataset="residence_records",
                            row=row,
                            page=page,
                            table=table,
                            row_index=row_index,
                        )
                    continue
                ref = _source_ref(page, table, row=row_index)
                if mode == "provider":
                    header_bound = (
                        table_id == provider_header_table_id
                        and active_slots == provider_header_slots
                    )
                    continuation_bound = (
                        continues
                        and table_id == provider_continuation_table_id
                        and sequence in records
                    )
                    if not header_bound and not continuation_bound:
                        _report_unkeyed_fragment(
                            parse_result,
                            dataset="residence_records",
                            row=row,
                            page=page,
                            table=table,
                            row_index=row_index,
                        )
                        continue
                    provider = _slot_value(row, active_slots, "data_provider")
                    provider_column = active_slots.get("data_provider")
                    if is_explicit_source_absence(provider):
                        provider_source_absent.add(sequence)
                    elif provider and provider_column is not None:
                        providers[sequence].append(
                            (provider, _source_ref(page, table, row=row_index, column=provider_column))
                        )
                    continue
                residence_id = stable_record_id("credit_residence", sequence)
                address = _slot_value(row, active_slots, "address")
                updated_raw = _slot_value(row, active_slots, "information_updated_date")
                updated = _date(updated_raw)
                split_updated_raw: str | None = None
                address_token = None
                date_token = None
                if address and not updated and not updated_raw:
                    split_components = _exact_residence_address_date_components(
                        parse_result,
                        table,
                        row=row_index,
                        column=active_slots["address"],
                        date_column=active_slots["information_updated_date"],
                        raw=address,
                    )
                    if split_components is not None:
                        address, split_updated_raw, address_token, date_token = split_components
                        updated = _date(split_updated_raw)
                record = records.setdefault(
                    sequence,
                    {
                        "sequence": sequence,
                        "page": page_number,
                        "source_page": source_page,
                        "source": "native_personal_detail_residence_table",
                        "source_refs": [],
                        "record_id": residence_id,
                        "residence_record_id": residence_id,
                        "confidence": 1.0,
                    },
                )
                record["source_refs"].append(ref)
                if address == "--":
                    _mark_source_absent(record, "address", address)
                elif address:
                    address_ref = _source_ref(page, table, row=row_index, column=active_slots["address"])
                    if address_token is not None:
                        address_ref = _residence_token_source_ref(
                            page,
                            table,
                            row=row_index,
                            column=active_slots["address"],
                            token=address_token,
                        )
                    suspicious_address = bool(
                        re.search(r"(?<!\d)1[3-9]\d{9}(?!\d)", address)
                        or any(label in _compact(address) for label_names in aliases.values() for label in label_names)
                    )
                    if suspicious_address:
                        _reject_exact_observation(
                            parse_result,
                            record,
                            dataset="residence_records",
                            target_record_id=residence_id,
                            field_name="address",
                            raw=address,
                            source_ref=address_ref,
                            parser_stage="candidate_b_residence_canonical_slots",
                        )
                    else:
                        _merge_exact_observation(
                            parse_result,
                            record,
                            dataset="residence_records",
                            target_record_id=residence_id,
                            field_name="address",
                            value=address,
                            raw=address,
                            source_ref=address_ref,
                            parser_stage="candidate_b_residence_canonical_slots",
                        )
                else:
                    _report_required_row_failure(
                        parse_result,
                        issue_code="candidate_b_residence_required_cell_unresolved",
                        dataset="residence_records",
                        sequence=sequence,
                        field_name="address",
                        row=row,
                        page=page,
                        table=table,
                        row_index=row_index,
                        target_record_id=residence_id,
                    )
                phone = _slot_value(row, active_slots, "residential_phone")
                status = _slot_value(row, active_slots, "residence_status")
                three_role_combined = (
                    active_slots.get("residential_phone")
                    == active_slots.get("residence_status")
                    == active_slots.get("information_updated_date")
                )
                combined_components: tuple[str, str, str] | None = None
                if three_role_combined:
                    combined_column = active_slots["residential_phone"]
                    combined_components = _exact_residence_combined_cell_components(
                        parse_result,
                        table,
                        row=row_index,
                        column=combined_column,
                    )
                    if combined_components is not None:
                        phone, status, updated_raw = combined_components
                        updated = _date(updated_raw)
                    else:
                        phone = ""
                        status = ""
                        updated_raw = ""
                        updated = None
                elif active_slots.get("residence_status") == active_slots.get("information_updated_date"):
                    status, updated_raw = _split_residence_status_date_slot(status)
                    updated = _date(updated_raw)
                if is_explicit_source_absence(phone):
                    _mark_source_absent(record, "residential_phone", phone)
                elif phone:
                    canonical_phone = _canonical_exact_phone(phone, mobile=False)
                    phone_ref = _source_ref(page, table, row=row_index, column=active_slots["residential_phone"])
                    if canonical_phone is None:
                        _reject_exact_observation(
                            parse_result,
                            record,
                            dataset="residence_records",
                            target_record_id=residence_id,
                            field_name="residential_phone",
                            raw=phone,
                            source_ref=phone_ref,
                            parser_stage="candidate_b_residence_canonical_slots",
                        )
                    else:
                        _merge_exact_observation(
                            parse_result,
                            record,
                            dataset="residence_records",
                            target_record_id=residence_id,
                            field_name="residential_phone",
                            value=canonical_phone,
                            raw=phone,
                            source_ref=phone_ref,
                            parser_stage="candidate_b_residence_canonical_slots",
                        )
                elif three_role_combined:
                    _report_unreadable_exact_slot(
                        parse_result,
                        record,
                        dataset="residence_records",
                        target_record_id=residence_id,
                        field_name="residential_phone",
                        source_ref=_source_ref(
                            page,
                            table,
                            row=row_index,
                            column=active_slots["residential_phone"],
                        ),
                        parser_stage="candidate_b_residence_canonical_slots",
                        slot_state="combined_cell_phone_not_observed",
                        message=(
                            "The combined residence phone/status/date cell had no "
                            "independently owned residential-phone value."
                        ),
                    )
                if status == "--":
                    _mark_source_absent(record, "residence_status", status)
                elif status:
                    _merge_exact_observation(
                        parse_result,
                        record,
                        dataset="residence_records",
                        target_record_id=residence_id,
                        field_name="residence_status",
                        value=status,
                        raw=status,
                        source_ref=_source_ref(page, table, row=row_index, column=active_slots["residence_status"]),
                        parser_stage="candidate_b_residence_canonical_slots",
                    )
                elif active_slots.get("residence_status") == active_slots.get("information_updated_date"):
                    combined_column = active_slots["residence_status"]
                    combined_raw = _slot_value(row, active_slots, "residence_status")
                    if (
                        three_role_combined
                        or (combined_raw and _FULL_DATE_RE.search(combined_raw))
                    ):
                        _report_unreadable_exact_slot(
                            parse_result,
                            record,
                            dataset="residence_records",
                            target_record_id=residence_id,
                            field_name="residence_status",
                            source_ref=_source_ref(
                                page,
                                table,
                                row=row_index,
                                column=combined_column,
                            ),
                            parser_stage="candidate_b_residence_canonical_slots",
                            slot_state="combined_cell_status_not_observed",
                            message=(
                                "The combined residence-status/date cell preserved the date, "
                                "but no independently owned residence-status glyph was observed."
                            ),
                        )
                if updated_raw and not is_explicit_source_absence(updated_raw):
                    _merge_canonical_date_observation(
                        parse_result,
                        record,
                        dataset="residence_records",
                        target_record_id=residence_id,
                        field_name="information_updated_date",
                        raw=updated_raw,
                        source_ref=_source_ref(
                            page,
                            table,
                            row=row_index,
                            column=active_slots["information_updated_date"],
                        ),
                        parser_stage="candidate_b_residence_canonical_slots",
                    )
                elif split_updated_raw:
                    _merge_canonical_date_observation(
                        parse_result,
                        record,
                        dataset="residence_records",
                        target_record_id=residence_id,
                        field_name="information_updated_date",
                        raw=split_updated_raw,
                        source_ref=_residence_token_source_ref(
                            page,
                            table,
                            row=row_index,
                            column=active_slots["address"],
                            token=date_token,
                        )
                        if date_token is not None
                        else _source_ref(
                            page,
                            table,
                            row=row_index,
                            column=active_slots["address"],
                        ),
                        parser_stage="candidate_b_residence_canonical_slots",
                    )
                elif is_explicit_source_absence(updated_raw):
                    _mark_source_absent(record, "information_updated_date", updated_raw)
                elif not updated_raw and three_role_combined:
                    _report_unreadable_exact_slot(
                        parse_result,
                        record,
                        dataset="residence_records",
                        target_record_id=residence_id,
                        field_name="information_updated_date",
                        source_ref=_source_ref(
                            page,
                            table,
                            row=row_index,
                            column=active_slots["information_updated_date"],
                        ),
                        parser_stage="candidate_b_residence_canonical_slots",
                        slot_state="combined_cell_date_not_observed",
                        message=(
                            "The combined residence phone/status/date cell did not "
                            "preserve one independently owned update date."
                        ),
                    )
                elif not updated_raw:
                    _report_required_row_failure(
                        parse_result,
                        issue_code="candidate_b_residence_required_cell_unresolved",
                        dataset="residence_records",
                        sequence=sequence,
                        field_name="information_updated_date",
                        row=row,
                        page=page,
                        table=table,
                        row_index=row_index,
                        target_record_id=residence_id,
                    )
            previous_table_id = table_id or previous_table_id
            previous_table_owned = table_owned

    for sequence, record in records.items():
        residence_id = str(record["residence_record_id"])
        if sequence in provider_source_absent:
            _mark_source_absent(record, "data_provider", "--")
        for provider, provider_ref in providers.get(sequence, ()):
            record["source_refs"].append(provider_ref)
            _merge_exact_observation(
                parse_result,
                record,
                dataset="residence_records",
                target_record_id=residence_id,
                field_name="data_provider",
                value=provider,
                raw=provider,
                source_ref=provider_ref,
                parser_stage="candidate_b_residence_canonical_slots",
            )
        if not record.get("data_provider") and "data_provider" not in set(record.get("_source_absent_fields") or ()):
            from docmirror.plugins.credit_report.personal_detail_scanned.extraction_issues import (
                make_issue,
                record_issue,
            )

            record["extraction_status"] = "review"
            record_issue(
                parse_result,
                make_issue(
                    category="page_continuation",
                    issue_code="candidate_b_residence_provider_missing",
                    message="A canonical residence row has no safely bound provider row.",
                    parser_stage="candidate_b_residence_canonical_slots",
                    target_dataset="residence_records",
                    target_record_id=residence_id,
                    field_name="data_provider",
                    observed_value={"sequence": sequence},
                    source_refs=tuple(record.get("source_refs") or ()),
                    reason_codes=(
                        "canonical_residence_row_observed",
                        "provider_component_not_bound",
                        "row_marked_for_review",
                    ),
                ),
            )
    output = [records[key] for key in sorted(records)]
    _enforce_observed_header_terminal_invariant(
        parse_result,
        dataset="residence_records",
        aliases=aliases,
        records=output,
    )
    return output


def _extract_employment_records(parse_result: Any) -> list[dict[str, Any]]:
    basic_aliases = {
        "sequence": ("编号",),
        "employer": ("工作单位",),
        "employer_type": ("单位性质",),
        "employer_address": ("单位地址",),
        "employer_phone": ("单位电话",),
    }
    detail_aliases = {
        "sequence": ("编号",),
        "occupation": ("职业",),
        "industry": ("行业",),
        "position": ("职务",),
        "professional_title": ("职称",),
        "entry_year": ("进入本单位年份",),
        "information_updated_date": ("信息更新日期",),
    }
    records: dict[int, dict[str, Any]] = {}
    active_slots: dict[str, int] = {}
    mode = ""
    basic_header_recovered = False
    basic_cluster_column: int | None = None
    detail_header_clustered = False
    sequence_repairs: dict[int, int] = {}
    employment_section_active = False
    previous_table_id = ""
    previous_table_owned = False
    continuation_check = getattr(parse_result, "tables_continue", None)
    for page in getattr(parse_result, "pages", None) or []:
        page_number = int(getattr(page, "page_number", 0) or 0)
        source_page = int(getattr(page, "source_page_number", 0) or page_number)
        for table in getattr(page, "tables", None) or []:
            rows = _table_rows(table)
            table_id = str(getattr(table, "table_id", "") or "")
            table_text = _compact(" ".join(cell for row in rows for cell in row))
            table_has_employment_schema = _employment_source_owner(page, table) is not None and any(
                marker in table_text for marker in ("工作单位", "单位性质", "单位电话", "职业", "职务", "职称")
            )
            continues = bool(
                previous_table_id
                and previous_table_owned
                and table_id
                and callable(continuation_check)
                and continuation_check(previous_table_id, table_id) is True
                and _employment_source_owner(page, table) is not None
            )
            other_section_markers = (
                "居住地址",
                "住宅电话",
                "居住状况",
                "手机号码",
                "配偶",
                "学历",
                "学位",
                "电子邮箱",
                "通讯地址",
                "户籍地址",
            )
            if (
                employment_section_active
                and not table_has_employment_schema
                and any(marker in table_text for marker in other_section_markers)
            ):
                continues = False
                employment_section_active = False
            if not continues:
                active_slots = {}
                mode = ""
                basic_header_recovered = False
                basic_cluster_column = None
                detail_header_clustered = False
                sequence_repairs = {}
                employment_section_active = table_has_employment_schema
            elif table_has_employment_schema:
                employment_section_active = True
            if not employment_section_active and not table_has_employment_schema:
                previous_table_id = table_id or previous_table_id
                previous_table_owned = _employment_source_owner(page, table) is not None
                continue
            if continues and mode in {"basic", "detail"} and rows:
                provider_shaped, provider_column = _continuation_rows_are_provider_shaped(
                    rows,
                    known_sequences=set(records),
                )
                if (
                    provider_shaped
                    and provider_column is not None
                    and _employment_provider_tail_lattice_owned(
                        table,
                        rows,
                        provider_column=provider_column,
                    )
                ):
                    active_slots = {"sequence": 0, "data_provider": provider_column}
                    mode = "provider"
                    basic_header_recovered = False
                    basic_cluster_column = None
                    detail_header_clustered = False
                    sequence_repairs = {}
            for row_index, row in enumerate(rows):
                raw_basic_slots = _canonical_header_slots(row, basic_aliases)
                raw_detail_slots = _canonical_header_slots(row, detail_aliases)
                basic_slots = _employment_exact_header_slots(
                    page,
                    table,
                    row_index=row_index,
                    slots=raw_basic_slots,
                )
                detail_slots = _employment_exact_header_slots(
                    page,
                    table,
                    row_index=row_index,
                    slots=raw_detail_slots,
                )
                recovered_basic = _employment_recovered_basic_header_slots(
                    page,
                    table,
                    rows,
                    row_index=row_index,
                    recovered=_recovered_employment_basic_header(row, basic_aliases),
                )
                collapsed_basic = _employment_collapsed_basic_header_slots(
                    page,
                    table,
                    row_index=row_index,
                    collapsed=_collapsed_employment_basic_header(row),
                )
                clustered_detail_candidate = _clustered_employment_detail_header(
                    row,
                    detail_aliases,
                )
                clustered_detail = _employment_exact_header_slots(
                    page,
                    table,
                    row_index=row_index,
                    slots=clustered_detail_candidate or {},
                ) if clustered_detail_candidate is not None else None
                exact_fully_clustered_candidate = _exact_fully_clustered_employment_detail_header(
                    table,
                    row_index=row_index,
                    row=row,
                    aliases=detail_aliases,
                )
                exact_fully_clustered_detail = _employment_exact_header_slots(
                    page,
                    table,
                    row_index=row_index,
                    slots=exact_fully_clustered_candidate or {},
                ) if exact_fully_clustered_candidate is not None else None
                provider_header_candidate = _employment_provider_header(row)
                provider_header = (
                    _employment_exact_header_slots(
                        page,
                        table,
                        row_index=row_index,
                        slots=provider_header_candidate,
                    )
                    if provider_header_candidate is not None
                    else None
                )
                compact_header = _compact("".join(row))
                table_owned = _employment_source_owner(page, table) is not None
                basic_anchor = table_owned and len(raw_basic_slots) >= 2
                detail_anchor = table_owned and len(raw_detail_slots) >= 2
                broken_basic = (
                    (
                        all(marker in compact_header for marker in ("编号", "工作单位", "单位性质", "单位电话"))
                        or basic_anchor
                    )
                    and not set(basic_aliases) <= set(basic_slots or {})
                    and recovered_basic is None
                    and collapsed_basic is None
                )
                broken_detail = (
                    (
                        all(marker in compact_header for marker in ("编号", "职业", "行业", "职务", "职称"))
                        or detail_anchor
                    )
                    and not set(detail_aliases) <= set(detail_slots or {})
                    and clustered_detail is None
                    and exact_fully_clustered_detail is None
                )
                if broken_basic or broken_detail:
                    _report_header_graph_failure(
                        parse_result,
                        dataset="employment_records",
                        page=page,
                        table=table,
                        row_index=row_index,
                        row=row,
                    )
                    active_slots = {}
                    mode = ""
                    basic_header_recovered = False
                    basic_cluster_column = None
                    detail_header_clustered = False
                    sequence_repairs = {}
                    employment_section_active = True
                    continue
                if basic_slots is not None and set(basic_aliases) <= set(basic_slots):
                    active_slots = basic_slots
                    mode = "basic"
                    basic_header_recovered = False
                    basic_cluster_column = None
                    detail_header_clustered = False
                    sequence_repairs = _employment_sequence_repairs(
                        rows,
                        start=row_index + 1,
                        sequence_column=active_slots["sequence"],
                        mode="basic",
                    )
                    sequence_repairs.update(
                        _employment_basic_merged_sequence_repairs(
                            table,
                            rows,
                            start=row_index + 1,
                            sequence_column=active_slots["sequence"],
                            detail_aliases=detail_aliases,
                        )
                    )
                    continue
                if recovered_basic is not None:
                    active_slots, header_residue = recovered_basic
                    if header_residue:
                        # A label cell and the following business-value cell
                        # are distinct physical owners.  Residue in the header
                        # therefore remains row-level review evidence; it is
                        # never injected into a data row by adjacency.
                        _report_header_graph_failure(
                            parse_result,
                            dataset="employment_records",
                            page=page,
                            table=table,
                            row_index=row_index,
                            row=row,
                        )
                    mode = "basic"
                    basic_header_recovered = True
                    basic_cluster_column = None
                    detail_header_clustered = False
                    sequence_repairs = _employment_sequence_repairs(
                        rows,
                        start=row_index + 1,
                        sequence_column=active_slots["sequence"],
                        mode="basic",
                    )
                    continue
                if collapsed_basic is not None:
                    sequence_column, basic_cluster_column = collapsed_basic
                    active_slots = {"sequence": sequence_column}
                    mode = "basic"
                    basic_header_recovered = False
                    detail_header_clustered = False
                    sequence_repairs = _employment_sequence_repairs(
                        rows,
                        start=row_index + 1,
                        sequence_column=active_slots["sequence"],
                        mode="basic",
                        cluster_column=basic_cluster_column,
                    )
                    continue
                if detail_slots is not None and set(detail_aliases) <= set(detail_slots):
                    active_slots = detail_slots
                    mode = "detail"
                    basic_header_recovered = False
                    basic_cluster_column = None
                    detail_header_clustered = False
                    sequence_repairs = _employment_sequence_repairs(
                        rows,
                        start=row_index + 1,
                        sequence_column=active_slots["sequence"],
                        mode="detail",
                        known_basic_population=(
                            sequence
                            for sequence, record in records.items()
                            if "basic" in set(record.get("_observed_components") or ())
                        ),
                    )
                    continue
                if clustered_detail is not None or exact_fully_clustered_detail is not None:
                    active_slots = exact_fully_clustered_detail or clustered_detail or {}
                    mode = "detail"
                    basic_header_recovered = False
                    basic_cluster_column = None
                    detail_header_clustered = True
                    sequence_repairs = _employment_sequence_repairs(
                        rows,
                        start=row_index + 1,
                        sequence_column=active_slots["sequence"],
                        mode="detail",
                        known_basic_population=(
                            sequence
                            for sequence, record in records.items()
                            if "basic" in set(record.get("_observed_components") or ())
                        ),
                    )
                    continue
                if employment_section_active and provider_header is not None:
                    active_slots = provider_header
                    mode = "provider"
                    basic_header_recovered = False
                    basic_cluster_column = None
                    detail_header_clustered = False
                    sequence_repairs = {}
                    continue
                if not active_slots:
                    continue
                sequence_recovered = row_index in sequence_repairs
                sequence = sequence_repairs.get(row_index)
                if sequence is not None and not _employment_inferred_sequence_row_owned(
                    table,
                    row_index=row_index,
                    row=row,
                    sequence_column=active_slots["sequence"],
                    cluster_column=(
                        basic_cluster_column
                        if mode == "basic"
                        else None
                    ),
                ):
                    sequence = None
                    sequence_recovered = False
                if sequence is None:
                    sequence = _employment_sequence_value(row, active_slots)
                    if (
                        mode == "basic"
                        and _employment_sequence_cell_has_multirow_span(
                            table,
                            row=row_index,
                            column=active_slots["sequence"],
                        )
                    ):
                        sequence = None
                cluster_raw = ""
                if mode == "basic" and basic_cluster_column is not None:
                    cluster_raw = _slot_value(row, {"cluster": basic_cluster_column}, "cluster")
                    if active_slots.get("sequence") == basic_cluster_column:
                        match = re.fullmatch(r"\s*(\d{1,3})\s+(.+)", cluster_raw)
                        if match is not None:
                            sequence = sequence or int(match.group(1))
                            cluster_raw = match.group(2).strip()
                    cluster_owner = _employment_exact_lattice_owner(
                        table,
                        row=row_index,
                        column=basic_cluster_column,
                    )
                    if cluster_owner is None:
                        sequence = None
                        cluster_raw = ""
                    elif active_slots.get("sequence") == basic_cluster_column:
                        sequence_recovered = True
                if sequence is None and mode == "provider":
                    first = _clean(row[0] if row else "")
                    sequence = int(first) if first.isdigit() else None
                if sequence is not None and not sequence_recovered:
                    sequence_owner = _employment_exact_lattice_owner(
                        table,
                        row=row_index,
                        column=active_slots["sequence"],
                    )
                    if sequence_owner is None:
                        sequence = None
                if sequence is None:
                    if mode == "provider" and _nonempty(row):
                        _report_unkeyed_fragment(
                            parse_result,
                            dataset="employment_records",
                            row=row,
                            page=page,
                            table=table,
                            row_index=row_index,
                        )
                    elif mode in {"basic", "detail"} and _nonempty(row):
                        _report_unkeyed_business_row(
                            parse_result,
                            dataset="employment_records",
                            row=row,
                            page=page,
                            table=table,
                            row_index=row_index,
                        )
                    continue
                record = records.setdefault(
                    sequence,
                    {
                        "record_id": stable_record_id("credit_employment", sequence),
                        "employment_record_id": stable_record_id("credit_employment", sequence),
                        "sequence": sequence,
                        "page": page_number,
                        "source_page": source_page,
                        "source": "native_personal_detail_employment_table",
                        "source_refs": [],
                        "confidence": 1.0,
                    },
                )
                row_ref = _source_ref(page, table, row=row_index)
                if sequence_recovered:
                    row_ref["binding"] = "closed_canonical_employment_sequence_run"
                    row_ref["binding_quality"] = "closed_canonical_employment_sequence_run"
                record["source_refs"].append(row_ref)
                observed_components = record.setdefault("_observed_components", [])
                if mode not in observed_components:
                    observed_components.append(mode)
                if mode == "provider":
                    provider, provider_column, provider_resolution = _employment_provider_observation(
                        row,
                        sequence_column=active_slots["sequence"],
                    )
                    provider_owner = (
                        _employment_exact_lattice_owner(
                            table,
                            row=row_index,
                            column=provider_column,
                        )
                        if provider_column is not None
                        else None
                    )
                    if provider_resolution == "source_absent" and provider and provider_owner is not None:
                        _mark_source_absent(record, "data_provider", provider)
                    elif (
                        provider_resolution == "exact"
                        and provider
                        and provider_column is not None
                        and provider_owner is not None
                    ):
                        provider_raw = _clean(row[provider_column] if provider_column < len(row) else provider)
                        provider_bbox, provider_evidence = provider_owner
                        provider_ref = _source_ref(
                            page,
                            table,
                            row=row_index,
                            column=provider_column,
                        )
                        provider_ref.update(
                            {
                                "source": "native_detail_table_cell",
                                "bbox": list(provider_bbox),
                                "evidence_ids": list(provider_evidence),
                                "geometry_scope": "cell",
                                "geometry_status": "exact",
                                "canonical_template_id": str(
                                    getattr(page, "canonical_template_id", "") or ""
                                ),
                            }
                        )
                        _merge_exact_observation(
                            parse_result,
                            record,
                            dataset="employment_records",
                            target_record_id=str(record["employment_record_id"]),
                            field_name="data_provider",
                            value=provider,
                            raw=provider_raw,
                            source_ref=provider_ref,
                            parser_stage="candidate_b_employment_canonical_slots",
                        )
                    else:
                        _report_employment_provider_unresolved(
                            parse_result,
                            record=record,
                            row=row,
                            page=page,
                            table=table,
                            row_index=row_index,
                            resolution=(
                                "unowned"
                                if provider_column is not None and provider_owner is None
                                else provider_resolution
                            ),
                        )
                    continue
                if mode == "basic" and basic_cluster_column is not None:
                    target_record_id = str(record["employment_record_id"])
                    source_ref = _source_ref(
                        page,
                        table,
                        row=row_index,
                        column=basic_cluster_column,
                    )
                    source_ref["binding"] = "closed_canonical_employment_cluster"
                    source_ref["binding_quality"] = "closed_canonical_employment_cluster"
                    decoded = decode_employment_basic_cluster(cluster_raw)
                    for field_name, value in decoded.fields.items():
                        _merge_exact_observation(
                            parse_result,
                            record,
                            dataset="employment_records",
                            target_record_id=target_record_id,
                            field_name=field_name,
                            value=value,
                            raw=cluster_raw,
                            source_ref=source_ref,
                            parser_stage="candidate_b_employment_closed_cluster",
                        )
                    _report_collapsed_cluster_fields(
                        parse_result,
                        record,
                        dataset="employment_records",
                        target_record_id=target_record_id,
                        raw=decoded.unresolved_residue or cluster_raw,
                        source_ref=source_ref,
                        unresolved_fields=decoded.unresolved_fields,
                        parser_stage="candidate_b_employment_closed_cluster",
                    )
                    continue
                if mode == "detail" and detail_header_clustered:
                    _decode_clustered_employment_detail(
                        parse_result,
                        record=record,
                        row=row,
                        slots=active_slots,
                        page=page,
                        table=table,
                        row_index=row_index,
                    )
                    continue
                if mode == "basic" and sequence_recovered:
                    merged = _exact_employment_basic_merged_cell(table, row=row_index)
                    decoded = _decode_exact_employment_basic_merged_value(merged[1]) if merged is not None else None
                    if merged is not None and decoded is not None:
                        target_record_id = str(record["employment_record_id"])
                        employer_raw = _clean(row[1] if len(row) > 1 else "")
                        employer = _canonical_employer_name(employer_raw)
                        employer_owner = _exact_native_table_cell(table, row=row_index, column=1)
                        if employer is None or employer_owner is None:
                            _report_employment_slot_unresolved(
                                parse_result,
                                record=record,
                                field_name="employer",
                                row=row,
                                page=page,
                                table=table,
                                row_index=row_index,
                                column=1,
                            )
                        else:
                            _merge_exact_observation(
                                parse_result,
                                record,
                                dataset="employment_records",
                                target_record_id=target_record_id,
                                field_name="employer",
                                value=employer,
                                raw=employer_raw,
                                source_ref=_source_ref(page, table, row=row_index, column=1),
                                parser_stage="candidate_b_employment_exact_merged_basic_cell",
                            )
                        source_ref = _source_ref(page, table, row=row_index, column=merged[0])
                        source_ref["binding"] = "exact_three_slot_employment_cell"
                        source_ref["binding_quality"] = "exact_three_slot_employment_cell"
                        for field_name, value in decoded.items():
                            _merge_exact_observation(
                                parse_result,
                                record,
                                dataset="employment_records",
                                target_record_id=target_record_id,
                                field_name=field_name,
                                value=value,
                                raw=merged[1],
                                source_ref=source_ref,
                                parser_stage="candidate_b_employment_exact_merged_basic_cell",
                            )
                        _report_employment_slot_unresolved(
                            parse_result,
                            record=record,
                            field_name="employer_type",
                            row=row,
                            page=page,
                            table=table,
                            row_index=row_index,
                            column=merged[0],
                        )
                        continue
                roles = basic_aliases if mode == "basic" else detail_aliases
                for role in roles:
                    if role == "sequence":
                        continue
                    raw = _slot_value(row, active_slots, role)
                    ref = _source_ref(page, table, row=row_index, column=active_slots[role])
                    role_owner = _employment_exact_lattice_owner(
                        table,
                        row=row_index,
                        column=active_slots[role],
                    )
                    if role_owner is None:
                        _report_employment_slot_unresolved(
                            parse_result,
                            record=record,
                            field_name=role,
                            row=row,
                            page=page,
                            table=table,
                            row_index=row_index,
                            column=active_slots[role],
                        )
                        continue
                    owner_bbox, owner_evidence = role_owner
                    ref.update(
                        {
                            "source": "native_detail_table_cell",
                            "bbox": list(owner_bbox),
                            "evidence_ids": list(owner_evidence),
                            "geometry_scope": "cell",
                            "geometry_status": "exact",
                            "canonical_template_id": str(
                                getattr(page, "canonical_template_id", "") or ""
                            ),
                        }
                    )
                    if is_explicit_source_absence(raw):
                        _mark_source_absent(record, role, raw)
                        continue
                    if not raw:
                        if not (mode == "basic" and basic_header_recovered):
                            _report_employment_slot_unresolved(
                                parse_result,
                                record=record,
                                field_name=role,
                                row=row,
                                page=page,
                                table=table,
                                row_index=row_index,
                                column=active_slots[role],
                            )
                        continue
                    target_record_id = str(record["employment_record_id"])
                    if role == "entry_year":
                        match = re.fullmatch(r"\D*((?:19|20)\d{2})\D*", raw)
                        if match:
                            _merge_exact_observation(
                                parse_result,
                                record,
                                dataset="employment_records",
                                target_record_id=target_record_id,
                                field_name=role,
                                value=int(match.group(1)),
                                raw=raw,
                                source_ref=ref,
                                parser_stage="candidate_b_employment_canonical_slots",
                            )
                        else:
                            _reject_exact_observation(
                                parse_result,
                                record,
                                dataset="employment_records",
                                target_record_id=target_record_id,
                                field_name=role,
                                raw=raw,
                                source_ref=ref,
                                parser_stage="candidate_b_employment_canonical_slots",
                            )
                    elif role == "information_updated_date":
                        _merge_canonical_date_observation(
                            parse_result,
                            record,
                            dataset="employment_records",
                            target_record_id=target_record_id,
                            field_name=role,
                            raw=raw,
                            source_ref=ref,
                            parser_stage="candidate_b_employment_canonical_slots",
                        )
                    elif role == "employer_phone":
                        phone = _canonical_employer_phone(raw)
                        if phone is None:
                            _reject_exact_observation(
                                parse_result,
                                record,
                                dataset="employment_records",
                                target_record_id=target_record_id,
                                field_name=role,
                                raw=raw,
                                source_ref=ref,
                                parser_stage="candidate_b_employment_canonical_slots",
                            )
                        else:
                            _merge_exact_observation(
                                parse_result,
                                record,
                                dataset="employment_records",
                                target_record_id=target_record_id,
                                field_name=role,
                                value=phone,
                                raw=raw,
                                source_ref=ref,
                                parser_stage="candidate_b_employment_canonical_slots",
                            )
                    elif role == "employer_type":
                        employer_type = _finite_employment_value(raw, _EMPLOYER_TYPES)
                        if employer_type:
                            _merge_exact_observation(
                                parse_result,
                                record,
                                dataset="employment_records",
                                target_record_id=target_record_id,
                                field_name=role,
                                value=employer_type,
                                raw=raw,
                                source_ref=ref,
                                parser_stage="candidate_b_employment_canonical_slots",
                            )
                        else:
                            _reject_exact_observation(
                                parse_result,
                                record,
                                dataset="employment_records",
                                target_record_id=target_record_id,
                                field_name=role,
                                raw=raw,
                                source_ref=ref,
                                parser_stage="candidate_b_employment_canonical_slots",
                            )
                    elif role in _EMPLOYMENT_DETAIL_VOCABULARIES:
                        canonical = _finite_employment_value(raw, _EMPLOYMENT_DETAIL_VOCABULARIES[role])
                        if canonical:
                            _merge_exact_observation(
                                parse_result,
                                record,
                                dataset="employment_records",
                                target_record_id=target_record_id,
                                field_name=role,
                                value=canonical,
                                raw=raw,
                                source_ref=ref,
                                parser_stage="candidate_b_employment_canonical_slots",
                            )
                        else:
                            _reject_exact_observation(
                                parse_result,
                                record,
                                dataset="employment_records",
                                target_record_id=target_record_id,
                                field_name=role,
                                raw=raw,
                                source_ref=ref,
                                parser_stage="candidate_b_employment_canonical_slots",
                            )
                    elif role == "employer" and _canonical_employer_name(raw) is None:
                        _reject_exact_observation(
                            parse_result,
                            record,
                            dataset="employment_records",
                            target_record_id=target_record_id,
                            field_name=role,
                            raw=raw,
                            source_ref=ref,
                            parser_stage="candidate_b_employment_canonical_slots",
                        )
                    elif role == "employer_address" and (
                        not validate_pboc_field(raw, "address").valid
                        or re.match(r"^[A-Za-z](?:\s|(?=[\u3400-\u9fff]))", raw) is not None
                    ):
                        _reject_exact_observation(
                            parse_result,
                            record,
                            dataset="employment_records",
                            target_record_id=target_record_id,
                            field_name=role,
                            raw=raw,
                            source_ref=ref,
                            parser_stage="candidate_b_employment_canonical_slots",
                        )
                    else:
                        _merge_exact_observation(
                            parse_result,
                            record,
                            dataset="employment_records",
                            target_record_id=target_record_id,
                            field_name=role,
                            value=raw,
                            raw=raw,
                            source_ref=ref,
                            parser_stage="candidate_b_employment_canonical_slots",
                        )
                if mode == "basic" and basic_header_recovered:
                    for unresolved_role in basic_aliases:
                        if unresolved_role == "sequence":
                            continue
                        if (
                            record.get(unresolved_role)
                            or unresolved_role in record.get("_unresolved_fields", [])
                            or unresolved_role in record.get("_source_absent_fields", [])
                        ):
                            continue
                        _append_internal_field(record, "_unresolved_fields", unresolved_role)
                        record["extraction_status"] = "review"
                        _report_required_row_failure(
                            parse_result,
                            issue_code="candidate_b_employment_recovered_header_cell_unresolved",
                            dataset="employment_records",
                            sequence=sequence,
                            field_name=unresolved_role,
                            row=row,
                            page=page,
                            table=table,
                            row_index=row_index,
                            target_record_id=str(record["employment_record_id"]),
                        )
                required_roles = (
                    ("employer",)
                    if mode == "basic"
                    else (
                        "occupation",
                        "information_updated_date",
                    )
                )
                for required_role in required_roles:
                    if (
                        record.get(required_role)
                        or required_role in record.get("_unresolved_fields", [])
                        or required_role in record.get("_source_absent_fields", [])
                    ):
                        continue
                    _report_required_row_failure(
                        parse_result,
                        issue_code="candidate_b_employment_required_cell_unresolved",
                        dataset="employment_records",
                        sequence=sequence,
                        field_name=required_role,
                        row=row,
                        page=page,
                        table=table,
                        row_index=row_index,
                        target_record_id=str(record["employment_record_id"]),
                    )
            previous_table_id = table_id or previous_table_id
            previous_table_owned = _employment_source_owner(page, table) is not None
    from docmirror.plugins.credit_report.personal_detail_scanned.extraction_issues import (
        make_issue,
        record_issue,
    )

    _enforce_employment_record_contracts(parse_result, records.values())
    _prune_resolved_employment_field_issues(parse_result, records.values())
    for sequence, record in records.items():
        observed_components = set(record.get("_observed_components") or ())
        missing_components = [
            component for component in ("basic", "detail", "provider") if component not in observed_components
        ]
        if not missing_components:
            continue
        record["extraction_status"] = "review"
        record_issue(
            parse_result,
            make_issue(
                category="ocr_structure_correction",
                issue_code="candidate_b_employment_component_missing",
                message="A canonical employment row is missing one or more schema components.",
                parser_stage="candidate_b_employment_canonical_slots",
                target_dataset="employment_records",
                target_record_id=str(record["employment_record_id"]),
                field_name="employment_components",
                observed_value={
                    "sequence": sequence,
                    "observed_components": sorted(observed_components),
                },
                candidate_value={"missing_components": missing_components},
                source_refs=tuple(record.get("source_refs") or ()),
                reason_codes=(
                    "canonical_employment_row_observed",
                    "component_population_incomplete",
                    "row_marked_for_review",
                ),
            ),
        )
    output = [records[key] for key in sorted(records)]
    _enforce_observed_header_terminal_invariant(
        parse_result,
        dataset="employment_records",
        aliases=basic_aliases,
        records=output,
    )
    _enforce_observed_header_terminal_invariant(
        parse_result,
        dataset="employment_records",
        aliases=detail_aliases,
        records=output,
    )
    return output


def _credible_sequence_endpoint(values: set[int]) -> tuple[int | None, list[int]]:
    """Return a dense sequence endpoint and isolate implausible OCR outliers."""
    if not values:
        return None, []
    # Printed ordinals are dense within a PBOC account family. Permit a small
    # number of missing observations, but never let one account identifier or
    # OCR-joined number inflate the expected row count by dozens of records.
    ceiling = max(3, len(values) + max(2, len(values) // 4))
    credible = {value for value in values if 1 <= value <= ceiling}
    # Three exact consecutive ordinals at the observed high edge are an
    # independent printed tail, not one joined identifier.  Accept the whole
    # tail while retaining the conservative treatment of isolated highs such
    # as ``{1, 3, 115}``.
    high_values = sorted(value for value in values if value > ceiling and value > 0)
    consecutive_tail: list[int] = []
    if high_values:
        consecutive_tail = [high_values[-1]]
        for value in reversed(high_values[:-1]):
            if value != consecutive_tail[0] - 1:
                break
            consecutive_tail.insert(0, value)
    if len(consecutive_tail) >= 3:
        credible.update(consecutive_tail)
    outliers = sorted(values - credible)
    return (max(credible) if credible else None), outliers


def _inquiry_sequence_endpoint(
    values: set[int],
    rejected_values: Iterable[int] = (),
) -> tuple[int | None, list[int]]:
    """Return the endpoint after ordered row proof identifies any rejects.

    Unlike account-family discovery, a canonical inquiry sequence is already
    bound to the exact leftmost header column, so a sparse high ordinal is
    valid evidence of preceding rows.  Prefix removal is intentionally not
    attempted from this unordered set; callers must supply values rejected by
    :func:`_document_local_inquiry_ordinals` using exact adjacent-row proof.
    """

    retained = {value for value in values if 1 <= value <= 9999}
    rejected = sorted(
        {
            int(value)
            for value in rejected_values
            if isinstance(value, int) and not isinstance(value, bool) and 1 <= value <= 9999
        }
    )
    retained.difference_update(rejected)
    return (max(retained) if retained else None), rejected


def _bounded_exact_headerless_inquiry_continuation(
    parse_result: Any,
    active_group: Mapping[str, Any] | None,
    slots: Mapping[str, int],
    table: Any,
    rows: list[list[str]],
    *,
    start: int,
) -> bool:
    """Prove one headerless continuation from exact dense row-local cells.

    This is intentionally independent of dataset-wide page refs.  It exists for
    canonical inquiry pages whose registered order edge is unavailable while
    every printed row still proves the fixed four-column schema and the next
    dense ordinal in the one active typed population.
    """

    if (
        not isinstance(active_group, Mapping)
        or set(slots) != {"sequence", "inquiry_date", "institution", "reason"}
        or len(set(slots.values())) != 4
        or set(slots.values()) != {0, 1, 2, 3}
        or not 0 <= start < len(rows)
    ):
        return False
    prior_observations = [
        observation for observation in active_group.get("observations") or () if isinstance(observation, Mapping)
    ]
    prior_types = {
        str(observation.get("inquiry_type")) for observation in prior_observations if observation.get("inquiry_type")
    }
    prior_sequences = {
        int(observation.get("raw_sequence") or 0)
        for observation in prior_observations
        if isinstance(observation.get("raw_sequence"), int)
        and not isinstance(observation.get("raw_sequence"), bool)
        and int(observation.get("raw_sequence") or 0) > 0
    }
    if len(prior_types) != 1 or not prior_sequences:
        return False
    expected_type = next(iter(prior_types))
    expected_sequence = max(prior_sequences) + 1
    body_rows = [(row_index, row) for row_index, row in enumerate(rows[start:], start=start) if _nonempty(row)]
    if not body_rows:
        return False
    raw_sequences: list[int | None] = []
    noisy_sequences: list[tuple[int, str] | None] = []
    row_types: list[str] = []
    for row_index, row in body_rows:
        if len(row) != 4:
            return False
        split_rows = _bounded_two_row_inquiry_cell_split(
            parse_result,
            table,
            row_index=row_index,
            slots=slots,
        )
        if split_rows is not None:
            for split_row in split_rows:
                raw_sequences.append(int(split_row["sequence"]))
                noisy_sequences.append(None)
                row_types.append(str(split_row["inquiry_type"]))
            continue
        sequence = _inquiry_sequence_token(_slot_value(row, slots, "sequence"))
        institution = _slot_value(row, slots, "institution")
        reason = _slot_value(row, slots, "reason")
        inquiry_type = (
            "personal"
            if _compact(_normalized_inquiry_field("institution", institution)) == "本人"
            or _compact(_normalized_inquiry_field("reason", reason)).startswith("本人查询")
            else "institution"
            if _compact(institution) or _compact(reason)
            else ""
        )
        if (
            _exact_native_table_cell(
                table,
                row=row_index,
                column=int(slots["sequence"]),
            )
            is None
            or _bounded_inquiry_date(_slot_value(row, slots, "inquiry_date")) is None
            or (
                not _compact(institution)
                and _native_table_cell_span(
                    table,
                    row=row_index,
                    column=int(slots["inquiry_date"]),
                )
                != (1, 2)
            )
            or not _compact(reason)
            or inquiry_type != expected_type
            or any(
                _exact_native_table_cell(
                    table,
                    row=row_index,
                    column=int(slots[role]),
                )
                is None
                for role in ("reason",)
            )
        ):
            return False
        raw_sequences.append(sequence)
        noisy_sequences.append(_bounded_inquiry_sequence_noise_candidate(_slot_value(row, slots, "sequence")))
        row_types.append(inquiry_type)
    normalized = _document_local_inquiry_ordinals(
        raw_sequences,
        noisy_candidates=noisy_sequences,
    )
    sequences = [sequence for sequence, _repair in normalized]
    return bool(
        sequences
        and all(sequence is not None for sequence in sequences)
        and [int(sequence or 0) for sequence in sequences]
        == list(range(expected_sequence, expected_sequence + len(sequences)))
        and set(row_types) == {expected_type}
    )


def _bounded_headerless_inquiry_table_bootstrap(
    parse_result: Any,
    page: Any,
    table: Any,
    rows: list[list[str]],
    *,
    slots: Mapping[str, int],
    later_tables: Iterable[Any],
) -> dict[str, Any] | None:
    """Describe one source-sealed headerless institutional population.

    The descriptor proves record identities only.  It deliberately does not
    promote noisy dates, institutions, or reasons; the normal business-row path
    keeps those values subject to its stricter finite-field contracts.
    """

    required = ("sequence", "inquiry_date", "institution", "reason")
    if (
        not canonical_table_owned_by(
            parse_result,
            page,
            table,
            "annotations_and_inquiries",
        )
        or set(slots) != set(required)
        or len(set(slots.values())) != 4
        or set(slots.values()) != {0, 1, 2, 3}
        or not rows
        or any(not _nonempty(row) or len(row) != 4 for row in rows)
    ):
        return None

    logical_page = int(getattr(page, "page_number", 0) or 0)
    source_page = int(getattr(page, "source_page_number", 0) or logical_page)
    table_id = str(getattr(table, "table_id", "") or "")
    table_bbox = _exact_geometry_bbox(getattr(table, "bbox", None))
    geometry = _native_table_geometry(table)
    row_bands = (
        _indexed_geometry_bands(
            geometry,
            "row_bands",
            lower_key="y0",
            upper_key="y1",
        )
        if geometry is not None
        else None
    )
    column_bands = (
        _indexed_geometry_bands(
            geometry,
            "col_bands",
            lower_key="x0",
            upper_key="x1",
        )
        if geometry is not None
        else None
    )
    if (
        logical_page <= 0
        or source_page <= 0
        or not table_id
        or table_bbox is None
        or row_bands is None
        or set(row_bands) != set(range(len(rows)))
        or column_bands is None
        or set(column_bands) != set(slots.values())
    ):
        return None

    lower_seals: list[dict[str, Any]] = []
    for later_table in later_tables:
        later_rows = _table_rows(later_table)
        later_bbox = _exact_geometry_bbox(getattr(later_table, "bbox", None))
        if (
            len(later_rows) < 2
            or later_bbox is None
            or table_bbox[3] > later_bbox[1]
            or [_compact(value) for value in later_rows[0]] != ["编号", "查询日期", "查询机构", "查询原因"]
        ):
            continue
        header_cells = [
            _exact_native_table_cell(
                later_table,
                row=0,
                column=int(slots[role]),
            )
            for role in required
        ]
        if any(cell is None for cell in header_cells):
            continue
        personal_witness = _exact_native_inquiry_row_witness(
            page,
            later_table,
            row_index=1,
            slots=slots,
        )
        personal_record = personal_witness.get("record") if isinstance(personal_witness, Mapping) else None
        if (
            not isinstance(personal_record, Mapping)
            or personal_record.get("inquiry_type") != "personal"
            or int(personal_record.get("sequence") or 0) != 1
        ):
            continue
        header_evidence = {evidence_id for cell in header_cells if cell is not None for evidence_id in cell[1]}
        personal_ref = personal_witness.get("source_ref") or {}
        personal_evidence = {str(value) for value in personal_ref.get("evidence_ids") or () if str(value or "")}
        later_table_id = str(getattr(later_table, "table_id", "") or "")
        if not later_table_id or not header_evidence or not personal_evidence or header_evidence & personal_evidence:
            continue
        lower_seals.append(
            {
                "table_id": later_table_id,
                "bbox": list(later_bbox),
                "evidence_ids": sorted(header_evidence | personal_evidence),
            }
        )
    if len(lower_seals) != 1:
        return None

    observations: list[dict[str, Any]] = []
    all_tail_evidence: set[str] = set()
    collapsed_rows = 0
    for row_index, row in enumerate(rows):
        source_field_values: dict[str, str] = {}
        exact_cells: dict[
            str,
            tuple[tuple[float, float, float, float], tuple[str, ...]],
        ] = {}
        field_refs: dict[str, list[dict[str, Any]]] = {}
        for role in required:
            column = int(slots[role])
            exact_cell = _exact_native_table_cell(
                table,
                row=row_index,
                column=column,
            )
            if exact_cell is not None:
                bbox, evidence_ids = exact_cell
                if all_tail_evidence.intersection(evidence_ids):
                    return None
                all_tail_evidence.update(evidence_ids)
                exact_cells[role] = exact_cell
                if role != "sequence":
                    field_refs[role] = [
                        {
                            **_source_ref(
                                page,
                                table,
                                row=row_index,
                                column=column,
                            ),
                            "bbox": list(bbox),
                            "geometry_scope": "cell",
                            "evidence_ids": list(evidence_ids),
                            "field_name": role,
                            "binding": "canonical_header_column",
                            "binding_quality": "canonical_header_column",
                        }
                    ]
                continue
            date_column = int(slots["inquiry_date"])
            date_span = _native_table_cell_span(
                table,
                row=row_index,
                column=date_column,
            )
            if role == "institution" and date_span == (1, 2):
                continue
            if role != "inquiry_date" or date_span != (1, 2):
                return None
            span_owner = _exact_native_table_span_owner(
                table,
                row=row_index,
                column=date_column,
                span=(1, 2),
            )
            if span_owner is None:
                return None
            _span_bbox, span_evidence = span_owner
            if all_tail_evidence & set(span_evidence):
                return None
            all_tail_evidence.update(span_evidence)
            span_tokens = _exact_native_table_cell_tokens(
                parse_result,
                table,
                row=row_index,
                column=date_column,
                allowed_span=(1, 2),
                logical_page=logical_page,
            )
            # Token decoding is optional for the population descriptor.  The
            # exact merged-cell owner above proves that this source band exists;
            # it does not prove which token owns either business field.  Retain
            # field-local refs only when the stricter token geometry succeeds.
            if span_tokens is not None:
                date_tokens = [
                    token
                    for token in span_tokens
                    if _bounded_inquiry_date(token[0]) is not None
                    and column_bands[date_column][0] - 1.0
                    <= (token[1][0] + token[1][2]) / 2.0
                    <= column_bands[date_column][1] + 1.0
                ]
                institution_column = int(slots["institution"])
                institution_tokens = [
                    token
                    for token in span_tokens
                    if column_bands[institution_column][0] - 1.0
                    <= (token[1][0] + token[1][2]) / 2.0
                    <= column_bands[institution_column][1] + 1.0
                ]
                if (
                    len(date_tokens) == 1
                    and len(institution_tokens) == 1
                    and date_tokens[0][2] != institution_tokens[0][2]
                ):
                    for field_name, token in (
                        ("inquiry_date", date_tokens[0]),
                        ("institution", institution_tokens[0]),
                    ):
                        token_text, token_bbox, token_id = token
                        source_field_values[field_name] = token_text
                        field_refs[field_name] = [
                            {
                                "source": "native_detail_inquiry_token",
                                "logical_page": logical_page,
                                "source_page": source_page,
                                "table_id": table_id,
                                "row": row_index,
                                "column": int(slots[field_name]),
                                "bbox": list(token_bbox),
                                "geometry_scope": "token",
                                "evidence_ids": [token_id],
                                "field_name": field_name,
                                "binding": "canonical_header_column_token",
                                "binding_quality": "exact_token_in_canonical_cell",
                            }
                        ]

        raw_institution = _slot_value(row, slots, "institution")
        raw_reason = _slot_value(row, slots, "reason")
        if _compact(_normalized_inquiry_field("institution", raw_institution)) == "本人" or _compact(
            _normalized_inquiry_field("reason", raw_reason)
        ).startswith("本人查询"):
            return None
        sequence_cell = exact_cells.get("sequence")
        if sequence_cell is None:
            return None
        sequence_bbox, sequence_evidence = sequence_cell
        sequence = _inquiry_sequence_token(_slot_value(row, slots, "sequence"))
        if sequence is not None:
            observations.append(
                {
                    "raw_sequence": sequence,
                    "raw_sequence_text": _clean(_slot_value(row, slots, "sequence")),
                    "noisy_sequence": None,
                    "sequence": sequence,
                    "inquiry_type": "institution",
                    "inquiry_date": source_field_values.get(
                        "inquiry_date",
                        _slot_value(row, slots, "inquiry_date"),
                    ),
                    "institution": source_field_values.get(
                        "institution",
                        raw_institution,
                    ),
                    "reason": raw_reason,
                    "exact_lattice_row": len(exact_cells) == 4,
                    "population_ordinal_only": True,
                    "source_ref": {
                        **_source_ref(
                            page,
                            table,
                            row=row_index,
                            column=int(slots["sequence"]),
                        ),
                        "bbox": list(sequence_bbox),
                        "geometry_scope": "cell",
                        "evidence_ids": list(sequence_evidence),
                        "sequence": sequence,
                        "binding": "printed_inquiry_ordinal_cell",
                        "binding_quality": "exact_cell_in_sequence_column",
                    },
                    "field_source_refs": field_refs,
                    "row_index": row_index,
                }
            )
            continue

        if row_index != len(rows) - 1 or collapsed_rows:
            return None
        sequence_tokens = _exact_native_table_cell_tokens(
            parse_result,
            table,
            row=row_index,
            column=int(slots["sequence"]),
            logical_page=logical_page,
        )
        split_sequences = (
            [_inquiry_sequence_token(token[0]) for token in sequence_tokens]
            if sequence_tokens is not None and len(sequence_tokens) == 2
            else []
        )
        if (
            len(split_sequences) != 2
            or any(sequence is None for sequence in split_sequences)
            or int(split_sequences[1] or 0) != int(split_sequences[0] or 0) + 1
            or sequence_tokens is None
            or sequence_tokens[0][1][3] > sequence_tokens[1][1][1] + 1.0
        ):
            return None
        split_rows = _bounded_two_row_inquiry_cell_split(
            parse_result,
            table,
            row_index=row_index,
            slots=slots,
            logical_page=logical_page,
        )
        if split_rows is not None and (
            len(split_rows) != 2 or any(split_row.get("inquiry_type") != "institution" for split_row in split_rows)
        ):
            split_rows = None
        collapsed_rows += 1
        for split_index, (_text, token_bbox, token_id) in enumerate(sequence_tokens):
            split_sequence = int(split_sequences[split_index] or 0)
            split_row = split_rows[split_index] if split_rows is not None else {}
            split_field_refs = deepcopy(split_row.get("source_refs_by_field") or {})
            for refs in split_field_refs.values():
                for ref in refs:
                    ref["logical_page"] = logical_page
                    ref["source_page"] = source_page
            observations.append(
                {
                    "raw_sequence": split_sequence,
                    "raw_sequence_text": str(split_sequence),
                    "noisy_sequence": None,
                    "sequence": split_sequence,
                    "inquiry_type": "institution",
                    "inquiry_date": split_row.get("inquiry_date", ""),
                    "institution": split_row.get("institution", ""),
                    "reason": split_row.get("reason", ""),
                    "exact_lattice_row": False,
                    "population_ordinal_only": True,
                    "source_ref": {
                        "source": "native_detail_inquiry_token_ordinal",
                        "logical_page": logical_page,
                        "source_page": source_page,
                        "table_id": table_id,
                        "row": row_index,
                        "column": int(slots["sequence"]),
                        "sequence": split_sequence,
                        "bbox": list(token_bbox),
                        "geometry_scope": "token",
                        "evidence_ids": [token_id],
                        "binding": "printed_inquiry_ordinal_token",
                        "binding_quality": "exact_token_in_sequence_cell",
                    },
                    "field_source_refs": split_field_refs,
                    "row_index": row_index,
                }
            )

    sequences = [int(observation["sequence"]) for observation in observations]
    if (
        sequences[0] <= 1
        # Two distinct exact boundary rows are the smallest population that
        # can establish a headerless *tail*.  A single row remains an orphan,
        # even with the independent lower personal-header seal.
        or sequences[0] >= sequences[-1]
        or sequences != list(range(sequences[0], sequences[-1] + 1))
        or all_tail_evidence & set(lower_seals[0]["evidence_ids"])
    ):
        return None
    first_witness = _exact_native_inquiry_row_witness(
        page,
        table,
        row_index=0,
        slots=slots,
    )
    first_record = first_witness.get("record") if isinstance(first_witness, Mapping) else None
    if (
        not isinstance(first_record, Mapping)
        or first_record.get("inquiry_type") != "institution"
        or int(first_record.get("sequence") or 0) != sequences[0]
    ):
        return None
    if not collapsed_rows:
        last_witness = _exact_native_inquiry_row_witness(
            page,
            table,
            row_index=len(rows) - 1,
            slots=slots,
        )
        last_record = last_witness.get("record") if isinstance(last_witness, Mapping) else None
        if (
            not isinstance(last_record, Mapping)
            or last_record.get("inquiry_type") != "institution"
            or int(last_record.get("sequence") or 0) != sequences[-1]
        ):
            return None

    return {
        "inquiry_type": "institution",
        "slots": dict(slots),
        "start": 0,
        "first_sequence": sequences[0],
        "last_sequence": sequences[-1],
        "ordinal_observations": observations,
        "source_refs": [
            {
                **_source_ref(page, table),
                "bbox": list(table_bbox),
                "geometry_scope": "table",
                "evidence_ids": sorted(all_tail_evidence),
                "binding": "sealed_headerless_inquiry_population",
            }
        ],
        "lower_personal_header_seal": lower_seals[0],
    }


def _bounded_headerless_inquiry_population_continuation(
    descriptor: Mapping[str, Any] | None,
    *,
    active_slots: Mapping[str, int],
    active_sequence_endpoint: int,
    active_inquiry_types: Iterable[str],
    carry_allowed: bool,
) -> bool:
    """Bind a sealed tail only to its exact preceding institutional group."""

    if not isinstance(descriptor, Mapping) or not carry_allowed:
        return False
    try:
        first_sequence = int(descriptor.get("first_sequence") or 0)
        endpoint = int(active_sequence_endpoint or 0)
    except (TypeError, ValueError):
        return False
    types = {str(inquiry_type) for inquiry_type in active_inquiry_types if str(inquiry_type or "")}
    return bool(
        descriptor.get("inquiry_type") == "institution"
        and dict(descriptor.get("slots") or {}) == dict(active_slots)
        and set(active_slots) == {"sequence", "inquiry_date", "institution", "reason"}
        and len(set(active_slots.values())) == 4
        and types == {"institution"}
        and endpoint > 0
        and first_sequence == endpoint + 1
    )


def _bounded_headerless_inquiry_population_token_bridge(
    parse_result: Any,
    descriptor: Mapping[str, Any] | None,
    *,
    active_group: Mapping[str, Any] | None,
    active_sequence_endpoint: int,
    active_group_page: int | None,
    current_page: int,
    carry_allowed: bool,
) -> list[dict[str, Any]] | None:
    """Bridge one damaged schema boundary using its exact terminal token band.

    Some reconstructed inquiry headers collide the printed ordinal/date slots,
    so ordinary row coverage can stop two identities before a sealed headerless
    population.  The only accepted bridge is the immediately preceding page's
    unique final physical row, split into two complete four-column token rows.
    Those rows must be institutional and exactly close the ordinal gap to the
    descriptor.  This adds source observations only; extraction records remain
    owned by the ordinary exact-token row path.
    """

    if (
        not isinstance(descriptor, Mapping)
        or not isinstance(active_group, Mapping)
        or not carry_allowed
        or not isinstance(active_group_page, int)
        or isinstance(active_group_page, bool)
        or current_page != active_group_page + 1
        or descriptor.get("inquiry_type") != "institution"
    ):
        return None
    try:
        endpoint = int(active_sequence_endpoint or 0)
        first_sequence = int(descriptor.get("first_sequence") or 0)
    except (TypeError, ValueError):
        return None
    if endpoint <= 0 or first_sequence != endpoint + 3:
        return None

    prior_pages = [
        page
        for page in getattr(parse_result, "pages", None) or ()
        if int(getattr(page, "page_number", 0) or 0) == active_group_page
        and any(
            canonical_table_owned_by(
                parse_result,
                page,
                candidate,
                "annotations_and_inquiries",
            )
            for candidate in getattr(page, "tables", None) or ()
        )
    ]
    if len(prior_pages) != 1:
        return None
    candidates: list[tuple[Any, int]] = []
    for table in _inquiry_page_tables_in_physical_order(prior_pages[0]):
        if not canonical_table_owned_by(
            parse_result,
            prior_pages[0],
            table,
            "annotations_and_inquiries",
        ):
            continue
        rows = _table_rows(table)
        if not rows:
            continue
        row_index = len(rows) - 1
        split_rows = _bounded_two_row_inquiry_cell_split(
            parse_result,
            table,
            row_index=row_index,
            slots={
                "sequence": 0,
                "inquiry_date": 1,
                "institution": 2,
                "reason": 3,
            },
            logical_page=active_group_page,
        )
        if split_rows is not None:
            candidates.append((table, row_index))
    if len(candidates) != 1:
        return None
    table, row_index = candidates[0]
    split_rows = _bounded_two_row_inquiry_cell_split(
        parse_result,
        table,
        row_index=row_index,
        slots={
            "sequence": 0,
            "inquiry_date": 1,
            "institution": 2,
            "reason": 3,
        },
        logical_page=active_group_page,
    )
    if (
        split_rows is None
        or [row.get("sequence") for row in split_rows] != [endpoint + 1, endpoint + 2]
        or any(row.get("inquiry_type") != "institution" for row in split_rows)
    ):
        return None

    source_page = int(getattr(prior_pages[0], "source_page_number", 0) or active_group_page)
    observations: list[dict[str, Any]] = []
    for split_row in split_rows:
        sequence = int(split_row["sequence"])
        field_refs = deepcopy(split_row.get("source_refs_by_field") or {})
        for refs in field_refs.values():
            for ref in refs:
                ref["logical_page"] = active_group_page
                ref["source_page"] = source_page
        observations.append(
            {
                "raw_sequence": sequence,
                "raw_sequence_text": str(sequence),
                "noisy_sequence": None,
                "sequence": sequence,
                "inquiry_type": "institution",
                "inquiry_date": split_row.get("inquiry_date", ""),
                "institution": split_row.get("institution", ""),
                "reason": split_row.get("reason", ""),
                "exact_lattice_row": False,
                "population_ordinal_only": True,
                "source_ref": {
                    "source": "native_detail_inquiry_token_row",
                    "logical_page": active_group_page,
                    "source_page": source_page,
                    "table_id": str(getattr(table, "table_id", "") or ""),
                    "row": row_index,
                    "sequence": sequence,
                    "bbox": list(split_row["bbox"]),
                    "geometry_scope": "token_row",
                    "evidence_ids": list(split_row["evidence_ids"]),
                    "binding": "canonical_header_token_row",
                    "binding_quality": "exact_token_row",
                },
                "field_source_refs": field_refs,
                "row_index": row_index,
            }
        )
    return observations


def _raw_inquiry_source_member(value: Any, name: str, default: Any = None) -> Any:
    """Read one immutable source-plane member from mappings or models."""

    if isinstance(value, Mapping):
        return value.get(name, default)
    return getattr(value, name, default)


def _sealed_raw_inquiry_page_order(
    parse_result: Any,
) -> tuple[
    list[tuple[tuple[int, int], int, int, Any]],
    bool,
    frozenset[int],
] | None:
    """Return a complete authoritative order for the frozen source pages.

    The raw inquiry census must not consume the mutable canonical page plane.
    Global reading order is preferred.  When it is unavailable, the same
    frozen topology proof used by the agreement census is required; logical
    page numbers are never treated as an implicit order.
    """

    frozen_pages = getattr(parse_result, "_frozen_logical_pages", None)
    if not isinstance(frozen_pages, Mapping) or not frozen_pages:
        return None
    page_rows: list[tuple[int, int, Any]] = []
    seen_logical: set[int] = set()
    for page in frozen_pages.values():
        try:
            logical_page = int(
                _raw_inquiry_source_member(
                    page,
                    "page_number",
                    _raw_inquiry_source_member(page, "page", 0),
                )
            )
            source_page = int(
                _raw_inquiry_source_member(
                    page,
                    "source_page_number",
                    _raw_inquiry_source_member(page, "source_page", 0),
                )
            )
        except (TypeError, ValueError):
            return None
        if logical_page <= 0 or source_page <= 0 or logical_page in seen_logical:
            return None
        seen_logical.add(logical_page)
        page_rows.append((logical_page, source_page, page))

    resolution = getattr(parse_result, "reading_order_resolution", None)
    raw_order = getattr(parse_result, "reading_order_by_logical", None)
    global_authority = bool(
        isinstance(resolution, Mapping)
        and resolution.get("resolved") is True
        and resolution.get("authoritative") is True
        and isinstance(raw_order, Mapping)
        and raw_order
    )
    local_authority = False
    complete_sources: frozenset[int] = frozenset()
    positions: dict[int, tuple[int, int]] = {}
    if global_authority:
        normalized: dict[int, int] = {}
        try:
            for raw_logical, raw_position in raw_order.items():
                logical_page = int(raw_logical)
                position = int(raw_position)
                if logical_page <= 0 or position <= 0 or logical_page in normalized:
                    return None
                normalized[logical_page] = position
        except (TypeError, ValueError):
            return None
        if (
            len(normalized) != len(raw_order)
            or set(normalized) != seen_logical
            or len(set(normalized.values())) != len(normalized)
            or sorted(normalized.values()) != list(range(1, len(normalized) + 1))
        ):
            return None
        positions = {
            logical_page: (normalized[logical_page], 0)
            for logical_page in seen_logical
        }
    else:
        # Defined below this census in order to keep the agreement patch
        # isolated.  Runtime lookup occurs only after module initialization.
        local = _sealed_agreement_local_topology_keys(parse_result, page_rows)
        if local is None:
            return None
        local_authority = True
        positions, complete_sources = local

    ordered = [
        (positions[logical_page], logical_page, source_page, page)
        for logical_page, source_page, page in page_rows
    ]
    if len({position for position, *_rest in ordered}) != len(ordered):
        return None
    ordered.sort(key=lambda item: item[0])
    return ordered, local_authority, complete_sources


def _sealed_raw_inquiry_envelope(
    parse_result: Any,
) -> dict[str, Any] | None:
    """Locate one exact registered inquiry section on the frozen source plane."""

    ordered_result = _sealed_raw_inquiry_page_order(parse_result)
    if ordered_result is None:
        return None
    page_rows, local_authority, complete_sources = ordered_result
    text_evidence_counts: Counter[str] = Counter()
    for _position, _logical_page, _source_page, page in page_rows:
        for block in _raw_inquiry_source_member(page, "texts", ()) or ():
            raw_ids = _raw_inquiry_source_member(block, "evidence_ids")
            if isinstance(raw_ids, (list, tuple)):
                text_evidence_counts.update(
                    str(value or "").strip()
                    for value in raw_ids
                    if str(value or "").strip()
                )

    structural: list[dict[str, Any]] = []
    seen_structural_ids: set[str] = set()
    for page_position, logical_page, source_page, page in page_rows:
        local_items: list[dict[str, Any]] = []
        for block in _raw_inquiry_source_member(page, "texts", ()) or ():
            raw_text = str(
                _raw_inquiry_source_member(
                    block,
                    "content",
                    _raw_inquiry_source_member(block, "text", ""),
                )
                or ""
            )
            section = canonical_registered_section_heading(raw_text)
            subsection = canonical_registered_subsection_heading(raw_text)
            kind = ""
            title = ""
            if section == "查询记录明细" or (
                subsection is not None and subsection[1] == "查询记录"
            ):
                kind = "start"
                title = section or subsection[1]
            elif subsection is not None and subsection[1] in {
                "查询记录机构查询记录明细",
                "机构查询记录明细",
            }:
                kind = "institution_start"
                title = subsection[1]
            elif subsection is not None and subsection[1] == "本人查询记录明细":
                kind = "personal_start"
                title = subsection[1]
            elif (
                section is not None and section != "查询记录明细"
            ) or (
                subsection is not None
                and subsection[0] != "annotations_and_inquiries"
            ):
                kind = "boundary"
                title = section or subsection[1]
            if not kind:
                continue
            bbox = _exact_geometry_bbox(_raw_inquiry_source_member(block, "bbox"))
            raw_ids = _raw_inquiry_source_member(block, "evidence_ids")
            if bbox is None or not isinstance(raw_ids, (list, tuple)):
                return None
            evidence_ids = tuple(str(value or "").strip() for value in raw_ids)
            if (
                not evidence_ids
                or any(not value for value in evidence_ids)
                or len(evidence_ids) != len(set(evidence_ids))
                or any(value in seen_structural_ids for value in evidence_ids)
                or any(text_evidence_counts[value] != 1 for value in evidence_ids)
            ):
                return None
            seen_structural_ids.update(evidence_ids)
            local_items.append(
                {
                    "kind": kind,
                    "title": title,
                    "logical_page": logical_page,
                    "source_page": source_page,
                    "page_position": page_position,
                    "bbox": bbox,
                    "evidence_ids": evidence_ids,
                }
            )
        local_items.sort(
            key=lambda item: (
                item["bbox"][1],
                item["bbox"][0],
                item["bbox"][3],
                item["bbox"][2],
            )
        )
        if any(
            min(left["bbox"][3], right["bbox"][3])
            > max(left["bbox"][1], right["bbox"][1])
            for left, right in zip(local_items, local_items[1:])
        ):
            return None
        structural.extend(local_items)

    starts = [item for item in structural if item["kind"] == "start"]
    institution_starts = [
        item for item in structural if item["kind"] == "institution_start"
    ]
    if len(starts) != 1 or len(institution_starts) != 1:
        return None
    start = starts[0]
    institution_start = institution_starts[0]

    def structural_key(item: Mapping[str, Any]) -> tuple[Any, ...]:
        bbox = item["bbox"]
        return (*item["page_position"], bbox[1], bbox[0], bbox[3], bbox[2])

    start_key = structural_key(start)
    institution_key = structural_key(institution_start)
    boundaries = [
        item
        for item in structural
        if item["kind"] == "boundary" and structural_key(item) > start_key
    ]
    if institution_key <= start_key or not boundaries:
        return None
    boundary = min(boundaries, key=structural_key)
    boundary_key = structural_key(boundary)
    if institution_key >= boundary_key:
        return None
    # A second query start/owner is a competing envelope, even if its page
    # happens to be adjacent to the accepted one.
    if any(
        item is not institution_start
        and item["kind"] == "institution_start"
        and start_key < structural_key(item) < boundary_key
        for item in structural
    ):
        return None

    if local_authority:
        envelope_pages = [
            row
            for row in page_rows
            if start["page_position"] <= row[0] <= boundary["page_position"]
        ]
        sources: list[int] = []
        for _position, _logical_page, source_page, _page in envelope_pages:
            if not sources or sources[-1] != source_page:
                sources.append(source_page)
        if (
            not envelope_pages
            or any(source not in complete_sources for source in sources)
            or sources != list(range(sources[0], sources[-1] + 1))
        ):
            return None

    return {
        "page_rows": page_rows,
        "start": start,
        "institution_start": institution_start,
        "structural": tuple(structural),
        "boundary": boundary,
        "lower_key": institution_key,
        "upper_key": boundary_key,
        "structural_evidence_ids": frozenset(seen_structural_ids),
    }


def _sealed_raw_inquiry_cell_grid(
    parse_result: Any,
    page: Any,
    table: Any,
) -> dict[str, Any] | None:
    """Authenticate every cell/token owner in one physical source table."""

    rows = _table_rows(table)
    geometry = _native_table_geometry(table)
    table_bbox = _exact_geometry_bbox(getattr(table, "bbox", None))
    logical_page = int(_raw_inquiry_source_member(page, "page_number", 0) or 0)
    source_page = int(
        _raw_inquiry_source_member(page, "source_page_number", logical_page)
        or logical_page
    )
    table_id = str(_raw_inquiry_source_member(table, "table_id", "") or "")
    if (
        not rows
        or geometry is None
        or table_bbox is None
        or logical_page <= 0
        or source_page <= 0
        or not table_id
    ):
        return None
    column_count = len(rows[0])
    if column_count not in {3, 4, 6} or any(len(row) != column_count for row in rows):
        return None
    exact_header_owner = exact_inquiry_header_owner(table)
    exact_header_columns = (
        exact_header_owner.columns() if exact_header_owner is not None else {}
    )
    row_bands = _indexed_geometry_bands(
        geometry, "row_bands", lower_key="y0", upper_key="y1"
    )
    column_bands = _indexed_geometry_bands(
        geometry, "col_bands", lower_key="x0", upper_key="x1"
    )
    if (
        row_bands is None
        or column_bands is None
        or set(row_bands) != set(range(len(rows)))
        or set(column_bands) != set(range(column_count))
    ):
        return None
    grid_names = (
        "cell_bboxes",
        "cell_geometry_status",
        "cell_evidence_ids",
        "cell_token_ids",
    )
    grids = {name: geometry.get(name) for name in grid_names}
    if any(
        not isinstance(grid, list)
        or len(grid) != len(rows)
        or any(not isinstance(line, list) or len(line) != column_count for line in grid)
        for grid in grids.values()
    ):
        return None

    owner_by_coordinate: dict[tuple[int, int], tuple[int, int]] = {}
    span_by_owner: dict[tuple[int, int], tuple[int, int]] = {}
    for raw_span in geometry.get("cell_spans") or ():
        if not isinstance(raw_span, Mapping):
            return None
        try:
            row = int(raw_span.get("row"))
            column = int(raw_span.get("col"))
            row_span = int(raw_span.get("row_span"))
            column_span = int(raw_span.get("col_span"))
        except (TypeError, ValueError):
            return None
        if (
            row < 0
            or column < 0
            or row_span < 1
            or column_span < 1
            or row + row_span > len(rows)
            or column + column_span > column_count
            or (row_span, column_span) == (1, 1)
            or (row, column) in span_by_owner
        ):
            return None
        for covered_row in range(row, row + row_span):
            for covered_column in range(column, column + column_span):
                coordinate = (covered_row, covered_column)
                if coordinate in owner_by_coordinate:
                    return None
                owner_by_coordinate[coordinate] = (row, column)
        span_by_owner[(row, column)] = (row_span, column_span)

    cells: list[list[dict[str, Any] | None]] = [
        [None for _column in range(column_count)] for _row in rows
    ]
    seen_evidence_ids: set[str] = set()
    derived_empty_sequence_rows: list[int] = []
    for row in range(len(rows)):
        for column in range(column_count):
            coordinate = (row, column)
            owner = owner_by_coordinate.get(coordinate, coordinate)
            is_owner = owner == coordinate
            if not is_owner:
                if (
                    str(grids["cell_geometry_status"][row][column] or "") != "derived"
                    or grids["cell_bboxes"][row][column] is not None
                    or grids["cell_evidence_ids"][row][column] not in ([], None)
                    or grids["cell_token_ids"][row][column] not in ([], None)
                    or _compact(rows[row][column])
                ):
                    return None
                continue
            row_span, column_span = span_by_owner.get(coordinate, (1, 1))
            geometry_status = str(grids["cell_geometry_status"][row][column] or "")
            raw_evidence_ids = grids["cell_evidence_ids"][row][column]
            raw_token_ids = grids["cell_token_ids"][row][column]
            source_texts = [
                rows[covered_row][covered_column]
                for covered_row in range(row, row + row_span)
                for covered_column in range(column, column + column_span)
            ]
            if (
                geometry_status == "derived"
                and exact_header_owner is not None
                and set(exact_header_columns)
                == {"sequence", "inquiry_date", "institution", "reason"}
                and len(set(exact_header_columns.values())) == 4
                and row >= int(exact_header_owner.body_start)
                and column == int(exact_header_columns["sequence"])
                and (row_span, column_span) == (1, 1)
                and grids["cell_bboxes"][row][column] is None
                and raw_evidence_ids in ([], None)
                and raw_token_ids in ([], None)
                and not any(_compact(value) for value in source_texts)
            ):
                # A ruled inquiry table can leave a genuinely unreadable
                # ordinal slot without a closed cell rectangle.  The exact
                # registered header owns the role, while the empty slot owns
                # no token, bbox, ordinal, or value.  Retain only this inert
                # topology marker; the bounded table-level proof below must
                # still reconcile the populated peer roles and endpoints.
                cells[row][column] = {
                    "bbox": None,
                    "tokens": (),
                    "row_span": 1,
                    "column_span": 1,
                    "derived_empty_sequence_slot": True,
                }
                derived_empty_sequence_rows.append(row)
                continue
            if (
                geometry_status == "derived"
                and row == len(rows) - 1
                and column in {0, column_count - 1}
                and sum(
                    str(grids["cell_geometry_status"][row][candidate] or "")
                    == "derived"
                    for candidate in range(column_count)
                )
                == 1
                and not _nonempty(rows[row])
                and grids["cell_bboxes"][row][column] is None
                and raw_evidence_ids in ([], None)
                and raw_token_ids in ([], None)
                and abs(row_bands[row][1] - table_bbox[3]) <= 1.0
                and (
                    abs(column_bands[column][0] - table_bbox[0]) <= 1.0
                    if column == 0
                    else abs(column_bands[column][1] - table_bbox[2]) <= 1.0
                )
            ):
                # Some bordered-table reconstructors leave one terminal corner
                # without a closed rectangle.  It is admissible only as inert
                # furniture on a wholly empty row: it owns no text, token,
                # evidence, or geometry and therefore cannot create a source
                # position or lend authority to a business cell.
                cells[row][column] = {
                    "bbox": None,
                    "tokens": (),
                    "row_span": 1,
                    "column_span": 1,
                    "empty_furniture": True,
                }
                continue
            if geometry_status != "exact":
                return None
            bbox = _exact_geometry_bbox(grids["cell_bboxes"][row][column])
            expected_bbox = (
                column_bands[column][0],
                row_bands[row][0],
                column_bands[column + column_span - 1][1],
                row_bands[row + row_span - 1][1],
            )
            if (
                bbox is None
                or any(
                    abs(left - right) > 1.0
                    for left, right in zip(bbox, expected_bbox, strict=True)
                )
                or not isinstance(raw_evidence_ids, list)
                or not isinstance(raw_token_ids, list)
            ):
                return None
            evidence_ids = tuple(str(value) for value in raw_evidence_ids if str(value or ""))
            token_ids = tuple(str(value) for value in raw_token_ids if str(value or ""))
            if (
                len(evidence_ids) != len(set(evidence_ids))
                or len(token_ids) != len(set(token_ids))
                or set(evidence_ids) != set(token_ids)
                or seen_evidence_ids.intersection(evidence_ids)
            ):
                return None
            if not evidence_ids:
                if any(_compact(value) for value in source_texts):
                    return None
                tokens: tuple[tuple[str, tuple[float, float, float, float], str], ...] = ()
            else:
                if not any(_compact(value) for value in source_texts):
                    return None
                resolved = resolve_exact_page_token_atoms(
                    parse_result,
                    token_ids,
                    logical_page=logical_page,
                )
                if resolved is None or len(resolved) != len(token_ids):
                    return None
                # ``scanned_image_line_grid`` seals cell ownership by token
                # centre.  OCR glyph boxes may legitimately cross a ruled
                # border, so requiring the complete glyph box to fit inside
                # the cell would reject evidence the producer assigned
                # unambiguously.  Recheck the same centre-owner contract here;
                # exact cell geometry and one-use token IDs are still required
                # above and across the complete table.
                tokens = tuple(
                    sorted(
                        (
                            (str(text), token_bbox, str(token_id))
                            for text, token_bbox, token_id in resolved
                            if (
                                bbox[0]
                                <= (token_bbox[0] + token_bbox[2]) / 2.0
                                <= bbox[2]
                                and bbox[1]
                                <= (token_bbox[1] + token_bbox[3]) / 2.0
                                <= bbox[3]
                            )
                        ),
                        key=lambda item: (item[1][1], item[1][0], item[2]),
                    )
                )
                if len(tokens) != len(token_ids) or {item[2] for item in tokens} != set(token_ids):
                    return None
            seen_evidence_ids.update(evidence_ids)
            cells[row][column] = {
                "bbox": bbox,
                "tokens": tokens,
                "row_span": row_span,
                "column_span": column_span,
            }

    if derived_empty_sequence_rows:
        body_start = int(exact_header_owner.body_start) if exact_header_owner is not None else 0
        body_count = len(rows) - body_start
        maximum_derived_slots = min(4, max(1, body_count // 4))
        peer_roles = ("inquiry_date", "institution", "reason")
        if (
            body_count <= 0
            or len(derived_empty_sequence_rows) > maximum_derived_slots
            or len(derived_empty_sequence_rows) != len(set(derived_empty_sequence_rows))
            or any(
                not all(
                    isinstance(
                        peer := cells[row][int(exact_header_columns[role])],
                        Mapping,
                    )
                    and peer.get("bbox") is not None
                    and peer.get("row_span") == 1
                    and peer.get("column_span") == 1
                    and bool(peer.get("tokens"))
                    for role in peer_roles
                )
                for row in derived_empty_sequence_rows
            )
        ):
            return None

    return {
        "rows": rows,
        "cells": cells,
        "row_bands": row_bands,
        "column_bands": column_bands,
        "table_bbox": table_bbox,
        "logical_page": logical_page,
        "source_page": source_page,
        "table_id": table_id,
        "evidence_ids": frozenset(seen_evidence_ids),
    }


def _raw_inquiry_exact_date_tokens(text: Any) -> tuple[str, ...]:
    """Return only complete exact date tokens; no OCR repair is admissible."""

    source = str(text or "")
    matches = tuple(match.group(0) for match in _FULL_DATE_RE.finditer(source))
    return tuple(value for value in matches if _date(value) is not None)


def _raw_inquiry_sequence_cell(value: Any) -> bool:
    text = _clean(value)
    if (
        not text
        or _raw_inquiry_exact_date_tokens(text)
        # Comma separators are source-visible OCR residue, so the exact raw
        # typed-date census above does not consume them.  A valid complete
        # source-date token is nevertheless not an ordinal column:
        # classification may use its shape without publishing the value.
        or _sealed_raw_inquiry_source_date_token(text)
    ):
        return False
    values = re.findall(r"\d{1,4}", text)
    residue = re.sub(r"[\d\s.,，。:：;；()（）\[\]【】]+", "", text)
    return bool(values and not residue and all(int(value) > 0 for value in values))


def _raw_inquiry_reason_cell(value: Any) -> bool:
    text = re.sub(r"\s+", "", str(value or "")).translate(
        str.maketrans({"（": "(", "）": ")"})
    )
    if not text:
        return False
    forms = tuple(
        sorted(
            {*_INQUIRY_REASONS, *_SELF_INQUIRY_REASON_CHANNELS},
            key=len,
            reverse=True,
        )
    )
    cursor = 0
    while cursor < len(text):
        match = next((form for form in forms if text.startswith(form, cursor)), None)
        if match is None:
            return False
        cursor += len(match)
    return True


def _raw_inquiry_cell_text(cell: Mapping[str, Any] | None) -> str:
    return "" if cell is None else " ".join(str(token[0]) for token in cell.get("tokens") or ())


def _sealed_raw_inquiry_table_descriptor(
    table: Any,
    grid: Mapping[str, Any],
) -> dict[str, Any] | None:
    """Prove one registered inquiry lattice without schema carry."""

    rows = grid["rows"]
    cells = grid["cells"]
    column_count = len(rows[0])
    exact_owner: ExactInquiryHeaderOwner | None = exact_inquiry_header_owner(table)
    if exact_owner is not None:
        columns = exact_owner.columns()
        if (
            set(columns) != {"sequence", "inquiry_date", "institution", "reason"}
            or len(set(columns.values())) != 4
            or any(column not in range(column_count) for column in columns.values())
            or exact_owner.body_start >= len(rows)
        ):
            return None
        return {
            "body_start": exact_owner.body_start,
            "role_columns": columns,
            "trait": exact_owner.binding,
            "column_count": column_count,
            "exact_header": True,
            "header_evidence_ids": tuple(exact_owner.evidence_ids),
        }

    # A malformed or residual header is a hard boundary, not a headerless
    # candidate.  In particular this preserves the fail-closed ``... X``
    # source header instead of silently treating its body as a continuation.
    registered_labels = ("编号", "序号", "查询日期", "查询机构", "查询原因")
    if any(
        any(label in _compact(cell) for label in registered_labels)
        for row in rows
        for cell in row
        if _compact(cell)
    ):
        return None

    nonempty_by_column = {
        column: [
            _raw_inquiry_cell_text(cells[row][column])
            for row in range(len(rows))
            if _raw_inquiry_cell_text(cells[row][column])
        ]
        for column in range(column_count)
    }
    active_columns = tuple(
        column for column, values in nonempty_by_column.items() if values
    )
    if column_count in {4, 6}:
        if len(active_columns) != 4:
            return None
        sequence_columns = {
            column
            for column in active_columns
            if sum(_raw_inquiry_sequence_cell(value) for value in nonempty_by_column[column]) >= 2
            and not any(_raw_inquiry_exact_date_tokens(value) for value in nonempty_by_column[column])
        }
        date_columns = {
            column
            for column in active_columns
            if sum(bool(_raw_inquiry_exact_date_tokens(value)) for value in nonempty_by_column[column]) >= 2
            and not any(_raw_inquiry_sequence_cell(value) for value in nonempty_by_column[column])
        }
        reason_columns = {
            column
            for column in active_columns
            if sum(_raw_inquiry_reason_cell(value) for value in nonempty_by_column[column]) >= 2
        }
        candidates: list[dict[str, int]] = []
        for sequence_column, date_column, reason_column in product(
            sequence_columns,
            date_columns,
            reason_columns,
        ):
            selected = {sequence_column, date_column, reason_column}
            institution_columns = set(active_columns) - selected
            if len(selected) != 3 or len(institution_columns) != 1:
                continue
            institution_column = next(iter(institution_columns))
            if len(nonempty_by_column[institution_column]) < 2:
                continue
            candidates.append(
                {
                    "sequence": sequence_column,
                    "inquiry_date": date_column,
                    "institution": institution_column,
                    "reason": reason_column,
                }
            )
        unique_candidates = {
            tuple(sorted(candidate.items())): candidate for candidate in candidates
        }
        if len(unique_candidates) != 1:
            return None
        return {
            "body_start": 0,
            "role_columns": next(iter(unique_candidates.values())),
            "column_count": column_count,
            "exact_header": False,
            "trait": (
                "sealed_headerless_four_active_of_six_lattice"
                if column_count == 6
                else "sealed_headerless_four_role_lattice"
            ),
        }

    if column_count != 3 or len(active_columns) != 3:
        return None
    candidates: list[tuple[str, dict[str, int]]] = []
    for sequence_column, reason_column in permutations(active_columns, 2):
        merged_column = next(
            (
                column
                for column in active_columns
                if column not in {sequence_column, reason_column}
            ),
            None,
        )
        if merged_column is None:
            continue
        sequence_values = nonempty_by_column[sequence_column]
        reason_values = nonempty_by_column[reason_column]
        merged_values = nonempty_by_column[merged_column]
        if (
            sum(_raw_inquiry_sequence_cell(value) for value in sequence_values) >= 2
            and sum(_raw_inquiry_reason_cell(value) for value in reason_values) >= 2
            and sum(bool(_raw_inquiry_exact_date_tokens(value)) for value in merged_values) >= 2
            and sum(
                bool(
                    re.sub(
                        _FULL_DATE_RE,
                        "",
                        value,
                    ).strip()
                )
                for value in merged_values
            )
            >= 2
        ):
            candidates.append(
                (
                    "date_institution",
                    {
                        "sequence": sequence_column,
                        "inquiry_date": merged_column,
                        "institution": merged_column,
                        "reason": reason_column,
                    },
                )
            )
    for merged_column, institution_column, reason_column in permutations(active_columns, 3):
        merged_values = nonempty_by_column[merged_column]
        if (
            sum(bool(_raw_inquiry_exact_date_tokens(value)) for value in merged_values) >= 2
            and sum(
                bool(re.search(r"(?:^|\s)\d{1,4}(?:\s|$)", value))
                for value in merged_values
            )
            >= 2
            and len(nonempty_by_column[institution_column]) >= 2
            and sum(_raw_inquiry_reason_cell(value) for value in nonempty_by_column[reason_column]) >= 2
        ):
            candidates.append(
                (
                    "sequence_date",
                    {
                        "sequence": merged_column,
                        "inquiry_date": merged_column,
                        "institution": institution_column,
                        "reason": reason_column,
                    },
                )
            )
    unique = {
        (kind, tuple(sorted(columns.items()))): (kind, columns)
        for kind, columns in candidates
    }
    if len(unique) != 1:
        return None
    merged_kind, columns = next(iter(unique.values()))
    return {
        "body_start": 0,
        "role_columns": columns,
        "column_count": column_count,
        "exact_header": False,
        "merged_kind": merged_kind,
        "trait": f"sealed_headerless_three_column_{merged_kind}_lattice",
    }


def _sealed_raw_inquiry_anonymous_body_start(
    grid: Mapping[str, Any],
) -> int | None:
    """Locate a malformed registered header without assigning semantic roles."""

    rows = grid.get("rows")
    cells = grid.get("cells")
    if (
        not isinstance(rows, list)
        or len(rows) < 2
        or len(rows[0]) != 4
        or not isinstance(cells, list)
        or len(cells) != len(rows)
    ):
        return None

    def evidence_text(row_index: int) -> str:
        row_cells = cells[row_index]
        if not isinstance(row_cells, list) or len(row_cells) != 4:
            return ""
        return " ".join(
            _raw_inquiry_cell_text(cell)
            for cell in row_cells
            if isinstance(cell, Mapping) and cell.get("tokens")
        )

    labels = ("编号", "查询日期", "查询机构", "查询原因")
    candidates: list[int] = []
    for row_index, row in enumerate(rows[:2]):
        if len(row) != 4 or any(evidence_text(prior) for prior in range(row_index)):
            continue
        compact = _compact(evidence_text(row_index))
        if all(compact.count(label) == 1 for label in labels):
            candidates.append(row_index)
    if len(candidates) != 1:
        return None
    body_start = candidates[0] + 1
    if body_start >= len(rows) or not any(
        evidence_text(row_index) for row_index in range(body_start, len(rows))
    ):
        return None
    if any(
        label in _compact(evidence_text(row_index))
        for row_index in range(body_start, len(rows))
        for label in labels
    ):
        return None
    return body_start


def _sealed_raw_inquiry_source_date_token(value: Any) -> bool:
    """Recognize an immutable complete date-shaped token without publishing it."""

    text = str(value or "").strip()
    return bool(
        text
        and _CANONICAL_FULL_DATE_RE.fullmatch(text)
        and _date(text) is not None
    )


def _sealed_raw_inquiry_anonymous_row_proven(
    grid: Mapping[str, Any],
    *,
    row_index: int,
    role_columns: Mapping[str, Any] | None = None,
) -> bool:
    """Prove one evidence row is inquiry-shaped without returning any roles."""

    cells = grid.get("cells")
    if (
        not isinstance(cells, list)
        or not 0 <= row_index < len(cells)
        or not isinstance(cells[row_index], list)
    ):
        return False
    column_count = len(cells[row_index])
    owners: list[dict[str, Any]] = []
    evidence_ids: set[str] = set()
    for column, cell in enumerate(cells[row_index]):
        if not isinstance(cell, Mapping):
            continue
        tokens = tuple(cell.get("tokens") or ())
        if not tokens:
            continue
        row_span = cell.get("row_span")
        column_span = cell.get("column_span")
        if (
            not isinstance(row_span, int)
            or isinstance(row_span, bool)
            or row_span != 1
            or not isinstance(column_span, int)
            or isinstance(column_span, bool)
            or column_span <= 0
            or column + column_span > column_count
        ):
            return False
        token_ids = [str(token[2]) for token in tokens if str(token[2] or "")]
        if (
            len(token_ids) != len(tokens)
            or len(token_ids) != len(set(token_ids))
            or evidence_ids.intersection(token_ids)
        ):
            return False
        evidence_ids.update(token_ids)
        token_texts = [str(token[0] or "").strip() for token in tokens]
        if any(
            label in _compact(text)
            for text in token_texts
            for label in ("编号", "序号", "查询日期", "查询机构", "查询原因")
        ):
            return False
        dates = [_sealed_raw_inquiry_source_date_token(text) for text in token_texts]
        sequences = [
            not is_date and _raw_inquiry_sequence_cell(text)
            for text, is_date in zip(token_texts, dates, strict=True)
        ]
        owners.append(
            {
                "coverage": frozenset(range(column, column + column_span)),
                "tokens": tokens,
                "text": " ".join(token_texts),
                "dates": dates,
                "sequences": sequences,
            }
        )
    if not evidence_ids or len(owners) not in {3, 4}:
        return False

    def sequence_date_owners_are_exact(
        candidates: list[Mapping[str, Any]],
    ) -> bool:
        if not 1 <= len(candidates) <= 2:
            return False
        date_count = sum(sum(bool(value) for value in owner["dates"]) for owner in candidates)
        sequence_count = sum(
            sum(bool(value) for value in owner["sequences"]) for owner in candidates
        )
        return bool(
            date_count > 0
            and date_count == sequence_count
            and all(
                all(
                    bool(is_date) or bool(is_sequence)
                    for is_date, is_sequence in zip(
                        owner["dates"],
                        owner["sequences"],
                        strict=True,
                    )
                )
                for owner in candidates
            )
        )

    if role_columns is None:
        reason_owners = [
            owner for owner in owners if _raw_inquiry_reason_cell(owner["text"])
        ]
        if len(reason_owners) != 1 or len(reason_owners[0]["coverage"]) != 1:
            return False
        remaining = [owner for owner in owners if owner is not reason_owners[0]]
        sequence_date_owners = [
            owner
            for owner in remaining
            if all(
                bool(is_date) or bool(is_sequence)
                for is_date, is_sequence in zip(
                    owner["dates"],
                    owner["sequences"],
                    strict=True,
                )
            )
        ]
        institution_owners = [
            owner for owner in remaining if owner not in sequence_date_owners
        ]
        if (
            len(institution_owners) != 1
            or len(institution_owners[0]["coverage"]) != 1
            or _raw_inquiry_reason_cell(institution_owners[0]["text"])
            or any(institution_owners[0]["dates"])
            or any(institution_owners[0]["sequences"])
            or any(reason_owners[0]["dates"])
            or any(reason_owners[0]["sequences"])
            or not sequence_date_owners_are_exact(sequence_date_owners)
        ):
            return False
        return bool(
            (len(sequence_date_owners) == 1)
            or all(len(owner["coverage"]) == 1 for owner in sequence_date_owners)
        )

    required = ("sequence", "inquiry_date", "institution", "reason")
    columns = dict(role_columns)
    if (
        set(columns) != set(required)
        or len(set(columns.values())) != len(required)
        or any(
            not isinstance(column, int)
            or isinstance(column, bool)
            or not 0 <= column < column_count
            for column in columns.values()
        )
    ):
        return False
    singleton_topology = {
        frozenset({int(columns[role])}) for role in required
    }
    merged_topology = {
        frozenset({int(columns["sequence"]), int(columns["inquiry_date"])}),
        frozenset({int(columns["institution"])}),
        frozenset({int(columns["reason"])}),
    }
    topology = frozenset(owner["coverage"] for owner in owners)
    if topology not in {frozenset(singleton_topology), frozenset(merged_topology)}:
        return False
    by_coverage = {owner["coverage"]: owner for owner in owners}
    institution_owner = by_coverage.get(frozenset({int(columns["institution"])}))
    reason_owner = by_coverage.get(frozenset({int(columns["reason"])}))
    if (
        not isinstance(institution_owner, Mapping)
        or not isinstance(reason_owner, Mapping)
        or _raw_inquiry_reason_cell(institution_owner["text"])
        or any(institution_owner["dates"])
        or any(institution_owner["sequences"])
        or not _raw_inquiry_reason_cell(reason_owner["text"])
        or any(reason_owner["dates"])
        or any(reason_owner["sequences"])
    ):
        return False
    sequence_date_columns = frozenset(
        {int(columns["sequence"]), int(columns["inquiry_date"])}
    )
    sequence_date_owners = [
        owner for owner in owners if owner["coverage"].issubset(sequence_date_columns)
    ]
    return sequence_date_owners_are_exact(sequence_date_owners)


def _sealed_raw_inquiry_anonymous_grid_positions(
    grid: Mapping[str, Any],
    *,
    body_start: int,
    registered_continuation: bool = False,
) -> list[dict[str, Any]]:
    """Conserve exact physical rows while withholding every semantic role."""

    rows = grid.get("rows")
    cells = grid.get("cells")
    if (
        not isinstance(rows, list)
        or not isinstance(cells, list)
        or len(cells) != len(rows)
        or not 0 <= body_start < len(rows)
    ):
        return []
    binding = (
        "sealed_raw_inquiry_registered_lattice_band"
        if registered_continuation
        else "sealed_raw_inquiry_anonymous_exact_grid_row"
    )
    binding_quality = (
        "sealed_exact_physical_position"
        if registered_continuation
        else "exact_grid_below_non_authoritative_registered_header"
    )
    positions: list[dict[str, Any]] = []
    for row_index in range(body_start, len(rows)):
        if not isinstance(cells[row_index], list):
            return []
        tokens = [
            token
            for cell in cells[row_index]
            if isinstance(cell, Mapping)
            for token in cell.get("tokens") or ()
        ]
        if not tokens:
            continue
        if not registered_continuation and not _sealed_raw_inquiry_anonymous_row_proven(
            grid,
            row_index=row_index,
        ):
            return []
        evidence_ids = [str(token[2]) for token in tokens if str(token[2] or "")]
        if not tokens or len(evidence_ids) != len(tokens) or len(evidence_ids) != len(set(evidence_ids)):
            return []
        boxes = [token[1] for token in tokens]
        bbox = [
            min(box[0] for box in boxes),
            min(box[1] for box in boxes),
            max(box[2] for box in boxes),
            max(box[3] for box in boxes),
        ]
        positions.append(
            {
                "source_physical_row_id": stable_record_id(
                    "source_inquiry_raw_physical_position",
                    grid["logical_page"],
                    grid["source_page"],
                    grid["table_id"],
                    row_index,
                    *sorted(evidence_ids),
                ),
                "source_refs": [
                    {
                        "source": "native_detail_inquiry_raw_physical_row",
                        "logical_page": grid["logical_page"],
                        "source_page": grid["source_page"],
                        "table_id": grid["table_id"],
                        "row": row_index,
                        "bbox": bbox,
                        "geometry_scope": "exact_source_row_band",
                        "evidence_ids": evidence_ids,
                        "binding": binding,
                        "binding_quality": binding_quality,
                    }
                ],
            }
        )
    return positions


def _sealed_raw_inquiry_structural_key(item: Mapping[str, Any]) -> tuple[Any, ...]:
    bbox = item.get("bbox")
    page_position = item.get("page_position")
    if (
        not isinstance(page_position, tuple)
        or len(page_position) != 2
        or not isinstance(bbox, tuple)
        or len(bbox) != 4
    ):
        return ()
    return (*page_position, bbox[1], bbox[0], bbox[3], bbox[2])


def _sealed_raw_inquiry_inherited_descriptor(
    grid: Mapping[str, Any],
    seed_descriptor: Mapping[str, Any],
) -> dict[str, Any] | None:
    """Prove a headerless table has the seed's immutable four-role lattice."""

    required = ("sequence", "inquiry_date", "institution", "reason")
    role_columns = dict(seed_descriptor.get("role_columns") or {})
    rows = grid.get("rows")
    cells = grid.get("cells")
    try:
        column_count = int(seed_descriptor.get("column_count") or 0)
    except (TypeError, ValueError):
        return None
    if (
        set(role_columns) != set(required)
        or len(set(role_columns.values())) != len(required)
        or not isinstance(rows, list)
        or not rows
        or not isinstance(cells, list)
        or len(cells) != len(rows)
        or column_count <= 0
        or any(len(row) != column_count for row in rows)
        or any(
            not isinstance(column, int)
            or isinstance(column, bool)
            or not 0 <= column < column_count
            for column in role_columns.values()
        )
    ):
        return None
    registered_labels = ("编号", "序号", "查询日期", "查询机构", "查询原因")
    if any(
        any(label in _compact(value) for label in registered_labels)
        for row in rows
        for value in row
        if _compact(value)
    ):
        return None
    inactive_columns = set(range(column_count)) - set(role_columns.values())
    observed_body = False
    for row_index, row in enumerate(rows):
        if not isinstance(cells[row_index], list) or len(cells[row_index]) != column_count:
            return None
        if any(
            _compact(row[column])
            or (
                isinstance(cells[row_index][column], Mapping)
                and bool(cells[row_index][column].get("tokens"))
            )
            for column in inactive_columns
        ):
            return None
        role_cells = [cells[row_index][int(role_columns[role])] for role in required]
        if any(not isinstance(cell, Mapping) for cell in role_cells):
            return None
        if any(cell.get("tokens") for cell in role_cells):
            observed_body = True
    if not observed_body:
        return None
    return {
        "body_start": 0,
        "role_columns": role_columns,
        "column_count": column_count,
        "exact_header": False,
        "trait": "sealed_headerless_inherited_four_role_lattice",
    }


def _sealed_raw_inquiry_role_token_bands(
    grid: Mapping[str, Any],
    descriptor: Mapping[str, Any],
    *,
    row_index: int,
) -> list[dict[str, dict[str, Any]]] | None:
    """Partition one exact physical row into one-to-one four-role token bands.

    Token text is deliberately not decoded except for the printed ordinal.  A
    packed row is typed only when every semantic role has the same number of
    non-overlapping vertical bands and the bands align one-to-one.
    """

    required = ("sequence", "inquiry_date", "institution", "reason")
    role_columns = dict(descriptor.get("role_columns") or {})
    cells = grid.get("cells")
    if (
        set(role_columns) != set(required)
        or len(set(role_columns.values())) != len(required)
        or not isinstance(cells, list)
        or not 0 <= row_index < len(cells)
        or not isinstance(cells[row_index], list)
    ):
        return None

    def role_bands(role: str) -> list[dict[str, Any]] | None:
        column = int(role_columns[role])
        if not 0 <= column < len(cells[row_index]):
            return None
        cell = cells[row_index][column]
        if not isinstance(cell, Mapping):
            return None
        tokens = sorted(
            tuple(cell.get("tokens") or ()),
            key=lambda token: (token[1][1], token[1][0], token[1][3], token[1][2], token[2]),
        )
        if not tokens:
            return None
        output: list[dict[str, Any]] = []
        for token in tokens:
            text, bbox, evidence_id = token
            if not str(evidence_id or "") or _exact_geometry_bbox(bbox) is None:
                return None
            if output:
                prior_bbox = output[-1]["bbox"]
                overlap = min(float(prior_bbox[3]), float(bbox[3])) - max(
                    float(prior_bbox[1]),
                    float(bbox[1]),
                )
                minimum_height = min(
                    float(prior_bbox[3]) - float(prior_bbox[1]),
                    float(bbox[3]) - float(bbox[1]),
                )
            else:
                overlap = -1.0
                minimum_height = 0.0
            if output and overlap >= minimum_height * 0.35:
                band = output[-1]
                band["tokens"].append(token)
                band["bbox"] = (
                    min(float(band["bbox"][0]), float(bbox[0])),
                    min(float(band["bbox"][1]), float(bbox[1])),
                    max(float(band["bbox"][2]), float(bbox[2])),
                    max(float(band["bbox"][3]), float(bbox[3])),
                )
            else:
                output.append(
                    {
                        "tokens": [token],
                        "bbox": tuple(float(value) for value in bbox),
                    }
                )
        for band in output:
            band["tokens"].sort(key=lambda token: (token[1][0], token[1][1], token[2]))
            evidence_ids = [str(token[2]) for token in band["tokens"]]
            if len(evidence_ids) != len(set(evidence_ids)):
                return None
            band["evidence_ids"] = evidence_ids
        return output

    bands_by_role = {role: role_bands(role) for role in required}
    if any(bands is None for bands in bands_by_role.values()):
        return None
    cardinalities = {len(bands or ()) for bands in bands_by_role.values()}
    if len(cardinalities) != 1 or not cardinalities or next(iter(cardinalities)) <= 0:
        return None
    band_count = next(iter(cardinalities))
    aligned: list[dict[str, dict[str, Any]]] = []
    used_evidence_ids: set[str] = set()
    prior_bottom: float | None = None
    for band_index in range(band_count):
        candidate = {
            role: (bands_by_role[role] or [])[band_index]
            for role in required
        }
        top = max(float(candidate[role]["bbox"][1]) for role in required)
        bottom = min(float(candidate[role]["bbox"][3]) for role in required)
        if bottom < top - 1.0 or (prior_bottom is not None and top < prior_bottom - 1.0):
            return None
        prior_bottom = max(float(candidate[role]["bbox"][3]) for role in required)
        sequence_tokens = candidate["sequence"]["tokens"]
        if len(sequence_tokens) != 1:
            return None
        sequence_text = _clean(sequence_tokens[0][0])
        if re.fullmatch(r"[1-9]\d{0,3}", sequence_text) is None:
            return None
        candidate["sequence"]["sequence"] = int(sequence_text)
        evidence_ids = {
            str(evidence_id)
            for role in required
            for evidence_id in candidate[role]["evidence_ids"]
        }
        if not evidence_ids or used_evidence_ids.intersection(evidence_ids):
            return None
        used_evidence_ids.update(evidence_ids)
        aligned.append(candidate)
    return aligned


def _sealed_raw_inquiry_table_ordinal_observations(
    grid: Mapping[str, Any],
    descriptor: Mapping[str, Any],
    *,
    inquiry_type: str,
) -> list[dict[str, Any]] | None:
    """Return exact typed ordinals while withholding all business values."""

    if inquiry_type not in {"institution", "personal"}:
        return None
    rows = grid.get("rows")
    try:
        body_start = int(descriptor.get("body_start") or 0)
    except (TypeError, ValueError):
        return None
    if not isinstance(rows, list) or not 0 <= body_start < len(rows):
        return None
    role_columns = dict(descriptor.get("role_columns") or {})
    sequence_column = role_columns.get("sequence")
    if not isinstance(sequence_column, int) or isinstance(sequence_column, bool):
        return None
    observations: list[dict[str, Any]] = []
    seen_evidence_ids: set[str] = set()
    for row_index in range(body_start, len(rows)):
        row = rows[row_index]
        if not _nonempty(row):
            continue
        aligned = _sealed_raw_inquiry_role_token_bands(
            grid,
            descriptor,
            row_index=row_index,
        )
        if aligned is None:
            return None
        for band in aligned:
            sequence_band = band["sequence"]
            sequence_token = sequence_band["tokens"][0]
            sequence = int(sequence_band["sequence"])
            evidence_ids = tuple(str(value) for value in sequence_band["evidence_ids"])
            if not evidence_ids or seen_evidence_ids.intersection(evidence_ids):
                return None
            seen_evidence_ids.update(evidence_ids)
            observations.append(
                {
                    "raw_sequence": sequence,
                    "raw_sequence_text": _clean(sequence_token[0]),
                    "noisy_sequence": None,
                    "sequence": sequence,
                    "inquiry_type": inquiry_type,
                    "inquiry_date": "",
                    "institution": "",
                    "reason": "",
                    "exact_lattice_row": False,
                    "population_ordinal_only": True,
                    "source_ref": {
                        "source": "native_detail_inquiry_token_ordinal",
                        "logical_page": int(grid["logical_page"]),
                        "source_page": int(grid["source_page"]),
                        "table_id": str(grid["table_id"]),
                        "row": row_index,
                        "column": sequence_column,
                        "sequence": sequence,
                        "bbox": list(sequence_token[1]),
                        "geometry_scope": "token",
                        "evidence_ids": list(evidence_ids),
                        "binding": "printed_inquiry_ordinal_token",
                        "binding_quality": "exact_token_in_sequence_cell",
                    },
                    "field_source_refs": {},
                    "row_index": row_index,
                }
            )
    return observations or None


def _sealed_raw_inquiry_typed_population(
    envelope: Mapping[str, Any],
    table_entries: list[dict[str, Any]],
) -> dict[str, Any]:
    """Bind exact header seeds and their dense headerless continuations."""

    structural = [
        item
        for item in envelope.get("structural") or ()
        if isinstance(item, Mapping) and _sealed_raw_inquiry_structural_key(item)
    ]
    boundary = envelope.get("boundary")
    institution_start = envelope.get("institution_start")
    if not isinstance(boundary, Mapping) or not isinstance(institution_start, Mapping):
        return {
            "groups": [],
            "proofs": [],
            "admitted_descriptors": {},
            "physical_descriptors": {},
            "complete": False,
        }
    boundary_key = _sealed_raw_inquiry_structural_key(boundary)
    institution_key = _sealed_raw_inquiry_structural_key(institution_start)
    personal_starts = [
        item
        for item in structural
        if item.get("kind") == "personal_start"
        and institution_key < _sealed_raw_inquiry_structural_key(item) < boundary_key
    ]
    if len(personal_starts) > 1:
        return {
            "groups": [],
            "proofs": [],
            "admitted_descriptors": {},
            "physical_descriptors": {},
            "complete": False,
        }
    personal_start = personal_starts[0] if personal_starts else None
    personal_key = (
        _sealed_raw_inquiry_structural_key(personal_start)
        if personal_start is not None
        else ()
    )
    sections: list[tuple[str, tuple[Any, ...], tuple[Any, ...]]] = [
        ("institution", institution_key, personal_key or boundary_key)
    ]
    if personal_key:
        sections.append(("personal", personal_key, boundary_key))

    groups: list[dict[str, Any]] = []
    proofs: list[dict[str, Any]] = []
    admitted_descriptors: dict[tuple[int, int, str], dict[str, Any]] = {}
    physical_descriptors: dict[tuple[int, int, str], dict[str, Any]] = {}
    every_section_complete = True
    for inquiry_type, lower_key, upper_key in sections:
        section_entries = [
            entry
            for entry in table_entries
            if lower_key < entry["table_key"] < upper_key
        ]
        if not section_entries:
            every_section_complete = False
            continue
        seed = section_entries[0]
        seed_descriptor = seed.get("descriptor")
        seed_grid = seed.get("grid")
        if (
            not isinstance(seed_descriptor, Mapping)
            or seed_descriptor.get("exact_header") is not True
            or not isinstance(seed_grid, Mapping)
        ):
            every_section_complete = False
            continue
        seed_observations = _sealed_raw_inquiry_table_ordinal_observations(
            seed_grid,
            seed_descriptor,
            inquiry_type=inquiry_type,
        )
        seed_sequences = [
            int(observation["sequence"])
            for observation in seed_observations or ()
        ]
        if not seed_sequences or seed_sequences != list(range(1, seed_sequences[-1] + 1)):
            every_section_complete = False
            continue

        group = {
            "logical_page": int(seed_grid["logical_page"]),
            "last_logical_page": int(seed_grid["logical_page"]),
            "observations": list(seed_observations or ()),
            "source_refs": [],
            "sealed_raw_population": True,
        }
        endpoint = seed_sequences[-1]
        previous_page_rank = int(seed["page_rank"])
        admitted_count = 0
        for entry_index, entry in enumerate(section_entries):
            grid = entry.get("grid")
            if not isinstance(grid, Mapping):
                break
            marker = (
                int(grid["logical_page"]),
                int(grid["source_page"]),
                str(grid["table_id"]),
            )
            if entry_index == 0:
                descriptor = dict(seed_descriptor)
                observations = list(seed_observations or ())
                proof_kind = "exact_header_seed"
            else:
                page_rank = int(entry["page_rank"])
                if page_rank not in {previous_page_rank, previous_page_rank + 1}:
                    break
                descriptor = _sealed_raw_inquiry_inherited_descriptor(
                    grid,
                    seed_descriptor,
                )
                if descriptor is None:
                    break
                observations = _sealed_raw_inquiry_table_ordinal_observations(
                    grid,
                    descriptor,
                    inquiry_type=inquiry_type,
                )
                sequences = [
                    int(observation["sequence"])
                    for observation in observations or ()
                ]
                if (
                    not sequences
                    or sequences
                    != list(range(endpoint + 1, endpoint + 1 + len(sequences)))
                ):
                    break
                proof_kind = "headerless_continuation"
                group["observations"].extend(observations or ())
                endpoint = sequences[-1]
                previous_page_rank = page_rank
            physical_descriptors[marker] = dict(descriptor)
            if marker in admitted_descriptors:
                break
            admitted_descriptors[marker] = dict(descriptor)
            ordinal_evidence = [
                str(evidence_id)
                for observation in observations
                for evidence_id in (observation.get("source_ref") or {}).get("evidence_ids") or ()
            ]
            header_evidence = [
                str(value)
                for value in descriptor.get("header_evidence_ids") or ()
                if str(value or "")
            ]
            group["source_refs"].append(
                {
                    "source": "native_detail_inquiry_raw_population_table",
                    "logical_page": marker[0],
                    "source_page": marker[1],
                    "table_id": marker[2],
                    "bbox": list(grid["table_bbox"]),
                    "geometry_scope": "table",
                    "evidence_ids": [*header_evidence, *ordinal_evidence],
                    "binding": proof_kind,
                }
            )
            proofs.append(
                {
                    "kind": proof_kind,
                    "inquiry_type": inquiry_type,
                    "logical_page": marker[0],
                    "source_page": marker[1],
                    "table_id": marker[2],
                    "first_sequence": int(observations[0]["sequence"]),
                    "last_sequence": int(observations[-1]["sequence"]),
                    "role_columns": dict(descriptor["role_columns"]),
                    "column_count": int(descriptor["column_count"]),
                    "evidence_ids": sorted(str(value) for value in grid["evidence_ids"]),
                }
            )
            group["last_logical_page"] = marker[0]
            admitted_count += 1
        if admitted_count != len(section_entries):
            every_section_complete = False
        groups.append(group)

    return {
        "groups": groups,
        "proofs": proofs,
        "admitted_descriptors": admitted_descriptors,
        "physical_descriptors": physical_descriptors,
        "complete": bool(groups)
        and every_section_complete
        and len(groups) == len(sections),
    }


def _sealed_raw_inquiry_column_lattice(
    grid: Mapping[str, Any],
) -> tuple[tuple[float, ...], float] | None:
    """Return affine-invariant exact column boundaries for one sealed grid."""

    bands = grid.get("column_bands")
    table_bbox = _exact_geometry_bbox(grid.get("table_bbox"))
    if not isinstance(bands, Mapping) or table_bbox is None or not bands:
        return None
    column_count = len(bands)
    if set(bands) != set(range(column_count)):
        return None
    width = float(table_bbox[2]) - float(table_bbox[0])
    if width <= 0:
        return None
    boundaries: list[float] = []
    for column in range(column_count):
        band = bands[column]
        if (
            not isinstance(band, tuple)
            or len(band) != 2
            or not all(isinstance(value, (int, float)) for value in band)
        ):
            return None
        left, right = (float(value) for value in band)
        if (
            not math.isfinite(left)
            or not math.isfinite(right)
            or right <= left
            or (
                column == 0
                and abs(left - float(table_bbox[0])) > 1.0
            )
            or (
                column > 0
                and abs(left - float(bands[column - 1][1])) > 1.0
            )
        ):
            return None
        if column < column_count - 1:
            boundaries.append((right - float(table_bbox[0])) / width)
        elif abs(right - float(table_bbox[2])) > 1.0:
            return None
    return tuple(boundaries), width


def _sealed_raw_inquiry_same_column_lattice(
    grid: Mapping[str, Any],
    seed_grid: Mapping[str, Any],
) -> bool:
    current = _sealed_raw_inquiry_column_lattice(grid)
    seed = _sealed_raw_inquiry_column_lattice(seed_grid)
    if current is None or seed is None or len(current[0]) != len(seed[0]):
        return False
    # Compare after affine page/table scaling.  One seed-space geometry unit is
    # the same tolerance already used to authenticate exact cell rectangles.
    tolerance = max(1.0 / seed[1], 1.0 / current[1])
    return all(
        abs(current_boundary - seed_boundary) <= tolerance
        for current_boundary, seed_boundary in zip(
            current[0],
            seed[0],
            strict=True,
        )
    )


def _sealed_raw_inquiry_same_population_column_lattice(
    grid: Mapping[str, Any],
    seed_grid: Mapping[str, Any],
) -> bool:
    """Match exact column widths for anonymous population conservation only.

    The typed continuation contract above deliberately compares cumulative
    boundaries.  Scanned line reconstruction can distribute sub-point jitter
    across adjacent columns, however, so a later boundary may move by more than
    one point even when every individual ruled column remains within one exact
    geometry unit of the registered seed.  This independent proof compares the
    affine-normalized widths themselves.  It never authorizes a descriptor,
    role, ordinal, or business value.
    """

    current = _sealed_raw_inquiry_column_lattice(grid)
    seed = _sealed_raw_inquiry_column_lattice(seed_grid)
    if current is None or seed is None or len(current[0]) != len(seed[0]):
        return False

    def widths(boundaries: tuple[float, ...]) -> tuple[float, ...]:
        edges = (0.0, *boundaries, 1.0)
        return tuple(right - left for left, right in zip(edges, edges[1:]))

    tolerance = max(1.0 / seed[1], 1.0 / current[1])
    return all(
        abs(current_width - seed_width) <= tolerance
        for current_width, seed_width in zip(
            widths(current[0]),
            widths(seed[0]),
            strict=True,
        )
    )


def _sealed_raw_inquiry_population_only_row_signature(
    grid: Mapping[str, Any],
    descriptor: Mapping[str, Any],
    *,
    row_index: int,
    expected_sequence: int,
) -> dict[str, Any] | None:
    """Prove one anonymous continuation row from exact token/role coverage.

    This is a classification-only signature.  It tolerates one contiguous
    ruled cell spanning two adjacent registered roles and unrelated OCR tokens
    inside a role owner, but it does not return any source value.  The expected
    ordinal is used only to authenticate a dense physical-row chain.
    """

    required = ("sequence", "inquiry_date", "institution", "reason")
    role_columns = dict(descriptor.get("role_columns") or {})
    cells = grid.get("cells")
    if (
        set(role_columns) != set(required)
        or len(set(role_columns.values())) != len(required)
        or not isinstance(cells, list)
        or not 0 <= row_index < len(cells)
        or not isinstance(cells[row_index], list)
        or not isinstance(expected_sequence, int)
        or isinstance(expected_sequence, bool)
        or expected_sequence <= 0
    ):
        return None
    column_count = len(cells[row_index])
    if any(
        not isinstance(column, int)
        or isinstance(column, bool)
        or not 0 <= column < column_count
        for column in role_columns.values()
    ):
        return None

    active_columns = frozenset(int(column) for column in role_columns.values())
    owners: list[dict[str, Any]] = []
    evidence_ids: set[str] = set()
    for column, cell in enumerate(cells[row_index]):
        if not isinstance(cell, Mapping):
            continue
        tokens = tuple(cell.get("tokens") or ())
        if not tokens:
            continue
        row_span = cell.get("row_span")
        column_span = cell.get("column_span")
        if (
            not isinstance(row_span, int)
            or isinstance(row_span, bool)
            or row_span != 1
            or not isinstance(column_span, int)
            or isinstance(column_span, bool)
            or not 1 <= column_span <= 2
            or column + column_span > column_count
        ):
            return None
        coverage = frozenset(range(column, column + column_span))
        if not coverage.issubset(active_columns):
            return None
        token_ids = [str(token[2]) for token in tokens if str(token[2] or "")]
        if (
            len(token_ids) != len(tokens)
            or len(token_ids) != len(set(token_ids))
            or evidence_ids.intersection(token_ids)
        ):
            return None
        evidence_ids.update(token_ids)
        token_texts = [str(token[0] or "").strip() for token in tokens]
        if any(
            label in _compact(text)
            for text in token_texts
            for label in ("编号", "序号", "查询日期", "查询机构", "查询原因")
        ):
            return None
        owners.append(
            {
                "coverage": coverage,
                "tokens": tokens,
                "token_texts": token_texts,
            }
        )
    if not evidence_ids or not owners:
        return None

    owners_by_role: dict[str, list[Mapping[str, Any]]] = {
        role: [
            owner
            for owner in owners
            if int(role_columns[role]) in owner["coverage"]
        ]
        for role in required
    }
    if any(len(role_owners) != 1 for role_owners in owners_by_role.values()):
        return None

    sequence_owner = owners_by_role["sequence"][0]
    sequence_candidates = [
        int(text)
        for text in sequence_owner["token_texts"]
        if re.fullmatch(r"0*[1-9]\d{0,3}", _clean(text))
    ]
    if sequence_candidates != [expected_sequence]:
        return None

    date_owner = owners_by_role["inquiry_date"][0]
    date_tokens = [
        text
        for text in date_owner["token_texts"]
        if _sealed_raw_inquiry_source_date_token(text)
    ]
    if len(date_tokens) != 1:
        return None

    def semantic_anchor_tokens(owner: Mapping[str, Any]) -> list[str]:
        return [
            text
            for text in owner["token_texts"]
            if text
            and not _sealed_raw_inquiry_source_date_token(text)
            and re.fullmatch(r"0*[1-9]\d{0,3}", _clean(text)) is None
        ]

    institution_tokens = semantic_anchor_tokens(owners_by_role["institution"][0])
    reason_tokens = semantic_anchor_tokens(owners_by_role["reason"][0])
    if (
        not any(re.search(r"[\u3400-\u9fff]", text) for text in institution_tokens)
        or not any(re.search(r"[\u3400-\u9fff]", text) for text in reason_tokens)
    ):
        return None

    def has_exact_contiguous_anchor(
        tokens: list[str],
        validator: Any,
    ) -> bool:
        return any(
            validator(" ".join(tokens[start:end]))
            for start in range(len(tokens))
            for end in range(start + 1, len(tokens) + 1)
        )

    exact_institution_anchor = has_exact_contiguous_anchor(
        institution_tokens,
        is_pboc_institution_name,
    )
    exact_reason_anchor = has_exact_contiguous_anchor(
        reason_tokens,
        _raw_inquiry_reason_cell,
    )
    if not (exact_institution_anchor or exact_reason_anchor):
        return None
    return {
        "evidence_ids": frozenset(evidence_ids),
        "exact_institution_anchor": exact_institution_anchor,
        "exact_reason_anchor": exact_reason_anchor,
    }


def _sealed_raw_inquiry_population_only_sequence_endpoint(
    grid: Mapping[str, Any],
    descriptor: Mapping[str, Any],
    *,
    expected_first_sequence: int,
) -> int | None:
    """Authenticate a dense anonymous row population without publishing it."""

    rows = grid.get("rows")
    try:
        body_start = int(descriptor.get("body_start") or 0)
    except (TypeError, ValueError):
        return None
    if (
        not isinstance(rows, list)
        or not 0 <= body_start < len(rows)
        or not isinstance(expected_first_sequence, int)
        or isinstance(expected_first_sequence, bool)
        or expected_first_sequence <= 0
    ):
        return None

    signatures: list[Mapping[str, Any]] = []
    owned_evidence_ids: set[str] = set()
    for row_index in range(body_start, len(rows)):
        if not _nonempty(rows[row_index]):
            continue
        signature = _sealed_raw_inquiry_population_only_row_signature(
            grid,
            descriptor,
            row_index=row_index,
            expected_sequence=expected_first_sequence + len(signatures),
        )
        if signature is None:
            return None
        signature_evidence = set(signature["evidence_ids"])
        if owned_evidence_ids.intersection(signature_evidence):
            return None
        owned_evidence_ids.update(signature_evidence)
        signatures.append(signature)
    if not signatures:
        return None
    required_anchors = min(2, len(signatures))
    if (
        sum(bool(signature["exact_institution_anchor"]) for signature in signatures)
        < required_anchors
        or sum(bool(signature["exact_reason_anchor"]) for signature in signatures)
        < required_anchors
    ):
        return None
    return expected_first_sequence + len(signatures) - 1


def _sealed_raw_inquiry_bounded_physical_date_shape(value: Any) -> bool:
    """Classify one source cell as date-shaped without decoding its value."""

    text = str(value or "").strip()
    compact = re.sub(r"\s+", "", text)
    if not compact or len(compact) > 16:
        return False
    digits = re.findall(r"\d", compact)
    matches = list(_RAW_INQUIRY_PHYSICAL_DATE_SHAPE_RE.finditer(text))
    if not 8 <= len(digits) <= 10 or len(matches) != 1:
        return False
    year, month, day = matches[0].groups()
    return _date(f"{year}.{month}.{day}") is not None


def _sealed_raw_inquiry_bounded_physical_population_endpoint(
    grid: Mapping[str, Any],
    descriptor: Mapping[str, Any],
    *,
    expected_first_sequence: int,
) -> int | None:
    """Prove a damaged exact lattice for anonymous physical positions only.

    A small bounded set of unreadable ordinal cells is tolerated only when the
    registered four-column lattice, first/last ordinals, every other readable
    ordinal, every date-shaped source cell, and the institution/reason columns
    independently reconcile.  Nothing from this proof is eligible to become a
    typed ordinal, date, inquiry type, or business value.
    """

    rows = grid.get("rows")
    cells = grid.get("cells")
    role_columns = dict(descriptor.get("role_columns") or {})
    try:
        body_start = int(descriptor.get("body_start") or 0)
    except (TypeError, ValueError):
        return None
    required = ("sequence", "inquiry_date", "institution", "reason")
    if (
        set(role_columns) != set(required)
        or len(set(role_columns.values())) != len(required)
        or not isinstance(rows, list)
        or not isinstance(cells, list)
        or len(cells) != len(rows)
        or not 0 <= body_start < len(rows)
        or not isinstance(expected_first_sequence, int)
        or isinstance(expected_first_sequence, bool)
        or expected_first_sequence <= 0
    ):
        return None

    body_indices = list(range(body_start, len(rows)))
    if not body_indices:
        return None
    column_count = len(rows[body_indices[0]])
    if (
        column_count != 4
        or set(role_columns.values()) != set(range(column_count))
        or any(
            not isinstance(rows[row_index], list)
            or len(rows[row_index]) != column_count
            or not _nonempty(rows[row_index])
            or not isinstance(cells[row_index], list)
            or len(cells[row_index]) != column_count
            for row_index in body_indices
        )
    ):
        return None

    registered_labels = ("编号", "序号", "查询日期", "查询机构", "查询原因")
    evidence_ids: set[str] = set()
    exact_sequence_offsets: set[int] = set()
    damaged_sequence_count = 0
    exact_institution_anchors = 0
    exact_reason_anchors = 0
    unanchored_semantic_rows = 0
    for offset, row_index in enumerate(body_indices):
        role_tokens: dict[str, tuple[Any, ...]] = {}
        for role in required:
            cell = cells[row_index][int(role_columns[role])]
            if (
                not isinstance(cell, Mapping)
                or cell.get("row_span") != 1
                or cell.get("column_span") != 1
            ):
                return None
            tokens = tuple(cell.get("tokens") or ())
            token_ids = [str(token[2]) for token in tokens if str(token[2] or "")]
            if (
                len(token_ids) != len(tokens)
                or len(token_ids) != len(set(token_ids))
                or evidence_ids.intersection(token_ids)
            ):
                return None
            evidence_ids.update(token_ids)
            role_tokens[role] = tokens

        token_texts = {
            role: [str(token[0] or "").strip() for token in role_tokens[role]]
            for role in required
        }
        if any(
            label in _compact(text)
            for texts in token_texts.values()
            for text in texts
            for label in registered_labels
        ):
            return None

        expected_sequence = expected_first_sequence + offset
        sequence_candidates = [
            int(text)
            for text in token_texts["sequence"]
            if re.fullmatch(r"0*[1-9]\d{0,3}", _clean(text))
        ]
        if len(sequence_candidates) > 1:
            return None
        if sequence_candidates:
            if sequence_candidates != [expected_sequence]:
                return None
            exact_sequence_offsets.add(offset)
        else:
            sequence_text = _compact(" ".join(token_texts["sequence"]))
            if (
                len(sequence_text) > 6
                or _sealed_raw_inquiry_bounded_physical_date_shape(sequence_text)
            ):
                return None
            damaged_sequence_count += 1

        date_text = " ".join(token_texts["inquiry_date"])
        institution_text = " ".join(token_texts["institution"])
        reason_text = " ".join(token_texts["reason"])
        if (
            not _sealed_raw_inquiry_bounded_physical_date_shape(date_text)
            or not re.search(r"[\u3400-\u9fff]", institution_text)
            or not re.search(r"[\u3400-\u9fff]", reason_text)
        ):
            return None
        institution_anchor = is_pboc_institution_name(institution_text)
        reason_anchor = _raw_inquiry_reason_cell(reason_text)
        exact_institution_anchors += int(institution_anchor)
        exact_reason_anchors += int(reason_anchor)
        if not (institution_anchor or reason_anchor):
            unanchored_semantic_rows += 1

    maximum_damaged_sequences = min(4, max(1, len(body_indices) // 4))
    required_semantic_anchors = min(2, len(body_indices))
    if (
        not evidence_ids
        or not {0, len(body_indices) - 1}.issubset(exact_sequence_offsets)
        or damaged_sequence_count > maximum_damaged_sequences
        or exact_institution_anchors < required_semantic_anchors
        or exact_reason_anchors < required_semantic_anchors
        or unanchored_semantic_rows > 1
    ):
        return None
    return expected_first_sequence + len(body_indices) - 1


def _sealed_raw_inquiry_population_only_continuation_endpoint(
    grid: Mapping[str, Any],
    seed_grid: Mapping[str, Any],
    seed_descriptor: Mapping[str, Any],
    *,
    expected_first_sequence: int,
) -> int | None:
    """Prove one exact continuation table for anonymous positions only."""

    if (
        seed_descriptor.get("exact_header") is not True
        or not _sealed_raw_inquiry_same_population_column_lattice(grid, seed_grid)
    ):
        return None
    descriptor = {
        "body_start": 0,
        "role_columns": dict(seed_descriptor.get("role_columns") or {}),
    }
    return _sealed_raw_inquiry_population_only_sequence_endpoint(
        grid,
        descriptor,
        expected_first_sequence=expected_first_sequence,
    )


def _sealed_raw_inquiry_bounded_damaged_continuation_endpoint(
    grid: Mapping[str, Any],
    seed_grid: Mapping[str, Any],
    seed_descriptor: Mapping[str, Any],
    *,
    expected_first_sequence: int,
) -> int | None:
    """Prove only physical rows on one bounded damaged continuation lattice."""

    if (
        seed_descriptor.get("exact_header") is not True
        or not _sealed_raw_inquiry_same_population_column_lattice(grid, seed_grid)
    ):
        return None
    descriptor = {
        "body_start": 0,
        "role_columns": dict(seed_descriptor.get("role_columns") or {}),
    }
    return _sealed_raw_inquiry_bounded_physical_population_endpoint(
        grid,
        descriptor,
        expected_first_sequence=expected_first_sequence,
    )


def _sealed_raw_inquiry_headerless_continuation_grid(
    grid: Mapping[str, Any],
    seed_grid: Mapping[str, Any],
    seed_descriptor: Mapping[str, Any],
) -> bool:
    """Prove an exact grid remains in one registered four-role lattice.

    This proof authorizes physical row identities only.  A contaminated cell
    may prevent the complete business descriptor from being recovered, so no
    role, inquiry type, ordinal, or value is returned from this path.
    """

    required = ("sequence", "inquiry_date", "institution", "reason")
    role_columns = dict(seed_descriptor.get("role_columns") or {})
    rows = grid.get("rows")
    cells = grid.get("cells")
    try:
        column_count = int(seed_descriptor.get("column_count") or 0)
    except (TypeError, ValueError):
        return False
    if (
        seed_descriptor.get("exact_header") is not True
        or set(role_columns) != set(required)
        or len(set(role_columns.values())) != len(required)
        or not isinstance(rows, list)
        or not rows
        or not isinstance(cells, list)
        or len(cells) != len(rows)
        or not _sealed_raw_inquiry_same_column_lattice(grid, seed_grid)
        or column_count not in {4, 6}
        or any(not isinstance(row, list) or len(row) != column_count for row in rows)
        or any(
            not isinstance(column, int)
            or isinstance(column, bool)
            or not 0 <= column < column_count
            for column in role_columns.values()
        )
    ):
        return False
    registered_labels = ("编号", "序号", "查询日期", "查询机构", "查询原因")
    if any(
        label in _compact(str(token[0] or ""))
        for row in cells
        if isinstance(row, list)
        for cell in row
        if isinstance(cell, Mapping)
        for token in cell.get("tokens") or ()
        for label in registered_labels
    ):
        return False

    observed_rows = 0
    for row_index, _row in enumerate(rows):
        if not isinstance(cells[row_index], list) or len(cells[row_index]) != column_count:
            return False
        row_tokens = [
            token
            for cell in cells[row_index]
            if isinstance(cell, Mapping)
            for token in cell.get("tokens") or ()
        ]
        if not row_tokens:
            continue
        observed_rows += 1
        if not _sealed_raw_inquiry_anonymous_row_proven(
            grid,
            row_index=row_index,
            role_columns=role_columns,
        ):
            return False
    return observed_rows > 0


def _sealed_raw_inquiry_anonymous_continuation_markers(
    envelope: Mapping[str, Any],
    table_entries: list[dict[str, Any]],
) -> frozenset[tuple[int, int, str]]:
    """Bind descriptor-failed grids to an exact registered subsection chain."""

    structural = [
        item
        for item in envelope.get("structural") or ()
        if isinstance(item, Mapping) and _sealed_raw_inquiry_structural_key(item)
    ]
    boundary = envelope.get("boundary")
    institution_start = envelope.get("institution_start")
    if not isinstance(boundary, Mapping) or not isinstance(institution_start, Mapping):
        return frozenset()
    boundary_key = _sealed_raw_inquiry_structural_key(boundary)
    institution_key = _sealed_raw_inquiry_structural_key(institution_start)
    personal_starts = [
        item
        for item in structural
        if item.get("kind") == "personal_start"
        and institution_key < _sealed_raw_inquiry_structural_key(item) < boundary_key
    ]
    if len(personal_starts) > 1:
        return frozenset()
    personal_key = (
        _sealed_raw_inquiry_structural_key(personal_starts[0])
        if personal_starts
        else ()
    )
    sections: list[tuple[tuple[Any, ...], tuple[Any, ...]]] = [
        (institution_key, personal_key or boundary_key)
    ]
    if personal_key:
        sections.append((personal_key, boundary_key))

    admitted: set[tuple[int, int, str]] = set()
    for lower_key, upper_key in sections:
        section_entries = [
            entry
            for entry in table_entries
            if lower_key < entry["table_key"] < upper_key
        ]
        if not section_entries:
            continue
        seed = section_entries[0]
        seed_grid = seed.get("grid")
        seed_descriptor = seed.get("descriptor")
        if (
            not isinstance(seed_grid, Mapping)
            or not isinstance(seed_descriptor, Mapping)
            or seed_descriptor.get("exact_header") is not True
        ):
            continue
        active_descriptor = dict(seed_descriptor)
        active_grid = seed_grid
        active_sequence_endpoint = _sealed_raw_inquiry_population_only_sequence_endpoint(
            seed_grid,
            seed_descriptor,
            expected_first_sequence=1,
        )
        if active_sequence_endpoint is None:
            active_sequence_endpoint = (
                _sealed_raw_inquiry_bounded_physical_population_endpoint(
                    seed_grid,
                    seed_descriptor,
                    expected_first_sequence=1,
                )
            )
        if active_sequence_endpoint is None:
            continue
        previous_page_rank = int(seed["page_rank"])
        for entry in section_entries[1:]:
            page_rank = int(entry["page_rank"])
            if page_rank not in {previous_page_rank, previous_page_rank + 1}:
                break
            grid = entry.get("grid")
            if not isinstance(grid, Mapping):
                break
            descriptor = entry.get("descriptor")
            if isinstance(descriptor, Mapping):
                if (
                    dict(descriptor.get("role_columns") or {})
                    != dict(active_descriptor.get("role_columns") or {})
                    or int(descriptor.get("column_count") or 0)
                    != int(active_descriptor.get("column_count") or 0)
                ):
                    break
                population_endpoint = _sealed_raw_inquiry_population_only_sequence_endpoint(
                    grid,
                    descriptor,
                    expected_first_sequence=active_sequence_endpoint + 1,
                )
                if population_endpoint is None:
                    population_endpoint = (
                        _sealed_raw_inquiry_bounded_physical_population_endpoint(
                            grid,
                            descriptor,
                            expected_first_sequence=active_sequence_endpoint + 1,
                        )
                    )
                if population_endpoint is None:
                    break
                active_sequence_endpoint = population_endpoint
                if descriptor.get("exact_header") is True:
                    active_descriptor = dict(descriptor)
                    active_grid = grid
                previous_page_rank = page_rank
                continue
            population_endpoint = (
                _sealed_raw_inquiry_population_only_continuation_endpoint(
                    grid,
                    active_grid,
                    active_descriptor,
                    expected_first_sequence=active_sequence_endpoint + 1,
                )
            )
            if population_endpoint is None:
                population_endpoint = (
                    _sealed_raw_inquiry_bounded_damaged_continuation_endpoint(
                        grid,
                        active_grid,
                        active_descriptor,
                        expected_first_sequence=active_sequence_endpoint + 1,
                    )
                )
            if population_endpoint is None:
                break
            active_sequence_endpoint = population_endpoint
            admitted.add(
                (
                    int(grid["logical_page"]),
                    int(grid["source_page"]),
                    str(grid["table_id"]),
                )
            )
            previous_page_rank = page_rank
    return frozenset(admitted)


def _sealed_raw_inquiry_row_observations(
    grid: Mapping[str, Any],
    descriptor: Mapping[str, Any],
    *,
    row_index: int,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """Build anonymous row/band positions and optional exact field owners."""

    role_columns = dict(descriptor.get("role_columns") or {})
    cells = grid["cells"]
    active_columns = sorted(set(role_columns.values()))
    tokens_by_column: dict[int, tuple[Any, ...]] = {
        column: tuple(
            cells[row_index][column].get("tokens") or ()
            if isinstance(cells[row_index][column], Mapping)
            else ()
        )
        for column in active_columns
    }
    all_tokens = [token for column in active_columns for token in tokens_by_column[column]]
    if not all_tokens:
        return [], []
    token_ids = [str(token[2]) for token in all_tokens]
    if len(token_ids) != len(set(token_ids)):
        return [], []

    partition: list[list[tuple[int, Any]]] | None = None
    date_tokens: list[Any] = []
    if len(set(role_columns.values())) == 4:
        aligned = _sealed_raw_inquiry_role_token_bands(
            grid,
            descriptor,
            row_index=row_index,
        )
        if aligned is not None:
            partition = [
                [
                    (int(role_columns[role]), token)
                    for role in ("sequence", "inquiry_date", "institution", "reason")
                    for token in band[role]["tokens"]
                ]
                for band in aligned
            ]
    else:
        # Merged three-column lattices remain anonymous.  Their established
        # date-band path may conserve fields, but it can never create a typed
        # ordinal because the four semantic roles do not have distinct owners.
        date_column = int(role_columns["inquiry_date"])
        date_tokens = [
            token
            for token in tokens_by_column[date_column]
            if _date(token[0]) is not None
        ]
        date_tokens.sort(key=lambda token: (token[1][1], token[1][0], token[2]))
        if date_tokens and not any(
            upper[1][3] > lower[1][1]
            for upper, lower in zip(date_tokens, date_tokens[1:])
        ):
            proposed = [[] for _token in date_tokens]
            for column, column_tokens in tokens_by_column.items():
                for token in column_tokens:
                    owners = [
                        index
                        for index, date_token in enumerate(date_tokens)
                        if token[1][3] >= date_token[1][1] - 1.0
                        and token[1][1] <= date_token[1][3] + 1.0
                    ]
                    if len(owners) != 1:
                        proposed = []
                        break
                    proposed[owners[0]].append((column, token))
                if not proposed:
                    break
            if proposed and all(values for values in proposed):
                partition = proposed

    band_groups = partition or [[(column, token) for column in active_columns for token in tokens_by_column[column]]]
    positions: list[dict[str, Any]] = []
    field_observations: list[dict[str, Any]] = []
    for band in band_groups:
        band_ids = [str(token[2]) for _column, token in band]
        band_boxes = [token[1] for _column, token in band]
        bbox = [
            min(box[0] for box in band_boxes),
            min(box[1] for box in band_boxes),
            max(box[2] for box in band_boxes),
            max(box[3] for box in band_boxes),
        ]
        physical_id = stable_record_id(
            "source_inquiry_raw_physical_position",
            grid["logical_page"],
            grid["source_page"],
            grid["table_id"],
            row_index,
            *sorted(band_ids),
        )
        split_band = partition is not None and len(partition) > 1
        owner_ref = {
            "source": "native_detail_inquiry_raw_physical_row",
            "logical_page": grid["logical_page"],
            "source_page": grid["source_page"],
            "table_id": grid["table_id"],
            "row": row_index,
            "bbox": bbox,
            "geometry_scope": "token_y_band" if split_band else "exact_source_row_band",
            "evidence_ids": band_ids,
            "binding": "sealed_raw_inquiry_registered_lattice_band",
            "binding_quality": (
                "all_exact_tokens_uniquely_partitioned"
                if split_band
                else "sealed_exact_physical_position"
            ),
        }
        positions.append(
            {
                "source_physical_row_id": physical_id,
                "source_refs": [owner_ref],
            }
        )
        if partition is None:
            # One exact date anchor is still sufficient for field-local
            # conservation when every token belongs to this physical row.
            if len(date_tokens) != 1:
                continue

        role_tokens: dict[str, list[Any]] = {
            "sequence": [],
            "inquiry_date": [],
            "institution": [],
            "reason": [],
        }
        valid = True
        merged_kind = str(descriptor.get("merged_kind") or "")
        for column, token in band:
            matching_roles = [
                role for role, role_column in role_columns.items() if role_column == column
            ]
            if len(matching_roles) == 1:
                role_tokens[matching_roles[0]].append(token)
                continue
            if set(matching_roles) == {"inquiry_date", "institution"} and merged_kind == "date_institution":
                if _date(token[0]) is not None:
                    role_tokens["inquiry_date"].append(token)
                elif not _raw_inquiry_exact_date_tokens(token[0]):
                    role_tokens["institution"].append(token)
                else:
                    valid = False
                    break
                continue
            if set(matching_roles) == {"sequence", "inquiry_date"} and merged_kind == "sequence_date":
                if _date(token[0]) is not None:
                    role_tokens["inquiry_date"].append(token)
                elif _raw_inquiry_sequence_cell(token[0]):
                    role_tokens["sequence"].append(token)
                else:
                    valid = False
                    break
                continue
            valid = False
            break
        fields = ("inquiry_date", "institution", "reason")
        if not valid or any(not role_tokens[field] for field in fields):
            continue
        field_refs: dict[str, list[dict[str, Any]]] = {}
        field_ids: set[str] = set()
        for field in fields:
            field_boxes = [token[1] for token in role_tokens[field]]
            ids = [str(token[2]) for token in role_tokens[field]]
            if field_ids.intersection(ids):
                valid = False
                break
            field_ids.update(ids)
            field_refs[field] = [
                {
                    "source": "native_detail_inquiry_raw_physical_field",
                    "logical_page": grid["logical_page"],
                    "source_page": grid["source_page"],
                    "table_id": grid["table_id"],
                    "row": row_index,
                    "column": int(role_columns[field]),
                    "bbox": [
                        min(box[0] for box in field_boxes),
                        min(box[1] for box in field_boxes),
                        max(box[2] for box in field_boxes),
                        max(box[3] for box in field_boxes),
                    ],
                    "geometry_scope": "token_y_band",
                    "evidence_ids": ids,
                    "field_name": field,
                    "binding": "sealed_raw_inquiry_role_y_band",
                    "binding_quality": "exact_tokens_uniquely_partitioned_in_registered_lattice",
                }
            ]
        if valid:
            field_observations.append(
                {
                    "source_physical_row_id": physical_id,
                    "printed_fields": list(fields),
                    "field_source_refs": field_refs,
                    "source_refs": [dict(owner_ref)],
                }
            )
    return positions, field_observations


def _sealed_raw_inquiry_population_census(
    parse_result: Any,
) -> dict[str, Any] | None:
    """Inventory physical positions and fully proved typed inquiry populations."""

    envelope = _sealed_raw_inquiry_envelope(parse_result)
    if envelope is None:
        return None
    lower_key = envelope["lower_key"]
    upper_key = envelope["upper_key"]
    all_table_evidence_counts: Counter[str] = Counter()
    table_entries: list[dict[str, Any]] = []
    for page_rank, (page_position, _logical_page, _source_page, page) in enumerate(
        envelope["page_rows"]
    ):
        page_entries: list[dict[str, Any]] = []
        for table in _raw_inquiry_source_member(page, "tables", ()) or ():
            table_bbox = _exact_geometry_bbox(_raw_inquiry_source_member(table, "bbox"))
            if table_bbox is None:
                continue
            table_key = (*page_position, table_bbox[1], table_bbox[0], table_bbox[3], table_bbox[2])
            if not (lower_key < table_key < upper_key):
                continue
            grid = _sealed_raw_inquiry_cell_grid(parse_result, page, table)
            descriptor = (
                _sealed_raw_inquiry_table_descriptor(table, grid)
                if isinstance(grid, Mapping)
                else None
            )
            entry = {
                "table_key": table_key,
                "page_rank": page_rank,
                "page": page,
                "table": table,
                "table_bbox": table_bbox,
                "grid": grid,
                "descriptor": descriptor,
            }
            page_entries.append(entry)
            if isinstance(grid, Mapping):
                if set(grid["evidence_ids"]).intersection(envelope["structural_evidence_ids"]):
                    return None
                all_table_evidence_counts.update(grid["evidence_ids"])
        page_entries.sort(key=lambda item: item["table_key"])
        for left, right in zip(page_entries, page_entries[1:]):
            left_bbox = left["table_bbox"]
            right_bbox = right["table_bbox"]
            if (
                min(left_bbox[2], right_bbox[2]) > max(left_bbox[0], right_bbox[0])
                and min(left_bbox[3], right_bbox[3]) > max(left_bbox[1], right_bbox[1])
            ):
                return None
        table_entries.extend(page_entries)

    if not table_entries:
        return None
    table_marker_counts: Counter[tuple[int, int, str]] = Counter(
        (
            int(grid["logical_page"]),
            int(grid["source_page"]),
            str(grid["table_id"]),
        )
        for entry in table_entries
        if isinstance((grid := entry.get("grid")), Mapping)
    )
    if any(count != 1 for count in table_marker_counts.values()):
        return None
    for entry in table_entries:
        grid = entry.get("grid")
        if isinstance(grid, Mapping) and any(
            all_table_evidence_counts[value] != 1 for value in grid["evidence_ids"]
        ):
            return None

    typed = _sealed_raw_inquiry_typed_population(envelope, table_entries)
    physical_descriptors = typed.get("physical_descriptors") or {}
    anonymous_continuation_markers = (
        _sealed_raw_inquiry_anonymous_continuation_markers(
            envelope,
            table_entries,
        )
    )
    candidates: list[tuple[tuple[Any, ...], Mapping[str, Any], Mapping[str, Any]]] = []
    anonymous_positions: list[dict[str, Any]] = []
    for entry in table_entries:
        grid = entry.get("grid")
        if not isinstance(grid, Mapping):
            continue
        marker = (
            int(grid["logical_page"]),
            int(grid["source_page"]),
            str(grid["table_id"]),
        )
        descriptor = physical_descriptors.get(marker) or entry.get("descriptor")
        if isinstance(descriptor, Mapping):
            candidates.append((entry["table_key"], grid, descriptor))
            continue
        anonymous_body_start = _sealed_raw_inquiry_anonymous_body_start(grid)
        if anonymous_body_start is not None:
            anonymous_positions.extend(
                _sealed_raw_inquiry_anonymous_grid_positions(
                    grid,
                    body_start=anonymous_body_start,
                )
            )
        elif marker in anonymous_continuation_markers:
            anonymous_positions.extend(
                _sealed_raw_inquiry_anonymous_grid_positions(
                    grid,
                    body_start=0,
                    registered_continuation=True,
                )
            )
    if not candidates and not anonymous_positions:
        return None

    positions: list[dict[str, Any]] = list(anonymous_positions)
    physical_fields: list[dict[str, Any]] = []
    for _table_key, grid, descriptor in sorted(candidates, key=lambda item: item[0]):
        for row_index in range(int(descriptor["body_start"]), len(grid["rows"])):
            row_positions, row_fields = _sealed_raw_inquiry_row_observations(
                grid,
                descriptor,
                row_index=row_index,
            )
            positions.extend(row_positions)
            physical_fields.extend(row_fields)

    evidence_owner_counts: Counter[str] = Counter()
    id_counts: Counter[str] = Counter()
    for position in positions:
        id_counts[str(position.get("source_physical_row_id") or "")] += 1
        ref = (position.get("source_refs") or [{}])[0]
        evidence_owner_counts.update(str(value) for value in ref.get("evidence_ids") or ())
    if (
        not positions
        or any(count != 1 for count in id_counts.values())
        or any(count != 1 for count in evidence_owner_counts.values())
    ):
        return None
    position_ids = {
        str(position["source_physical_row_id"]) for position in positions
    }
    physical_fields = [
        observation
        for observation in physical_fields
        if str(observation.get("source_physical_row_id") or "") in position_ids
    ]
    return {
        "raw_physical_positions": positions,
        "physical_field_observations": physical_fields,
        "typed_ordinal_groups": deepcopy(typed.get("groups") or []),
        "typed_table_proofs": deepcopy(typed.get("proofs") or []),
        "typed_population_complete": typed.get("complete") is True,
    }


def _sealed_raw_inquiry_continuation_proven(
    parse_result: Any,
    raw_census: Mapping[str, Any] | None,
    page: Any,
    table: Any,
    *,
    active_slots: Mapping[str, int],
    active_sequence_endpoint: int,
    active_inquiry_types: Iterable[str],
) -> bool:
    """Reconcile one canonical table to its immutable raw continuation proof."""

    if not isinstance(raw_census, Mapping) or active_sequence_endpoint <= 0:
        return False
    logical_page = int(getattr(page, "page_number", 0) or 0)
    source_page = int(getattr(page, "source_page_number", 0) or logical_page)
    table_id = str(getattr(table, "table_id", "") or "")
    types = {
        str(inquiry_type)
        for inquiry_type in active_inquiry_types
        if str(inquiry_type or "")
    }
    matches = [
        proof
        for proof in raw_census.get("typed_table_proofs") or ()
        if isinstance(proof, Mapping)
        and proof.get("kind") == "headerless_continuation"
        and int(proof.get("logical_page") or 0) == logical_page
        and int(proof.get("source_page") or 0) == source_page
        and str(proof.get("table_id") or "") == table_id
        and dict(proof.get("role_columns") or {}) == dict(active_slots)
        and int(proof.get("first_sequence") or 0) == active_sequence_endpoint + 1
        and types == {str(proof.get("inquiry_type") or "")}
    ]
    if len(matches) != 1:
        return False
    proof = matches[0]
    grid = _sealed_raw_inquiry_cell_grid(parse_result, page, table)
    if (
        grid is None
        or sorted(str(value) for value in grid["evidence_ids"])
        != sorted(str(value) for value in proof.get("evidence_ids") or ())
    ):
        return False
    descriptor = {
        "body_start": 0,
        "role_columns": dict(proof["role_columns"]),
        "column_count": int(proof["column_count"]),
        "exact_header": False,
        "trait": "sealed_headerless_inherited_four_role_lattice",
    }
    observations = _sealed_raw_inquiry_table_ordinal_observations(
        grid,
        descriptor,
        inquiry_type=str(proof["inquiry_type"]),
    )
    sequences = [int(observation["sequence"]) for observation in observations or ()]
    return bool(
        sequences
        and sequences[0] == int(proof["first_sequence"])
        and sequences[-1] == int(proof["last_sequence"])
        and sequences == list(range(sequences[0], sequences[-1] + 1))
    )


def _merge_exact_inquiry_physical_observation_planes(
    canonical: Iterable[Mapping[str, Any]],
    raw: Iterable[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    """Dedupe physical observations by immutable evidence ownership."""

    by_evidence: defaultdict[frozenset[str], list[dict[str, Any]]] = defaultdict(list)
    for observation in (*list(canonical), *list(raw)):
        if not isinstance(observation, Mapping):
            continue
        refs = observation.get("source_refs")
        if not isinstance(refs, list) or len(refs) != 1 or not isinstance(refs[0], Mapping):
            continue
        evidence_ids = frozenset(
            str(value) for value in refs[0].get("evidence_ids") or () if str(value or "")
        )
        if evidence_ids:
            by_evidence[evidence_ids].append(dict(observation))
    ambiguous = {
        evidence
        for evidence in by_evidence
        if any(evidence != other and evidence.intersection(other) for other in by_evidence)
    }
    output: list[dict[str, Any]] = []
    for evidence in sorted(by_evidence, key=lambda values: tuple(sorted(values))):
        if evidence in ambiguous:
            continue
        candidates = by_evidence[evidence]
        canonical_candidates = [
            candidate
            for candidate in candidates
            if (candidate.get("source_refs") or [{}])[0].get("source")
            == "native_detail_inquiry_physical_row"
        ]
        selected = canonical_candidates or candidates
        markers = {
            json.dumps(candidate, ensure_ascii=False, sort_keys=True, default=str)
            for candidate in selected
        }
        if len(markers) == 1:
            output.append(selected[0])
    return output


def _inquiry_source_coverage(parse_result: Any) -> dict[str, Any]:
    """Inventory printed inquiry ordinals before any business row is emitted.

    Inquiry rows are closed-world canonical records.  Completeness comes from
    the printed ordinal populations only after the document proves whether its
    subsections restart independently or use one combined sequence.  Headerless
    physical-page continuations remain revision-capability gated.
    """

    layout_profile = _pboc_layout_profile(parse_result)
    aliases = {
        "sequence": ("编号", "序号"),
        "inquiry_date": ("查询日期",),
        "institution": ("查询机构",),
        "reason": ("查询原因",),
    }
    cached_line_sequences = getattr(
        parse_result,
        "_candidate_b_canonical_inquiry_line_sequences",
        None,
    )
    institutional_line_sequences = {
        int(sequence)
        for sequence in (
            cached_line_sequences.get("institution", ()) if isinstance(cached_line_sequences, Mapping) else ()
        )
        if isinstance(sequence, int) and not isinstance(sequence, bool) and sequence > 0
    }
    profile_slots = layout_profile.inquiry_columns()
    native_reconciliation_slots = _exact_native_inquiry_reconciliation_slots(
        parse_result,
        layout_profile,
    )
    raw_census = _sealed_raw_inquiry_population_census(parse_result)
    canonical_physical_field_observations = _collect_inquiry_physical_field_observations(
        parse_result,
        slots=native_reconciliation_slots,
    )
    physical_field_observations = _merge_exact_inquiry_physical_observation_planes(
        canonical_physical_field_observations,
        (raw_census or {}).get("physical_field_observations") or (),
    )
    exact_native_witnesses = (
        _collect_exact_native_inquiry_row_witnesses(
            parse_result,
            slots=native_reconciliation_slots,
        )
        if set(native_reconciliation_slots) == set(aliases)
        else []
    )
    reconciled_native_sequences = getattr(
        parse_result,
        "_candidate_b_reconciled_exact_native_inquiry_sequences",
        None,
    )
    exact_native_sequences_by_type: defaultdict[str, set[int]] = defaultdict(set)
    for witness in exact_native_witnesses:
        record = witness.get("record")
        if not isinstance(record, Mapping):
            continue
        inquiry_type = str(record.get("inquiry_type") or "")
        sequence = record.get("sequence")
        if (
            inquiry_type
            and isinstance(sequence, int)
            and not isinstance(sequence, bool)
            and sequence > 0
            and isinstance(reconciled_native_sequences, Mapping)
            and sequence in reconciled_native_sequences.get(inquiry_type, ())
        ):
            exact_native_sequences_by_type[inquiry_type].add(sequence)
    groups: list[dict[str, Any]] = []
    active_group: dict[str, Any] | None = None
    active_slots: dict[str, int] = {}
    active_group_page: int | None = None

    for page in getattr(parse_result, "pages", None) or []:
        page_number = int(getattr(page, "page_number", 0) or 0)
        canonical_page = False
        page_had_inquiry_table = False
        ordered_page_tables = _inquiry_page_tables_in_physical_order(page)
        for table_index, table in enumerate(ordered_page_tables):
            if not canonical_table_owned_by(
                parse_result,
                page,
                table,
                "annotations_and_inquiries",
            ):
                continue
            canonical_page = True
            rows = _table_rows(table)
            if not rows:
                continue
            header_text = _compact("".join(_nonempty(rows[0])))
            has_header = all(marker in header_text for marker in ("查询日期", "查询机构", "查询原因"))
            header_slots = _canonical_header_slots(tuple(str(value or "") for value in rows[0]), aliases)
            has_exact_header = has_header and set(header_slots) == set(aliases)
            repaired_header_candidate = (
                _bounded_collapsed_inquiry_header_slots(rows, table=table)
                if has_header
                and not has_exact_header
                else None
            )
            repaired_header_slots = (
                repaired_header_candidate
                if repaired_header_candidate is not None
                and _inquiry_local_repair_allowed(
                    layout_profile,
                    LayoutCapability.COLLAPSED_HEADER,
                    table=table,
                    slots=repaired_header_candidate,
                    local_trait="exact_collapsed_header_lattice",
                )
                else None
            )
            split_header_candidate = (
                _bounded_split_personal_inquiry_header_slots(rows, table=table)
                if not has_header
                else None
            )
            split_header_slots = (
                split_header_candidate
                if split_header_candidate is not None
                and _inquiry_local_repair_allowed(
                    layout_profile,
                    LayoutCapability.SPLIT_PERSONAL_HEADER,
                    table=table,
                    slots=split_header_candidate,
                    local_trait="exact_split_personal_header_lattice",
                )
                else None
            )
            has_split_header = split_header_slots is not None
            mixed_header_candidate = (
                _bounded_mixed_page_inquiry_header_slots(page, table, rows)
                if not has_header
                and not has_split_header
                else None
            )
            mixed_header_slots = (
                mixed_header_candidate
                if mixed_header_candidate is not None
                and _inquiry_local_repair_allowed(
                    layout_profile,
                    LayoutCapability.MIXED_PAGE_HEADER,
                    table=table,
                    slots=mixed_header_candidate,
                    local_trait="exact_mixed_page_heading_header_lattice",
                    rows=(1,),
                    section_owner_role="annotations_and_inquiries",
                )
                else None
            )
            has_mixed_header = mixed_header_slots is not None
            bootstrap_slots = dict(profile_slots)
            bootstrap_candidate = (
                _bounded_headerless_inquiry_table_bootstrap(
                    parse_result,
                    page,
                    table,
                    rows,
                    slots=bootstrap_slots,
                    later_tables=ordered_page_tables[table_index + 1 :],
                )
                if not has_header
                and not has_split_header
                and not has_mixed_header
                else None
            )
            bootstrap_descriptor = (
                bootstrap_candidate
                if bootstrap_candidate is not None
                and layout_profile.allows_local_proof(
                    LayoutCapability.HEADERLESS_BOOTSTRAP,
                    proof=_descriptor_local_repair_proof(
                        LayoutCapability.HEADERLESS_BOOTSTRAP,
                        bootstrap_candidate,
                        local_trait="sealed_headerless_population",
                    ),
                )
                else None
            )
            leading_blank_continuation_start = (
                _bounded_inquiry_leading_blank_continuation_start(
                    rows,
                    table=table,
                    slots=active_slots,
                )
                if (
                    not has_header
                    and not has_split_header
                    and not has_mixed_header
                    and canonical_page
                    and active_group is not None
                    and "sequence" in active_slots
                    and _headerless_continuation_local_proof(
                        layout_profile,
                        table=table,
                        slots=active_slots,
                        row_index=1,
                    )
                )
                else None
            )
            continuation_first_row = (
                rows[leading_blank_continuation_start] if leading_blank_continuation_start is not None else rows[0]
            )
            first_value = _slot_value(tuple(continuation_first_row), active_slots, "sequence")
            looks_like_continuation = bool(
                not has_header
                and not has_split_header
                and not has_mixed_header
                and canonical_page
                and active_group is not None
                and "sequence" in active_slots
                and _headerless_continuation_local_proof(
                    layout_profile,
                    table=table,
                    slots=active_slots,
                    row_index=leading_blank_continuation_start or 0,
                )
                and re.fullmatch(r"\D*\d{1,4}\D*", first_value)
            )
            carry_allowed = _inquiry_schema_carry_allowed(
                parse_result,
                active_group_page,
                page_number,
            )
            active_observations = [
                observation
                for observation in (active_group.get("observations") if isinstance(active_group, Mapping) else ())
                if isinstance(observation, Mapping)
            ]
            active_sequences = {
                int(observation.get("raw_sequence") or observation.get("sequence") or 0)
                for observation in active_observations
                if isinstance(
                    observation.get("raw_sequence") or observation.get("sequence"),
                    int,
                )
                and not isinstance(
                    observation.get("raw_sequence") or observation.get("sequence"),
                    bool,
                )
                and int(observation.get("raw_sequence") or observation.get("sequence") or 0) > 0
            }
            descriptor_continuation = bool(
                active_group is not None
                and bootstrap_descriptor is not None
                and active_sequences
                and _bounded_headerless_inquiry_population_continuation(
                    bootstrap_descriptor,
                    active_slots=active_slots,
                    active_sequence_endpoint=max(active_sequences),
                    active_inquiry_types=(
                        str(observation.get("inquiry_type") or "") for observation in active_observations
                    ),
                    carry_allowed=carry_allowed,
                )
            )
            descriptor_token_bridge = (
                _bounded_headerless_inquiry_population_token_bridge(
                    parse_result,
                    bootstrap_descriptor,
                    active_group=active_group,
                    active_sequence_endpoint=max(active_sequences),
                    active_group_page=active_group_page,
                    current_page=page_number,
                    carry_allowed=carry_allowed,
                )
                if active_group is not None
                and bootstrap_descriptor is not None
                and active_sequences
                and layout_profile.allows_local_proof(
                    LayoutCapability.TOKEN_BRIDGE,
                    proof=_descriptor_local_repair_proof(
                        LayoutCapability.TOKEN_BRIDGE,
                        bootstrap_descriptor,
                        local_trait="exact_terminal_token_bridge",
                        extra_evidence_ids=(
                            evidence_id
                            for observation in active_observations
                            if isinstance(observation, Mapping)
                            for evidence_id in (
                                (observation.get("source_ref") or {}).get("evidence_ids")
                                if isinstance(observation.get("source_ref"), Mapping)
                                else ()
                            )
                            if str(evidence_id or "")
                        ),
                    ),
                )
                else None
            )
            if descriptor_token_bridge is not None:
                descriptor_continuation = True
            bounded_exact_carry = bool(
                active_group is not None
                and active_sequences
                and _sealed_raw_inquiry_continuation_proven(
                    parse_result,
                    raw_census,
                    page,
                    table,
                    active_slots=active_slots,
                    active_sequence_endpoint=max(active_sequences),
                    active_inquiry_types=(
                        str(observation.get("inquiry_type") or "")
                        for observation in active_observations
                    ),
                )
            )
            is_continuation = bool(
                (looks_like_continuation and carry_allowed)
                or bounded_exact_carry
            )
            if looks_like_continuation and not carry_allowed and not bounded_exact_carry:
                _record_inquiry_schema_carry_unresolved(
                    parse_result,
                    left_logical_page=active_group_page,
                    page=page,
                    table=table,
                )
                active_group = None
                active_slots = {}
                active_group_page = None
                continue
            if (
                bootstrap_descriptor is not None
                and active_group is not None
                and not (descriptor_continuation or bounded_exact_carry)
            ):
                # A sealed tail whose first ordinal is not the exact next
                # active ordinal is a population conflict, not a generic
                # continuation candidate.
                continue
            if has_header:
                # Even a damaged/merged header is useful as a section boundary.
                # A body-proven collapsed header may recover all four fixed
                # slots; otherwise only exact partial bindings plus the printed
                # leftmost ordinal contribute to this independent inventory.
                active_slots = dict(repaired_header_slots or header_slots)
                active_slots.setdefault("sequence", 0)
                active_group = {
                    "logical_page": page_number,
                    "last_logical_page": page_number,
                    "observations": [],
                    "source_refs": [],
                }
                groups.append(active_group)
                active_group_page = page_number
                start = 1
            elif has_split_header:
                active_slots = dict(split_header_slots)
                active_group = {
                    "logical_page": page_number,
                    "last_logical_page": page_number,
                    "observations": [],
                    "source_refs": [],
                }
                groups.append(active_group)
                active_group_page = page_number
                start = 2
            elif has_mixed_header:
                active_slots = dict(mixed_header_slots)
                active_group = {
                    "logical_page": page_number,
                    "last_logical_page": page_number,
                    "observations": [],
                    "source_refs": [],
                    "mixed_page_header": True,
                }
                groups.append(active_group)
                active_group_page = page_number
                start = 2
            elif descriptor_continuation:
                active_slots = dict(bootstrap_descriptor["slots"])
                active_group["last_logical_page"] = page_number
                if descriptor_token_bridge is not None:
                    active_group["observations"].extend(deepcopy(descriptor_token_bridge))
                active_group["observations"].extend(deepcopy(bootstrap_descriptor["ordinal_observations"]))
                active_group["source_refs"].extend(deepcopy(bootstrap_descriptor["source_refs"]))
                active_group["headerless_population_continuation"] = True
                active_group_page = page_number
                page_had_inquiry_table = True
                # The descriptor owns the complete physical table, including
                # the terminal two-ordinal band.  Avoid a second row scan.
                continue
            elif bootstrap_descriptor is not None and active_group is None:
                active_slots = dict(bootstrap_descriptor["slots"])
                active_group = {
                    "logical_page": page_number,
                    "last_logical_page": page_number,
                    "observations": deepcopy(bootstrap_descriptor["ordinal_observations"]),
                    "source_refs": deepcopy(bootstrap_descriptor["source_refs"]),
                    "headerless_population_bootstrap": True,
                }
                groups.append(active_group)
                active_group_page = page_number
                page_had_inquiry_table = True
                # The shared descriptor already inventories every physical row,
                # including a collapsed two-ordinal band.  Do not scan the same
                # source cells a second time below.
                continue
            elif is_continuation:
                active_group_page = page_number
                active_group["last_logical_page"] = page_number
                start = leading_blank_continuation_start or 0
            else:
                continue

            if has_split_header:
                split_rows = [
                    (row_index, tuple(str(value or "").strip() for value in row))
                    for row_index, row in enumerate(rows[start:], start=start)
                    if _nonempty(row)
                ]
                active_group["repair_leading_personal_ordinal"] = _bounded_split_personal_leading_ordinal(
                    split_rows,
                    table=table,
                    slots=active_slots,
                )

            page_had_inquiry_table = True
            table_ref = _source_ref(page, table)
            active_group["source_refs"].append(table_ref)
            for row_index, row in enumerate(rows[start:], start=start):
                cells = tuple(str(value or "").strip() for value in row)
                if not _nonempty(cells):
                    continue
                token_ordinal_observations = _bounded_inquiry_token_ordinal_observations(
                    parse_result,
                    page,
                    table,
                    row_index=row_index,
                    slots=active_slots,
                )
                if token_ordinal_observations:
                    for token_observation in token_ordinal_observations:
                        active_group["observations"].append(
                            {
                                "raw_sequence": token_observation["sequence"],
                                "raw_sequence_text": str(token_observation["sequence"]),
                                "noisy_sequence": None,
                                "sequence": token_observation["sequence"],
                                "inquiry_type": token_observation["inquiry_type"],
                                "inquiry_date": "",
                                "institution": "",
                                "reason": "",
                                "exact_lattice_row": True,
                                "source_ref": token_observation["source_ref"],
                                "field_source_refs": {},
                                "token_ordinal_only": True,
                            }
                        )
                    continue
                raw_sequence = _inquiry_sequence_token(_slot_value(cells, active_slots, "sequence"))
                noisy_sequence = _bounded_inquiry_sequence_noise_candidate(_slot_value(cells, active_slots, "sequence"))
                institution = _slot_value(cells, active_slots, "institution")
                reason = _slot_value(cells, active_slots, "reason")
                inquiry_date = _slot_value(cells, active_slots, "inquiry_date")
                if raw_sequence is None and not any(value for value in (inquiry_date, institution, reason)):
                    continue
                compact_institution = _compact(_normalized_inquiry_field("institution", institution))
                compact_reason = _compact(_normalized_inquiry_field("reason", reason))
                inquiry_type: str | None
                if compact_institution == "本人" or compact_reason.startswith("本人查询"):
                    inquiry_type = "personal"
                elif compact_institution or compact_reason:
                    inquiry_type = "institution"
                else:
                    inquiry_type = None
                exact_lattice_row = bool(
                    set(active_slots)
                    >= {
                        "sequence",
                        "inquiry_date",
                        "institution",
                        "reason",
                    }
                    and all(
                        _exact_native_table_cell(
                            table,
                            row=row_index,
                            column=int(active_slots[role]),
                        )
                        is not None
                        for role in (
                            "sequence",
                            "inquiry_date",
                            "institution",
                            "reason",
                        )
                    )
                )
                active_group["observations"].append(
                    {
                        "raw_sequence": raw_sequence,
                        "raw_sequence_text": _clean(_slot_value(cells, active_slots, "sequence")),
                        "noisy_sequence": noisy_sequence,
                        "sequence": raw_sequence,
                        "inquiry_type": inquiry_type,
                        "inquiry_date": inquiry_date,
                        "institution": institution,
                        "reason": reason,
                        "exact_lattice_row": exact_lattice_row,
                        "source_ref": (
                            _exact_native_inquiry_row_ref(
                                page,
                                table,
                                row_index=row_index,
                            )
                            if exact_lattice_row
                            else None
                        )
                        or _source_ref(page, table, row=row_index),
                        "field_source_refs": (
                            {
                                role: [
                                    {
                                        **_source_ref(
                                            page,
                                            table,
                                            row=row_index,
                                            column=int(active_slots[role]),
                                        ),
                                        "field_name": role,
                                        "binding": "canonical_header_column",
                                        "binding_quality": "canonical_header_column",
                                    }
                                ]
                                for role in (
                                    "inquiry_date",
                                    "institution",
                                    "reason",
                                )
                            }
                            if exact_lattice_row
                            else {}
                        ),
                    }
                )

        if not canonical_page and not page_had_inquiry_table:
            active_group = None
            active_slots = {}
            active_group_page = None

    raw_typed_groups = (
        raw_census.get("typed_ordinal_groups")
        if isinstance(raw_census, Mapping)
        and raw_census.get("typed_population_complete") is True
        else None
    )
    if isinstance(raw_typed_groups, list) and raw_typed_groups:
        # The frozen source plane is authoritative for population identity.
        # Materialized canonical rows remain responsible for business values,
        # but they cannot shrink a fully sealed raw ordinal census.
        groups = deepcopy(raw_typed_groups)

    for group in groups:
        observations = group["observations"]
        normalized_ordinals = _document_local_inquiry_ordinals(
            (observation.get("raw_sequence") for observation in observations),
            noisy_candidates=(observation.get("noisy_sequence") for observation in observations),
        )
        if group.get("repair_leading_personal_ordinal") and normalized_ordinals:
            normalized_ordinals[0] = (1, "missing")
        synthetic_rows = [
            (
                index,
                (
                    str(observation.get("raw_sequence_text") or ""),
                    str(observation.get("inquiry_date") or ""),
                    str(observation.get("institution") or ""),
                    str(observation.get("reason") or ""),
                ),
            )
            for index, observation in enumerate(observations)
        ]
        trailing_sequence = _bounded_trailing_inquiry_ordinal(
            synthetic_rows,
            normalized_ordinals,
            slots={
                "sequence": 0,
                "inquiry_date": 1,
                "institution": 2,
                "reason": 3,
            },
            prior_endpoint=0,
            supplemental_sequences=institutional_line_sequences,
            final_row_exact=bool(
                observations
                and (
                    observations[-1].get("exact_lattice_row")
                    or observations[-1].get("population_ordinal_only")
                )
            ),
        )
        if trailing_sequence is not None:
            normalized_ordinals[-1] = (trailing_sequence, "missing")
        for observation, (sequence, repair_kind) in zip(observations, normalized_ordinals, strict=True):
            if observation.get("token_ordinal_only"):
                observation["sequence_repair_kind"] = None
            else:
                observation["sequence"] = sequence
                observation["sequence_repair_kind"] = repair_kind

    # A header can repeat at a physical-page boundary.  If all readable rows in
    # that group have one type, their unreadable neighbours share that canonical
    # population.  A headerless group beginning above one likewise continues
    # the nearest preceding typed population.  Mixed groups stay unclassified.
    group_types: list[str | None] = []
    for group in groups:
        types = {
            str(observation.get("inquiry_type"))
            for observation in group["observations"]
            if observation.get("inquiry_type")
        }
        group_types.append(next(iter(types)) if len(types) == 1 else None)
    for index, group in enumerate(groups):
        if group_types[index] is not None:
            continue
        sequences = {
            int(observation["sequence"])
            for observation in group["observations"]
            if int(observation.get("sequence") or 0) > 0
        }
        if sequences and min(sequences) > 1:
            preceding_index = next(
                (cursor for cursor in range(index - 1, -1, -1) if group_types[cursor]),
                None,
            )
            if preceding_index is not None and _inquiry_schema_carry_allowed(
                parse_result,
                int(
                    groups[preceding_index].get("last_logical_page") or groups[preceding_index].get("logical_page") or 0
                ),
                int(group.get("logical_page") or 0),
            ):
                group_types[index] = group_types[preceding_index]

    sequences_by_type: defaultdict[str, set[int]] = defaultdict(set)
    rejected_by_type: defaultdict[str, set[int]] = defaultdict(set)
    ordinal_observations: defaultdict[str, dict[int, dict[str, Any]]] = defaultdict(dict)
    unclassified_endpoints: list[int] = []
    all_refs: list[dict[str, Any]] = []
    for index, group in enumerate(groups):
        group_type = group_types[index]
        known_types = {
            str(observation.get("inquiry_type"))
            for observation in group["observations"]
            if observation.get("inquiry_type")
        }
        group_sequences: set[int] = set()
        for observation in group["observations"]:
            explicit_type = observation.get("inquiry_type")
            inquiry_type = group_type if len(known_types) <= 1 else explicit_type
            sequence = int(observation.get("sequence") or 0)
            if inquiry_type and sequence > 0:
                inquiry_type = str(inquiry_type)
                sequences_by_type[inquiry_type].add(sequence)
                current = ordinal_observations[inquiry_type].setdefault(
                    sequence,
                    {
                        "sequence": sequence,
                        "inquiry_type": inquiry_type,
                        "printed_fields": [],
                        "field_source_refs": {},
                        "source_refs": [],
                        "_source_owner_markers": [],
                    },
                )
                source_ref = observation.get("source_ref")
                if isinstance(source_ref, Mapping) and (
                    observation.get("exact_lattice_row")
                    or observation.get("token_ordinal_only")
                    or observation.get("population_ordinal_only")
                ):
                    owner_marker = json.dumps(
                        {
                            "logical_page": source_ref.get("logical_page"),
                            "source_page": source_ref.get("source_page"),
                            "table_id": source_ref.get("table_id"),
                            "row": source_ref.get("row"),
                            "bbox": source_ref.get("bbox"),
                            "evidence_ids": source_ref.get("evidence_ids"),
                        },
                        ensure_ascii=False,
                        sort_keys=True,
                        default=str,
                    )
                    owner_markers = current["_source_owner_markers"]
                    if owner_marker not in owner_markers:
                        owner_markers.append(owner_marker)
                    if dict(source_ref) not in current["source_refs"]:
                        current["source_refs"].append(dict(source_ref))
                if (
                    observation.get("exact_lattice_row") or observation.get("population_ordinal_only")
                ) and not observation.get("token_ordinal_only"):
                    observed_field_refs = observation.get("field_source_refs")
                    observed_field_ref_map = (
                        dict(observed_field_refs) if isinstance(observed_field_refs, Mapping) else {}
                    )
                    for field_name in ("inquiry_date", "institution", "reason"):
                        if not _clean(observation.get(field_name)):
                            continue
                        refs = current["field_source_refs"].setdefault(field_name, [])
                        for field_ref in observed_field_ref_map.get(field_name) or ():
                            if isinstance(field_ref, Mapping) and dict(field_ref) not in refs:
                                refs.append(dict(field_ref))
                        if refs and field_name not in current["printed_fields"]:
                            current["printed_fields"].append(field_name)
                if observation.get("sequence_repair_kind") == "prefixed_noise":
                    raw_sequence = observation.get("raw_sequence")
                    if isinstance(raw_sequence, int) and not isinstance(raw_sequence, bool):
                        rejected_by_type[inquiry_type].add(raw_sequence)
            elif sequence > 0:
                group_sequences.add(sequence)
        if group_sequences:
            endpoint, _outliers = _inquiry_sequence_endpoint(group_sequences)
            if endpoint:
                unclassified_endpoints.append(endpoint)
        all_refs.extend(dict(ref) for ref in group.get("source_refs") or () if isinstance(ref, Mapping))

    exact_numbering_groups: list[tuple[str, tuple[int, ...], tuple[str, ...], int]] = []
    for index, group in enumerate(groups):
        inquiry_type = group_types[index]
        exact_observations = [
            observation
            for observation in group.get("observations") or ()
            if isinstance(observation, Mapping)
            and (
                observation.get("exact_lattice_row") is True
                or observation.get("population_ordinal_only") is True
            )
            and isinstance(observation.get("sequence"), int)
            and not isinstance(observation.get("sequence"), bool)
            and int(observation.get("sequence") or 0) > 0
        ]
        sequences = tuple(int(observation["sequence"]) for observation in exact_observations)
        evidence_ids = tuple(
            str(evidence_id)
            for observation in exact_observations
            for evidence_id in (
                (observation.get("source_ref") or {}).get("evidence_ids") or ()
                if isinstance(observation.get("source_ref"), Mapping)
                else ()
            )
            if str(evidence_id or "")
        )
        if inquiry_type and sequences and evidence_ids:
            exact_numbering_groups.append((inquiry_type, sequences, evidence_ids, index))

    observed_numbering_model, observed_numbering_reason, observed_group_count = infer_inquiry_numbering_model(
        exact_numbering_groups
    )
    if observed_numbering_model is InquiryNumberingModel.UNKNOWN:
        numbering_model = layout_profile.inquiry_numbering_model
        numbering_reason = next(
            (
                reason
                for reason in layout_profile.detection_reasons
                if reason.startswith("numbering_") or "subsections" in reason
            ),
            observed_numbering_reason,
        )
    else:
        numbering_model = observed_numbering_model
        numbering_reason = observed_numbering_reason

    endpoints: dict[str, int] = {}
    outliers: dict[str, list[int]] = {}
    observed: dict[str, list[int]] = {}
    for inquiry_type, values in sequences_by_type.items():
        endpoint, rejected = _inquiry_sequence_endpoint(values, rejected_by_type.get(inquiry_type, set()))
        if endpoint:
            endpoints[inquiry_type] = endpoint
        observed[inquiry_type] = sorted(values)
        if rejected:
            outliers[inquiry_type] = rejected

    for inquiry_type, native_values in exact_native_sequences_by_type.items():
        values = sequences_by_type[inquiry_type]
        values.update(native_values)
        endpoint, rejected = _inquiry_sequence_endpoint(
            values,
            rejected_by_type.get(inquiry_type, set()),
        )
        if endpoint:
            endpoints[inquiry_type] = endpoint
        observed[inquiry_type] = sorted(values)
        if rejected:
            outliers[inquiry_type] = rejected
        else:
            outliers.pop(inquiry_type, None)

    _merge_unique_inquiry_physical_fields_into_ordinals(
        parse_result,
        physical_field_observations,
        ordinal_observations,
    )

    # Keep issue evidence compact and deterministic: one source table reference
    # is sufficient to select each affected page for the one-shot repair pass.
    unique_refs: list[dict[str, Any]] = []
    seen_refs: set[str] = set()
    for ref in all_refs:
        marker = json.dumps(ref, ensure_ascii=False, sort_keys=True, default=str)
        if marker not in seen_refs:
            seen_refs.add(marker)
            unique_refs.append(ref)
    expected: int | None
    if numbering_model is InquiryNumberingModel.INDEPENDENT_RESTARTS:
        expected = sum(endpoints.values()) + sum(unclassified_endpoints)
    elif numbering_model is InquiryNumberingModel.COMBINED_CONTINUITY:
        combined_endpoints = [*endpoints.values(), *unclassified_endpoints]
        expected = max(combined_endpoints, default=0) or None
    else:
        # One typed population has no subsection-combination ambiguity.  Its
        # own exact printed endpoint is sufficient; only two or more channels
        # require a proven restart/continuity model before aggregation.
        expected = (
            next(iter(endpoints.values())) + sum(unclassified_endpoints)
            if len(endpoints) == 1
            else None
        )
    raw_physical_positions = (
        list(raw_census.get("raw_physical_positions") or ())
        if isinstance(raw_census, Mapping)
        else []
    )
    if raw_physical_positions:
        # A fully sealed source-row/band census is independent of typed
        # numbering.  It remains authoritative when one noisy ordinal makes a
        # packed row anonymous: typed endpoints must stay fail-closed, while
        # exact physical positions still establish source population.
        expected = max(expected or 0, len(raw_physical_positions))
    return {
        "layout_profile_id": layout_profile.profile_id,
        "numbering_model": numbering_model.value,
        "numbering_model_proven": numbering_model is not InquiryNumberingModel.UNKNOWN,
        "numbering_model_reason": numbering_reason,
        "exact_numbering_group_count": max(observed_group_count, layout_profile.exact_numbering_group_count),
        **({"sequence_endpoints": endpoints} if endpoints else {}),
        **({"observed_sequences": observed} if observed else {}),
        **(
            {
                "ordinal_observations": {
                    inquiry_type: {
                        str(sequence): {
                            key: value for key, value in observation.items() if key != "_source_owner_markers"
                        }
                        for sequence, observation in sorted(observations.items())
                        if observation.get("source_refs") and len(observation.get("_source_owner_markers") or ()) == 1
                    }
                    for inquiry_type, observations in sorted(ordinal_observations.items())
                    if any(
                        observation.get("source_refs") and len(observation.get("_source_owner_markers") or ()) == 1
                        for observation in observations.values()
                    )
                }
            }
            if ordinal_observations
            else {}
        ),
        **({"sequence_outliers": outliers} if outliers else {}),
        **({"unclassified_sequence_endpoints": unclassified_endpoints} if unclassified_endpoints else {}),
        **({"expected_row_count": expected} if expected is not None else {}),
        **(
            {"physical_field_observations": physical_field_observations}
            if physical_field_observations
            else {}
        ),
        **(
            {"raw_physical_positions": raw_physical_positions}
            if raw_physical_positions
            else {}
        ),
        **({"source_refs": unique_refs} if unique_refs else {}),
    }


def _agreement_source_member(value: Any, name: str, default: Any = None) -> Any:
    if isinstance(value, Mapping):
        return value.get(name, default)
    return getattr(value, name, default)


def _sealed_agreement_local_topology_keys(
    parse_result: Any,
    page_rows: Iterable[tuple[int, int, Any]],
) -> tuple[dict[int, tuple[int, int]], frozenset[int]] | None:
    """Prove frozen physical-page order without consuming identity fallback."""

    frozen_pages = getattr(parse_result, "_frozen_logical_pages", None)
    topology = getattr(parse_result, "page_topology", None)
    source_by_logical = getattr(parse_result, "source_page_by_logical", None)
    if not (
        isinstance(frozen_pages, Mapping)
        and frozen_pages
        and topology is not None
        and callable(getattr(topology, "audit", None))
        and callable(getattr(topology, "geometry", None))
        and callable(getattr(topology, "ordered_fragments", None))
        and callable(getattr(topology, "ordered_pair", None))
        and isinstance(source_by_logical, Mapping)
    ):
        return None
    audit = topology.audit()
    if not isinstance(audit, Mapping) or audit.get("valid") is not True:
        return None

    materialized = list(page_rows)
    logical_pages = {logical_page for logical_page, _source_page, _page in materialized}
    try:
        frozen_logical_pages = {int(value) for value in frozen_pages}
    except (TypeError, ValueError):
        return None
    if frozen_logical_pages != logical_pages:
        return None

    observed_by_source: defaultdict[int, set[int]] = defaultdict(set)
    raw_source_by_logical: dict[int, int] = {}
    for logical_page, source_page, _page in materialized:
        try:
            registered_source = int(source_by_logical.get(logical_page) or 0)
        except (TypeError, ValueError):
            return None
        if registered_source != source_page:
            return None
        observed_by_source[source_page].add(logical_page)
        raw_source_by_logical[logical_page] = source_page

    keys: dict[int, tuple[int, int]] = {}
    complete_sources: set[int] = set()
    for source_page, observed_logicals in observed_by_source.items():
        try:
            registered = tuple(int(value) for value in topology.ordered_fragments(source_page))
        except (TypeError, ValueError):
            return None
        if (
            not registered
            or len(registered) != len(set(registered))
            or set(registered) != observed_logicals
            or len(registered) not in {1, 2}
        ):
            return None
        geometries = []
        for logical_page in registered:
            geometry = topology.geometry(logical_page)
            if geometry is None or getattr(geometry, "transform_usable", None) is not True:
                return None
            try:
                geometry_source_page = int(
                    getattr(geometry, "source_page", 0) or 0
                )
                width = float(getattr(geometry, "width", 0.0) or 0.0)
                height = float(getattr(geometry, "height", 0.0) or 0.0)
                rotation = int(getattr(geometry, "selected_rotation", -1))
            except (TypeError, ValueError):
                return None
            if (
                geometry_source_page != source_page
                or raw_source_by_logical.get(logical_page) != source_page
                or not math.isfinite(width)
                or not math.isfinite(height)
                or width <= 0.0
                or height <= 0.0
                or rotation not in {0, 90, 180, 270}
            ):
                return None
            geometries.append(geometry)

        if len(registered) == 1:
            geometry = geometries[0]
            split_kind = str(getattr(geometry, "split_kind", "") or "")
            segment_index = getattr(geometry, "segment_index", None)
            if split_kind == "none" and segment_index in {None, 0}:
                keys[registered[0]] = (source_page, 0)
                complete_sources.add(source_page)
                continue
            # A statically valid final half-spread can order structural tokens
            # outside the agreement interval, but it is not a complete local
            # authority and is rejected if the interval actually reaches it.
            if (
                split_kind != "two_page_spread"
                or segment_index not in {0, 1}
                or _exact_geometry_bbox(
                    getattr(geometry, "source_crop_bbox", None)
                )
                is None
            ):
                return None
            keys[registered[0]] = (source_page, int(segment_index))
            continue

        if topology.ordered_pair(registered) != registered:
            return None
        segments = [getattr(geometry, "segment_index", None) for geometry in geometries]
        rotations = {int(getattr(geometry, "selected_rotation", -1)) for geometry in geometries}
        crops = [
            _exact_geometry_bbox(getattr(geometry, "source_crop_bbox", None))
            for geometry in geometries
        ]
        if (
            any(str(getattr(geometry, "split_kind", "") or "") != "two_page_spread" for geometry in geometries)
            or segments != [0, 1]
            or len(rotations) != 1
            or any(crop is None for crop in crops)
        ):
            return None
        left_crop, right_crop = crops
        if left_crop is None or right_crop is None:
            return None
        overlap_width = min(left_crop[2], right_crop[2]) - max(
            left_crop[0], right_crop[0]
        )
        overlap_height = min(left_crop[3], right_crop[3]) - max(
            left_crop[1], right_crop[1]
        )
        if overlap_width > 0.0 and overlap_height > 0.0:
            return None
        for segment, logical_page in enumerate(registered):
            keys[logical_page] = (source_page, segment)
        complete_sources.add(source_page)

    if len(keys) != len(materialized) or len(set(keys.values())) != len(keys):
        return None
    return keys, frozenset(complete_sources)


