def _strict_raw_profile_evidence_ids(value: Any) -> tuple[str, ...] | None:
    if not isinstance(value, (list, tuple)) or not value:
        return None
    if any(
        not isinstance(item, str) or not item or item != item.strip()
        for item in value
    ):
        return None
    normalized = tuple(value)
    return normalized if len(normalized) == len(set(normalized)) else None


def _strict_raw_profile_page_id(value: Any) -> int | None:
    return value if isinstance(value, int) and not isinstance(value, bool) and value > 0 else None


def _strict_raw_profile_grid_index(value: Any) -> int | None:
    return value if isinstance(value, int) and not isinstance(value, bool) and value >= 0 else None


def _raw_profile_table_id(table: Any) -> str | None:
    value = _agreement_source_member(table, "table_id", "")
    return value if isinstance(value, str) and value and value == value.strip() else None


def _sealed_raw_profile_page_rows(
    parse_result: Any,
) -> tuple[list[tuple[int, int, int, Any]], bool, frozenset[int]] | None:
    """Order the immutable source plane without using logical-page ordinals."""

    frozen_pages = getattr(parse_result, "_frozen_logical_pages", None)
    if not isinstance(frozen_pages, Mapping) or not frozen_pages:
        return None
    raw_rows: list[tuple[int, int, Any]] = []
    logical_pages: set[int] = set()
    for raw_logical, page in frozen_pages.items():
        logical_page = _strict_raw_profile_page_id(raw_logical)
        page_logical = _strict_raw_profile_page_id(
            _agreement_source_member(
                page,
                "page_number",
                _agreement_source_member(page, "page"),
            )
        )
        source_page = _strict_raw_profile_page_id(
            _agreement_source_member(
                page,
                "source_page_number",
                _agreement_source_member(page, "source_page"),
            )
        )
        if (
            logical_page is None
            or page_logical != logical_page
            or source_page is None
            or logical_page in logical_pages
        ):
            return None
        logical_pages.add(logical_page)
        raw_rows.append((logical_page, source_page, page))

    resolution = getattr(parse_result, "reading_order_resolution", None)
    raw_order = getattr(parse_result, "reading_order_by_logical", None)
    if (
        isinstance(resolution, Mapping)
        and resolution.get("resolved") is True
        and resolution.get("authoritative") is True
        and isinstance(raw_order, Mapping)
        and raw_order
    ):
        order: dict[int, int] = {}
        for raw_logical, raw_position in raw_order.items():
            logical_page = _strict_raw_profile_page_id(raw_logical)
            position = _strict_raw_profile_page_id(raw_position)
            if logical_page is None or position is None or logical_page in order:
                return None
            order[logical_page] = position
        if (
            set(order) != logical_pages
            or sorted(order.values()) != list(range(1, len(order) + 1))
        ):
            return None
        return (
            sorted(
                (
                    order[logical_page],
                    logical_page,
                    source_page,
                    page,
                )
                for logical_page, source_page, page in raw_rows
            ),
            False,
            frozenset(),
        )

    source_by_logical = getattr(parse_result, "source_page_by_logical", None)
    if not isinstance(source_by_logical, Mapping):
        return None
    for logical_page, source_page, _page in raw_rows:
        if _strict_raw_profile_page_id(source_by_logical.get(logical_page)) != source_page:
            return None
    local = _sealed_agreement_local_topology_keys(parse_result, raw_rows)
    if local is None:
        return None
    local_keys, complete_sources = local
    ordered_logicals = [
        logical_page
        for logical_page, _key in sorted(local_keys.items(), key=lambda item: item[1])
    ]
    if len(ordered_logicals) != len(logical_pages):
        return None
    rank = {logical_page: index for index, logical_page in enumerate(ordered_logicals, 1)}
    return (
        sorted(
            (
                rank[logical_page],
                logical_page,
                source_page,
                page,
            )
            for logical_page, source_page, page in raw_rows
        ),
        True,
        complete_sources,
    )


def _raw_profile_physical_owner_inventory(
    page_rows: Iterable[tuple[int, int, int, Any]],
) -> dict[str, set[tuple[Any, ...]]]:
    """Inventory every immutable table-cell and line occurrence of an OCR ID."""

    owners: defaultdict[str, set[tuple[Any, ...]]] = defaultdict(set)
    for _position, logical_page, source_page, page in page_rows:
        for text_index, text_block in enumerate(
            _agreement_source_member(page, "texts", ()) or ()
        ):
            raw_ids = _agreement_source_member(text_block, "evidence_ids")
            if not isinstance(raw_ids, (list, tuple)):
                continue
            bbox = _exact_geometry_bbox(_agreement_source_member(text_block, "bbox"))
            signature = (
                "line",
                logical_page,
                source_page,
                text_index,
                bbox,
            )
            for evidence_id in raw_ids:
                if (
                    isinstance(evidence_id, str)
                    and evidence_id
                    and evidence_id == evidence_id.strip()
                ):
                    owners[evidence_id].add(signature)

        for table_index, table in enumerate(
            _agreement_source_member(page, "tables", ()) or ()
        ):
            table_id = _raw_profile_table_id(table)
            geometry = _native_table_geometry(table)
            if table_id is None or geometry is None:
                continue
            evidence_grid = geometry.get("cell_evidence_ids")
            bbox_grid = geometry.get("cell_bboxes")
            if not isinstance(evidence_grid, list):
                continue
            for row, evidence_row in enumerate(evidence_grid):
                if not isinstance(evidence_row, list):
                    continue
                for column, raw_ids in enumerate(evidence_row):
                    if not isinstance(raw_ids, (list, tuple)):
                        continue
                    raw_bbox = (
                        bbox_grid[row][column]
                        if isinstance(bbox_grid, list)
                        and row < len(bbox_grid)
                        and isinstance(bbox_grid[row], list)
                        and column < len(bbox_grid[row])
                        else None
                    )
                    bbox = _exact_geometry_bbox(raw_bbox)
                    signature = (
                        "cell",
                        logical_page,
                        source_page,
                        table_index,
                        table_id,
                        row,
                        column,
                        bbox,
                    )
                    for evidence_id in raw_ids:
                        if (
                            isinstance(evidence_id, str)
                            and evidence_id
                            and evidence_id == evidence_id.strip()
                        ):
                            owners[evidence_id].add(signature)
    return dict(owners)


def _exact_raw_profile_text(
    text_block: Any,
    *,
    logical_page: int,
    source_page: int,
    text_index: int,
    owners: Mapping[str, set[tuple[Any, ...]]],
) -> tuple[str, tuple[float, float, float, float], tuple[str, ...]] | None:
    raw_content = _agreement_source_member(
        text_block,
        "content",
        _agreement_source_member(text_block, "text", ""),
    )
    bbox = _exact_geometry_bbox(_agreement_source_member(text_block, "bbox"))
    evidence_ids = _strict_raw_profile_evidence_ids(
        _agreement_source_member(text_block, "evidence_ids")
    )
    signature = ("line", logical_page, source_page, text_index, bbox)
    if (
        not isinstance(raw_content, str)
        or bbox is None
        or evidence_ids is None
        or any(owners.get(evidence_id) != {signature} for evidence_id in evidence_ids)
    ):
        return None
    return raw_content, bbox, evidence_ids


def _exact_raw_profile_cell(
    table: Any,
    *,
    logical_page: int,
    source_page: int,
    table_index: int,
    row: int,
    column: int,
    owners: Mapping[str, set[tuple[Any, ...]]],
) -> tuple[tuple[float, float, float, float], tuple[str, ...]] | None:
    table_id = _raw_profile_table_id(table)
    geometry = _native_table_geometry(table)
    exact_cell = _exact_native_table_cell(table, row=row, column=column)
    if table_id is None or geometry is None or exact_cell is None:
        return None
    evidence_grid = geometry.get("cell_evidence_ids")
    if (
        not isinstance(evidence_grid, list)
        or row >= len(evidence_grid)
        or not isinstance(evidence_grid[row], list)
        or column >= len(evidence_grid[row])
    ):
        return None
    evidence_ids = _strict_raw_profile_evidence_ids(evidence_grid[row][column])
    bbox, normalized_ids = exact_cell
    signature = (
        "cell",
        logical_page,
        source_page,
        table_index,
        table_id,
        row,
        column,
        bbox,
    )
    if (
        evidence_ids is None
        or normalized_ids != evidence_ids
        or any(owners.get(evidence_id) != {signature} for evidence_id in evidence_ids)
    ):
        return None
    return bbox, evidence_ids


def _raw_profile_cell_ref(
    *,
    source: str,
    binding: str,
    logical_page: int,
    source_page: int,
    table_id: str,
    row: int,
    column: int,
    bbox: tuple[float, float, float, float],
    evidence_ids: tuple[str, ...],
    dataset: str,
    component: str,
    sequence: int | None = None,
    field_name: str | None = None,
    header_fields: Iterable[str] = (),
) -> dict[str, Any]:
    return {
        "source": source,
        "logical_page": logical_page,
        "source_page": source_page,
        "table_id": table_id,
        "row": row,
        "column": column,
        "bbox": list(bbox),
        "evidence_ids": list(evidence_ids),
        "geometry_scope": "cell",
        "binding": binding,
        "binding_quality": binding,
        "canonical_template_id": _RAW_PROFILE_TEMPLATE_ID,
        "dataset_name": dataset,
        "component": component,
        **({"sequence": sequence} if sequence is not None else {}),
        **({"field_name": field_name} if field_name is not None else {}),
        **(
            {"header_fields": list(header_fields)}
            if tuple(header_fields)
            else {}
        ),
    }


def _raw_profile_header_roles(
    row: Iterable[str],
    fields: tuple[str, ...],
) -> dict[int, tuple[str, ...]] | None:
    labels = {field: _RAW_PROFILE_LABEL_BY_FIELD[field] for field in fields}
    compact_cells = [_compact(value) for value in row]
    combined = "".join(compact_cells)
    residue = combined
    for label in labels.values():
        if combined.count(label) != 1:
            return None
        residue = residue.replace(label, "", 1)
    if residue:
        return None
    roles: dict[int, tuple[str, ...]] = {}
    seen_fields: set[str] = set()
    for column, cell in enumerate(compact_cells):
        if not cell:
            continue
        cell_residue = cell
        cell_fields: list[str] = []
        for field_name, label in labels.items():
            if label not in cell_residue:
                continue
            if cell_residue.count(label) != 1:
                return None
            cell_residue = cell_residue.replace(label, "", 1)
            cell_fields.append(field_name)
        if cell_residue or not cell_fields or seen_fields.intersection(cell_fields):
            return None
        seen_fields.update(cell_fields)
        roles[column] = tuple(cell_fields)
    return roles if seen_fields == set(fields) else None


def _raw_profile_header_candidate(
    *,
    dataset: str,
    component: str,
    fields: tuple[str, ...],
    position: int,
    logical_page: int,
    source_page: int,
    page: Any,
    table: Any,
    table_index: int,
    row_index: int,
    rows: list[list[str]],
    next_header_index: int,
    owners: Mapping[str, set[tuple[Any, ...]]],
) -> dict[str, Any] | None:
    roles = _raw_profile_header_roles(rows[row_index], fields)
    table_id = _raw_profile_table_id(table)
    if roles is None or table_id is None:
        return None
    header_refs: list[dict[str, Any]] = []
    dedicated_columns: dict[str, int] = {}
    header_boxes: list[tuple[float, float, float, float]] = []
    for column, owned_fields in roles.items():
        exact_cell = _exact_raw_profile_cell(
            table,
            logical_page=logical_page,
            source_page=source_page,
            table_index=table_index,
            row=row_index,
            column=column,
            owners=owners,
        )
        if exact_cell is None:
            return None
        bbox, evidence_ids = exact_cell
        header_boxes.append(bbox)
        header_refs.append(
            _raw_profile_cell_ref(
                source="candidate_b_raw_profile_header_cell",
                binding="canonical_profile_component_header",
                logical_page=logical_page,
                source_page=source_page,
                table_id=table_id,
                row=row_index,
                column=column,
                bbox=bbox,
                evidence_ids=evidence_ids,
                dataset=dataset,
                component=component,
                header_fields=owned_fields,
            )
        )
        if len(owned_fields) == 1:
            dedicated_columns[owned_fields[0]] = column
    if "sequence" not in dedicated_columns:
        return None
    return {
        "dataset": dataset,
        "component": component,
        "fields": fields,
        "position": position,
        "logical_page": logical_page,
        "source_page": source_page,
        "page": page,
        "table": table,
        "table_index": table_index,
        "table_id": table_id,
        "row_index": row_index,
        "next_header_index": next_header_index,
        "rows": rows,
        "dedicated_columns": dedicated_columns,
        "header_refs": header_refs,
        "sort_key": (
            position,
            min(box[1] for box in header_boxes),
            min(box[0] for box in header_boxes),
        ),
    }


def _raw_profile_component_rows(
    candidate: Mapping[str, Any],
    owners: Mapping[str, set[tuple[Any, ...]]],
) -> list[dict[str, Any]] | None:
    rows = candidate["rows"]
    sequence_column = candidate["dedicated_columns"]["sequence"]
    output: list[dict[str, Any]] = []
    for row_index in range(
        int(candidate["row_index"]) + 1,
        int(candidate["next_header_index"]),
    ):
        row = rows[row_index]
        raw_sequence = row[sequence_column] if sequence_column < len(row) else ""
        marker = _compact(raw_sequence)
        if not re.fullmatch(r"[1-9]\d*", marker):
            continue
        sequence = int(marker)
        exact_sequence = _exact_raw_profile_cell(
            candidate["table"],
            logical_page=int(candidate["logical_page"]),
            source_page=int(candidate["source_page"]),
            table_index=int(candidate["table_index"]),
            row=row_index,
            column=sequence_column,
            owners=owners,
        )
        if exact_sequence is None:
            return None
        sequence_bbox, sequence_evidence_ids = exact_sequence
        sequence_ref = _raw_profile_cell_ref(
            source="candidate_b_raw_profile_sequence_cell",
            binding="printed_profile_sequence",
            logical_page=int(candidate["logical_page"]),
            source_page=int(candidate["source_page"]),
            table_id=str(candidate["table_id"]),
            row=row_index,
            column=sequence_column,
            bbox=sequence_bbox,
            evidence_ids=sequence_evidence_ids,
            dataset=str(candidate["dataset"]),
            component=str(candidate["component"]),
            sequence=sequence,
            field_name="sequence",
        )
        field_refs: dict[str, list[dict[str, Any]]] = {}
        for field_name, column in candidate["dedicated_columns"].items():
            if field_name == "sequence" or column >= len(row) or not _clean(row[column]):
                continue
            exact_field = _exact_raw_profile_cell(
                candidate["table"],
                logical_page=int(candidate["logical_page"]),
                source_page=int(candidate["source_page"]),
                table_index=int(candidate["table_index"]),
                row=row_index,
                column=int(column),
                owners=owners,
            )
            if exact_field is None:
                continue
            field_bbox, field_evidence_ids = exact_field
            field_refs[field_name] = [
                _raw_profile_cell_ref(
                    source="candidate_b_raw_profile_field_cell",
                    binding="printed_profile_field",
                    logical_page=int(candidate["logical_page"]),
                    source_page=int(candidate["source_page"]),
                    table_id=str(candidate["table_id"]),
                    row=row_index,
                    column=int(column),
                    bbox=field_bbox,
                    evidence_ids=field_evidence_ids,
                    dataset=str(candidate["dataset"]),
                    component=str(candidate["component"]),
                    sequence=sequence,
                    field_name=field_name,
                )
            ]
        output.append(
            {
                "sequence": sequence,
                "sequence_ref": sequence_ref,
                "field_source_refs": field_refs,
            }
        )
    return output or None


def _exact_raw_profile_sequence_ref(
    observation: Any,
    *,
    dataset: str,
    ordinal: int,
) -> dict[str, Any] | None:
    contract = _RAW_PROFILE_DATASET_CONTRACTS.get(dataset)
    if not isinstance(observation, Mapping) or contract is None:
        return None
    primary_component = str(contract["primary_component"])
    id_field = str(contract["id_field"])
    expected_id = stable_record_id(str(contract["id_prefix"]), ordinal)
    if (
        observation.get("sequence") != ordinal
        or isinstance(observation.get("sequence"), bool)
        or observation.get(id_field) != expected_id
    ):
        return None
    raw_refs = observation.get("source_refs")
    if not isinstance(raw_refs, (list, tuple)) or len(raw_refs) != 1:
        return None
    raw_ref = raw_refs[0]
    if not isinstance(raw_ref, Mapping):
        return None
    ref = dict(raw_ref)
    bbox = _exact_geometry_bbox(ref.get("bbox"))
    evidence_ids = _strict_raw_profile_evidence_ids(ref.get("evidence_ids"))
    logical_page = _strict_raw_profile_page_id(ref.get("logical_page"))
    source_page = _strict_raw_profile_page_id(ref.get("source_page"))
    row = _strict_raw_profile_grid_index(ref.get("row"))
    column = _strict_raw_profile_grid_index(ref.get("column"))
    if (
        ref.get("source") != "candidate_b_raw_profile_sequence_cell"
        or ref.get("geometry_scope") != "cell"
        or ref.get("binding") != "printed_profile_sequence"
        or ref.get("binding_quality") != "printed_profile_sequence"
        or ref.get("canonical_template_id") != _RAW_PROFILE_TEMPLATE_ID
        or ref.get("dataset_name") != dataset
        or ref.get("component") != primary_component
        or ref.get("field_name") != "sequence"
        or ref.get("sequence") != ordinal
        or isinstance(ref.get("sequence"), bool)
        or logical_page is None
        or source_page is None
        or row is None
        or column is None
        or bbox is None
        or evidence_ids is None
        or not isinstance(ref.get("table_id"), str)
        or not ref["table_id"]
        or ref["table_id"] != ref["table_id"].strip()
    ):
        return None
    return ref


def _sealed_raw_profile_population_census(
    parse_result: Any,
) -> dict[str, Any] | None:
    """Conserve exact profile ordinals from the immutable PBOC source plane.

    The census owns population and field provenance only.  It deliberately
    carries no phone, address, employer, provider, or other business value.
    """

    ordered = _sealed_raw_profile_page_rows(parse_result)
    if ordered is None:
        return None
    page_rows, local_topology, complete_sources = ordered
    owners = _raw_profile_physical_owner_inventory(page_rows)

    structural: list[dict[str, Any]] = []
    raw_structural_count = 0
    for position, logical_page, source_page, page in page_rows:
        for text_index, text_block in enumerate(
            _agreement_source_member(page, "texts", ()) or ()
        ):
            raw_content = _agreement_source_member(
                text_block,
                "content",
                _agreement_source_member(text_block, "text", ""),
            )
            if not isinstance(raw_content, str):
                continue
            compact = _compact(raw_content).rstrip("：:")
            section = canonical_registered_section_heading(compact)
            subsection_match = _RAW_PROFILE_SUBSECTION_RE.fullmatch(compact)
            if section is None and subsection_match is None:
                continue
            raw_structural_count += 1
            exact = _exact_raw_profile_text(
                text_block,
                logical_page=logical_page,
                source_page=source_page,
                text_index=text_index,
                owners=owners,
            )
            if exact is None:
                return None
            _content, bbox, evidence_ids = exact
            structural.append(
                {
                    "kind": "section" if section is not None else "subsection",
                    "title": section or subsection_match.group("title"),
                    "position": position,
                    "logical_page": logical_page,
                    "source_page": source_page,
                    "bbox": bbox,
                    "evidence_ids": evidence_ids,
                    "sort_key": (position, bbox[1], bbox[0], bbox[3], bbox[2]),
                }
            )
    if raw_structural_count != len(structural):
        return None
    structural.sort(key=lambda item: item["sort_key"])
    for left, right in zip(structural, structural[1:]):
        if left["position"] == right["position"] and min(
            left["bbox"][3], right["bbox"][3]
        ) > max(left["bbox"][1], right["bbox"][1]):
            return None

    starts = [
        item
        for item in structural
        if item["kind"] == "section" and item["title"] == "个人基本信息"
    ]
    if len(starts) != 1:
        return None
    start = starts[0]
    following_sections = [
        item
        for item in structural
        if item["kind"] == "section" and item["sort_key"] > start["sort_key"]
    ]
    if not following_sections or following_sections[0]["title"] != "信息概要":
        return None
    boundary = following_sections[0]
    if local_topology:
        envelope_rows = [
            row
            for row in page_rows
            if start["position"] <= row[0] <= boundary["position"]
        ]
        envelope_sources: list[int] = []
        for _position, _logical, source_page, _page in envelope_rows:
            if not envelope_sources or envelope_sources[-1] != source_page:
                envelope_sources.append(source_page)
        if (
            not envelope_sources
            or any(source not in complete_sources for source in envelope_sources)
            or envelope_sources
            != list(range(envelope_sources[0], envelope_sources[-1] + 1))
        ):
            return None

    subsection_by_title: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for item in structural:
        if (
            item["kind"] == "subsection"
            and start["sort_key"] < item["sort_key"] < boundary["sort_key"]
        ):
            subsection_by_title[str(item["title"])].append(item)

    semantic_headers: list[dict[str, Any]] = []
    header_rows_by_table: defaultdict[tuple[int, int], set[int]] = defaultdict(set)
    table_rows_by_key: dict[tuple[int, int], list[list[str]]] = {}
    table_by_key: dict[tuple[int, int], Any] = {}
    page_by_key: dict[tuple[int, int], Any] = {}
    page_metadata_by_key: dict[tuple[int, int], tuple[int, int, int]] = {}
    for position, logical_page, source_page, page in page_rows:
        for table_index, table in enumerate(
            _agreement_source_member(page, "tables", ()) or ()
        ):
            rows = _table_rows(table)
            key = (logical_page, table_index)
            table_rows_by_key[key] = rows
            table_by_key[key] = table
            page_by_key[key] = page
            page_metadata_by_key[key] = (position, logical_page, source_page)
            for row_index, row in enumerate(rows):
                for dataset, contract in _RAW_PROFILE_DATASET_CONTRACTS.items():
                    for component, fields in contract["components"].items():
                        if _raw_profile_header_roles(row, tuple(fields)) is None:
                            continue
                        semantic_headers.append(
                            {
                                "dataset": dataset,
                                "component": component,
                                "fields": tuple(fields),
                                "key": key,
                                "row_index": row_index,
                            }
                        )
                        header_rows_by_table[key].add(row_index)

    strict_headers: list[dict[str, Any]] = []
    for semantic in semantic_headers:
        key = semantic["key"]
        row_index = int(semantic["row_index"])
        following_rows = sorted(
            index for index in header_rows_by_table[key] if index > row_index
        )
        position, logical_page, source_page = page_metadata_by_key[key]
        candidate = _raw_profile_header_candidate(
            dataset=str(semantic["dataset"]),
            component=str(semantic["component"]),
            fields=tuple(semantic["fields"]),
            position=position,
            logical_page=logical_page,
            source_page=source_page,
            page=page_by_key[key],
            table=table_by_key[key],
            table_index=key[1],
            row_index=row_index,
            rows=table_rows_by_key[key],
            next_header_index=following_rows[0]
            if following_rows
            else len(table_rows_by_key[key]),
            owners=owners,
        )
        if candidate is not None:
            strict_headers.append(candidate)

    datasets: dict[str, list[int]] = {}
    ordinal_observations: dict[str, dict[int, dict[str, Any]]] = {}
    source_refs: dict[str, list[dict[str, Any]]] = {}
    vetoed: set[str] = set()
    for dataset, contract in _RAW_PROFILE_DATASET_CONTRACTS.items():
        primary = str(contract["primary_component"])
        semantic_primary = [
            item
            for item in semantic_headers
            if item["dataset"] == dataset and item["component"] == primary
        ]
        if not semantic_primary:
            continue
        if dataset == "residence_records":
            subsections = subsection_by_title.get("居住信息", [])
        elif dataset == "employment_records":
            subsections = subsection_by_title.get("职业信息", [])
        else:
            subsections = [start]
        if len(subsections) != 1:
            vetoed.add(dataset)
            continue
        window_start = subsections[0]
        window_end = boundary
        if dataset == "residence_records":
            employment_headings = subsection_by_title.get("职业信息", [])
            if len(employment_headings) == 1 and (
                window_start["sort_key"]
                < employment_headings[0]["sort_key"]
                < boundary["sort_key"]
            ):
                window_end = employment_headings[0]

        strict_primary = [
            item
            for item in strict_headers
            if item["dataset"] == dataset and item["component"] == primary
        ]
        if len(strict_primary) != len(semantic_primary) or any(
            not (
                window_start["sort_key"]
                < item["sort_key"]
                < window_end["sort_key"]
            )
            for item in strict_primary
        ):
            vetoed.add(dataset)
            continue
        ordered_rows: list[dict[str, Any]] = []
        primary_headers_by_sequence: dict[int, list[dict[str, Any]]] = {}
        primary_valid = True
        for candidate in sorted(strict_primary, key=lambda item: item["sort_key"]):
            component_rows = _raw_profile_component_rows(candidate, owners)
            if component_rows is None:
                primary_valid = False
                break
            ordered_rows.extend(component_rows)
            for row in component_rows:
                primary_headers_by_sequence[int(row["sequence"])] = list(
                    candidate["header_refs"]
                )
        sequences = [int(row["sequence"]) for row in ordered_rows]
        if (
            not primary_valid
            or not sequences
            or sequences != list(range(1, len(sequences) + 1))
        ):
            vetoed.add(dataset)
            continue

        observations: dict[int, dict[str, Any]] = {}
        primary_fields = tuple(contract["components"][primary])
        for row in ordered_rows:
            sequence = int(row["sequence"])
            field_ref_map = dict(row["field_source_refs"])
            observations[sequence] = {
                "sequence": sequence,
                str(contract["id_field"]): stable_record_id(
                    str(contract["id_prefix"]), sequence
                ),
                "canonical_template_id": _RAW_PROFILE_TEMPLATE_ID,
                "canonical_header_fields_by_component": {
                    primary: list(primary_fields)
                },
                **(
                    {"canonical_header_fields": list(primary_fields)}
                    if len(contract["components"]) == 1
                    else {}
                ),
                "printed_fields": sorted(field_ref_map),
                "field_source_refs": field_ref_map,
                "source_refs": [dict(row["sequence_ref"])],
                "component_header_source_refs": {
                    primary: primary_headers_by_sequence[sequence]
                },
            }

        for component, component_fields in contract["components"].items():
            if component == primary:
                continue
            component_candidates = [
                item
                for item in strict_headers
                if item["dataset"] == dataset
                and item["component"] == component
                and window_start["sort_key"]
                < item["sort_key"]
                < window_end["sort_key"]
            ]
            component_rows: list[dict[str, Any]] = []
            component_headers: dict[int, list[dict[str, Any]]] = {}
            component_valid = True
            for candidate in sorted(
                component_candidates, key=lambda item: item["sort_key"]
            ):
                local_rows = _raw_profile_component_rows(candidate, owners)
                if local_rows is None:
                    component_valid = False
                    break
                component_rows.extend(local_rows)
                for row in local_rows:
                    component_headers[int(row["sequence"])] = list(
                        candidate["header_refs"]
                    )
            component_sequences = [int(row["sequence"]) for row in component_rows]
            if (
                not component_valid
                or len(component_sequences) != len(set(component_sequences))
                or component_sequences != sorted(component_sequences)
                or any(sequence not in observations for sequence in component_sequences)
            ):
                continue
            for row in component_rows:
                sequence = int(row["sequence"])
                observation = observations[sequence]
                observation["canonical_header_fields_by_component"][component] = list(
                    component_fields
                )
                observation["component_header_source_refs"][component] = (
                    component_headers[sequence]
                )
                for field_name, refs in row["field_source_refs"].items():
                    if field_name in observation["field_source_refs"]:
                        continue
                    observation["field_source_refs"][field_name] = list(refs)
                    observation["printed_fields"].append(field_name)
                observation["printed_fields"] = sorted(
                    set(observation["printed_fields"])
                )

        datasets[dataset] = sequences
        ordinal_observations[dataset] = observations
        source_refs[dataset] = [
            dict(observations[sequence]["source_refs"][0])
            for sequence in sequences
        ]
        vetoed.discard(dataset)

    return {
        "sequences": datasets,
        "endpoints": {
            dataset: max(sequences)
            for dataset, sequences in datasets.items()
            if sequences
        },
        "ordinal_observations": ordinal_observations,
        "source_refs": source_refs,
        "vetoed_datasets": sorted(vetoed),
    }


def _sealed_agreement_population_census(
    parse_result: Any,
) -> dict[str, Any] | None:
    """Observe agreement-card identity on the immutable PBOC source plane.

    This census is deliberately independent of canonical table projection.  A
    numbered heading proves only that one source card exists; it never owns a
    table or authorizes any business-field value.  Every structural predicate
    below is closed-world so contents pages, prose, replayed OCR, and cards in a
    different section fail closed instead of manufacturing a denominator.
    """

    resolution = getattr(parse_result, "reading_order_resolution", None)
    raw_order = getattr(parse_result, "reading_order_by_logical", None)
    global_order_authoritative = bool(
        isinstance(resolution, Mapping)
        and resolution.get("resolved") is True
        and resolution.get("authoritative") is True
        and isinstance(raw_order, Mapping)
        and raw_order
    )

    frozen_pages = getattr(parse_result, "_frozen_logical_pages", None)
    if not isinstance(frozen_pages, Mapping) or not frozen_pages:
        # Only the context-owned immutable source snapshot is admissible.  In
        # particular, never consume a detached canonical ``pages`` property or
        # a caller-supplied mutable ParseResult-shaped page list.
        return None
    raw_pages = list(frozen_pages.values())
    if not raw_pages:
        return None

    raw_page_rows: list[tuple[int, int, Any]] = []
    seen_logical_pages: set[int] = set()
    for page in raw_pages:
        raw_logical = _agreement_source_member(
            page,
            "page_number",
            _agreement_source_member(page, "page", 0),
        )
        raw_source = _agreement_source_member(
            page,
            "source_page_number",
            _agreement_source_member(page, "source_page", 0),
        )
        try:
            logical_page = int(raw_logical)
            source_page = int(raw_source)
        except (TypeError, ValueError):
            return None
        if (
            logical_page <= 0
            or source_page <= 0
            or logical_page in seen_logical_pages
        ):
            return None
        seen_logical_pages.add(logical_page)
        raw_page_rows.append((logical_page, source_page, page))

    local_topology_order = False
    local_complete_sources: frozenset[int] = frozenset()
    position_by_logical: dict[int, tuple[int, int]] = {}
    if global_order_authoritative:
        normalized_order: dict[int, int] = {}
        try:
            for raw_logical, raw_position in raw_order.items():
                logical = int(raw_logical)
                position = int(raw_position)
                if logical <= 0 or position <= 0:
                    return None
                normalized_order[logical] = position
        except (TypeError, ValueError):
            return None
        if (
            len(normalized_order) != len(raw_order)
            or len(set(normalized_order.values())) != len(normalized_order)
            or set(normalized_order) != seen_logical_pages
            or sorted(normalized_order.values())
            != list(range(1, len(normalized_order) + 1))
        ):
            return None
        position_by_logical = {
            logical_page: (normalized_order[logical_page], 0)
            for logical_page in seen_logical_pages
        }
    else:
        local_order = _sealed_agreement_local_topology_keys(
            parse_result,
            raw_page_rows,
        )
        if local_order is None:
            return None
        local_topology_order = True
        position_by_logical, local_complete_sources = local_order

    page_rows = [
        (position_by_logical[logical_page], logical_page, source_page, page)
        for logical_page, source_page, page in raw_page_rows
    ]
    if len({row[0] for row in page_rows}) != len(page_rows):
        return None
    page_rows.sort(key=lambda row: row[0])

    structural: list[dict[str, Any]] = []
    seen_structural_evidence: set[str] = set()
    text_evidence_counts: Counter[str] = Counter()
    for _position, _logical_page, _source_page, page in page_rows:
        for text_block in _agreement_source_member(page, "texts", ()) or ():
            raw_evidence_ids = _agreement_source_member(text_block, "evidence_ids")
            if isinstance(raw_evidence_ids, (list, tuple)):
                text_evidence_counts.update(
                    str(value or "").strip()
                    for value in raw_evidence_ids
                    if str(value or "").strip()
                )
    for page_position, logical_page, source_page, page in page_rows:
        page_structural: list[dict[str, Any]] = []
        for text_block in _agreement_source_member(page, "texts", ()) or ():
            raw_text = str(
                _agreement_source_member(
                    text_block,
                    "content",
                    _agreement_source_member(text_block, "text", ""),
                )
                or ""
            )
            canonical_card = canonical_credit_agreement_heading(raw_text)
            canonical_section = canonical_credit_agreement_section_heading(raw_text)
            registered_section = canonical_registered_section_heading(raw_text)
            registered_subsection = canonical_registered_subsection_heading(raw_text)
            kind = ""
            sequence: int | None = None
            if canonical_card is not None:
                match = re.fullmatch(r"授信协议(\d{1,3})", canonical_card)
                if match is None:
                    return None
                kind = "card"
                sequence = int(match.group(1))
            elif canonical_section is not None:
                kind = "start"
            elif (
                registered_section is not None
                and registered_section != "授信协议信息"
            ) or (
                registered_subsection is not None
                and registered_subsection[0] != "credit_agreement"
            ):
                kind = "boundary"
            if not kind:
                continue

            bbox = _exact_geometry_bbox(_agreement_source_member(text_block, "bbox"))
            raw_evidence_ids = _agreement_source_member(text_block, "evidence_ids")
            if bbox is None or not isinstance(raw_evidence_ids, (list, tuple)):
                return None
            evidence_ids = tuple(str(value or "").strip() for value in raw_evidence_ids)
            if (
                not evidence_ids
                or any(not value for value in evidence_ids)
                or len(evidence_ids) != len(set(evidence_ids))
                or any(value in seen_structural_evidence for value in evidence_ids)
                or any(text_evidence_counts[value] != 1 for value in evidence_ids)
            ):
                return None
            seen_structural_evidence.update(evidence_ids)
            page_structural.append(
                {
                    "kind": kind,
                    "sequence": sequence,
                    "text": raw_text,
                    "logical_page": logical_page,
                    "source_page": source_page,
                    "page_position": page_position,
                    "bbox": bbox,
                    "evidence_ids": evidence_ids,
                }
            )

        page_structural.sort(
            key=lambda item: (
                item["bbox"][1],
                item["bbox"][0],
                item["bbox"][3],
                item["bbox"][2],
            )
        )
        # Structurally meaningful headings sharing a vertical band have no
        # authoritative within-page reading order on this one-column grammar.
        for left, right in zip(page_structural, page_structural[1:]):
            if min(left["bbox"][3], right["bbox"][3]) > max(
                left["bbox"][1], right["bbox"][1]
            ):
                return None
        structural.extend(page_structural)

    starts = [index for index, item in enumerate(structural) if item["kind"] == "start"]
    cards = [index for index, item in enumerate(structural) if item["kind"] == "card"]
    if len(starts) != 1 or not cards:
        return None
    start_index = starts[0]
    boundaries = [
        index
        for index, item in enumerate(structural)
        if index > start_index and item["kind"] == "boundary"
    ]
    if not boundaries:
        return None
    boundary_index = boundaries[0]
    if local_topology_order:
        start_position = structural[start_index]["page_position"]
        boundary_position = structural[boundary_index]["page_position"]
        if start_position > boundary_position:
            return None
        envelope_pages = [
            row
            for row in page_rows
            if start_position <= row[0] <= boundary_position
        ]
        envelope_positions = [row[0] for row in envelope_pages]
        if (
            not envelope_pages
            or envelope_positions != sorted(envelope_positions)
            or len(envelope_positions) != len(set(envelope_positions))
            or any(
                source_page not in local_complete_sources
                and position <= boundary_position
                for position, _logical_page, source_page, _page in page_rows
            )
        ):
            return None
        physical_sources: list[int] = []
        for _position, _logical_page, source_page, _page in envelope_pages:
            if not physical_sources or physical_sources[-1] != source_page:
                physical_sources.append(source_page)
        if (
            any(source_page not in local_complete_sources for source_page in physical_sources)
            or physical_sources
            != list(range(physical_sources[0], physical_sources[-1] + 1))
        ):
            return None
    inside_cards = [index for index in cards if start_index < index < boundary_index]
    # Exact card headings anywhere outside the unique registered envelope are
    # a contents/prose/cross-section conflict, not an additional source row.
    if inside_cards != cards:
        return None
    ordered_cards = [structural[index] for index in inside_cards]
    sequences = [int(item["sequence"]) for item in ordered_cards]
    if sequences != list(range(1, len(sequences) + 1)):
        return None

    observations: dict[int, dict[str, Any]] = {}
    page_refs: list[dict[str, Any]] = []
    seen_ref_pages: set[tuple[int, int]] = set()
    for card in ordered_cards:
        sequence = int(card["sequence"])
        observations[sequence] = {
            "sequence": sequence,
            "source_refs": [
                {
                    "source": "candidate_b_source_coverage_ledger",
                    "logical_page": int(card["logical_page"]),
                    "source_page": int(card["source_page"]),
                    "geometry_scope": "line",
                    "binding": "printed_credit_agreement_ordinal",
                    "binding_quality": "printed_credit_agreement_ordinal",
                    "sequence": sequence,
                    "bbox": list(card["bbox"]),
                    "evidence_ids": list(card["evidence_ids"]),
                }
            ],
        }
        page_key = (int(card["logical_page"]), int(card["source_page"]))
        if page_key in seen_ref_pages:
            continue
        seen_ref_pages.add(page_key)
        page_refs.append(
            {
                "source": "candidate_b_source_coverage_ledger",
                "logical_page": page_key[0],
                "source_page": page_key[1],
                "geometry_scope": "logical_page",
            }
        )
    return {
        "sequences": sequences,
        "ordinal_observations": observations,
        "source_refs": page_refs,
    }


def _raw_account_anchor_page_has_pboc_table(page: Any) -> bool:
    """Corroborate an account heading page without owning any table value."""

    return any(
        rows and _account_base(rows) and not _other_entity_table(rows)
        for table in _account_source_member(page, "tables", ()) or ()
        if (rows := _table_rows(table))
    )


def _sealed_raw_account_population_census(
    parse_result: Any,
) -> dict[str, Any] | None:
    """Observe exact family ordinals without adopting account-table values."""

    envelope = _sealed_account_frozen_section_envelope(parse_result)
    if envelope is None:
        return None
    structural = list(envelope["structural"])
    start_index = int(envelope["start_index"])
    boundary_index = int(envelope["boundary_index"])
    page_by_logical = {
        int(logical_page): page
        for _position, logical_page, _source_page, page in envelope["envelope_pages"]
    }

    # An exact family heading closes the ownership of every preceding family.
    # Quarantine a damaged family interval without letting it veto a later,
    # independently headed dense family.  Global envelope/evidence ambiguity
    # has already failed above, and a document with no admissible family still
    # fails closed below.
    active_family = ""
    family_heading_counts: Counter[str] = Counter()
    invalid_families: set[str] = set()
    anchors_by_family: defaultdict[str, list[dict[str, Any]]] = defaultdict(list)
    for item in structural[start_index + 1 : boundary_index]:
        if item["kind"] == "untyped_barrier":
            active_family = ""
            continue
        if item["kind"] == "family":
            family = str(item.get("family") or "")
            if not family:
                active_family = ""
                continue
            family_heading_counts[family] += 1
            if family_heading_counts[family] > 1:
                invalid_families.add(family)
            active_family = family
            continue
        if item["kind"] != "anchor":
            continue
        # A damaged leading family heading leaves its anchors unowned.  They
        # cannot establish that family, but nor can they own a later exact
        # family interval.
        if not active_family:
            continue
        ordinal = item.get("ordinal")
        logical_page = int(item.get("logical_page") or 0)
        if (
            not isinstance(ordinal, int)
            or isinstance(ordinal, bool)
            or ordinal <= 0
            or logical_page not in page_by_logical
            or not _raw_account_anchor_page_has_pboc_table(page_by_logical[logical_page])
        ):
            invalid_families.add(active_family)
            continue
        anchors_by_family[active_family].append(item)

    sequences: dict[str, list[int]] = {}
    endpoints: dict[str, int] = {}
    observations: dict[str, dict[int, dict[str, Any]]] = {}
    page_refs: list[dict[str, Any]] = []
    seen_pages: set[tuple[int, int]] = set()
    for family, heading_count in family_heading_counts.items():
        anchors = anchors_by_family.get(family, [])
        if heading_count != 1 or family in invalid_families or not anchors:
            continue
        family_sequences = [int(anchor["ordinal"]) for anchor in anchors]
        if family_sequences != list(range(1, len(family_sequences) + 1)):
            continue
        endpoint, outliers = _credible_sequence_endpoint(set(family_sequences))
        if outliers or endpoint != len(family_sequences):
            continue
        sequences[family] = family_sequences
        endpoints[family] = endpoint
        family_observations: dict[int, dict[str, Any]] = {}
        for anchor in anchors:
            ordinal = int(anchor["ordinal"])
            source_ref = {
                "source": "candidate_b_account_anchor",
                "logical_page": int(anchor["logical_page"]),
                "source_page": int(anchor["source_page"]),
                "geometry_scope": "line",
                "binding": "printed_account_ordinal",
                "binding_quality": "printed_account_ordinal",
                "account_type": family,
                "category_sequence": ordinal,
                "bbox": list(anchor["bbox"]),
                "evidence_ids": list(anchor["evidence_ids"]),
            }
            family_observations[ordinal] = {
                "account_id": f"credit_account:{family}:{ordinal}",
                "account_type": family,
                "category_sequence": ordinal,
                "source_refs": [source_ref],
            }
            page_key = (int(anchor["logical_page"]), int(anchor["source_page"]))
            if page_key not in seen_pages:
                seen_pages.add(page_key)
                page_refs.append(
                    {
                        "source": "candidate_b_source_coverage_ledger",
                        "logical_page": page_key[0],
                        "source_page": page_key[1],
                        "geometry_scope": "logical_page",
                    }
                )
        observations[family] = family_observations
    if not sequences:
        return None
    return {
        "sequences": sequences,
        "endpoints": endpoints,
        "ordinal_observations": observations,
        "source_refs": page_refs,
        "local_topology_authority": envelope.get("local_authority") is True,
        "envelope_logical_pages": list(envelope["envelope_logical_pages"]),
    }


def _exact_account_ordinal_owner_signature(
    observation: Any,
    *,
    family: str,
    ordinal: int,
) -> tuple[int, int, tuple[float, float, float, float], tuple[str, ...]] | None:
    """Return one immutable family/ordinal anchor owner or fail closed."""

    if (
        not isinstance(observation, Mapping)
        or str(observation.get("account_id") or "") != f"credit_account:{family}:{ordinal}"
    ):
        return None
    anchor_refs = [
        ref
        for ref in observation.get("source_refs") or ()
        if isinstance(ref, Mapping) and str(ref.get("source") or "") == "candidate_b_account_anchor"
    ]
    if len(anchor_refs) != 1:
        return None
    ref = anchor_refs[0]
    logical_page = ref.get("logical_page")
    source_page = ref.get("source_page")
    bbox = _exact_geometry_bbox(ref.get("bbox"))
    evidence_ids = _strict_physical_account_evidence_ids(ref.get("evidence_ids"))
    if (
        ref.get("geometry_scope") != "line"
        or ref.get("binding") != "printed_account_ordinal"
        or ref.get("binding_quality") != "printed_account_ordinal"
        or ref.get("account_type") != family
        or ref.get("category_sequence") != ordinal
        or not isinstance(logical_page, int)
        or isinstance(logical_page, bool)
        or logical_page <= 0
        or not isinstance(source_page, int)
        or isinstance(source_page, bool)
        or source_page <= 0
        or bbox is None
        or evidence_ids is None
    ):
        return None
    return logical_page, source_page, bbox, tuple(sorted(evidence_ids))


def _registered_account_population_observations(
    exact_section_inventory: Any,
) -> dict[str, dict[int, dict[str, Any]]] | None:
    """Read population-only account ordinals from one registered section plane.

    The registered plane has already proved a finite account-section envelope,
    authoritative document order, and exact family-heading ownership.  Card
    table materialization is deliberately stricter and may reject a page whose
    values cannot be owned.  That value-plane rejection must not erase an exact,
    dense printed card-heading chain from the source-population denominator.

    Loan families retain their table-edge ownership contract because their pages
    can begin with continuation-only repayment/history fragments.  Card headings
    have a finite, family-specific printed grammar and cannot be confused with
    those generic continuation rows.

    This adapter therefore adopts only a dense family/ordinal identity chain.  It
    publishes no business fields and fails closed on duplicate ordinals, replayed
    evidence, duplicate physical owners, or non-monotonic family order.
    """

    if (
        not isinstance(exact_section_inventory, tuple)
        or len(exact_section_inventory) != 2
    ):
        return None
    raw_pages, raw_plane = exact_section_inventory
    if not isinstance(raw_pages, list) or not isinstance(raw_plane, Mapping):
        return None

    allowed_families = {"credit_card", "quasi_credit_card"}
    page_owners: dict[int, tuple[int, int]] = {}
    for position, page in enumerate(raw_pages, start=1):
        if not isinstance(page, Mapping):
            return None
        logical_page = page.get("page")
        source_page = page.get("source_page")
        if (
            not isinstance(logical_page, int)
            or isinstance(logical_page, bool)
            or logical_page <= 0
            or not isinstance(source_page, int)
            or isinstance(source_page, bool)
            or source_page <= 0
            or logical_page in page_owners
        ):
            return None
        page_owners[logical_page] = (position, source_page)
    if not page_owners or not set(raw_plane).issubset(page_owners):
        return None

    candidates: defaultdict[
        tuple[str, int],
        list[
            tuple[
                tuple[int, float, float],
                tuple[int, tuple[float, float, float, float]],
                tuple[str, ...],
                dict[str, Any],
            ]
        ],
    ] = defaultdict(list)
    for logical_page, (position, source_page) in page_owners.items():
        lines = raw_plane.get(logical_page, ())
        if not isinstance(lines, list):
            return None
        for line in lines:
            if not isinstance(line, Mapping):
                return None
            family = str(line.get("account_type") or "")
            ordinal = _account_anchor_observation_ordinal(line)
            if family not in allowed_families or ordinal is None:
                continue
            bbox = _account_evidence_bbox(line)
            evidence_ids = _strict_account_source_evidence_ids(line)
            line_logical_page = line.get("page")
            line_source_page = line.get("source_page")
            if (
                line.get("account_family_quality") != "exact"
                or not isinstance(ordinal, int)
                or isinstance(ordinal, bool)
                or ordinal <= 0
                or bbox is None
                or evidence_ids is None
                or line_logical_page != logical_page
                or line_source_page != source_page
            ):
                continue
            source_ref = {
                "source": "candidate_b_account_anchor",
                "logical_page": logical_page,
                "source_page": source_page,
                "geometry_scope": "line",
                "binding": "printed_account_ordinal",
                "binding_quality": "printed_account_ordinal",
                "account_type": family,
                "category_sequence": ordinal,
                "bbox": list(bbox),
                "evidence_ids": list(evidence_ids),
            }
            observation = {
                "account_id": f"credit_account:{family}:{ordinal}",
                "account_type": family,
                "category_sequence": ordinal,
                "source_refs": [source_ref],
            }
            candidates[(family, ordinal)].append(
                (
                    (position, bbox[1], bbox[0]),
                    (source_page, bbox),
                    evidence_ids,
                    observation,
                )
            )

    if not candidates or any(len(values) != 1 for values in candidates.values()):
        return None
    flattened = [values[0] for values in candidates.values()]
    physical_owners = [physical_owner for _order, physical_owner, _ids, _row in flattened]
    evidence_ids = [evidence_id for _order, _owner, ids, _row in flattened for evidence_id in ids]
    if len(physical_owners) != len(set(physical_owners)) or len(evidence_ids) != len(
        set(evidence_ids)
    ):
        return None

    ordered_by_family: defaultdict[
        str,
        list[tuple[tuple[int, float, float], int, dict[str, Any]]],
    ] = defaultdict(list)
    for (family, ordinal), values in candidates.items():
        order, _physical_owner, _evidence_ids, observation = values[0]
        ordered_by_family[family].append((order, ordinal, observation))

    result: dict[str, dict[int, dict[str, Any]]] = {}
    for family, rows in ordered_by_family.items():
        rows.sort(key=lambda item: item[0])
        ordinals = [ordinal for _order, ordinal, _observation in rows]
        if any(left >= right for left, right in zip(ordinals, ordinals[1:])):
            return None
        if ordinals != list(range(1, ordinals[-1] + 1)):
            # A gap on an otherwise family-owned page can be a stray account-like
            # line or an incomplete OCR observation.  Existing table-bound
            # skeleton evidence remains available, but this population-only
            # adapter must not promote a convenient prefix from the open chain.
            continue
        result[family] = {
            ordinal: observation for _order, ordinal, observation in rows
        }
    return result


def _sealed_registered_account_population_observations(
    raw_observations: Any,
) -> dict[str, dict[int, dict[str, Any]]] | None:
    """Revalidate and strip one registered population plane for lifecycle use."""

    if not isinstance(raw_observations, Mapping) or not raw_observations:
        return None
    allowed_families = {"credit_card", "quasi_credit_card"}
    sealed: dict[str, dict[int, dict[str, Any]]] = {}
    physical_owners: set[tuple[int, tuple[float, float, float, float]]] = set()
    evidence_owners: set[str] = set()
    for raw_family, raw_family_observations in raw_observations.items():
        family = str(raw_family or "")
        if (
            family not in allowed_families
            or not isinstance(raw_family_observations, Mapping)
            or not raw_family_observations
        ):
            return None
        if any(
            not isinstance(ordinal, int)
            or isinstance(ordinal, bool)
            or ordinal <= 0
            for ordinal in raw_family_observations
        ):
            return None
        ordinals = sorted(raw_family_observations)
        if ordinals != list(range(1, ordinals[-1] + 1)):
            return None
        family_observations: dict[int, dict[str, Any]] = {}
        for ordinal in ordinals:
            observation = raw_family_observations[ordinal]
            owner = _exact_account_ordinal_owner_signature(
                observation,
                family=family,
                ordinal=ordinal,
            )
            if owner is None:
                return None
            logical_page, source_page, bbox, evidence_ids = owner
            physical_owner = (source_page, bbox)
            if physical_owner in physical_owners:
                return None
            if any(evidence_id in evidence_owners for evidence_id in evidence_ids):
                return None
            physical_owners.add(physical_owner)
            evidence_owners.update(evidence_ids)
            raw_source_ref = next(
                (
                    ref
                    for ref in observation.get("source_refs") or ()
                    if isinstance(ref, Mapping)
                    and str(ref.get("source") or "")
                    == "candidate_b_account_anchor"
                ),
                None,
            )
            if raw_source_ref is None:
                return None
            source_ref = {
                "source": "candidate_b_account_anchor",
                "logical_page": logical_page,
                "source_page": source_page,
                "geometry_scope": "line",
                "binding": "printed_account_ordinal",
                "binding_quality": "printed_account_ordinal",
                "account_type": family,
                "category_sequence": ordinal,
                "bbox": list(bbox),
                "evidence_ids": list(evidence_ids),
            }
            family_observations[ordinal] = {
                "account_id": f"credit_account:{family}:{ordinal}",
                "account_type": family,
                "category_sequence": ordinal,
                "source_refs": [source_ref],
            }
        sealed[family] = family_observations
    return sealed


_REGISTERED_ACCOUNT_POPULATION_AUTHORITY_VERSION = (
    "registered_account_population_authority:v1"
)


def _registered_account_population_authority_payload(
    exact_section_inventory: Any,
) -> tuple[
    str,
    tuple[tuple[int, int, int], ...],
    tuple[
        tuple[
            str,
            int,
            int,
            int,
            int,
            tuple[float, float, float, float],
            tuple[str, ...],
        ],
        ...,
    ],
] | None:
    """Seal population owners together with their registered document order."""

    observations = _registered_account_population_observations(
        exact_section_inventory
    )
    sealed = _sealed_registered_account_population_observations(observations)
    if sealed is None:
        return None
    raw_pages, _raw_plane = exact_section_inventory
    page_order: list[tuple[int, int, int]] = []
    page_positions: dict[int, tuple[int, int]] = {}
    for position, page in enumerate(raw_pages, start=1):
        if not isinstance(page, Mapping):
            return None
        logical_page = page.get("page")
        source_page = page.get("source_page")
        if (
            not isinstance(logical_page, int)
            or isinstance(logical_page, bool)
            or logical_page <= 0
            or not isinstance(source_page, int)
            or isinstance(source_page, bool)
            or source_page <= 0
            or logical_page in page_positions
        ):
            return None
        page_order.append((position, logical_page, source_page))
        page_positions[logical_page] = (position, source_page)

    owners: list[
        tuple[
            str,
            int,
            int,
            int,
            int,
            tuple[float, float, float, float],
            tuple[str, ...],
        ]
    ] = []
    for family in sorted(sealed):
        family_orders: list[tuple[int, float, float]] = []
        for ordinal in sorted(sealed[family]):
            owner = _exact_account_ordinal_owner_signature(
                sealed[family][ordinal],
                family=family,
                ordinal=ordinal,
            )
            if owner is None:
                return None
            logical_page, source_page, bbox, evidence_ids = owner
            registered_page = page_positions.get(logical_page)
            if registered_page is None or registered_page[1] != source_page:
                return None
            position = registered_page[0]
            family_orders.append((position, bbox[1], bbox[0]))
            owners.append(
                (
                    family,
                    ordinal,
                    position,
                    logical_page,
                    source_page,
                    bbox,
                    evidence_ids,
                )
            )
        if any(
            left >= right
            for left, right in zip(family_orders, family_orders[1:])
        ):
            return None
    return (
        _REGISTERED_ACCOUNT_POPULATION_AUTHORITY_VERSION,
        tuple(page_order),
        tuple(owners),
    )


def _registered_account_population_authority_digest(payload: Any) -> str | None:
    try:
        encoded = json.dumps(
            payload,
            ensure_ascii=False,
            separators=(",", ":"),
            allow_nan=False,
        ).encode("utf-8")
    except (TypeError, ValueError):
        return None
    return hashlib.sha256(encoded).hexdigest()


def _registered_account_population_authority_seal(
    exact_section_inventory: Any,
) -> tuple[Any, str] | None:
    payload = _registered_account_population_authority_payload(
        exact_section_inventory
    )
    digest = _registered_account_population_authority_digest(payload)
    return (payload, digest) if payload is not None and digest is not None else None


def _registered_account_population_from_authority_seal(
    raw_authority_seal: Any,
) -> dict[str, dict[int, dict[str, Any]]] | None:
    """Verify one immutable authority seal and reconstruct population-only rows."""

    if not isinstance(raw_authority_seal, tuple) or len(raw_authority_seal) != 2:
        return None
    payload, digest = raw_authority_seal
    if (
        not isinstance(payload, tuple)
        or len(payload) != 3
        or payload[0] != _REGISTERED_ACCOUNT_POPULATION_AUTHORITY_VERSION
        or not isinstance(digest, str)
        or digest != _registered_account_population_authority_digest(payload)
    ):
        return None
    raw_page_order, raw_owners = payload[1:]
    if (
        not isinstance(raw_page_order, tuple)
        or not raw_page_order
        or not isinstance(raw_owners, tuple)
        or not raw_owners
    ):
        return None

    registered_pages: dict[int, tuple[int, int]] = {}
    for expected_position, raw_page in enumerate(raw_page_order, start=1):
        if not isinstance(raw_page, tuple) or len(raw_page) != 3:
            return None
        position, logical_page, source_page = raw_page
        if (
            position != expected_position
            or not isinstance(logical_page, int)
            or isinstance(logical_page, bool)
            or logical_page <= 0
            or not isinstance(source_page, int)
            or isinstance(source_page, bool)
            or source_page <= 0
            or logical_page in registered_pages
        ):
            return None
        registered_pages[logical_page] = (position, source_page)

    allowed_families = {"credit_card", "quasi_credit_card"}
    reconstructed: defaultdict[str, dict[int, dict[str, Any]]] = defaultdict(dict)
    family_orders: defaultdict[str, list[tuple[int, float, float]]] = defaultdict(list)
    physical_owners: set[tuple[int, tuple[float, float, float, float]]] = set()
    evidence_owners: set[str] = set()
    previous_family_ordinal: tuple[str, int] | None = None
    for raw_owner in raw_owners:
        if not isinstance(raw_owner, tuple) or len(raw_owner) != 7:
            return None
        (
            family,
            ordinal,
            position,
            logical_page,
            source_page,
            raw_bbox,
            raw_evidence_ids,
        ) = raw_owner
        bbox = _exact_geometry_bbox(raw_bbox)
        if (
            family not in allowed_families
            or not isinstance(ordinal, int)
            or isinstance(ordinal, bool)
            or ordinal <= 0
            or not isinstance(position, int)
            or isinstance(position, bool)
            or not isinstance(logical_page, int)
            or isinstance(logical_page, bool)
            or not isinstance(source_page, int)
            or isinstance(source_page, bool)
            or bbox is None
            or not isinstance(raw_bbox, tuple)
            or not isinstance(raw_evidence_ids, tuple)
            or not raw_evidence_ids
            or any(
                not isinstance(evidence_id, str) or not evidence_id.strip()
                for evidence_id in raw_evidence_ids
            )
            or tuple(sorted(raw_evidence_ids)) != raw_evidence_ids
            or registered_pages.get(logical_page) != (position, source_page)
        ):
            return None
        family_ordinal = (family, ordinal)
        if (
            previous_family_ordinal is not None
            and family_ordinal <= previous_family_ordinal
        ):
            return None
        previous_family_ordinal = family_ordinal
        physical_owner = (source_page, bbox)
        if physical_owner in physical_owners or any(
            evidence_id in evidence_owners for evidence_id in raw_evidence_ids
        ):
            return None
        physical_owners.add(physical_owner)
        evidence_owners.update(raw_evidence_ids)
        family_orders[family].append((position, bbox[1], bbox[0]))
        source_ref = {
            "source": "candidate_b_account_anchor",
            "logical_page": logical_page,
            "source_page": source_page,
            "geometry_scope": "line",
            "binding": "printed_account_ordinal",
            "binding_quality": "printed_account_ordinal",
            "account_type": family,
            "category_sequence": ordinal,
            "bbox": list(bbox),
            "evidence_ids": list(raw_evidence_ids),
        }
        reconstructed[family][ordinal] = {
            "account_id": f"credit_account:{family}:{ordinal}",
            "account_type": family,
            "category_sequence": ordinal,
            "source_refs": [source_ref],
        }

    for family, observations in reconstructed.items():
        ordinals = sorted(observations)
        if ordinals != list(range(1, ordinals[-1] + 1)) or any(
            left >= right
            for left, right in zip(
                family_orders[family], family_orders[family][1:]
            )
        ):
            return None
    result = _sealed_registered_account_population_observations(reconstructed)
    return result if result == dict(reconstructed) else None


def _registered_account_population_lifecycle_observations(
    parse_result: Any,
    current_observations: Any,
    exact_section_inventory: Any,
) -> dict[str, dict[int, dict[str, Any]]] | None:
    """Conserve exact registered populations across Candidate B's repair pass.

    Complete-page repair is a value-decoding plane and may lose otherwise exact
    printed headings.  Preserve the discovery population plane, then select the
    longest independently dense observation chain for each family.  No business
    fields cross the pass boundary.
    """

    current_candidate = _sealed_registered_account_population_observations(
        current_observations
    )
    current_authority_seal = _registered_account_population_authority_seal(
        exact_section_inventory
    )
    authorized_current = _registered_account_population_from_authority_seal(
        current_authority_seal
    )
    current = (
        current_candidate
        if current_candidate is not None and current_candidate == authorized_current
        else None
    )
    repair_active = getattr(parse_result, "_business_repair_active", False) is True
    snapshot_name = (
        "_candidate_b_pre_repair_registered_account_population_observations"
    )
    authority_name = (
        "_candidate_b_pre_repair_registered_account_population_authority"
    )
    if not repair_active:
        for cache_name in (snapshot_name, authority_name):
            try:
                delattr(parse_result, cache_name)
            except (AttributeError, TypeError):
                pass
        if current is not None and current_authority_seal is not None:
            try:
                setattr(parse_result, snapshot_name, deepcopy(current))
                setattr(parse_result, authority_name, current_authority_seal)
            except (AttributeError, TypeError):
                pass
        return current

    discovery_candidate = _sealed_registered_account_population_observations(
        getattr(parse_result, snapshot_name, None)
    )
    authorized_discovery = _registered_account_population_from_authority_seal(
        getattr(parse_result, authority_name, None)
    )
    discovery = (
        discovery_candidate
        if discovery_candidate is not None
        and discovery_candidate == authorized_discovery
        else None
    )
    if discovery is None:
        return current
    if current is None:
        return discovery
    reconciled: dict[str, dict[int, dict[str, Any]]] = {}
    for family in sorted(set(discovery) | set(current)):
        discovery_family = discovery.get(family)
        current_family = current.get(family)
        if discovery_family is None:
            selected = current_family
        elif current_family is None or len(discovery_family) > len(current_family):
            selected = discovery_family
        else:
            selected = current_family
        if selected:
            reconciled[family] = deepcopy(selected)
    return _sealed_registered_account_population_observations(reconciled)


def _authoritative_account_anchor_order(parse_result: Any) -> dict[int, int] | None:
    """Return one immutable registered document position per logical page."""

    raw_order = getattr(parse_result, "reading_order_by_logical", None)
    resolution = getattr(parse_result, "reading_order_resolution", None)
    if (
        not isinstance(raw_order, Mapping)
        or not raw_order
        or not isinstance(resolution, Mapping)
        or resolution.get("resolved") is not True
        or resolution.get("authoritative") is not True
    ):
        return None
    normalized: dict[int, int] = {}
    for raw_logical_page, raw_position in raw_order.items():
        if isinstance(raw_logical_page, bool) or isinstance(raw_position, bool):
            return None
        try:
            logical_page = int(raw_logical_page)
            position = int(raw_position)
        except (TypeError, ValueError):
            return None
        if logical_page <= 0 or position <= 0:
            return None
        prior = normalized.get(logical_page)
        if prior is not None and prior != position:
            return None
        normalized[logical_page] = position
    if len(normalized) != len(raw_order) or len(set(normalized.values())) != len(normalized):
        return None
    return normalized


def _exact_source_supported_account_sequence_endpoint(
    parse_result: Any,
    values: set[int],
    *,
    family: str,
    observations: Mapping[int, Any],
) -> tuple[int | None, list[int]]:
    """Admit a sparse high endpoint only from two independent printed anchors.

    The general sequence helper deliberately needs a three-ordinal high tail and
    is also used by unsealed/non-account callers.  This stricter ledger-only path
    may admit two consecutive high ordinals because each one is already bound to
    a unique immutable same-family line and the authoritative document order can
    prove that the physical anchors progress with their printed ordinals.
    """

    baseline_endpoint, baseline_outliers = _credible_sequence_endpoint(values)
    if not baseline_outliers:
        return baseline_endpoint, baseline_outliers
    document_order = _authoritative_account_anchor_order(parse_result)
    if document_order is None or not isinstance(observations, Mapping):
        return baseline_endpoint, baseline_outliers

    positive_values = sorted(
        value for value in values if isinstance(value, int) and not isinstance(value, bool) and value > 0
    )
    baseline_value = int(baseline_endpoint or 0)
    candidate_endpoints = [value for value in positive_values if value > baseline_value and value - 1 in values]
    for candidate_endpoint in reversed(candidate_endpoints):
        tail_ordinals = {candidate_endpoint - 1, candidate_endpoint}
        exact_owners: list[
            tuple[
                int,
                tuple[int, int, tuple[float, float, float, float], tuple[str, ...]],
            ]
        ] = []
        tail_is_exact = True
        for ordinal in positive_values:
            if ordinal > candidate_endpoint:
                continue
            observation = observations.get(ordinal)
            owner = _exact_account_ordinal_owner_signature(
                observation,
                family=family,
                ordinal=ordinal,
            )
            if ordinal in tail_ordinals and owner is None:
                tail_is_exact = False
                break
            if owner is not None:
                exact_owners.append((ordinal, owner))
        if not tail_is_exact or not tail_ordinals.issubset({ordinal for ordinal, _owner in exact_owners}):
            continue

        seen_physical_owners: set[tuple[int, tuple[float, float, float, float]]] = set()
        seen_evidence_ids: set[str] = set()
        coherent = True
        for _ordinal, (_logical_page, source_page, bbox, evidence_ids) in exact_owners:
            physical_owner = (source_page, bbox)
            if physical_owner in seen_physical_owners or seen_evidence_ids.intersection(evidence_ids):
                coherent = False
                break
            seen_physical_owners.add(physical_owner)
            seen_evidence_ids.update(evidence_ids)
        if not coherent:
            continue

        for (_left_ordinal, left), (_right_ordinal, right) in zip(
            exact_owners,
            exact_owners[1:],
        ):
            left_logical, left_source, left_bbox, _left_evidence = left
            right_logical, right_source, right_bbox, _right_evidence = right
            left_position = document_order.get(left_logical)
            right_position = document_order.get(right_logical)
            if (
                left_position is None
                or right_position is None
                or left_source > right_source
                or left_position > right_position
                or (left_position == right_position and (left_logical != right_logical or left_bbox[3] > right_bbox[1]))
            ):
                coherent = False
                break
        if not coherent:
            continue

        outliers = sorted(
            value
            for value in values
            if not isinstance(value, int) or isinstance(value, bool) or value <= 0 or value > candidate_endpoint
        )
        return candidate_endpoint, outliers
    return baseline_endpoint, baseline_outliers


def _source_completeness_ledger(parse_result: Any) -> dict[str, Any]:
    """Count printed sequence evidence independently of emitted records."""
    sequences: dict[str, set[int]] = {
        "mobile_phone_records": set(),
        "residence_records": set(),
        "employment_records": set(),
    }
    sequence_ordinal_observations: defaultdict[
        str,
        dict[int, dict[str, Any]],
    ] = defaultdict(dict)
    sequence_components: dict[
        str,
        tuple[tuple[str, dict[str, tuple[str, ...]]], ...],
    ] = {
        "mobile_phone_records": (
            (
                "mobile",
                {
                    "sequence": ("编号",),
                    "mobile_phone": ("手机号码",),
                    "information_updated_date": ("信息更新日期",),
                    "data_provider": ("数据发生机构名称",),
                },
            ),
        ),
        "residence_records": (
            (
                "residence",
                {
                    "sequence": ("编号",),
                    "address": ("居住地址",),
                    "residential_phone": ("住宅电话",),
                    "residence_status": ("居住状况",),
                    "information_updated_date": ("信息更新日期",),
                },
            ),
        ),
        "employment_records": (
            (
                "basic",
                {
                    "sequence": ("编号",),
                    "employer": ("工作单位",),
                    "employer_type": ("单位性质",),
                    "employer_address": ("单位地址",),
                    "employer_phone": ("单位电话",),
                },
            ),
            (
                "detail",
                {
                    "sequence": ("编号",),
                    "occupation": ("职业",),
                    "industry": ("行业",),
                    "position": ("职务",),
                    "professional_title": ("职称",),
                    "entry_year": ("进入本单位年份",),
                    "information_updated_date": ("信息更新日期",),
                },
            ),
        ),
    }
    observation_component_counts: Counter[tuple[str, str, int]] = Counter()
    ambiguous_observations: set[tuple[str, int]] = set()
    for page in getattr(parse_result, "pages", None) or []:
        for table in getattr(page, "tables", None) or []:
            rows = _table_rows(table)
            if not rows:
                continue
            header_matches_by_row: defaultdict[
                int,
                list[tuple[str, str, dict[str, int]]],
            ] = defaultdict(list)
            header_targets_by_row: defaultdict[int, set[str]] = defaultdict(set)
            component_header_counts: Counter[tuple[str, str]] = Counter()
            for header_index, header_row in enumerate(rows):
                header = tuple(str(value or "") for value in header_row)
                for target, components in sequence_components.items():
                    for component, aliases in components:
                        observed_roles = _header_role_columns(header, aliases)
                        distinctive_roles = set(observed_roles) - {
                            "sequence",
                            "information_updated_date",
                        }
                        if (
                            observed_roles.get("sequence") == 0
                            and distinctive_roles
                            and (target != "mobile_phone_records" or set(observed_roles) == set(aliases))
                        ):
                            header_targets_by_row[header_index].add(target)
                        slots = _canonical_header_slots(header, aliases)
                        columns = list(slots.values())
                        if (
                            set(slots) != set(aliases)
                            or slots.get("sequence") != 0
                            or len(set(columns)) != len(columns)
                        ):
                            continue
                        header_matches_by_row[header_index].append((target, component, slots))
                        component_header_counts[(target, component)] += 1

            ambiguous_table_targets = {
                target for (target, _component), count in component_header_counts.items() if count != 1
            }
            for matches in header_matches_by_row.values():
                if len(matches) != 1:
                    ambiguous_table_targets.update(target for target, _component, _slots in matches)

            header_indices = sorted(header_targets_by_row)
            for header_offset, header_index in enumerate(header_indices):
                region_targets = header_targets_by_row[header_index]
                if len(region_targets) != 1:
                    continue
                target = next(iter(region_targets))
                matches = [match for match in header_matches_by_row.get(header_index, ()) if match[0] == target]
                exact_component = matches[0] if len(matches) == 1 else None
                region_end = header_indices[header_offset + 1] if header_offset + 1 < len(header_indices) else len(rows)
                for row_index in range(header_index + 1, region_end):
                    row = rows[row_index]
                    sequence_column = 0
                    first = _clean(row[sequence_column] if sequence_column < len(row) else "")
                    numbers = [int(value) for value in re.findall(r"\d{1,3}", first)]
                    sequence = numbers[0] if numbers and len(set(numbers)) == 1 else None
                    if sequence is None or sequence <= 0:
                        continue
                    # Population ordinals belong only to the region below their
                    # complete canonical header. A different section elsewhere
                    # in the same physical table cannot claim this row.
                    sequences[target].add(sequence)
                    if exact_component is None or target in ambiguous_table_targets:
                        continue
                    _target, component, slots = exact_component
                    key = (target, component, sequence)
                    observation_component_counts[key] += 1
                    if observation_component_counts[key] > 1:
                        ambiguous_observations.add((target, sequence))
                        sequence_ordinal_observations[target].pop(sequence, None)
                        continue
                    exact_sequence = _exact_native_table_cell(
                        table,
                        row=row_index,
                        column=sequence_column,
                    )
                    if exact_sequence is None or (target, sequence) in ambiguous_observations:
                        continue
                    sequence_bbox, sequence_evidence_ids = exact_sequence
                    row_ref = {
                        **_source_ref(
                            page,
                            table,
                            row=row_index,
                            column=sequence_column,
                        ),
                        "bbox": list(sequence_bbox),
                        "geometry_scope": "canonical_sequence_cell",
                        "evidence_ids": list(sequence_evidence_ids),
                        "binding": "canonical_sequence_row",
                        "binding_quality": "canonical_sequence_row",
                        "sequence": sequence,
                        "component": component,
                    }
                    local = sequence_ordinal_observations[target].setdefault(
                        sequence,
                        {
                            "sequence": sequence,
                            "canonical_header_fields_by_component": {component: sorted(slots)},
                            **(
                                {"canonical_header_fields": sorted(slots)}
                                if len(sequence_components[target]) == 1
                                else {}
                            ),
                            "printed_fields": [],
                            "field_source_refs": {},
                            "source_refs": [],
                        },
                    )
                    component_headers = local.setdefault(
                        "canonical_header_fields_by_component",
                        {},
                    )
                    prior_header = component_headers.get(component)
                    if prior_header and set(prior_header) != set(slots):
                        ambiguous_observations.add((target, sequence))
                        sequence_ordinal_observations[target].pop(sequence, None)
                        continue
                    component_headers[component] = sorted(slots)
                    if row_ref not in local["source_refs"]:
                        local["source_refs"].append(row_ref)
                    for field_name, column in slots.items():
                        if field_name == "sequence" or column >= len(row):
                            continue
                        if not _clean(row[column]):
                            continue
                        exact_cell = _exact_native_table_cell(
                            table,
                            row=row_index,
                            column=column,
                        )
                        if exact_cell is None:
                            continue
                        cell_ref = {
                            **_source_ref(
                                page,
                                table,
                                row=row_index,
                                column=column,
                            ),
                            "field_name": field_name,
                            "binding": "canonical_header_column",
                            "binding_quality": "canonical_header_column",
                            "sequence": sequence,
                            "component": component,
                        }
                        field_refs = local["field_source_refs"].setdefault(
                            field_name,
                            [],
                        )
                        if cell_ref not in field_refs:
                            field_refs.append(cell_ref)
                        if field_name not in local["printed_fields"]:
                            local["printed_fields"].append(field_name)

    for target, sequence in ambiguous_observations:
        sequence_ordinal_observations[target].pop(sequence, None)

    sequence_outliers: dict[str, list[int]] = {}
    for target, values in sequences.items():
        _endpoint, outliers = _credible_sequence_endpoint(values)
        if not outliers:
            continue
        sequence_outliers[target] = outliers
        values.difference_update(outliers)
        for sequence in outliers:
            sequence_ordinal_observations[target].pop(sequence, None)

    raw_profile_census = _sealed_raw_profile_population_census(parse_result)
    if isinstance(raw_profile_census, Mapping):
        for target in raw_profile_census.get("vetoed_datasets") or ():
            if target not in _RAW_PROFILE_DATASET_CONTRACTS:
                continue
            sequences[target].clear()
            sequence_ordinal_observations.pop(target, None)
            sequence_outliers.pop(target, None)
        raw_sequences = raw_profile_census.get("sequences")
        raw_observations = raw_profile_census.get("ordinal_observations")
        if isinstance(raw_sequences, Mapping) and isinstance(
            raw_observations, Mapping
        ):
            for target, values in raw_sequences.items():
                if (
                    target not in _RAW_PROFILE_DATASET_CONTRACTS
                    or not isinstance(values, (list, tuple))
                    or not isinstance(raw_observations.get(target), Mapping)
                ):
                    continue
                sequences[target] = set(values)
                sequence_ordinal_observations[target] = {
                    int(sequence): dict(observation)
                    for sequence, observation in raw_observations[target].items()
                    if isinstance(sequence, int)
                    and not isinstance(sequence, bool)
                    and isinstance(observation, Mapping)
                }
                sequence_outliers.pop(target, None)

    # Account numbers restart for each PBOC account family, so count the
    # maximum printed endpoint within each observed family instead of taking
    # one document-wide maximum.  Some exact families (notably R2) print an
    # account anchor without an ordinal.  Keep those anchors in a separate,
    # source-bound inventory: adding ``sum(endpoints)`` alone silently drops
    # the whole singleton family.
    family = ""
    family_quality = ""
    family_logical_page = 0
    family_last_ordinal = 0
    family_sequences: defaultdict[str, set[int]] = defaultdict(set)
    family_numbered_identifiers: defaultdict[str, set[str]] = defaultdict(set)
    family_unnumbered_identifiers: defaultdict[str, set[str]] = defaultdict(set)
    family_weak_unnumbered_anchors: defaultdict[str, set[str]] = defaultdict(set)
    account_skeletons = _account_anchor_skeletons(parse_result)
    account_inventory_resolution = getattr(parse_result, "reading_order_resolution", None)
    account_inventory_order = getattr(parse_result, "reading_order_by_logical", None)
    global_account_inventory_authority = bool(
        isinstance(account_inventory_resolution, Mapping)
        and account_inventory_resolution.get("resolved") is True
        and account_inventory_resolution.get("authoritative") is True
        and isinstance(account_inventory_order, Mapping)
        and account_inventory_order
    )
    # The source census and business extraction share one repair lifecycle.
    # Complete-page OCR changes evidence IDs even when it observes the same
    # physical anchor, so source-ref identity cannot be used to count the two
    # planes as independent rows.  Reconcile on exact printed family/ordinal
    # ownership, with the same ambiguity checks used by final account output.
    account_inventory_skeletons: list[Mapping[str, Any]] = (
        _repair_complete_account_anchor_skeletons(parse_result, account_skeletons)
        if global_account_inventory_authority
        else []
    )
    anchor_inventory_candidates: Counter[tuple[str, int]] = Counter()
    for skeleton in account_inventory_skeletons:
        if not isinstance(skeleton, Mapping):
            continue
        account_family = str(skeleton.get("account_type") or "")
        ordinal = skeleton.get("category_sequence")
        segment = skeleton.get("_canonical_segment")
        if (
            account_family
            not in {
                "non_revolving_loan",
                "revolving_loan_subaccount",
                "revolving_loan_account",
                "credit_card",
                "quasi_credit_card",
            }
            or skeleton.get("account_family_quality") != "exact"
            or skeleton.get("_printed_ordinal_status") != "printed_unique"
            or not isinstance(ordinal, int)
            or isinstance(ordinal, bool)
            or ordinal <= 0
            or skeleton.get("account_id") != f"credit_account:{account_family}:{ordinal}"
            or not isinstance(segment, Mapping)
            or segment.get("ownership_basis") != "printed_anchor_to_next_anchor"
        ):
            continue
        anchor_inventory_candidates[(account_family, ordinal)] += 1
    anchor_inventory_sequences: defaultdict[str, set[int]] = defaultdict(set)
    for (account_family, ordinal), count in anchor_inventory_candidates.items():
        # The skeleton builder labels a printed ordinal unique before caching
        # it.  Recheck uniqueness here so a duplicated or externally mutated
        # cache cannot manufacture source-population evidence.
        if count == 1:
            anchor_inventory_sequences[account_family].add(ordinal)
            family_sequences[account_family].add(ordinal)
    account_ordinal_observations: defaultdict[
        str,
        dict[int, dict[str, Any]],
    ] = defaultdict(dict)
    for skeleton in account_inventory_skeletons:
        if not isinstance(skeleton, Mapping):
            continue
        account_family = str(skeleton.get("account_type") or "")
        ordinal = skeleton.get("category_sequence")
        account_id = str(skeleton.get("account_id") or "")
        segment = skeleton.get("_canonical_segment")
        if (
            account_family
            not in {
                "non_revolving_loan",
                "revolving_loan_subaccount",
                "revolving_loan_account",
                "credit_card",
                "quasi_credit_card",
            }
            or skeleton.get("account_family_quality") != "exact"
            or skeleton.get("_printed_ordinal_status") != "printed_unique"
            or not isinstance(ordinal, int)
            or isinstance(ordinal, bool)
            or ordinal <= 0
            or account_id != f"credit_account:{account_family}:{ordinal}"
            or not isinstance(segment, Mapping)
            or segment.get("ownership_basis") != "printed_anchor_to_next_anchor"
            or anchor_inventory_candidates[(account_family, ordinal)] != 1
        ):
            continue
        ordinal_refs = [
            {
                **dict(ref),
                "geometry_scope": "line",
                "binding": "printed_account_ordinal",
                "binding_quality": "printed_account_ordinal",
                "account_type": account_family,
                "category_sequence": ordinal,
            }
            for ref in skeleton.get("source_refs") or ()
            if isinstance(ref, Mapping)
            and ref.get("source") == "candidate_b_account_anchor"
            and isinstance(ref.get("logical_page"), int)
            and not isinstance(ref.get("logical_page"), bool)
            and int(ref["logical_page"]) > 0
            and isinstance(ref.get("source_page"), int)
            and not isinstance(ref.get("source_page"), bool)
            and int(ref["source_page"]) > 0
            and _exact_geometry_bbox(ref.get("bbox")) is not None
            and _strict_physical_account_evidence_ids(ref.get("evidence_ids"))
            is not None
        ]
        if len(ordinal_refs) != 1:
            continue
        raw_field_refs = skeleton.get("source_refs_by_field")
        field_ref_map = dict(raw_field_refs) if isinstance(raw_field_refs, Mapping) else {}
        heading_field_names = {
            field_name
            for field_name in ("credit_agreement_identifier",)
            if skeleton.get(field_name) not in (None, "")
        }
        heading_refs = [
            {
                **ref,
                "field_name": field_name,
                "binding": "printed_account_anchor_heading",
                "binding_quality": "printed_account_anchor_heading",
            }
            for field_name in sorted(heading_field_names)
            for ref in ordinal_refs
        ]
        for heading_ref in heading_refs:
            field_ref_map.setdefault(str(heading_ref["field_name"]), []).append(heading_ref)
        local_field_refs = {
            str(field_name): [
                dict(ref) for ref in refs or () if isinstance(ref, Mapping) and int(ref.get("logical_page") or 0) > 0
            ]
            for field_name, refs in field_ref_map.items()
            if isinstance(refs, (list, tuple))
        }
        local_field_refs = {field_name: refs for field_name, refs in local_field_refs.items() if refs}
        account_ordinal_observations[account_family][ordinal] = {
            "account_id": account_id,
            "printed_fields": sorted(local_field_refs),
            "field_source_refs": local_field_refs,
            "source_refs": ordinal_refs,
        }
    loader = getattr(parse_result, "corrected_evidence_pages", None)
    evidence_pages = list(loader()) if callable(loader) else []
    exact_section_inventory = _registered_account_section_plane(
        parse_result,
        evidence_pages,
        _exact_account_table_cell_anchors(parse_result),
    )
    current_registered_population_observations = (
        _registered_account_population_observations(exact_section_inventory)
        if exact_section_inventory is not None
        else None
    )
    registered_population_observations = (
        _registered_account_population_lifecycle_observations(
            parse_result,
            current_registered_population_observations,
            exact_section_inventory,
        )
    )
    if registered_population_observations is not None:
        for account_family, observations in registered_population_observations.items():
            for ordinal, observation in observations.items():
                registered_owner = _exact_account_ordinal_owner_signature(
                    observation,
                    family=account_family,
                    ordinal=ordinal,
                )
                existing = account_ordinal_observations.get(account_family, {}).get(
                    ordinal
                )
                existing_owner = (
                    _exact_account_ordinal_owner_signature(
                        existing,
                        family=account_family,
                        ordinal=ordinal,
                    )
                    if existing is not None
                    else None
                )
                if registered_owner is None or (
                    existing is not None and existing_owner != registered_owner
                ):
                    continue
                family_sequences[account_family].add(ordinal)
                if existing is None:
                    account_ordinal_observations[account_family][ordinal] = deepcopy(
                        observation
                    )
    if exact_section_inventory is not None:
        for skeleton in account_skeletons:
            if not isinstance(skeleton, Mapping):
                continue
            account_family = str(skeleton.get("account_type") or "")
            if (
                account_family
                not in {
                    "non_revolving_loan",
                    "revolving_loan_subaccount",
                    "revolving_loan_account",
                    "credit_card",
                    "quasi_credit_card",
                }
                or skeleton.get("account_family_quality") != "exact"
                or skeleton.get("_printed_ordinal_status") != "printed_unreadable"
                or skeleton.get("category_sequence") is not None
                or not isinstance(skeleton.get("_canonical_segment"), Mapping)
                or skeleton["_canonical_segment"].get("ownership_basis") != "printed_anchor_to_next_anchor"
            ):
                continue
            refs = [
                ref
                for ref in skeleton.get("source_refs") or ()
                if isinstance(ref, Mapping)
                and ref.get("source") == "candidate_b_account_anchor"
                and int(ref.get("logical_page") or 0) > 0
                and _exact_geometry_bbox(ref.get("bbox")) is not None
                and isinstance(ref.get("evidence_ids"), (list, tuple))
                and any(str(value or "").strip() for value in ref["evidence_ids"])
            ]
            if len(refs) != 1:
                continue
            family_weak_unnumbered_anchors[account_family].add(
                json.dumps(
                    {
                        "logical_page": int(refs[0]["logical_page"]),
                        "source_page": int(refs[0].get("source_page") or 0),
                        "bbox": list(refs[0]["bbox"]),
                        "evidence_ids": sorted(str(value) for value in refs[0]["evidence_ids"] if value),
                    },
                    ensure_ascii=False,
                    sort_keys=True,
                    default=str,
                )
            )
    cross_page_order_resolved = _account_reading_order_resolution(parse_result, evidence_pages)[-1]
    pages = _account_ordered_pages(parse_result, evidence_pages)
    account_order_resolution = getattr(parse_result, "reading_order_resolution", None)
    global_account_order_authoritative = bool(
        isinstance(account_order_resolution, Mapping)
        and account_order_resolution.get("resolved") is True
        and account_order_resolution.get("authoritative") is True
        and cross_page_order_resolved
    )
    ledger_scan_pages = (
        pages
        if exact_section_inventory is None and global_account_order_authoritative
        else []
    )
    for page_offset, page in enumerate(ledger_scan_pages):
        logical_page = int(page.get("page") or 0)
        local_table_family, shared_revolving_carry = _account_page_table_evidence(
            parse_result,
            logical_page,
        )
        family_carry_allowed = bool(
            logical_page > 0
            and family_logical_page > 0
            and (
                logical_page == family_logical_page
                or (
                    cross_page_order_resolved
                    and _registered_account_pages_are_adjacent(
                        parse_result,
                        family_logical_page,
                        logical_page,
                    )
                )
            )
        )
        if page_offset > 0 and family and not family_carry_allowed:
            family = ""
            family_quality = ""
            family_logical_page = 0
            family_last_ordinal = 0
        preserve_revolving_family = _bounded_revolving_family_carry_over_generic_table(
            parse_result,
            page=page,
            active_family=family,
            active_family_quality=family_quality,
            active_family_logical_page=family_logical_page,
            active_family_last_ordinal=family_last_ordinal,
            local_table_family=local_table_family,
            cross_page_order_resolved=cross_page_order_resolved,
        )
        anchor_only_family_carry = bool(
            local_table_family is None
            and not preserve_revolving_family
            and not shared_revolving_carry
            and _bounded_anchor_only_family_carry(
                parse_result,
                page=page,
                active_family=family,
                active_family_quality=family_quality,
                active_family_logical_page=family_logical_page,
                active_family_last_ordinal=family_last_ordinal,
                cross_page_order_resolved=cross_page_order_resolved,
            )
        )
        verified_detail_family_carry = bool(
            local_table_family is None
            and not preserve_revolving_family
            and not shared_revolving_carry
            and not anchor_only_family_carry
            and _bounded_verified_detail_family_carry(
                parse_result,
                previous_page=(ledger_scan_pages[page_offset - 1] if page_offset > 0 else None),
                page=page,
                active_family=family,
                active_family_quality=family_quality,
                active_family_logical_page=family_logical_page,
                active_family_last_ordinal=family_last_ordinal,
                cross_page_order_resolved=cross_page_order_resolved,
            )
        )
        if local_table_family is not None and not preserve_revolving_family:
            family, family_quality = local_table_family
            family_logical_page = logical_page
            family_last_ordinal = 0
        elif preserve_revolving_family:
            family_logical_page = logical_page
        elif (
            family
            in {
                "revolving_loan_subaccount",
                "revolving_loan_account",
            }
            and shared_revolving_carry
        ):
            family_logical_page = logical_page
        elif anchor_only_family_carry:
            family_logical_page = logical_page
        elif verified_detail_family_carry:
            family_logical_page = logical_page
        elif local_table_family is None and not preserve_revolving_family:
            family = ""
            family_quality = ""
            family_logical_page = 0
            family_last_ordinal = 0
        source_page = int(page.get("source_page") or logical_page)
        for line_index, line in enumerate(page.get("lines") or []):
            if not isinstance(line, Mapping):
                continue
            raw_text = str(line.get("text") or line.get("content") or "")
            text = _compact(raw_text)
            if family and any(marker in text for marker in _ACCOUNT_SECTION_END):
                family = ""
                family_quality = ""
                family_logical_page = 0
                family_last_ordinal = 0
            heading = _account_family_from_heading(text)
            if heading is not None:
                family, family_quality = heading
                family_logical_page = logical_page
                family_last_ordinal = 0
            match = re.match(r"^(?:账户|业务)[（(]?(\d{1,3})(?:[）)]|\D|$)", text)
            if match and family:
                ordinal_value = int(match.group(1))
                family_sequences[family].add(ordinal_value)
                family_last_ordinal = ordinal_value
            anchor = _ACCOUNT_ANCHOR_RE.search(raw_text)
            if family and (match is not None or anchor is not None):
                family_logical_page = logical_page
                if anchor is not None and anchor.group(1):
                    family_last_ordinal = int(anchor.group(1))
            if anchor is None or not family:
                continue
            ordinal = int(anchor.group(1)) if anchor.group(1) else None
            heading_fields = _account_heading_fields(raw_text)
            agreement_identifier = _agreement_identifier_text(
                heading_fields.get("credit_agreement_identifier")
            )
            if ordinal is not None and ordinal > 0:
                if agreement_identifier:
                    family_numbered_identifiers[family].add(agreement_identifier)
                continue
            # An ambiguous ``循环贷账户`` heading cannot prove whether an
            # unnumbered anchor is R1 or R2.  It may still contribute numbered
            # population evidence above, but never a subtype-specific singleton.
            if family_quality != "exact":
                continue
            if agreement_identifier:
                family_unnumbered_identifiers[family].add(agreement_identifier)
                continue
            # A single exact source anchor is a bounded singleton witness.  Two
            # or more weak anchors are deliberately not counted: overlapping
            # corrected pages could otherwise manufacture extra accounts.
            evidence_ids = tuple(sorted(str(value) for value in line.get("evidence_ids") or ()))
            bbox = tuple(line.get("bbox") or ())
            weak_identity = json.dumps(
                {
                    "source_page": source_page,
                    "logical_page": logical_page,
                    "line_index": line_index,
                    "bbox": bbox,
                    "evidence_ids": evidence_ids,
                    "text": text,
                },
                ensure_ascii=False,
                sort_keys=True,
                default=str,
            )
            family_weak_unnumbered_anchors[family].add(weak_identity)

    # Agreement population comes only from the immutable numbered-heading
    # plane.  Canonical tables remain the sole authority for field values.
    agreement_census = _sealed_agreement_population_census(parse_result)
    agreement_sequence_values = list(
        (agreement_census or {}).get("sequences") or ()
    )
    agreement_sequences = set(agreement_sequence_values)
    agreement_ordinal_counts: Counter[int] = Counter(agreement_sequence_values)
    agreement_ordinal_observations: dict[int, dict[str, Any]] = deepcopy(
        (agreement_census or {}).get("ordinal_observations") or {}
    )
    agreement_refs: list[dict[str, Any]] = deepcopy(
        (agreement_census or {}).get("source_refs") or []
    )
    agreement_field_names = {
        "\u6388\u4fe1\u534f\u8bae\u6807\u8bc6": "account_identifier",
        "\u7ba1\u7406\u673a\u6784": "institution",
        "\u6388\u4fe1\u989d\u5ea6\u7528\u9014": "facility_type",
        "\u751f\u6548\u65e5\u671f": "effective_date",
        "\u5230\u671f\u65e5\u671f": "due_date",
        "\u6388\u4fe1\u989d\u5ea6": "total_limit",
        "\u6388\u4fe1\u9650\u989d": "credit_limit",
        "\u5df2\u7528\u989d\u5ea6": "used_limit",
        "\u6388\u4fe1\u9650\u989d\u7f16\u53f7": "limit_identifier",
        "\u5e01\u79cd": "currency",
    }
    # Field occurrences can be localized only through an explicit ordinal on
    # the same card plus exact, evidence-sealed label/value cells.  This uses
    # neither record encounter order nor broad record/table refs.
    try:
        from docmirror.plugins.credit_report.personal_detail_scanned.native_parser import (
            PBOCPersonalDetailNativeParser,
        )

        agreement_candidates = PBOCPersonalDetailNativeParser(parse_result).records("credit_lines")
    except (AttributeError, KeyError, TypeError, ValueError):
        agreement_candidates = []
    candidate_field_observations: defaultdict[
        int,
        list[tuple[str, dict[str, list[dict[str, Any]]]]],
    ] = defaultdict(list)
    for candidate in agreement_candidates:
        fields = getattr(candidate, "fields", None)
        refs_by_label = getattr(candidate, "source_refs_by_field", None)
        if not isinstance(fields, Mapping) or not isinstance(refs_by_label, Mapping):
            continue
        raw_sequence = fields.get("__printed_sequence")
        if not str(raw_sequence or "").isdigit():
            continue
        sequence = int(str(raw_sequence))
        if sequence <= 0 or agreement_ordinal_counts[sequence] != 1:
            continue
        sequence_refs = [
            dict(ref)
            for ref in refs_by_label.get("__printed_sequence") or ()
            if isinstance(ref, Mapping)
            and ref.get("binding") == "canonical_card_anchor"
            and _exact_geometry_bbox(ref.get("bbox")) is not None
            and isinstance(ref.get("evidence_ids"), (list, tuple))
            and any(str(value or "").strip() for value in ref["evidence_ids"])
        ]
        ordinal_observation = agreement_ordinal_observations.get(sequence)
        if len(sequence_refs) != 1 or not ordinal_observation:
            continue
        ordinal_refs = ordinal_observation.get("source_refs") or ()
        if not any(
            int(ref.get("logical_page") or 0) == int(sequence_refs[0].get("logical_page") or 0)
            and int(ref.get("source_page") or 0) == int(sequence_refs[0].get("source_page") or 0)
            and set(str(value) for value in ref.get("evidence_ids") or ())
            & set(str(value) for value in sequence_refs[0].get("evidence_ids") or ())
            for ref in ordinal_refs
            if isinstance(ref, Mapping)
        ):
            continue
        local_field_refs: dict[str, list[dict[str, Any]]] = {}
        owner_markers: set[str] = set()
        for label, field_name in agreement_field_names.items():
            raw_value = fields.get(label)
            if raw_value in (None, "") or _agreement_source_absent(raw_value):
                continue
            probe = {
                "source_refs_by_field": {
                    field_name: [
                        {**dict(ref), "field_name": field_name}
                        for ref in refs_by_label.get(label) or ()
                        if isinstance(ref, Mapping)
                    ]
                }
            }
            exact_refs = _exact_agreement_field_refs(probe, field_name)
            if not exact_refs:
                continue
            local_field_refs[field_name] = exact_refs
            owner_markers.update(
                f"{ref.get('source')}:{ref.get('logical_page')}:{ref.get('source_page')}:{ref.get('table_id') or ''}"
                for ref in exact_refs
            )
        if local_field_refs:
            candidate_field_observations[sequence].append((json.dumps(sorted(owner_markers)), local_field_refs))

    for sequence, candidates in candidate_field_observations.items():
        owners = {owner for owner, _refs in candidates}
        if len(owners) != 1:
            continue
        observation = agreement_ordinal_observations.get(sequence)
        if observation is None:
            continue
        field_ref_candidates: defaultdict[str, list[list[dict[str, Any]]]] = defaultdict(list)
        for _owner, local_refs in candidates:
            for field_name, refs in local_refs.items():
                field_ref_candidates[field_name].append(refs)
        field_refs: dict[str, list[dict[str, Any]]] = {}
        for field_name, ref_groups in field_ref_candidates.items():
            distinct = {json.dumps(refs, ensure_ascii=False, sort_keys=True, default=str) for refs in ref_groups}
            if len(distinct) == 1:
                field_refs[field_name] = ref_groups[0]
        if not field_refs:
            continue
        observation["printed_fields"] = sorted(field_refs)
        observation["field_source_refs"] = field_refs

    agreement_endpoint, agreement_outliers = _credible_sequence_endpoint(agreement_sequences)
    credible_agreement_sequences = agreement_sequences - set(agreement_outliers)
    agreement_ordinal_observations = {
        sequence: observation
        for sequence, observation in agreement_ordinal_observations.items()
        if sequence in credible_agreement_sequences and agreement_ordinal_counts[sequence] == 1
    }

    raw_account_anchor_census = _sealed_raw_account_population_census(parse_result)
    admitted_raw_anchor_sequences: dict[str, list[int]] = {}
    admitted_raw_anchor_observations: dict[str, dict[int, dict[str, Any]]] = {}
    raw_anchor_conflicts: dict[str, list[int]] = {}
    raw_sequences = (
        raw_account_anchor_census.get("sequences")
        if isinstance(raw_account_anchor_census, Mapping)
        else None
    )
    raw_observations = (
        raw_account_anchor_census.get("ordinal_observations")
        if isinstance(raw_account_anchor_census, Mapping)
        else None
    )
    if isinstance(raw_sequences, Mapping) and isinstance(raw_observations, Mapping):
        for account_family, raw_family_values in raw_sequences.items():
            family_name = str(account_family or "")
            family_observations = raw_observations.get(account_family)
            if not family_name or not isinstance(family_observations, Mapping):
                continue
            values = [
                int(value)
                for value in raw_family_values or ()
                if isinstance(value, int) and not isinstance(value, bool) and value > 0
            ]
            # This census is built from the context-owned immutable source
            # snapshot and has already proved one closed, dense family
            # envelope.  Account skeletons are a later, repairable decoding
            # plane: complete-page re-OCR legitimately changes both evidence
            # IDs and line geometry for the same printed heading.  A derived
            # owner therefore cannot veto or truncate the frozen source
            # population merely because its observation identity differs.
            #
            # Revalidate every raw owner here, then replace the family
            # population plane wholesale.  Business-field refs from a derived
            # observation are retained only when its immutable owner is
            # literally concordant; otherwise the raw row remains
            # population-only and source_projection emits a localized record
            # omission without publishing any guessed values.
            conflicts: list[int] = []
            admitted_family_observations: dict[int, dict[str, Any]] = {}
            raw_family_population_observations: dict[int, dict[str, Any]] = {}
            for ordinal in values:
                raw_observation = family_observations.get(
                    ordinal,
                    family_observations.get(str(ordinal)),
                )
                raw_owner = _exact_account_ordinal_owner_signature(
                    raw_observation,
                    family=family_name,
                    ordinal=ordinal,
                )
                existing = account_ordinal_observations.get(family_name, {}).get(ordinal)
                existing_owner = (
                    _exact_account_ordinal_owner_signature(
                        existing,
                        family=family_name,
                        ordinal=ordinal,
                    )
                    if existing is not None
                    else None
                )
                if raw_owner is None:
                    conflicts.append(ordinal)
                    continue
                admitted_observation = deepcopy(raw_observation)
                raw_family_population_observations[ordinal] = deepcopy(
                    raw_observation
                )
                if (
                    existing_owner == raw_owner
                    and isinstance(existing, Mapping)
                    and existing.get("account_id")
                    == f"credit_account:{family_name}:{ordinal}"
                ):
                    existing_field_refs = existing.get("field_source_refs")
                    if isinstance(existing_field_refs, Mapping):
                        admitted_observation["field_source_refs"] = deepcopy(
                            dict(existing_field_refs)
                        )
                    existing_printed_fields = existing.get("printed_fields")
                    if isinstance(existing_printed_fields, (list, tuple)):
                        admitted_observation["printed_fields"] = sorted(
                            {
                                str(field_name)
                                for field_name in existing_printed_fields
                                if str(field_name)
                            }
                        )
                admitted_family_observations[ordinal] = admitted_observation
            if (
                len(values) != len(set(values))
                or values != list(range(1, len(values) + 1))
            ):
                conflicts.extend(values)
            if conflicts:
                raw_anchor_conflicts[family_name] = sorted(set(conflicts))
                continue

            admitted_raw_anchor_sequences[family_name] = values
            admitted_raw_anchor_observations[family_name] = deepcopy(
                raw_family_population_observations
            )
            family_sequences[family_name] = set(values)
            account_ordinal_observations[family_name] = deepcopy(
                admitted_family_observations
            )

    endpoints: dict[str, int] = {}
    account_sequence_outliers: dict[str, list[int]] = {}
    exact_source_high_tail_endpoints: dict[str, int] = {}
    for account_family, values in family_sequences.items():
        baseline_endpoint, _baseline_outliers = _credible_sequence_endpoint(values)
        endpoint, outliers = _exact_source_supported_account_sequence_endpoint(
            parse_result,
            values,
            family=account_family,
            observations=account_ordinal_observations.get(account_family, {}),
        )
        if endpoint is not None:
            endpoints[account_family] = endpoint
            if endpoint > int(baseline_endpoint or 0):
                exact_source_high_tail_endpoints[account_family] = endpoint
        if outliers:
            account_sequence_outliers[account_family] = outliers

    family_source_populations: dict[str, int] = {}
    unnumbered_anchor_counts: dict[str, int] = {}
    account_families = set(endpoints) | set(family_unnumbered_identifiers) | set(family_weak_unnumbered_anchors)
    for account_family in sorted(account_families):
        endpoint = int(endpoints.get(account_family) or 0)
        # A strong identifier seen on a numbered anchor proves that a repeated
        # unnumbered observation is the same account, not an additional row.
        strong_unnumbered = family_unnumbered_identifiers.get(account_family, set()) - family_numbered_identifiers.get(
            account_family, set()
        )
        unnumbered_count = len(strong_unnumbered)
        if endpoint == 0 and unnumbered_count == 0:
            weak_anchors = family_weak_unnumbered_anchors.get(account_family, set())
            if len(weak_anchors) == 1:
                unnumbered_count = 1
        # Mixing numbered and unnumbered observations within one family is not
        # sufficient proof that the latter are additional rows.  Use the dense
        # printed endpoint in that case; exact unnumbered populations are used
        # only for a family with no credible numbered sequence.
        population = endpoint or unnumbered_count
        if population > 0:
            family_source_populations[account_family] = population
        if endpoint == 0 and unnumbered_count > 0:
            unnumbered_anchor_counts[account_family] = unnumbered_count

    account_raw_physical_coverage = _raw_physical_account_source_coverage(
        parse_result
    )
    admitted_raw_anchor_endpoints = {
        account_family: max(values)
        for account_family, values in admitted_raw_anchor_sequences.items()
        if values
    }
    inquiry_coverage = _inquiry_source_coverage(parse_result)
    # A field label is not a record identity.  Only the dense, sealed ordinal
    # census may establish an agreement population denominator.
    agreement_expected = agreement_endpoint
    source_refs: dict[str, list[dict[str, Any]]] = {}
    if isinstance(raw_profile_census, Mapping) and isinstance(
        raw_profile_census.get("source_refs"), Mapping
    ):
        for target, refs in raw_profile_census["source_refs"].items():
            if target in _RAW_PROFILE_DATASET_CONTRACTS and isinstance(
                refs, (list, tuple)
            ):
                source_refs[target] = [
                    dict(ref) for ref in refs if isinstance(ref, Mapping)
                ]
    if agreement_refs:
        source_refs["credit_lines"] = agreement_refs
    if inquiry_coverage.get("source_refs"):
        source_refs["inquiry_records"] = list(inquiry_coverage["source_refs"])
    return {
        "sequence_endpoints": {name: max(values) for name, values in sequences.items() if values},
        **(
            {
                "sequence_observed_sequences": {
                    name: sorted(values) for name, values in sorted(sequences.items()) if values
                }
            }
            if any(sequences.values())
            else {}
        ),
        **({"sequence_outliers": sequence_outliers} if sequence_outliers else {}),
        **(
            {
                "sequence_ordinal_observations": {
                    name: {
                        str(sequence): {
                            **observation,
                            "printed_fields": sorted(observation.get("printed_fields") or ()),
                        }
                        for sequence, observation in sorted(observations.items())
                        if observation.get("source_refs")
                    }
                    for name, observations in sorted(sequence_ordinal_observations.items())
                    if any(observation.get("source_refs") for observation in observations.values())
                }
            }
            if sequence_ordinal_observations
            else {}
        ),
        **({"credit_accounts": sum(family_source_populations.values())} if family_source_populations else {}),
        **({"credit_agreements": agreement_expected} if agreement_expected else {}),
        **({"credit_agreement_sequence_endpoint": agreement_endpoint} if agreement_endpoint else {}),
        **(
            {"credit_agreement_observed_sequences": sorted(credible_agreement_sequences)}
            if credible_agreement_sequences
            else {}
        ),
        **(
            {
                "credit_agreement_ordinal_observations": {
                    str(sequence): observation
                    for sequence, observation in sorted(agreement_ordinal_observations.items())
                }
            }
            if agreement_ordinal_observations
            else {}
        ),
        **({"credit_agreement_sequence_outliers": agreement_outliers} if agreement_outliers else {}),
        **(
            {"inquiry_records": int(inquiry_coverage["expected_row_count"])}
            if inquiry_coverage.get("expected_row_count")
            else {}
        ),
        **(
            {"inquiry_sequence_endpoints": dict(inquiry_coverage["sequence_endpoints"])}
            if inquiry_coverage.get("sequence_endpoints")
            else {}
        ),
        **(
            {"inquiry_observed_sequences": dict(inquiry_coverage["observed_sequences"])}
            if inquiry_coverage.get("observed_sequences")
            else {}
        ),
        **(
            {"inquiry_ordinal_observations": dict(inquiry_coverage["ordinal_observations"])}
            if inquiry_coverage.get("ordinal_observations")
            else {}
        ),
        **(
            {"inquiry_physical_field_observations": list(inquiry_coverage["physical_field_observations"])}
            if inquiry_coverage.get("physical_field_observations")
            else {}
        ),
        **(
            {"inquiry_raw_physical_positions": list(inquiry_coverage["raw_physical_positions"])}
            if inquiry_coverage.get("raw_physical_positions")
            else {}
        ),
        **(
            {"inquiry_sequence_outliers": dict(inquiry_coverage["sequence_outliers"])}
            if inquiry_coverage.get("sequence_outliers")
            else {}
        ),
        **(
            {"inquiry_unclassified_sequence_endpoints": list(inquiry_coverage["unclassified_sequence_endpoints"])}
            if inquiry_coverage.get("unclassified_sequence_endpoints")
            else {}
        ),
        **(
            {"account_raw_physical_count": int(account_raw_physical_coverage["count"])}
            if account_raw_physical_coverage.get("count")
            else {}
        ),
        **(
            {"account_raw_physical_observations": list(account_raw_physical_coverage["observations"])}
            if account_raw_physical_coverage.get("observations")
            else {}
        ),
        **(
            {"account_raw_anchor_sequence_endpoints": dict(admitted_raw_anchor_endpoints)}
            if admitted_raw_anchor_endpoints
            else {}
        ),
        **(
            {
                "account_raw_anchor_observed_sequences": {
                    account_family: list(values)
                    for account_family, values in sorted(admitted_raw_anchor_sequences.items())
                }
            }
            if admitted_raw_anchor_sequences
            else {}
        ),
        **(
            {
                "account_raw_anchor_ordinal_observations": {
                    account_family: {str(ordinal): observation for ordinal, observation in sorted(observations.items())}
                    for account_family, observations in sorted(admitted_raw_anchor_observations.items())
                    if observations
                }
            }
            if admitted_raw_anchor_observations
            else {}
        ),
        **({"account_raw_anchor_ordinal_conflicts": raw_anchor_conflicts} if raw_anchor_conflicts else {}),
        **({"account_family_endpoints": dict(endpoints)} if endpoints else {}),
        **(
            {
                "account_family_anchor_inventory_sequences": {
                    account_family: sorted(ordinals)
                    for account_family, ordinals in sorted(anchor_inventory_sequences.items())
                }
            }
            if anchor_inventory_sequences
            else {}
        ),
        **(
            {
                "account_family_ordinal_observations": {
                    account_family: {str(ordinal): observation for ordinal, observation in sorted(observations.items())}
                    for account_family, observations in sorted(account_ordinal_observations.items())
                    if observations
                }
            }
            if account_ordinal_observations
            else {}
        ),
        **({"account_family_source_populations": family_source_populations} if family_source_populations else {}),
        **({"account_family_unnumbered_anchor_counts": unnumbered_anchor_counts} if unnumbered_anchor_counts else {}),
        **(
            {"account_family_exact_source_high_tail_endpoints": exact_source_high_tail_endpoints}
            if exact_source_high_tail_endpoints
            else {}
        ),
        **({"account_family_sequence_outliers": account_sequence_outliers} if account_sequence_outliers else {}),
        **({"source_refs": source_refs} if source_refs else {}),
    }


def reconcile_candidate_b_account_sequence_issues(
    parse_result: Any,
    ledger: Mapping[str, Any],
    accounts: Iterable[Mapping[str, Any]],
) -> dict[str, Any]:
    """Replace provisional family gaps with exact final source-ledger gaps.

    Account extraction must report uncertainty early enough to drive the one
    allowed repair pass, so its first issue uses the generic density heuristic.
    Final publication has stronger evidence: the frozen source census has then
    authenticated every ordinal and any sparse high-tail endpoint.  Reconcile
    only those fully closed families and retain all other provisional issues.
    """

    from docmirror.plugins.credit_report.personal_detail_scanned.extraction_issues import (
        make_issue,
    )

    families = frozenset(
        {
            "non_revolving_loan",
            "revolving_loan_subaccount",
            "revolving_loan_account",
            "credit_card",
            "quasi_credit_card",
        }
    )
    endpoints = ledger.get("account_family_endpoints")
    raw_observations = ledger.get("account_family_ordinal_observations")
    anchor_sequences = ledger.get("account_family_anchor_inventory_sequences")
    raw_outliers = ledger.get("account_family_sequence_outliers")
    if (
        not isinstance(endpoints, Mapping)
        or not isinstance(raw_observations, Mapping)
        or not isinstance(anchor_sequences, Mapping)
    ):
        return {"reconciled_families": [], "localized_missing_identities": []}

    emitted_by_family: defaultdict[str, list[Mapping[str, Any]]] = defaultdict(list)
    for account in accounts:
        if not isinstance(account, Mapping):
            continue
        family = str(account.get("account_type") or "")
        if family in families:
            emitted_by_family[family].append(account)

    replacements: dict[str, dict[str, Any] | None] = {}
    localized_missing: set[str] = set()
    for family in sorted(families):
        endpoint = endpoints.get(family)
        family_observations = raw_observations.get(family)
        source_sequences = anchor_sequences.get(family)
        if (
            not isinstance(endpoint, int)
            or isinstance(endpoint, bool)
            or endpoint <= 0
            or not isinstance(family_observations, Mapping)
            or not isinstance(source_sequences, (list, tuple))
            or any(
                not isinstance(value, int)
                or isinstance(value, bool)
                or value <= 0
                for value in source_sequences
            )
            or list(source_sequences) != sorted(set(source_sequences))
            or endpoint not in source_sequences
        ):
            continue

        observations: dict[int, Mapping[str, Any]] = {}
        malformed_observation = False
        for raw_ordinal, observation in family_observations.items():
            try:
                ordinal = int(raw_ordinal)
            except (TypeError, ValueError):
                malformed_observation = True
                break
            if (
                isinstance(raw_ordinal, bool)
                or ordinal <= 0
                or not isinstance(observation, Mapping)
                or ordinal in observations
            ):
                malformed_observation = True
                break
            observations[ordinal] = observation
        if malformed_observation or set(observations) != set(source_sequences):
            continue

        refs: list[dict[str, Any]] = []
        physical_owners: set[tuple[int, tuple[float, float, float, float]]] = set()
        evidence_owners: set[str] = set()
        exact_source_family = True
        for ordinal in source_sequences:
            observation = observations[ordinal]
            owner = _exact_account_ordinal_owner_signature(
                observation,
                family=family,
                ordinal=ordinal,
            )
            if owner is None:
                exact_source_family = False
                break
            _logical_page, source_page, bbox, evidence_ids = owner
            physical_owner = (source_page, bbox)
            if (
                physical_owner in physical_owners
                or evidence_owners.intersection(evidence_ids)
            ):
                exact_source_family = False
                break
            physical_owners.add(physical_owner)
            evidence_owners.update(evidence_ids)
            ordinal_refs = [
                dict(ref)
                for ref in observation.get("source_refs") or ()
                if isinstance(ref, Mapping)
                and str(ref.get("source") or "") == "candidate_b_account_anchor"
            ]
            if len(ordinal_refs) != 1:
                exact_source_family = False
                break
            refs.extend(ordinal_refs)
        if not exact_source_family:
            continue

        emitted_sequences: list[int] = []
        unresolved_accounts: list[Mapping[str, Any]] = []
        duplicate_emitted = False
        for account in emitted_by_family.get(family, ()):
            ordinal = account.get("category_sequence")
            if (
                not isinstance(ordinal, int)
                or isinstance(ordinal, bool)
                or ordinal <= 0
                or account.get("account_id")
                != f"credit_account:{family}:{ordinal}"
            ):
                unresolved_accounts.append(account)
                continue
            if ordinal in emitted_sequences:
                duplicate_emitted = True
                break
            emitted_sequences.append(ordinal)
        if duplicate_emitted:
            continue
        emitted_sequences.sort()
        missing = sorted(
            set(range(1, endpoint + 1)).difference(emitted_sequences)
        )
        outliers = (
            raw_outliers.get(family, [])
            if isinstance(raw_outliers, Mapping)
            else []
        )
        if not isinstance(outliers, (list, tuple)) or any(
            not isinstance(value, int)
            or isinstance(value, bool)
            or value <= 0
            for value in outliers
        ):
            continue
        outliers = sorted(set(outliers))
        replacements[family] = None
        if not missing and not outliers and not unresolved_accounts:
            continue
        replacements[family] = make_issue(
            category="schema_incompleteness",
            issue_code="candidate_b_account_sequence_gap",
            message=(
                "The authenticated source account-family endpoint exceeds the "
                "uniquely emitted canonical ordinals; missing records were not invented."
            ),
            parser_stage="candidate_b_account_source_ledger_reconciliation",
            target_dataset="credit_accounts",
            observed_value={
                "account_type": family,
                "observed_category_sequences": emitted_sequences,
            },
            candidate_value={
                "missing_category_sequences": missing,
                "outlier_category_sequences": outliers,
                "authoritative_family_endpoint": endpoint,
                "source_supported_category_sequences": list(source_sequences),
                "unresolved_printed_ordinal_count": len(unresolved_accounts),
                "provisional_account_ids": sorted(
                    str(account.get("account_id") or "")
                    for account in unresolved_accounts
                    if account.get("account_id")
                ),
            },
            source_refs=refs,
            reason_codes=(
                "independent_source_ledger",
                "authenticated_account_family_endpoint",
                "exact_printed_ordinal_anchors",
                "missing_records_not_invented",
                "business_population_uncertain",
            ),
        )
        localized_missing.update(
            f"credit_account:{family}:{ordinal}" for ordinal in missing
        )

    if not replacements:
        return {"reconciled_families": [], "localized_missing_identities": []}
    existing = getattr(parse_result, "_personal_detail_extraction_issues", None)
    rows = list(existing) if isinstance(existing, list) else []
    reconciled_rows: list[dict[str, Any]] = []
    installed: set[str] = set()
    for row in rows:
        observed = row.get("observed_value") if isinstance(row, Mapping) else None
        family = (
            str(observed.get("account_type") or "")
            if isinstance(observed, Mapping)
            else ""
        )
        if (
            isinstance(row, Mapping)
            and row.get("issue_code") == "candidate_b_account_sequence_gap"
            and family in replacements
        ):
            replacement = replacements[family]
            if replacement is not None and family not in installed:
                reconciled_rows.append(deepcopy(replacement))
                installed.add(family)
            continue
        if isinstance(row, Mapping):
            reconciled_rows.append(deepcopy(dict(row)))
    for family in sorted(replacements):
        replacement = replacements[family]
        if replacement is not None and family not in installed:
            reconciled_rows.append(deepcopy(replacement))
    setattr(parse_result, "_personal_detail_extraction_issues", reconciled_rows)
    return {
        "reconciled_families": sorted(replacements),
        "localized_missing_identities": sorted(localized_missing),
    }


def _record_pre_repair_source_gaps(
    parse_result: Any,
    datasets: Mapping[str, Any],
) -> dict[str, Any]:
    """Publish source-population gaps early enough to select repair pages.

    The final completeness pass remains authoritative.  This early pass exists
    solely so a record that was never instantiated can still trigger the one
    allowed page repair instead of disappearing silently.
    """
    from docmirror.plugins.credit_report.personal_detail_scanned.extraction_issues import (
        make_issue,
        record_issue,
    )

    ledger = _source_completeness_ledger(parse_result)
    source_refs = ledger.get("source_refs") if isinstance(ledger.get("source_refs"), Mapping) else {}
    endpoints = ledger.get("sequence_endpoints")
    observed_sequences = ledger.get("sequence_observed_sequences")
    all_observations = ledger.get("sequence_ordinal_observations")
    if (
        isinstance(endpoints, Mapping)
        and isinstance(observed_sequences, Mapping)
        and isinstance(all_observations, Mapping)
    ):
        for dataset_name, contract in _RAW_PROFILE_DATASET_CONTRACTS.items():
            endpoint = _strict_raw_profile_page_id(endpoints.get(dataset_name))
            raw_sequences = observed_sequences.get(dataset_name)
            raw_observations = all_observations.get(dataset_name)
            if (
                endpoint is None
                or not isinstance(raw_sequences, (list, tuple))
                or any(
                    not isinstance(value, int)
                    or isinstance(value, bool)
                    for value in raw_sequences
                )
                or list(raw_sequences) != list(range(1, endpoint + 1))
                or not isinstance(raw_observations, Mapping)
            ):
                continue
            observations: dict[int, Mapping[str, Any]] = {}
            observations_valid = True
            for raw_ordinal, observation in raw_observations.items():
                if (
                    isinstance(raw_ordinal, int)
                    and not isinstance(raw_ordinal, bool)
                    and raw_ordinal > 0
                ):
                    ordinal = raw_ordinal
                elif isinstance(raw_ordinal, str) and re.fullmatch(
                    r"[1-9]\d*", raw_ordinal
                ):
                    ordinal = int(raw_ordinal)
                else:
                    observations_valid = False
                    break
                if ordinal in observations or not isinstance(observation, Mapping):
                    observations_valid = False
                    break
                observations[ordinal] = observation
            if not observations_valid or set(observations) != set(
                range(1, endpoint + 1)
            ):
                continue
            exact_refs: dict[int, dict[str, Any]] = {}
            for ordinal, observation in observations.items():
                ref = _exact_raw_profile_sequence_ref(
                    observation,
                    dataset=dataset_name,
                    ordinal=ordinal,
                )
                if ref is None:
                    exact_refs = {}
                    break
                exact_refs[ordinal] = ref
            if len(exact_refs) != endpoint:
                continue

            emitted_ordinals: set[int] = set()
            id_field = str(contract["id_field"])
            id_prefix = str(contract["id_prefix"])
            for row in datasets.get(dataset_name) or ():
                if not isinstance(row, Mapping):
                    continue
                normalized = row.get("normalized")
                values = normalized if isinstance(normalized, Mapping) else row
                sequence = values.get("sequence")
                if (
                    not isinstance(sequence, int)
                    or isinstance(sequence, bool)
                    or sequence <= 0
                    or values.get(id_field) != stable_record_id(id_prefix, sequence)
                ):
                    continue
                emitted_ordinals.add(sequence)
            for ordinal in range(1, endpoint + 1):
                if ordinal in emitted_ordinals:
                    continue
                target_id = stable_record_id(id_prefix, ordinal)
                record_issue(
                    parse_result,
                    make_issue(
                        category="page_continuation",
                        issue_code="source_sequence_or_count_gap",
                        message=(
                            "An immutable PBOC profile-table ordinal was not "
                            "instantiated by the first schema pass."
                        ),
                        parser_stage="candidate_b_pre_repair_source_coverage",
                        target_dataset=dataset_name,
                        target_record_id=target_id,
                        field_name=id_field,
                        observed_value={
                            "source_sequence": ordinal,
                            "source_field_observed": True,
                        },
                        candidate_value={
                            "source_expected_row_count": endpoint,
                        },
                        source_refs=(exact_refs[ordinal],),
                        reason_codes=(
                            "independent_source_ledger",
                            "exact_sequence_ordinal",
                            "ordinal_local_source_evidence",
                            "schema_triggered_page_repair_eligible",
                            "no_missing_row_invented",
                        ),
                    ),
                )
    checks = (
        ("credit_lines", "credit_agreements"),
        ("inquiry_records", "inquiry_records"),
    )
    for dataset_name, ledger_name in checks:
        expected = ledger.get(ledger_name)
        if not isinstance(expected, int) or isinstance(expected, bool) or expected <= 0:
            continue
        observed = sum(isinstance(row, Mapping) for row in datasets.get(dataset_name) or ())
        if observed >= expected:
            continue
        record_issue(
            parse_result,
            make_issue(
                category="page_continuation",
                issue_code="source_sequence_or_count_gap",
                message=(
                    "Independent canonical section evidence contains more records than the first schema pass; "
                    "the affected pages must be repaired before completeness is decided."
                ),
                parser_stage="candidate_b_pre_repair_source_coverage",
                target_dataset=dataset_name,
                observed_value={"observed_row_count": observed},
                candidate_value={
                    "source_expected_row_count": expected,
                    **(
                        {
                            "source_sequence_endpoints": ledger.get("inquiry_sequence_endpoints", {}),
                            "unclassified_sequence_endpoints": ledger.get(
                                "inquiry_unclassified_sequence_endpoints", []
                            ),
                        }
                        if dataset_name == "inquiry_records"
                        else {}
                    ),
                },
                source_refs=(source_refs.get(dataset_name) or ()),
                reason_codes=(
                    "independent_source_ledger",
                    "missing_business_records",
                    "schema_triggered_page_repair_eligible",
                    "no_missing_row_invented",
                ),
            ),
        )
    return ledger


def _canonical_exact_phone(value: Any, *, mobile: bool) -> str | None:
    """Canonicalize only a complete, finite phone presentation grammar."""

    raw = _clean(value)
    if mobile:
        match = re.fullmatch(
            r"(?:(?:\+?86|0086)[ -]?)?(1[3-9]\d[ -]?\d{4}[ -]?\d{4})",
            raw,
        )
        if match is None:
            return None
        return re.sub(r"[ -]", "", match.group(1))

    return _canonical_nonmobile_phone(raw)


def _materialize_mobile_record(
    parse_result: Any,
    records: dict[int, dict[str, Any]],
    *,
    page: Any,
    table: Any,
    row: tuple[str, ...],
    row_index: int,
    sequence: int,
    values: Mapping[str, str],
    columns: Mapping[str, int],
    field_refs: Mapping[str, Mapping[str, Any]] | None = None,
) -> None:
    mobile_id = stable_record_id("personal_mobile_phone", sequence)
    record = records.setdefault(
        sequence,
        {
            "record_id": mobile_id,
            "mobile_phone_record_id": mobile_id,
            "sequence": sequence,
            "source": "native_personal_detail_profile_table",
            "source_refs": [],
            "confidence": 1.0,
        },
    )
    record["source_refs"].append(_source_ref(page, table, row=row_index))
    sequence_ref = (field_refs or {}).get("sequence")
    if sequence_ref is not None:
        _merge_exact_observation(
            parse_result,
            record,
            dataset="mobile_phone_records",
            target_record_id=mobile_id,
            field_name="sequence",
            value=sequence,
            raw=str(sequence),
            source_ref=sequence_ref,
            parser_stage="candidate_b_mobile_exact_merged_lattice",
        )
    raw_phone = _clean(values.get("mobile_phone"))
    canonical_phone = _canonical_exact_phone(raw_phone, mobile=True)
    phone_column = int(columns.get("mobile_phone", 0) or 0)
    phone_ref = dict(
        (field_refs or {}).get("mobile_phone") or _source_ref(page, table, row=row_index, column=phone_column)
    )
    if not raw_phone:
        _report_required_row_failure(
            parse_result,
            issue_code="candidate_b_mobile_row_unresolved",
            dataset="mobile_phone_records",
            sequence=sequence,
            field_name="mobile_phone",
            row=row,
            page=page,
            table=table,
            row_index=row_index,
            target_record_id=mobile_id,
        )
    elif raw_phone == "--":
        _mark_source_absent(record, "mobile_phone", raw_phone)
    elif canonical_phone is None:
        _reject_exact_observation(
            parse_result,
            record,
            dataset="mobile_phone_records",
            target_record_id=mobile_id,
            field_name="mobile_phone",
            raw=raw_phone,
            source_ref=phone_ref,
            parser_stage="candidate_b_mobile_canonical_slots",
        )
    else:
        _merge_exact_observation(
            parse_result,
            record,
            dataset="mobile_phone_records",
            target_record_id=mobile_id,
            field_name="mobile_phone",
            value=canonical_phone,
            raw=raw_phone,
            source_ref=phone_ref,
            parser_stage="candidate_b_mobile_canonical_slots",
        )

    raw_updated = _clean(values.get("information_updated_date"))
    updated_column = int(columns.get("information_updated_date", 0) or 0)
    updated_ref = dict(
        (field_refs or {}).get("information_updated_date")
        or _source_ref(page, table, row=row_index, column=updated_column)
    )
    if raw_updated and not is_explicit_source_absence(raw_updated):
        _merge_canonical_date_observation(
            parse_result,
            record,
            dataset="mobile_phone_records",
            target_record_id=mobile_id,
            field_name="information_updated_date",
            raw=raw_updated,
            source_ref=updated_ref,
            parser_stage="candidate_b_mobile_canonical_slots",
        )
    elif is_explicit_source_absence(raw_updated):
        _mark_source_absent(record, "information_updated_date", raw_updated)
    else:
        _report_required_row_failure(
            parse_result,
            issue_code="candidate_b_mobile_row_unresolved",
            dataset="mobile_phone_records",
            sequence=sequence,
            field_name="information_updated_date",
            row=row,
            page=page,
            table=table,
            row_index=row_index,
            target_record_id=mobile_id,
        )

    provider = _clean(values.get("data_provider"))
    provider_column = int(columns.get("data_provider", 0) or 0)
    provider_ref = dict(
        (field_refs or {}).get("data_provider") or _source_ref(page, table, row=row_index, column=provider_column)
    )
    if provider == "--":
        _mark_source_absent(record, "data_provider", provider)
    elif provider:
        normalized_provider = _strict_whole_cell_business_name(provider, "institution_name")
        glyph_alternate = _profile_exact_one_glyph_institution_alternate(parse_result, provider, source_table=table)
        if normalized_provider is None or glyph_alternate is not None:
            _reject_exact_observation(
                parse_result,
                record,
                dataset="mobile_phone_records",
                target_record_id=mobile_id,
                field_name="data_provider",
                raw=provider,
                source_ref=provider_ref,
                parser_stage="candidate_b_mobile_canonical_slots",
            )
        else:
            _merge_exact_observation(
                parse_result,
                record,
                dataset="mobile_phone_records",
                target_record_id=mobile_id,
                field_name="data_provider",
                value=normalized_provider,
                raw=provider,
                source_ref=provider_ref,
                parser_stage="candidate_b_mobile_canonical_slots",
            )
    else:
        _report_required_row_failure(
            parse_result,
            issue_code="candidate_b_mobile_row_unresolved",
            dataset="mobile_phone_records",
            sequence=sequence,
            field_name="data_provider",
            row=row,
            page=page,
            table=table,
            row_index=row_index,
            target_record_id=mobile_id,
        )


def _profile_token_ref(
    page: Any,
    table: Any,
    *,
    row: int,
    column: int,
    token: tuple[str, tuple[float, float, float, float], str],
) -> dict[str, Any]:
    ref = _profile_source_ref(page, table, row=row, column=column)
    ref.update(
        {
            "source": "native_detail_table_token",
            "bbox": list(token[1]),
            "evidence_ids": [token[2]],
            "geometry_scope": "token",
            "binding": "canonical_field_token",
            "binding_quality": "exact_token_in_canonical_span",
        }
    )
    return ref


_PROFILE_CANONICAL_TEMPLATE_ID = "report_header_and_identity"


def _profile_table_source_owner(page: Any, table: Any) -> tuple[int, int] | None:
    """Return the immutable source owner for one canonical profile table.

    Collapsed profile cells are not self-identifying.  They are eligible only
    after canonical assembly has bound the page and table to the PBOC
    report-header/profile template and retained both source-page axes.
    """

    metadata = getattr(table, "metadata", None)
    if (
        not isinstance(metadata, Mapping)
        or str(getattr(page, "canonical_template_id", "") or "") != _PROFILE_CANONICAL_TEMPLATE_ID
        or str(metadata.get("canonical_template_id") or "") != _PROFILE_CANONICAL_TEMPLATE_ID
        or not str(getattr(table, "table_id", "") or "")
    ):
        return None
    source_logical_page = metadata.get("source_logical_page")
    source_page = metadata.get("source_page")
    if (
        not isinstance(source_logical_page, int)
        or isinstance(source_logical_page, bool)
        or source_logical_page <= 0
        or not isinstance(source_page, int)
        or isinstance(source_page, bool)
        or source_page <= 0
    ):
        return None
    fragment_pages = getattr(page, "canonical_fragment_logical_pages", None)
    if (
        not isinstance(fragment_pages, (list, tuple))
        or not fragment_pages
        or any(
            not isinstance(value, int) or isinstance(value, bool) or value <= 0
            for value in fragment_pages
        )
        or len(set(fragment_pages)) != len(fragment_pages)
        or source_logical_page not in fragment_pages
    ):
        return None
    coordinate_transform = getattr(page, "coordinate_transform", None)
    source_page_numbers = (
        coordinate_transform.get("source_page_numbers") if isinstance(coordinate_transform, Mapping) else None
    )
    if (
        not isinstance(source_page_numbers, (list, tuple))
        or not source_page_numbers
        or any(
            not isinstance(value, int) or isinstance(value, bool) or value <= 0
            for value in source_page_numbers
        )
        or len(set(source_page_numbers)) != len(source_page_numbers)
        or source_page not in source_page_numbers
    ):
        return None
    return source_logical_page, source_page


def _profile_source_ref(
    page: Any,
    table: Any,
    *,
    row: int | None = None,
    column: int | None = None,
) -> dict[str, Any]:
    ref = _source_ref(page, table, row=row, column=column)
    owner = _profile_table_source_owner(page, table)
    if owner is not None:
        ref["logical_page"], ref["source_page"] = owner
        ref["canonical_template_id"] = _PROFILE_CANONICAL_TEMPLATE_ID
    return ref


def _profile_tokens_ref(
    page: Any,
    table: Any,
    *,
    row: int,
    column: int,
    tokens: tuple[tuple[str, tuple[float, float, float, float], str], ...],
    label_tokens: tuple[tuple[str, tuple[float, float, float, float], str], ...] = (),
) -> dict[str, Any] | None:
    token_ids = tuple(token[2] for token in tokens)
    label_ids = tuple(token[2] for token in label_tokens)
    if not token_ids or len(set(token_ids + label_ids)) != len(token_ids) + len(label_ids):
        return None
    ref = _profile_source_ref(page, table, row=row, column=column)
    ref.update(
        {
            "source": "native_detail_table_token_span",
            "bbox": [
                min(token[1][0] for token in tokens),
                min(token[1][1] for token in tokens),
                max(token[1][2] for token in tokens),
                max(token[1][3] for token in tokens),
            ],
            "evidence_ids": list(token_ids),
            "geometry_scope": "token_span",
            "binding": "canonical_field_token",
            "binding_quality": "exact_token_in_canonical_span",
        }
    )
    if label_ids:
        ref.update(
            {
                "binding": "canonical_label_value_role",
                "binding_quality": "exact_label_value_same_source_owned_band",
                "label_evidence_ids": list(label_ids),
            }
        )
    return ref


def _profile_distinct_token_roles(
    *roles: tuple[tuple[str, tuple[float, float, float, float], str], ...],
) -> bool:
    if not roles or any(not role for role in roles):
        return False
    token_ids = [token[2] for role in roles for token in role]
    return len(token_ids) == len(set(token_ids))


def _tokens_in_x_band(
    tokens: tuple[tuple[str, tuple[float, float, float, float], str], ...],
    band: tuple[float, float],
) -> list[tuple[str, tuple[float, float, float, float], str]]:
    return [token for token in tokens if band[0] <= (token[1][0] + token[1][2]) / 2 <= band[1]]


def _bounded_merged_mobile_table(
    parse_result: Any,
    page: Any,
    table: Any,
    rows: list[list[str]],
) -> list[dict[str, Any]] | None:
    """Decode only the exact four-band mobile topology seen in native source tables."""

    if _profile_table_source_owner(page, table) is None:
        return None
    geometry = _native_table_geometry(table)
    if geometry is None:
        return None
    column_bands = _indexed_geometry_bands(geometry, "col_bands", lower_key="x0", upper_key="x1")
    if column_bands is None or set(column_bands) != {0, 1, 2, 3}:
        return None
    header_rows = [
        index for index, row in enumerate(rows) if _compact("".join(row)) == "编号手机号码信息更新日期数据发生机构名称"
    ]
    if len(header_rows) != 1:
        return None
    header_row = header_rows[0]
    logical_page = int(getattr(page, "page_number", 0) or 0)
    left_header = _exact_native_table_cell_tokens(
        parse_result,
        table,
        row=header_row,
        column=0,
        allowed_span=(1, 2),
        logical_page=logical_page,
    )
    right_header = _exact_native_table_cell_tokens(
        parse_result,
        table,
        row=header_row,
        column=2,
        allowed_span=(1, 2),
        logical_page=logical_page,
    )
    if left_header is None or right_header is None:
        return None
    header_roles = {
        0: (left_header, "编号"),
        1: (left_header, "手机号码"),
        2: (right_header, "信息更新日期"),
        3: (right_header, "数据发生机构名称"),
    }
    owned_header_roles: dict[int, tuple[tuple[str, tuple[float, float, float, float], str], ...]] = {}
    for column, (tokens, label) in header_roles.items():
        owned = _tokens_in_x_band(tokens, column_bands[column])
        if len(owned) != 1 or _compact(owned[0][0]) != label:
            return None
        owned_header_roles[column] = tuple(owned)
    if (
        {token[2] for token in left_header + right_header}
        != {token[2] for role in owned_header_roles.values() for token in role}
        or not _profile_distinct_token_roles(*owned_header_roles.values())
    ):
        return None

    output: list[dict[str, Any]] = []
    for row_index in range(header_row + 1, len(rows)):
        row = rows[row_index]
        if not _nonempty(row):
            continue
        if len(row) != 4:
            return None
        merged = _exact_native_table_cell_tokens(
            parse_result,
            table,
            row=row_index,
            column=0,
            allowed_span=(1, 2),
            logical_page=logical_page,
        )
        updated = _exact_native_table_cell_tokens(
            parse_result,
            table,
            row=row_index,
            column=2,
            logical_page=logical_page,
        )
        provider = _exact_native_table_cell_tokens(
            parse_result,
            table,
            row=row_index,
            column=3,
            logical_page=logical_page,
        )
        if merged is None or updated is None or provider is None:
            return None
        sequences = [
            token
            for token in _tokens_in_x_band(merged, column_bands[0])
            if re.fullmatch(r"\d{1,3}", _compact(token[0])) and 1 <= int(_compact(token[0])) <= 999
        ]
        phones = [
            token
            for token in _tokens_in_x_band(merged, column_bands[1])
            if re.fullmatch(r"(?:86)?1[3-9]\d{9}", _compact(token[0]))
        ]
        dates = [token for token in updated if _DATE_RE.fullmatch(_compact(token[0]))]
        sequence_tokens = tuple(sequences)
        phone_tokens = tuple(phones)
        date_tokens = tuple(dates)
        provider_tokens = tuple(provider)
        if (
            len(sequence_tokens) != 1
            or len(phone_tokens) != 1
            or len(date_tokens) != 1
            or {token[2] for token in merged} != {sequence_tokens[0][2], phone_tokens[0][2]}
            or {token[2] for token in updated} != {date_tokens[0][2]}
            or not _profile_distinct_token_roles(
                *owned_header_roles.values(),
                sequence_tokens,
                phone_tokens,
                date_tokens,
                provider_tokens,
            )
        ):
            return None
        provider_raw = _business_text(
            "".join(token[0] for token in sorted(provider, key=lambda item: (item[1][1], item[1][0])))
        )
        if not provider_raw:
            return None
        output.append(
            {
                "row_index": row_index,
                "sequence": int(_compact(sequence_tokens[0][0])),
                "mobile_phone": _compact(phone_tokens[0][0]),
                "information_updated_date": _compact(date_tokens[0][0]),
                "data_provider": provider_raw,
                "columns": {
                    "sequence": 0,
                    "mobile_phone": 0,
                    "information_updated_date": 2,
                    "data_provider": 3,
                },
                "field_refs": {
                    "sequence": _profile_token_ref(page, table, row=row_index, column=0, token=sequence_tokens[0]),
                    "mobile_phone": _profile_token_ref(page, table, row=row_index, column=0, token=phone_tokens[0]),
                    "information_updated_date": _profile_token_ref(
                        page, table, row=row_index, column=2, token=date_tokens[0]
                    ),
                    "data_provider": _profile_tokens_ref(
                        page,
                        table,
                        row=row_index,
                        column=3,
                        tokens=provider_tokens,
                    ),
                },
            }
        )
    return output or None


def _bounded_merged_spouse_table(
    parse_result: Any,
    page: Any,
    table: Any,
    rows: list[list[str]],
) -> dict[str, Any] | None:
    """Decode one spouse row from exact token boxes when two logical columns collapse."""

    if _profile_table_source_owner(page, table) is None:
        return None
    if len(rows) != 2 or any(len(row) != 4 for row in rows):
        return None
    geometry = _native_table_geometry(table)
    if geometry is None:
        return None
    bands = _indexed_geometry_bands(geometry, "col_bands", lower_key="x0", upper_key="x1")
    if bands is None or set(bands) != {0, 1, 2, 3}:
        return None
    logical_page = int(getattr(page, "page_number", 0) or 0)
    headers = {
        column: _exact_native_table_cell_tokens(
            parse_result,
            table,
            row=0,
            column=column,
            logical_page=logical_page,
        )
        for column in range(4)
    }
    if any(tokens is None for tokens in headers.values()):
        return None
    expected_single = {0: "姓名", 2: "工作单位", 3: "联系电话"}
    if any(
        len(headers[column] or ()) != 1 or _compact((headers[column] or (("", (), ""),))[0][0]) != label
        for column, label in expected_single.items()
    ):
        return None
    identity_headers = {_compact(token[0]): token for token in headers[1] or ()}
    if set(identity_headers) != {"证件类型", "证件号码"}:
        return None
    type_header = identity_headers["证件类型"]
    number_header = identity_headers["证件号码"]
    if type_header[1][2] >= number_header[1][0]:
        return None
    identity_boundary = (type_header[1][2] + number_header[1][0]) / 2
    merged = _exact_native_table_cell_tokens(
        parse_result,
        table,
        row=1,
        column=0,
        allowed_span=(1, 2),
        logical_page=logical_page,
    )
    employer = _exact_native_table_cell_tokens(
        parse_result,
        table,
        row=1,
        column=2,
        logical_page=logical_page,
    )
    phone = _exact_native_table_cell_tokens(
        parse_result,
        table,
        row=1,
        column=3,
        logical_page=logical_page,
    )
    if merged is None or employer is None or phone is None:
        return None
    names = _tokens_in_x_band(merged, bands[0])
    types = [token for token in merged if bands[1][0] <= (token[1][0] + token[1][2]) / 2 < identity_boundary]
    numbers = [token for token in merged if identity_boundary <= (token[1][0] + token[1][2]) / 2 <= bands[1][1]]
    phone_tokens = [token for token in phone if re.fullmatch(r"\d{5,16}", _compact(token[0]))]
    name_tokens = tuple(names)
    type_tokens = tuple(types)
    number_tokens = tuple(numbers)
    phone_role_tokens = tuple(phone_tokens)
    employer_tokens = tuple(employer)
    header_token_roles = tuple(
        (token,)
        for token in (
            (headers[0] or ())[0],
            type_header,
            number_header,
            (headers[2] or ())[0],
            (headers[3] or ())[0],
        )
    )
    if (
        not all(len(tokens) == 1 for tokens in (name_tokens, type_tokens, number_tokens, phone_role_tokens))
        or {token[2] for token in merged}
        != {name_tokens[0][2], type_tokens[0][2], number_tokens[0][2]}
        or {token[2] for token in phone} != {phone_role_tokens[0][2]}
        or not _profile_distinct_token_roles(
            *header_token_roles,
            name_tokens,
            type_tokens,
            number_tokens,
            employer_tokens,
            phone_role_tokens,
        )
    ):
        return None
    values = {
        "name": _business_text(name_tokens[0][0]),
        "document_type": _business_text(type_tokens[0][0]),
        "document_number": _compact(number_tokens[0][0]),
        "employer": _business_text(
            "".join(token[0] for token in sorted(employer, key=lambda item: (item[1][1], item[1][0])))
        ),
        "phone": _compact(phone_role_tokens[0][0]),
    }
    invalid_fields: set[str] = set()
    if _strict_whole_cell_business_name(values["employer"], "employer_name") is None:
        invalid_fields.add("employer")
    if _canonical_nonmobile_phone(values["phone"]) is None:
        invalid_fields.add("phone")
    if (
        not re.fullmatch(r"[\u3400-\u9fffA-Za-z·]{2,30}", values["name"])
        or not re.fullmatch(r"[\u3400-\u9fffA-Za-z]{2,20}", values["document_type"])
        or not re.fullmatch(r"[A-Za-z0-9()（）-]{4,40}", values["document_number"])
        or not values["employer"]
    ):
        return None
    role_tokens = {
        "name": name_tokens[0],
        "document_type": type_tokens[0],
        "document_number": number_tokens[0],
        "phone": phone_role_tokens[0],
    }
    return {
        "row_index": 1,
        "values": values,
        "invalid_fields": sorted(invalid_fields),
        "field_refs": {
            role: _profile_token_ref(page, table, row=1, column=0 if role != "phone" else 3, token=token)
            for role, token in role_tokens.items()
        }
        | {
            "employer": _profile_tokens_ref(page, table, row=1, column=2, tokens=employer_tokens),
        },
    }


def _bounded_spouse_provider_observation(
    parse_result: Any,
    page: Any,
    table: Any,
    rows: list[list[str]],
) -> dict[str, Any] | None:
    """Bind a spouse provider only through one exact same-table label/value band."""

    if _profile_table_source_owner(page, table) is None:
        return None
    geometry = _native_table_geometry(table)
    if geometry is None:
        return None
    column_bands = _indexed_geometry_bands(geometry, "col_bands", lower_key="x0", upper_key="x1")
    row_bands = _indexed_geometry_bands(geometry, "row_bands", lower_key="y0", upper_key="y1")
    if (
        column_bands is None
        or row_bands is None
        or set(column_bands) != set(range(len(column_bands)))
        or set(row_bands) != set(range(len(rows)))
        or any(len(row) != len(column_bands) for row in rows)
    ):
        return None
    logical_page = int(getattr(page, "page_number", 0) or 0)
    candidates: list[dict[str, Any]] = []
    aliases = {"sequence": ("编号",), "data_provider": ("数据发生机构名称",)}
    for header_index in range(len(rows) - 1):
        header = tuple(rows[header_index])
        populated = [column for column, value in enumerate(header) if _compact(value)]
        slots = _canonical_header_slots(header, aliases)
        if "data_provider" not in slots or set(populated) != set(slots.values()):
            continue
        if _compact(header[slots["data_provider"]]) != "数据发生机构名称":
            continue
        if "sequence" in slots and _compact(header[slots["sequence"]]) != "编号":
            continue
        provider_column = slots["data_provider"]
        label_tokens = _exact_native_table_cell_tokens(
            parse_result,
            table,
            row=header_index,
            column=provider_column,
            logical_page=logical_page,
        )
        if label_tokens is None or len(label_tokens) != 1 or _compact(label_tokens[0][0]) != "数据发生机构名称":
            continue
        sequence_label_tokens: tuple[tuple[str, tuple[float, float, float, float], str], ...] = ()
        if "sequence" in slots:
            sequence_label_tokens = (
                _exact_native_table_cell_tokens(
                    parse_result,
                    table,
                    row=header_index,
                    column=slots["sequence"],
                    logical_page=logical_page,
                )
                or ()
            )
            if len(sequence_label_tokens) != 1 or _compact(sequence_label_tokens[0][0]) != "编号":
                continue

        value_index = header_index + 1
        value_row = tuple(rows[value_index])
        value_populated = [column for column, value in enumerate(value_row) if _compact(value)]
        expected_populated = {provider_column}
        if "sequence" in slots:
            expected_populated.add(slots["sequence"])
        if set(value_populated) != expected_populated:
            continue
        provider_tokens = _exact_native_table_cell_tokens(
            parse_result,
            table,
            row=value_index,
            column=provider_column,
            logical_page=logical_page,
        )
        if provider_tokens is None:
            continue
        sequence_value_tokens: tuple[tuple[str, tuple[float, float, float, float], str], ...] = ()
        if "sequence" in slots:
            sequence_column = slots["sequence"]
            sequence_value_tokens = (
                _exact_native_table_cell_tokens(
                    parse_result,
                    table,
                    row=value_index,
                    column=sequence_column,
                    logical_page=logical_page,
                )
                or ()
            )
            if (
                len(sequence_value_tokens) != 1
                or not re.fullmatch(r"\d{1,3}", _compact(sequence_value_tokens[0][0]))
                or not 1 <= int(_compact(sequence_value_tokens[0][0])) <= 999
            ):
                continue
        if not _profile_distinct_token_roles(
            tuple(label_tokens),
            tuple(provider_tokens),
            *(role for role in (sequence_label_tokens, sequence_value_tokens) if role),
        ):
            continue
        raw_provider = _business_text(
            "".join(token[0] for token in sorted(provider_tokens, key=lambda item: (item[1][1], item[1][0])))
        )
        if is_explicit_source_absence(raw_provider):
            provider = raw_provider
        else:
            provider = _strict_employment_provider_span(raw_provider)
        if provider is None:
            continue
        ref = _profile_tokens_ref(
            page,
            table,
            row=value_index,
            column=provider_column,
            tokens=tuple(provider_tokens),
            label_tokens=tuple(label_tokens),
        )
        if ref is None:
            continue
        candidates.append(
            {
                "data_provider": provider,
                "row_index": value_index,
                "column": provider_column,
                "source_ref": ref,
            }
        )
    return candidates[0] if len(candidates) == 1 else None


def _exact_spouse_provider_subtable_rows(
    parse_result: Any,
    page: Any,
    table: Any,
    rows: list[list[str]],
) -> frozenset[int]:
    """Return rows owned by exact provider headers, including invalid values.

    An unreadable provider must not be reinterpreted as another spouse row.
    This helper affects traversal only; publishing the provider still requires
    the stricter complete witness above.
    """

    if _profile_table_source_owner(page, table) is None or _native_table_geometry(table) is None:
        return frozenset()
    logical_page = int(getattr(page, "page_number", 0) or 0)
    aliases = {"sequence": ("编号",), "data_provider": ("数据发生机构名称",)}
    owned_rows: set[int] = set()
    for header_index in range(len(rows) - 1):
        header = tuple(rows[header_index])
        populated = {column for column, value in enumerate(header) if _compact(value)}
        slots = _canonical_header_slots(header, aliases)
        if "data_provider" not in slots or populated != set(slots.values()):
            continue
        provider_column = slots["data_provider"]
        provider_label = _exact_native_table_cell_tokens(
            parse_result,
            table,
            row=header_index,
            column=provider_column,
            logical_page=logical_page,
        )
        if provider_label is None or len(provider_label) != 1 or _compact(provider_label[0][0]) != "数据发生机构名称":
            continue
        if "sequence" in slots:
            sequence_label = _exact_native_table_cell_tokens(
                parse_result,
                table,
                row=header_index,
                column=slots["sequence"],
                logical_page=logical_page,
            )
            if sequence_label is None or len(sequence_label) != 1 or _compact(sequence_label[0][0]) != "编号":
                continue
            if sequence_label[0][2] == provider_label[0][2]:
                continue
        owned_rows.update((header_index, header_index + 1))
    return frozenset(owned_rows)


def _merge_spouse_provider_observation(
    parse_result: Any,
    spouse_record: dict[str, Any],
    observation: Mapping[str, Any] | None,
) -> None:
    if observation is None:
        return
    provider = _clean(observation.get("data_provider"))
    source_ref = observation.get("source_ref")
    if not provider or not isinstance(source_ref, Mapping):
        return
    if is_explicit_source_absence(provider):
        _mark_source_absent(spouse_record, "data_provider", provider)
        return
    spouse_record["source_refs"].append(dict(source_ref))
    _merge_exact_observation(
        parse_result,
        spouse_record,
        dataset="spouse_records",
        target_record_id=str(spouse_record["spouse_record_id"]),
        field_name="data_provider",
        value=provider,
        raw=provider,
        source_ref=dict(source_ref),
        parser_stage="candidate_b_spouse_exact_provider_label_value",
    )


def _profile_exact_one_glyph_institution_alternate(
    parse_result: Any,
    raw: str,
    *,
    source_table: Any,
) -> str | None:
    """Return one independently exact near-match, making the source glyph ambiguous."""

    compact_raw = _compact(raw)
    if len(compact_raw) < 10:
        return None
    candidates: set[str] = set()
    for page in getattr(parse_result, "pages", None) or ():
        for table in getattr(page, "tables", None) or ():
            if table is source_table:
                continue
            for row_index, row in enumerate(_table_rows(table)):
                for column, value in enumerate(row):
                    candidate = _compact(value)
                    if (
                        len(candidate) != len(compact_raw)
                        or sum(left != right for left, right in zip(compact_raw, candidate, strict=True)) != 1
                        or _account_institution(candidate) is None
                        or _exact_native_table_cell(table, row=row_index, column=column) is None
                    ):
                        continue
                    candidates.add(candidate)
    return next(iter(candidates)) if len(candidates) == 1 else None


def _extract_profile_detail_records(parse_result: Any) -> dict[str, list[dict[str, Any]]]:
    mobile_aliases = {
        "sequence": ("编号",),
        "mobile_phone": ("手机号码",),
        "information_updated_date": ("信息更新日期",),
        "data_provider": ("数据发生机构名称",),
    }
    spouse_aliases = {
        "name": ("姓名",),
        "document_type": ("证件类型",),
        "document_number": ("证件号码",),
        "employer": ("工作单位",),
        "phone": ("联系电话",),
    }
    mobile_records: dict[int, dict[str, Any]] = {}
    spouse_record: dict[str, Any] | None = None
    active_slots: dict[str, int] = {}
    mode = ""
    previous_table_id = ""
    continuation_check = getattr(parse_result, "tables_continue", None)
    for page in getattr(parse_result, "pages", None) or []:
        for table in getattr(page, "tables", None) or []:
            rows = _table_rows(table)
            table_id = str(getattr(table, "table_id", "") or "")
            profile_table_owned = (
                _profile_table_source_owner(page, table) is not None
                or canonical_table_owned_by(
                    parse_result,
                    page,
                    table,
                    _PROFILE_CANONICAL_TEMPLATE_ID,
                )
            )
            continues = bool(
                previous_table_id
                and table_id
                and callable(continuation_check)
                and continuation_check(previous_table_id, table_id) is True
            )
            if not continues:
                active_slots = {}
                mode = ""
            if not profile_table_owned:
                # Exact PBOC labels describe a profile schema, but they do not
                # make a public-information or mismatched page/table pair its
                # owner.  Clear carry state as well so an intervening foreign
                # table cannot borrow slots from the preceding profile table.
                active_slots = {}
                mode = ""
                previous_table_id = ""
                continue
            spouse_provider = _bounded_spouse_provider_observation(parse_result, page, table, rows)
            spouse_provider_rows = _exact_spouse_provider_subtable_rows(parse_result, page, table, rows)
            merged_mobile_rows = _bounded_merged_mobile_table(parse_result, page, table, rows)
            if merged_mobile_rows is not None:
                for observation in merged_mobile_rows:
                    provider = str(observation["data_provider"])
                    _materialize_mobile_record(
                        parse_result,
                        mobile_records,
                        page=page,
                        table=table,
                        row=tuple(rows[int(observation["row_index"])]),
                        row_index=int(observation["row_index"]),
                        sequence=int(observation["sequence"]),
                        values={
                            "mobile_phone": str(observation["mobile_phone"]),
                            "information_updated_date": str(observation["information_updated_date"]),
                            "data_provider": provider,
                        },
                        columns=observation["columns"],
                        field_refs=observation["field_refs"],
                    )
                previous_table_id = table_id or previous_table_id
                continue
            merged_spouse = _bounded_merged_spouse_table(parse_result, page, table, rows)
            if merged_spouse is not None:
                spouse_id = stable_record_id("personal_spouse", 1)
                spouse_record = spouse_record or {
                    "record_id": spouse_id,
                    "spouse_record_id": spouse_id,
                    "source": "native_personal_detail_profile_table",
                    "source_refs": [],
                    "confidence": 1.0,
                }
                row_index = int(merged_spouse["row_index"])
                spouse_record["source_refs"].append(_source_ref(page, table, row=row_index))
                for role, raw in merged_spouse["values"].items():
                    ref = merged_spouse["field_refs"].get(role) or _source_ref(page, table, row=row_index, column=2)
                    if role in set(merged_spouse.get("invalid_fields") or ()):
                        _reject_exact_observation(
                            parse_result,
                            spouse_record,
                            dataset="spouse_records",
                            target_record_id=spouse_id,
                            field_name=role,
                            raw=raw,
                            source_ref=ref,
                            parser_stage="candidate_b_spouse_exact_merged_lattice",
                        )
                    else:
                        _merge_exact_observation(
                            parse_result,
                            spouse_record,
                            dataset="spouse_records",
                            target_record_id=spouse_id,
                            field_name=role,
                            value=raw,
                            raw=raw,
                            source_ref=ref,
                            parser_stage="candidate_b_spouse_exact_merged_lattice",
                        )
                _merge_spouse_provider_observation(parse_result, spouse_record, spouse_provider)
                previous_table_id = table_id or previous_table_id
                continue
            for row_index, row in enumerate(rows):
                if row_index in spouse_provider_rows:
                    active_slots = {}
                    mode = ""
                    continue
                mobile_slots = _canonical_header_slots(row, mobile_aliases)
                spouse_slots = _canonical_header_slots(row, spouse_aliases)
                compact_header = _compact("".join(row))
                broken_mobile = all(
                    marker in compact_header for marker in ("编号", "手机号码", "信息更新日期", "数据发生机构名称")
                ) and not set(mobile_aliases) <= set(mobile_slots)
                broken_mobile = broken_mobile or (
                    len(mobile_slots) >= 2
                    and "mobile_phone" in mobile_slots
                    and not set(mobile_aliases) <= set(mobile_slots)
                )
                broken_spouse = all(
                    marker in compact_header for marker in ("姓名", "证件类型", "证件号码", "工作单位", "联系电话")
                ) and not set(spouse_aliases) <= set(spouse_slots)
                broken_spouse = broken_spouse or (
                    len(spouse_slots) >= 2
                    and bool({"employer", "phone"} & set(spouse_slots))
                    and not set(spouse_aliases) <= set(spouse_slots)
                )
                if broken_mobile or broken_spouse:
                    _report_header_graph_failure(
                        parse_result,
                        dataset="mobile_phone_records" if broken_mobile else "spouse_records",
                        page=page,
                        table=table,
                        row_index=row_index,
                        row=row,
                    )
                    active_slots = {}
                    mode = ""
                    continue
                if set(mobile_aliases) <= set(mobile_slots):
                    active_slots = mobile_slots
                    mode = "mobile"
                    continue
                if set(spouse_aliases) <= set(spouse_slots):
                    active_slots = spouse_slots
                    mode = "spouse"
                    continue
                if "数据发生机构名称" in compact_header and mode == "spouse":
                    # A provider subtable terminates the spouse value band even
                    # when its evidence is too weak to publish a provider.
                    # Never reinterpret its exact label (or following value)
                    # as another spouse row through stale active slots.
                    active_slots = {}
                    mode = ""
                    continue
                if not active_slots:
                    continue
                if mode == "mobile":
                    sequence = _sequence_value(row, active_slots)
                    if sequence is None:
                        if _nonempty(row):
                            _report_unkeyed_business_row(
                                parse_result,
                                dataset="mobile_phone_records",
                                row=row,
                                page=page,
                                table=table,
                                row_index=row_index,
                            )
                        continue
                    _materialize_mobile_record(
                        parse_result,
                        mobile_records,
                        page=page,
                        table=table,
                        row=row,
                        row_index=row_index,
                        sequence=sequence,
                        values={
                            role: _slot_value(row, active_slots, role)
                            for role in ("mobile_phone", "information_updated_date", "data_provider")
                        },
                        columns=active_slots,
                    )
                elif mode == "spouse":
                    values = {role: _slot_value(row, active_slots, role) for role in spouse_aliases}
                    row_is_source_absent = bool(values) and all(
                        not value or is_explicit_source_absence(value) for value in values.values()
                    )
                    if not any(value for value in values.values()) or row_is_source_absent:
                        continue
                    spouse_id = stable_record_id("personal_spouse", 1)
                    if spouse_record is None:
                        spouse_record = {
                            "record_id": spouse_id,
                            "spouse_record_id": spouse_id,
                            "source": "native_personal_detail_profile_table",
                            "source_refs": [],
                            "confidence": 1.0,
                        }
                    spouse_record["source_refs"].append(_source_ref(page, table, row=row_index))
                    for role, raw in values.items():
                        if is_explicit_source_absence(raw):
                            _mark_source_absent(spouse_record, role, raw)
                            continue
                        if not raw:
                            continue
                        ref = _source_ref(page, table, row=row_index, column=active_slots[role])
                        valid = True
                        normalized = raw
                        if role == "phone":
                            phone = _canonical_exact_phone(raw, mobile=False)
                            valid = phone is not None
                            normalized = phone or raw
                        elif role == "employer":
                            employer = _strict_whole_cell_business_name(raw, "employer_name")
                            valid = employer is not None
                            normalized = employer or raw
                        elif role == "name":
                            valid = (
                                bool(re.search(r"[\u3400-\u9fffA-Za-z]", raw)) and _compact(raw) not in _ACCOUNT_LABELS
                            )
                        elif role == "document_number":
                            compact_number = re.sub(r"\s+", "", raw)
                            valid = bool(re.fullmatch(r"[A-Za-z0-9()（）-]{4,40}", compact_number))
                            normalized = compact_number
                        if valid:
                            _merge_exact_observation(
                                parse_result,
                                spouse_record,
                                dataset="spouse_records",
                                target_record_id=spouse_id,
                                field_name=role,
                                value=normalized,
                                raw=raw,
                                source_ref=ref,
                                parser_stage="candidate_b_spouse_canonical_slots",
                            )
                        else:
                            _reject_exact_observation(
                                parse_result,
                                spouse_record,
                                dataset="spouse_records",
                                target_record_id=spouse_id,
                                field_name=role,
                                raw=raw,
                                source_ref=ref,
                                parser_stage="candidate_b_spouse_canonical_slots",
                            )
                    if not spouse_record.get("name") and "name" not in set(
                        spouse_record.get("_source_absent_fields") or ()
                    ):
                        _report_required_row_failure(
                            parse_result,
                            issue_code="candidate_b_spouse_row_unresolved",
                            dataset="spouse_records",
                            sequence=1,
                            field_name="name",
                            row=row,
                            page=page,
                            table=table,
                            row_index=row_index,
                            target_record_id=spouse_id,
                        )
                    _merge_spouse_provider_observation(parse_result, spouse_record, spouse_provider)
            previous_table_id = table_id or previous_table_id
    mobile_output = [mobile_records[key] for key in sorted(mobile_records)]
    spouse_output = [spouse_record] if spouse_record is not None else []
    _enforce_observed_header_terminal_invariant(
        parse_result,
        dataset="mobile_phone_records",
        aliases=mobile_aliases,
        records=mobile_output,
    )
    _enforce_observed_header_terminal_invariant(
        parse_result,
        dataset="spouse_records",
        aliases=spouse_aliases,
        records=spouse_output,
    )
    return {
        "mobile_phone_records": mobile_output,
        "spouse_records": spouse_output,
    }


def _extract_personal_notes(parse_result: Any) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    annotations: list[dict[str, Any]] = []
    statements: list[dict[str, Any]] = []
    for page in getattr(parse_result, "pages", None) or []:
        page_number = int(getattr(page, "page_number", 0) or 0)
        source_page = int(getattr(page, "source_page_number", 0) or page_number)
        for table in getattr(page, "tables", None) or []:
            if not canonical_table_owned_by(
                parse_result,
                page,
                table,
                "annotations_and_inquiries",
            ):
                continue
            rows = _table_rows(table)
            for row_index, row in enumerate(rows):
                compact = _compact("".join(row))
                if all(marker in compact for marker in ("编号", "标注内容", "添加日期")):
                    slots = _canonical_header_slots(
                        tuple(row),
                        {"sequence": ("编号",), "text": ("标注内容",), "added_date": ("添加日期",)},
                    )
                    if set(slots) != {"sequence", "text", "added_date"}:
                        _report_header_graph_failure(
                            parse_result,
                            dataset="annotation_statements",
                            page=page,
                            table=table,
                            row_index=row_index,
                            row=tuple(row),
                        )
                        continue
                    for data_index, data_row in enumerate(rows[row_index + 1 :], start=row_index + 1):
                        physical = tuple(data_row)
                        sequence = _sequence_value(physical, slots)
                        if sequence is None:
                            if _slot_value(physical, slots, "sequence"):
                                _report_unkeyed_business_row(
                                    parse_result,
                                    dataset="annotation_statements",
                                    row=physical,
                                    page=page,
                                    table=table,
                                    row_index=data_index,
                                )
                            break
                        target_id = stable_record_id("personal_detail_annotation", sequence)
                        record: dict[str, Any] = {
                            "id": target_id,
                            "annotation_id": target_id,
                            "sequence": sequence,
                            "note_type": "report_annotation",
                            "logical_page": page_number,
                            "source_page": source_page,
                            "source": "native_personal_detail_note_table",
                            "source_refs": [_source_ref(page, table, row=data_index)],
                            "confidence": float(getattr(table, "confidence", None) or 0.9),
                        }
                        for role, field_name, kind in (
                            ("text", "text", "text"),
                            ("added_date", "added_date", "date"),
                        ):
                            raw = _slot_value(physical, slots, role)
                            ref = _source_ref(page, table, row=data_index, column=slots[role])
                            value = _date(raw) if kind == "date" else _clean(raw)
                            if value in (None, ""):
                                _reject_exact_observation(
                                    parse_result,
                                    record,
                                    dataset="annotation_statements",
                                    target_record_id=f"annotation_statement:{target_id}",
                                    field_name=field_name,
                                    raw=raw,
                                    source_ref=ref,
                                    parser_stage="candidate_b_note_canonical_slots",
                                )
                            else:
                                _merge_exact_observation(
                                    parse_result,
                                    record,
                                    dataset="annotation_statements",
                                    target_record_id=f"annotation_statement:{target_id}",
                                    field_name=field_name,
                                    value=value,
                                    raw=raw,
                                    source_ref=ref,
                                    parser_stage="candidate_b_note_canonical_slots",
                                )
                        annotations.append(record)
                marker = next(
                    (candidate for candidate in ("异议标注", "本人声明", "机构说明") if candidate in compact),
                    None,
                )
                if marker is None or row_index + 1 >= len(rows):
                    continue
                # A standalone canonical heading is followed by one narrative
                # cell (and, for annotation forms, optionally one date cell).
                # Multiple free-floating cells are not concatenated into an
                # unstructured text blob.
                if any(label in compact for label in ("编号", "标注内容", "添加日期")):
                    continue
                next_compact = _compact("".join(rows[row_index + 1]))
                if all(label in next_compact for label in ("编号", "标注内容", "添加日期")):
                    continue
                values = [(column, _clean(value)) for column, value in enumerate(rows[row_index + 1]) if _clean(value)]
                if not values:
                    continue
                target = annotations if marker == "异议标注" else statements
                target_id = stable_record_id("personal_detail_note", marker, page_number, row_index)
                record = {
                    "id": target_id,
                    ("annotation_id" if marker == "异议标注" else "statement_id"): target_id,
                    "note_type": {
                        "异议标注": "dispute_annotation",
                        "本人声明": "subject_statement",
                        "机构说明": "institution_statement",
                    }[marker],
                    "logical_page": page_number,
                    "source_page": source_page,
                    "source": "native_personal_detail_note_table",
                    "source_refs": [_source_ref(page, table, row=row_index + 1)],
                    "confidence": float(getattr(table, "confidence", None) or 0.9),
                }
                text_column, text = values[0]
                if len(values) > 2 or (len(values) == 2 and _date(values[1][1]) is None):
                    _report_required_row_failure(
                        parse_result,
                        issue_code="candidate_b_note_narrative_cells_unresolved",
                        dataset="annotation_statements",
                        sequence=len(target) + 1,
                        field_name="text",
                        row=tuple(rows[row_index + 1]),
                        page=page,
                        table=table,
                        row_index=row_index + 1,
                        target_record_id=f"annotation_statement:{target_id}",
                    )
                    _append_internal_field(record, "_unresolved_fields", "text")
                else:
                    _merge_exact_observation(
                        parse_result,
                        record,
                        dataset="annotation_statements",
                        target_record_id=f"annotation_statement:{target_id}",
                        field_name="text",
                        value=text,
                        raw=text,
                        source_ref=_source_ref(page, table, row=row_index + 1, column=text_column),
                        parser_stage="candidate_b_note_narrative_slot",
                    )
                    if len(values) == 2:
                        date_column, date_raw = values[1]
                        record["added_date"] = _date(date_raw)
                        record.setdefault("source_refs_by_field", {})["added_date"] = [
                            _source_ref(page, table, row=row_index + 1, column=date_column)
                        ]
                target.append(record)
    return annotations, statements


def _extract_source_rows(parse_result: Any) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    for page in getattr(parse_result, "pages", None) or []:
        page_number = int(getattr(page, "page_number", 0) or 0)
        for table in getattr(page, "tables", None) or []:
            table_id = str(getattr(table, "table_id", "") or "")
            for row_index, row in enumerate(_table_rows(table)):
                cells = [_clean(cell) for cell in row]
                records.append(
                    {
                        "source_table_row_id": stable_record_id(
                            "personal_detail_source_row", page_number, table_id, row_index
                        ),
                        "page": page_number,
                        "table_id": table_id,
                        "row_index": row_index,
                        "cells": cells,
                        "nonempty_cells": [cell for cell in cells if cell],
                        "source": "native_detail_source_table",
                        "source_refs": [_source_ref(page, table, row=row_index)],
                        "confidence": 1.0,
                    }
                )
    return records


def _decode_exact_label_card(
    parse_result: Any,
    *,
    page: Any,
    table: Any,
    dataset: str,
    target_record_id: str,
    fields: Mapping[str, tuple[tuple[str, ...], str]],
) -> dict[str, Any]:
    """Decode a canonical label/value card without compacting physical cells."""

    rows = _table_rows(table)
    observations, unresolved = _exact_label_observations(rows)
    record: dict[str, Any] = {"source_refs": [_source_ref(page, table)]}
    for field_name, (labels, kind) in fields.items():
        candidates = [item for label in labels for item in observations.get(_compact(label), ())]
        if not candidates:
            label_location = next(
                ((row, column) for label, row, column in unresolved if label in {_compact(item) for item in labels}),
                None,
            )
            row_index = label_location[0] if label_location is not None else 0
            _report_required_row_failure(
                parse_result,
                issue_code="candidate_b_canonical_card_field_unresolved",
                dataset=dataset,
                sequence=1,
                field_name=field_name,
                row=tuple(rows[row_index]) if row_index < len(rows) else (),
                page=page,
                table=table,
                row_index=row_index,
                target_record_id=target_record_id,
            )
            _append_internal_field(record, "_unresolved_fields", field_name)
            continue
        for raw, row_index, column in candidates:
            ref = _source_ref(page, table, row=row_index, column=column)
            if _compact(raw) in {"-", "--", "---"}:
                _mark_source_absent(record, field_name, raw)
                continue
            if kind == "date":
                value = _date(raw)
            elif kind == "number":
                candidate = _number(raw)
                value = candidate if isinstance(candidate, int) and not isinstance(candidate, bool) else None
            else:
                value = _clean(raw)
            if value in (None, ""):
                _reject_exact_observation(
                    parse_result,
                    record,
                    dataset=dataset,
                    target_record_id=target_record_id,
                    field_name=field_name,
                    raw=raw,
                    source_ref=ref,
                    parser_stage="candidate_b_canonical_label_card",
                )
                continue
            _merge_exact_observation(
                parse_result,
                record,
                dataset=dataset,
                target_record_id=target_record_id,
                field_name=field_name,
                value=value,
                raw=raw,
                source_ref=ref,
                parser_stage="candidate_b_canonical_label_card",
            )
    return record


_POSTPAID_CARD_FIELDS: dict[str, tuple[tuple[str, ...], str]] = {
    "institution": (("机构名称",), "institution"),
    "business_type": (("业务类型",), "business_type"),
    "service_start_date": (("业务开通日期",), "date"),
    "payment_status": (("当前缴费状态",), "payment_status"),
    "current_arrears_amount": (("当前欠费金额", "当前欠款金额"), "number"),
    "billing_month": (("记账年月",), "date"),
}
_POSTPAID_BUSINESS_TYPES = frozenset(
    {
        "固定电话",
        "固定电话后付费",
        "移动电话",
        "移动电话后付费",
        "有线电视",
        "有线电视后付费",
        "电信业务",
        "水费",
        "电费",
        "燃气费",
        "水电气等公用事业",
    }
)
_POSTPAID_PAYMENT_STATUSES = frozenset({"正常", "欠费"})
_POSTPAID_HISTORY_STATUS_CODES = frozenset({"*", "N", "0", "1", "2", "3", "4", "5", "6", "C", "G", "#"})
_POSTPAID_VALUE_RE = re.compile(r"[A-Za-z0-9\u3400-\u9fff（）()\[\]【】._/\-]+")


def _strict_postpaid_text_value(raw: str, kind: str) -> str | None:
    """Validate a complete postpaid scalar; no token or substring mining."""

    cleaned = _clean(raw)
    compact = _compact(cleaned)
    if not compact or cleaned != compact or _POSTPAID_VALUE_RE.fullmatch(compact) is None:
        return None
    labels = {
        _compact(label)
        for aliases, _kind in _POSTPAID_CARD_FIELDS.values()
        for label in aliases
    }
    if any(label in compact for label in labels):
        return None
    if kind == "business_type":
        return compact if compact in _POSTPAID_BUSINESS_TYPES else None
    if kind == "payment_status":
        return compact if compact in _POSTPAID_PAYMENT_STATUSES else None
    if any(
        token in compact
        for token in (*_POSTPAID_BUSINESS_TYPES, *_POSTPAID_PAYMENT_STATUSES)
    ):
        return None
    if _valid_date_spans(compact) or _PUBLIC_TYPED_AMOUNT_RE.search(compact):
        return None
    return compact


def _postpaid_card_lattice_candidates(
    parse_result: Any,
    table: Any,
    rows: list[list[str]],
) -> list[tuple[int, dict[str, int]]]:
    """Return every complete sealed postpaid header/value pair."""

    label_roles = {
        _compact(label): field_name
        for field_name, (labels, _kind) in _POSTPAID_CARD_FIELDS.items()
        for label in labels
    }
    evidence_counts = _native_evidence_id_counts(
        parse_result,
        roles=frozenset({"postpaid_detail"}),
    )
    candidates: list[tuple[int, dict[str, int]]] = []
    for row_index in range(len(rows) - 1):
        header = rows[row_index]
        values = rows[row_index + 1]
        if len(header) != len(values) or len(header) != len(_POSTPAID_CARD_FIELDS):
            continue
        roles = tuple(label_roles.get(_compact(cell), "") for cell in header)
        if not all(roles) or len(set(roles)) != len(_POSTPAID_CARD_FIELDS):
            continue
        valid = all(
            _sealed_exact_native_cell(
                table,
                row=physical_row,
                column=column,
                evidence_counts=evidence_counts,
            )
            is not None
            for physical_row in (row_index, row_index + 1)
            for column in range(len(header))
        )
        if valid:
            candidates.append((row_index, {role: column for column, role in enumerate(roles)}))
    return candidates


def _exact_postpaid_card_lattice(
    parse_result: Any,
    table: Any,
    rows: list[list[str]],
) -> tuple[int, dict[str, int]] | None:
    """Prove one and only one complete sealed postpaid header/value lattice."""

    candidates = _postpaid_card_lattice_candidates(parse_result, table, rows)
    if len(candidates) != 1:
        return None
    return candidates[0]


def _decode_exact_postpaid_card(
    parse_result: Any,
    *,
    page: Any,
    table: Any,
    rows: list[list[str]],
    header_index: int,
    slots: Mapping[str, int],
    target_record_id: str,
) -> dict[str, Any]:
    record: dict[str, Any] = {"source_refs": [_source_ref(page, table)]}
    value_row = tuple(rows[header_index + 1])
    for field_name, (_labels, kind) in _POSTPAID_CARD_FIELDS.items():
        column = int(slots[field_name])
        raw = _clean(value_row[column])
        ref = _source_ref(page, table, row=header_index + 1, column=column)
        if not raw:
            _report_required_row_failure(
                parse_result,
                issue_code="candidate_b_canonical_card_field_unresolved",
                dataset="postpaid_records",
                sequence=1,
                field_name=field_name,
                row=value_row,
                page=page,
                table=table,
                row_index=header_index + 1,
                target_record_id=target_record_id,
            )
            _append_internal_field(record, "_unresolved_fields", field_name)
            continue
        if _compact(raw) in {"-", "--", "---"}:
            _mark_source_absent(record, field_name, raw)
            continue
        if kind == "date":
            value = _date(raw)
        elif kind == "number":
            candidate = _number(raw)
            value = candidate if isinstance(candidate, int) and not isinstance(candidate, bool) else None
        else:
            value = _strict_postpaid_text_value(raw, kind)
        if value in (None, ""):
            _reject_exact_observation(
                parse_result,
                record,
                dataset="postpaid_records",
                target_record_id=target_record_id,
                field_name=field_name,
                raw=raw,
                source_ref=ref,
                parser_stage="candidate_b_postpaid_exact_card",
            )
            continue
        _merge_exact_observation(
            parse_result,
            record,
            dataset="postpaid_records",
            target_record_id=target_record_id,
            field_name=field_name,
            value=value,
            raw=raw,
            source_ref=ref,
            parser_stage="candidate_b_postpaid_exact_card",
        )
    return record


def _postpaid_id(page: Any, table: Any, record: Mapping[str, Any]) -> str:
    identity = (record.get("institution"), record.get("business_type"), record.get("billing_month"))
    if all(value not in (None, "") for value in identity):
        return stable_record_id("postpaid", *identity)
    return stable_record_id(
        "postpaid_unresolved",
        int(getattr(page, "page_number", 0) or 0),
        str(getattr(table, "table_id", "") or ""),
    )


def _postpaid_physical_owner_id(
    page: Any,
    table: Any,
    record: Mapping[str, Any],
    *,
    header_index: int,
) -> str:
    refs_by_field = record.get("source_refs_by_field")
    immutable_refs = {
        str(field): list(refs)
        for field, refs in (refs_by_field.items() if isinstance(refs_by_field, Mapping) else ())
        if isinstance(refs, (list, tuple))
    }
    return stable_record_id(
        "postpaid_physical_owner",
        int(getattr(page, "page_number", 0) or 0),
        int(
            getattr(page, "source_page_number", 0)
            or getattr(page, "page_number", 0)
            or 0
        ),
        str(getattr(table, "table_id", "") or ""),
        header_index,
        json.dumps(immutable_refs, ensure_ascii=False, sort_keys=True),
    )


def _report_postpaid_identity_not_unique(
    parse_result: Any,
    *,
    record: Mapping[str, Any],
    semantic_id: str,
    physical_id: str,
) -> None:
    from docmirror.plugins.credit_report.personal_detail_scanned.extraction_issues import (
        make_issue,
        record_issue,
    )

    record_issue(
        parse_result,
        make_issue(
            category="schema_incompleteness",
            issue_code="candidate_b_postpaid_identity_not_unique",
            message=(
                "More than one physical postpaid card had the same complete canonical identity; "
                "each row was retained under its immutable physical owner without inventing a business ordinal."
            ),
            parser_stage="candidate_b_postpaid_identity",
            target_dataset="postpaid_records",
            target_record_id=physical_id,
            field_name="postpaid_record_id",
            observed_value={
                "semantic_identity_id": semantic_id,
                "institution": record.get("institution"),
                "business_type": record.get("business_type"),
                "billing_month": record.get("billing_month"),
            },
            source_refs=tuple(
                ref
                for refs in (record.get("source_refs_by_field") or {}).values()
                for ref in refs
                if isinstance(ref, Mapping)
            ),
            reason_codes=(
                "duplicate_complete_postpaid_identity",
                "immutable_physical_owner_retained",
                "business_ordinal_not_invented",
            ),
        ),
    )


def _extract_postpaid_records(parse_result: Any) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    for page in getattr(parse_result, "pages", None) or []:
        for table in getattr(page, "tables", None) or []:
            if not canonical_table_owned_by(
                parse_result,
                page,
                table,
                "postpaid_detail",
            ):
                continue
            rows = _table_rows(table)
            if not rows:
                continue
            compact = _compact(" ".join(cell for row in rows[:2] for cell in row))
            if not all(
                marker in compact
                for marker in ("机构名称", "业务类型", "业务开通日期", "当前缴费状态", "当前欠费金额", "记账年月")
            ):
                continue
            lattice_candidates = _postpaid_card_lattice_candidates(
                parse_result,
                table,
                rows,
            )
            if len(lattice_candidates) != 1:
                _report_header_graph_failure(
                    parse_result,
                    dataset="postpaid_records",
                    page=page,
                    table=table,
                    row_index=0,
                    row=tuple(rows[0]),
                )
                for candidate_header, candidate_slots in lattice_candidates:
                    value_row = tuple(rows[candidate_header + 1])
                    unresolved_id = stable_record_id(
                        "postpaid_card_pair_unresolved",
                        json.dumps(
                            {
                                field_name: _source_ref(
                                    page,
                                    table,
                                    row=candidate_header + 1,
                                    column=int(column),
                                )
                                for field_name, column in candidate_slots.items()
                            },
                            ensure_ascii=False,
                            sort_keys=True,
                        ),
                    )
                    for field_name in _POSTPAID_CARD_FIELDS:
                        _report_required_row_failure(
                            parse_result,
                            issue_code="candidate_b_postpaid_card_pair_owner_unresolved",
                            dataset="postpaid_records",
                            sequence=0,
                            field_name=field_name,
                            row=value_row,
                            page=page,
                            table=table,
                            row_index=candidate_header + 1,
                            target_record_id=unresolved_id,
                        )
                continue
            lattice = lattice_candidates[0]
            header_index, slots = lattice
            provisional_id = stable_record_id(
                "postpaid_unresolved",
                json.dumps(
                    {
                        field_name: _source_ref(
                            page,
                            table,
                            row=header_index + 1,
                            column=int(column),
                        )
                        for field_name, column in slots.items()
                    },
                    ensure_ascii=False,
                    sort_keys=True,
                ),
            )
            record = _decode_exact_postpaid_card(
                parse_result,
                page=page,
                table=table,
                rows=rows,
                header_index=header_index,
                slots=slots,
                target_record_id=provisional_id,
            )
            postpaid_id = _postpaid_id(page, table, record)
            owner_id = _postpaid_physical_owner_id(
                page,
                table,
                record,
                header_index=header_index,
            )
            record.update(
                {
                    "postpaid_record_id": provisional_id,
                    "_postpaid_semantic_id": postpaid_id,
                    "_postpaid_physical_owner_id": owner_id,
                    "_postpaid_provisional_id": provisional_id,
                    "sequence": len(records) + 1,
                    "reporting_amount_currency": "CNY",
                    "reporting_amount_unit": "yuan",
                    "source": "native_detail_postpaid_table",
                    "confidence": float(getattr(table, "confidence", None) or 0.9),
                }
            )
            history_marker = next(
                (
                    row_index
                    for row_index in range(header_index + 2, len(rows))
                    if any(_compact(cell) == "缴费记录" for cell in rows[row_index])
                ),
                len(rows),
            )
            for row_index in range(header_index + 2, history_marker):
                row = tuple(rows[row_index])
                if len(row) != len(_POSTPAID_CARD_FIELDS) or not any(_clean(cell) for cell in row):
                    continue
                unresolved_id = stable_record_id(
                    "postpaid_extra_value_row_unresolved",
                    owner_id,
                    row_index,
                )
                for field_name in _POSTPAID_CARD_FIELDS:
                    _report_required_row_failure(
                        parse_result,
                        issue_code="candidate_b_postpaid_card_pair_owner_unresolved",
                        dataset="postpaid_records",
                        sequence=0,
                        field_name=field_name,
                        row=row,
                        page=page,
                        table=table,
                        row_index=row_index,
                        target_record_id=unresolved_id,
                    )
            records.append(record)

    identities: defaultdict[str, list[dict[str, Any]]] = defaultdict(list)
    for record in records:
        identities[str(record["_postpaid_semantic_id"])].append(record)
    for semantic_id, candidates in identities.items():
        duplicate = len(candidates) > 1
        for record in candidates:
            physical_id = str(record["_postpaid_physical_owner_id"])
            final_id = physical_id if duplicate else semantic_id
            provisional_id = str(record["_postpaid_provisional_id"])
            record["postpaid_record_id"] = final_id
            for issue in getattr(parse_result, "_personal_detail_extraction_issues", []) or []:
                if isinstance(issue, dict) and issue.get("target_record_id") == provisional_id:
                    issue["target_record_id"] = final_id
            if duplicate:
                _report_postpaid_identity_not_unique(
                    parse_result,
                    record=record,
                    semantic_id=semantic_id,
                    physical_id=physical_id,
                )
            for key in (
                "_postpaid_semantic_id",
                "_postpaid_physical_owner_id",
                "_postpaid_provisional_id",
            ):
                record.pop(key, None)
    return records


def _exact_postpaid_history_identity_lattice(
    table: Any,
    rows: list[list[str]],
    *,
    evidence_counts: Mapping[str, int] | None,
) -> tuple[int, dict[str, int]] | None:
    label_roles = {
        "机构名称": "institution",
        "业务类型": "business_type",
        "记账年月": "billing_month",
    }
    candidates: list[tuple[int, dict[str, int]]] = []
    for row_index in range(len(rows) - 1):
        header = rows[row_index]
        values = rows[row_index + 1]
        if len(header) != len(values) or len(header) not in {2, 3}:
            continue
        roles = tuple(label_roles.get(_compact(cell), "") for cell in header)
        if (
            not all(roles)
            or len(set(roles)) != len(roles)
            or not {"institution", "business_type"}.issubset(roles)
        ):
            continue
        if not all(
            _sealed_exact_native_cell(
                table,
                row=physical_row,
                column=column,
                evidence_counts=evidence_counts,
            )
            is not None
            for physical_row in (row_index, row_index + 1)
            for column in range(len(header))
        ):
            continue
        candidates.append((row_index, {role: column for column, role in enumerate(roles)}))
    return candidates[0] if len(candidates) == 1 else None


def _decode_exact_postpaid_history_identity(
    parse_result: Any,
    *,
    page: Any,
    table: Any,
    rows: list[list[str]],
    lattice: tuple[int, Mapping[str, int]],
    target_record_id: str,
) -> dict[str, Any]:
    header_index, slots = lattice
    value_row = tuple(rows[header_index + 1])
    identity: dict[str, Any] = {}
    identity_refs: dict[str, list[dict[str, Any]]] = {}
    issue_record: dict[str, Any] = {}
    for field_name, column in slots.items():
        raw = _clean(value_row[int(column)])
        ref = _source_ref(page, table, row=header_index + 1, column=int(column))
        if field_name == "billing_month":
            value = _date(raw)
        else:
            value = _strict_postpaid_text_value(raw, field_name)
        if value in (None, ""):
            _reject_exact_observation(
                parse_result,
                issue_record,
                dataset="postpaid_records",
                target_record_id=target_record_id,
                field_name=field_name,
                raw=raw,
                source_ref=ref,
                parser_stage="candidate_b_postpaid_history_identity",
            )
            continue
        identity[field_name] = value
        identity_refs[field_name] = [{**ref, "field_name": field_name}]
    if identity_refs:
        identity["_source_refs_by_field"] = identity_refs
    return identity


def _exact_postpaid_history_lattice(
    table: Any,
    rows: list[list[str]],
    *,
    evidence_counts: Mapping[str, int] | None,
) -> int | None:
    expected = ("缴费记录", *(str(month) for month in range(1, 13)))
    candidates = [
        row_index
        for row_index, row in enumerate(rows)
        if len(row) == 13
        and tuple(_clean(cell) for cell in row) == expected
        and all(
            _sealed_exact_native_cell(
                table,
                row=row_index,
                column=column,
                evidence_counts=evidence_counts,
            )
            is not None
            for column in range(13)
        )
    ]
    return candidates[0] if len(candidates) == 1 else None


def _report_postpaid_history_identity_not_unique(
    parse_result: Any,
    *,
    record: Mapping[str, Any],
    semantic_id: str,
    physical_id: str,
) -> None:
    from docmirror.plugins.credit_report.personal_detail_scanned.extraction_issues import (
        make_issue,
        record_issue,
    )

    record_issue(
        parse_result,
        make_issue(
            category="schema_incompleteness",
            issue_code="candidate_b_postpaid_history_identity_not_unique",
            message=(
                "More than one physical postpaid month occupied the same canonical account/year/month identity; "
                "each observation was retained under its immutable physical owner."
            ),
            parser_stage="candidate_b_postpaid_month_identity",
            target_dataset="postpaid_payment_history",
            target_record_id=physical_id,
            field_name="postpaid_payment_history_id",
            observed_value={
                "semantic_identity_id": semantic_id,
                "year": record.get("year"),
                "month": record.get("month"),
                "status": record.get("status"),
            },
            source_refs=tuple(
                ref
                for ref in record.get("source_refs") or ()
                if isinstance(ref, Mapping)
            ),
            reason_codes=(
                "duplicate_postpaid_month_identity",
                "immutable_physical_owner_retained",
                "business_ordinal_not_invented",
            ),
        ),
    )


def _report_postpaid_duplicate_year_statuses(
    parse_result: Any,
    *,
    page: Any,
    table: Any,
    row: tuple[str, ...],
    row_index: int,
    month_header_index: int,
    postpaid_id: str,
    year: str,
) -> None:
    """Localize every month in a duplicate year row without choosing an owner."""

    from docmirror.plugins.credit_report.personal_detail_scanned.extraction_issues import (
        make_issue,
        record_issue,
    )

    for month in range(1, 13):
        record_issue(
            parse_result,
            make_issue(
                category="schema_incompleteness",
                issue_code="candidate_b_postpaid_history_duplicate_year_owner_unresolved",
                message=(
                    "A sealed postpaid status cell belonged to a duplicated printed year; "
                    "the exact month observation was retained without choosing either physical row."
                ),
                parser_stage="candidate_b_postpaid_month_identity",
                target_dataset="postpaid_payment_history",
                target_record_id=stable_record_id(
                    "postpaid_history_duplicate_month_unresolved",
                    postpaid_id,
                    year,
                    row_index,
                    month,
                ),
                field_name="status",
                observed_value={
                    "year": year,
                    "month": month,
                    "status": _clean(row[month]),
                },
                source_refs=(
                    {
                        **_source_ref(page, table, row=row_index, column=month),
                        "field_name": "status",
                    },
                    _source_ref(page, table, row=row_index, column=0),
                    _source_ref(page, table, row=month_header_index, column=month),
                ),
                reason_codes=(
                    "duplicate_printed_year_owner",
                    "exact_month_header_column",
                    "physical_row_choice_forbidden",
                    "business_ordinal_not_invented",
                ),
            ),
        )


def _extract_postpaid_payment_history(parse_result: Any) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    evidence_counts = _native_evidence_id_counts(
        parse_result,
        roles=frozenset({"postpaid_detail"}),
    )
    for page in getattr(parse_result, "pages", None) or []:
        for table in getattr(page, "tables", None) or []:
            if not canonical_table_owned_by(
                parse_result,
                page,
                table,
                "postpaid_detail",
            ):
                continue
            rows = _table_rows(table)
            compact = _compact(" ".join(cell for row in rows for cell in row))
            if not all(marker in compact for marker in ("机构名称", "业务类型", "缴费记录")):
                continue
            provisional_id = stable_record_id(
                "postpaid_unresolved",
                int(getattr(page, "page_number", 0) or 0),
                str(getattr(table, "table_id", "") or ""),
            )
            month_header_index = _exact_postpaid_history_lattice(
                table,
                rows,
                evidence_counts=evidence_counts,
            )
            identity_lattice = _exact_postpaid_history_identity_lattice(
                table,
                rows,
                evidence_counts=evidence_counts,
            )
            if (
                identity_lattice is not None
                and month_header_index is not None
                and identity_lattice[0] + 2 != month_header_index
            ):
                identity_lattice = None
            identity: dict[str, Any] = {}
            if identity_lattice is None:
                _report_header_graph_failure(
                    parse_result,
                    dataset="postpaid_payment_history",
                    page=page,
                    table=table,
                    row_index=0,
                    row=tuple(rows[0]) if rows else (),
                )
            else:
                identity = _decode_exact_postpaid_history_identity(
                    parse_result,
                    page=page,
                    table=table,
                    rows=rows,
                    lattice=identity_lattice,
                    target_record_id=provisional_id,
                )
            postpaid_id = _postpaid_id(page, table, identity)
            if postpaid_id != provisional_id:
                for issue in getattr(parse_result, "_personal_detail_extraction_issues", []) or []:
                    if isinstance(issue, dict) and issue.get("target_record_id") == provisional_id:
                        issue["target_record_id"] = postpaid_id
            if month_header_index is None:
                observed_header_index = next(
                    (
                        row_index
                        for row_index, row in enumerate(rows)
                        if any("缴费记录" in _compact(cell) for cell in row)
                    ),
                    0,
                )
                _report_header_graph_failure(
                    parse_result,
                    dataset="postpaid_payment_history",
                    page=page,
                    table=table,
                    row_index=observed_header_index,
                    row=tuple(rows[observed_header_index]) if rows else (),
                )
                continue
            sealed_years: Counter[str] = Counter()
            for candidate_index, candidate_row in enumerate(rows):
                if candidate_index <= month_header_index or len(candidate_row) != 13:
                    continue
                candidate_year = _clean(candidate_row[0])
                if re.fullmatch(r"(?:19|20)\d{2}", candidate_year) is None:
                    continue
                if all(
                    _sealed_exact_native_cell(
                        table,
                        row=candidate_index,
                        column=column,
                        evidence_counts=evidence_counts,
                    )
                    is not None
                    for column in range(13)
                ):
                    sealed_years[candidate_year] += 1
            for row_index, raw_row in enumerate(rows):
                if row_index <= month_header_index:
                    continue
                row = tuple(raw_row)
                if not any(_clean(cell) for cell in row):
                    continue
                if len(row) != 13 or not all(
                    _sealed_exact_native_cell(
                        table,
                        row=row_index,
                        column=column,
                        evidence_counts=evidence_counts,
                    )
                    is not None
                    for column in range(13)
                ):
                    _report_required_row_failure(
                        parse_result,
                        issue_code="candidate_b_postpaid_history_lattice_row_unresolved",
                        dataset="postpaid_payment_history",
                        sequence=0,
                        field_name="status",
                        row=row,
                        page=page,
                        table=table,
                        row_index=row_index,
                        target_record_id=stable_record_id(
                            "postpaid_history_row_unresolved",
                            postpaid_id,
                            row_index,
                        ),
                    )
                    continue
                year_raw = _clean(row[0])
                if re.fullmatch(r"(?:19|20)\d{2}", year_raw) is None:
                    _report_required_row_failure(
                        parse_result,
                        issue_code="candidate_b_postpaid_history_year_unresolved",
                        dataset="postpaid_payment_history",
                        sequence=0,
                        field_name="year",
                        row=row,
                        page=page,
                        table=table,
                        row_index=row_index,
                        target_record_id=stable_record_id(
                            "postpaid_history_year_unresolved",
                            postpaid_id,
                            row_index,
                        ),
                    )
                    continue
                if sealed_years[year_raw] != 1:
                    _report_required_row_failure(
                        parse_result,
                        issue_code="candidate_b_postpaid_history_duplicate_year_owner_unresolved",
                        dataset="postpaid_payment_history",
                        sequence=0,
                        field_name="year",
                        row=row,
                        page=page,
                        table=table,
                        row_index=row_index,
                        target_record_id=stable_record_id(
                            "postpaid_history_duplicate_year_unresolved",
                            postpaid_id,
                            year_raw,
                            row_index,
                        ),
                    )
                    _report_postpaid_duplicate_year_statuses(
                        parse_result,
                        page=page,
                        table=table,
                        row=row,
                        row_index=row_index,
                        month_header_index=month_header_index,
                        postpaid_id=postpaid_id,
                        year=year_raw,
                    )
                    continue
                for month in range(1, 13):
                    column = month
                    status = _clean(row[column])
                    history_id = stable_record_id("postpaid_payment_history", postpaid_id, year_raw, month)
                    status_ref = {
                        **_source_ref(page, table, row=row_index, column=column),
                        "field_name": "status",
                    }
                    raw_identity_refs = identity.get("_source_refs_by_field")
                    identity_refs = (
                        {
                            str(field_name): [dict(ref) for ref in refs if isinstance(ref, Mapping)]
                            for field_name, refs in raw_identity_refs.items()
                            if isinstance(refs, (list, tuple))
                        }
                        if isinstance(raw_identity_refs, Mapping)
                        else {}
                    )
                    refs_by_field = {**identity_refs, "status": [status_ref]}
                    physical_history_id = stable_record_id(
                        "postpaid_history_physical_owner",
                        json.dumps(refs_by_field, ensure_ascii=False, sort_keys=True),
                    )
                    record = {
                        "record_id": physical_history_id,
                        "postpaid_payment_history_id": physical_history_id,
                        "_postpaid_history_semantic_id": history_id,
                        "_postpaid_history_physical_id": physical_history_id,
                        "postpaid_record_id": postpaid_id,
                        "institution": identity.get("institution"),
                        "business_type": identity.get("business_type"),
                        "year": int(year_raw),
                        "month": month,
                        "source": "native_personal_detail_postpaid_history",
                        "source_refs": [
                            status_ref,
                            *(
                                ref
                                for refs in identity_refs.values()
                                for ref in refs
                            ),
                        ],
                        "source_refs_by_field": refs_by_field,
                        "confidence": float(getattr(table, "confidence", None) or 0.9),
                    }
                    if status in _POSTPAID_HISTORY_STATUS_CODES:
                        record["status"] = status
                    else:
                        _reject_exact_observation(
                            parse_result,
                            record,
                            dataset="postpaid_payment_history",
                            target_record_id=physical_history_id,
                            field_name="status",
                            raw=status,
                            source_ref=status_ref,
                            parser_stage="candidate_b_postpaid_month_slots",
                        )
                    records.append(record)
    identities: defaultdict[str, list[dict[str, Any]]] = defaultdict(list)
    for record in records:
        identities[str(record["_postpaid_history_semantic_id"])].append(record)
    for semantic_id, candidates in identities.items():
        duplicate = len(candidates) > 1
        for record in candidates:
            physical_id = str(record["_postpaid_history_physical_id"])
            final_id = physical_id if duplicate else semantic_id
            record["record_id"] = final_id
            record["postpaid_payment_history_id"] = final_id
            if final_id != physical_id:
                for issue in getattr(parse_result, "_personal_detail_extraction_issues", []) or []:
                    if isinstance(issue, dict) and issue.get("target_record_id") == physical_id:
                        issue["target_record_id"] = final_id
            if duplicate:
                _report_postpaid_history_identity_not_unique(
                    parse_result,
                    record=record,
                    semantic_id=semantic_id,
                    physical_id=physical_id,
                )
            record.pop("_postpaid_history_semantic_id", None)
            record.pop("_postpaid_history_physical_id", None)
    return records


def _is_summary_anchor(rows: list[list[str]]) -> bool:
    compact = _compact(" ".join(cell for row in rows for cell in row))
    return bool(
        "汇总" in compact or ("账户数" in compact and "首笔业务发放月份" in compact) or "最近1个月内的查询" in compact
    )


_CREDIT_OVERVIEW_BUSINESS_TYPES = (
    "个人商用房贷款（包括商住两用房）",
    "个人商用房贷款(包括商住两用房)",
    "个人住房贷款",
    "其他类贷款",
    "准贷记卡",
    "贷记卡",
)


def _is_headerless_credit_overview_fragment(rows: list[list[str]]) -> bool:
    """Recognize only the four-column tail of the canonical credit overview."""

    if not rows or max((len(row) for row in rows), default=0) != 4:
        return False
    witnessed = 0
    for row in rows:
        category_cell = _compact(row[1] if len(row) > 1 else "")
        matches = [value for value in _CREDIT_OVERVIEW_BUSINESS_TYPES if value in category_cell]
        if "准贷记卡" in matches and "贷记卡" in matches:
            matches.remove("贷记卡")
        if len(matches) != 1:
            continue
        count_cell = _compact(row[2] if len(row) > 2 else "")
        month_cell = _compact(row[3] if len(row) > 3 else "")
        if re.search(r"\d", count_cell) or re.search(r"(?:19|20)\d{2}[.:/-]\d{1,2}", month_cell):
            witnessed += 1
    return witnessed >= 2


def _corrected_text_source_ref(
    page: Mapping[str, Any],
    line: Mapping[str, Any],
    line_index: int,
) -> dict[str, Any]:
    logical_page = int(page.get("page") or 0)
    source_page = int(page.get("source_page") or logical_page)
    ref: dict[str, Any] = {
        "source": "candidate_b_corrected_page_line",
        "logical_page": logical_page,
        "source_page": source_page,
        "line": line_index,
        "geometry_scope": "line",
        "binding": "closed_canonical_summary_text_row",
        "binding_quality": "closed_canonical_summary_text_row",
    }
    bbox = line.get("bbox")
    if isinstance(bbox, (list, tuple)) and len(bbox) == 4:
        ref["bbox"] = list(bbox)
    evidence_ids = line.get("evidence_ids")
    if isinstance(evidence_ids, list) and evidence_ids:
        ref["evidence_ids"] = [str(value) for value in evidence_ids if value]
    elif line.get("evidence_id"):
        ref["evidence_ids"] = [str(line["evidence_id"])]
    return ref


def _credit_overview_text_evidence(parse_result: Any) -> dict[int, dict[str, Any]]:
    """Collect exact header-anchored overview rows from corrected page evidence."""

    loader = getattr(parse_result, "corrected_evidence_pages", None)
    pages = loader() if callable(loader) else []
    output: dict[int, dict[str, Any]] = {}
    for page in pages or ():
        if not isinstance(page, Mapping):
            continue
        lines = [line for line in page.get("lines") or () if isinstance(line, Mapping)]
        texts = [_clean(line.get("text") or line.get("content") or "") for line in lines]
        decoded_rows, unresolved_rows = decode_credit_business_overview_text_lines(texts)
        active = False
        header_refs: list[dict[str, Any]] = []
        decoded: list[tuple[dict[str, Any], dict[str, Any], str]] = []
        unresolved_counts = Counter(unresolved_rows)
        unresolved: list[tuple[str, dict[str, Any]]] = []
        for line_index, (line, text) in enumerate(zip(lines, texts, strict=True)):
            if is_credit_business_overview_text_header(text):
                active = True
                header_refs.append(_corrected_text_source_ref(page, line, line_index))
                continue
            if not active:
                continue
            if "汇总" in _compact(text):
                break
            ref = _corrected_text_source_ref(page, line, line_index)
            row = decode_credit_business_overview_text_line(text)
            if row is not None:
                decoded.append((row, ref, text))
            elif unresolved_counts[text] > 0:
                unresolved.append((text, ref))
                unresolved_counts[text] -= 1
        if not header_refs:
            continue
        logical_page = int(page.get("page") or 0)
        if logical_page:
            output[logical_page] = {
                "decoded": decoded,
                "unresolved": unresolved,
                "header_refs": header_refs,
                "source_page": int(page.get("source_page") or logical_page),
            }
    return output


