# This is a closed PBOC section schema, not a document fingerprint.  Physical
# column widths and the order of the three groups may vary, but every group
# must own exactly its registered semantic leaves on one exact source lattice.
_QUERY_OVERVIEW_SCHEMA: tuple[tuple[str, tuple[str, ...]], ...] = (
    ("最近1个月内的查询机构数", ("贷款审批", "信用卡审批")),
    ("最近1个月内的查询次数", ("贷款审批", "信用卡审批", "本人查询")),
    ("最近2年内的查询次数", ("贷后管理", "担保资格审查", "特约商户实名审查")),
)
_QUERY_OVERVIEW_GROUPS = tuple(group for group, _leaves in _QUERY_OVERVIEW_SCHEMA)
_QUERY_OVERVIEW_LEAF_COUNTS = Counter(
    leaf for _group, leaves in _QUERY_OVERVIEW_SCHEMA for leaf in leaves
)
_QUERY_OVERVIEW_INTEGER_RE = re.compile(r"(?:0|[1-9]\d*)")

_CANONICAL_SUMMARY_COLUMN_TEMPLATES: dict[str, tuple[str, ...]] = {
    "信用业务概要": ("业务分组", "业务类型", "账户数", "首笔业务发放月份"),
    "逾期(透支)信息汇总": (
        "账户类型",
        "账户数",
        "月份数",
        "单月最高逾期/透支总额",
        "最长逾期/透支月数",
    ),
    "非循环贷账户信息汇总": (
        "管理机构数",
        "账户数",
        "授信总额",
        "余额",
        "最近6个月平均应还款",
    ),
    "循环贷账户一信息汇总": (
        "管理机构数",
        "账户数",
        "授信总额",
        "余额",
        "最近6个月平均应还款",
    ),
    "循环贷账户二信息汇总": (
        "管理机构数",
        "账户数",
        "授信总额",
        "余额",
        "最近6个月平均应还款",
    ),
    "贷记卡账户信息汇总": (
        "发卡机构数",
        "账户数",
        "授信总额",
        "单家机构最高授信额",
        "单家机构最低授信额",
        "已用额度",
        "最近6个月平均使用额度",
    ),
    "准贷记卡账户信息汇总": (
        "发卡机构数",
        "账户数",
        "授信总额",
        "单家机构最高授信额",
        "单家机构最低授信额",
        "透支余额",
        "最近6个月平均透支余额",
    ),
}


def _canonical_summary_columns(title: str, width: int) -> tuple[str, ...] | None:
    key = _compact(title).translate(str.maketrans({"（": "(", "）": ")"}))
    columns = _CANONICAL_SUMMARY_COLUMN_TEMPLATES.get(key)
    return columns if columns is not None and len(columns) == width else None


def _summary_title(rows: list[list[str]]) -> str:
    compact = _compact(" ".join(cell for row in rows for cell in row))
    return next(
        (_clean(cell) for row in rows for cell in row if "汇总" in _compact(cell)),
        "信用业务概要" if "首笔业务发放月份" in compact else "查询记录概要",
    )


def _summary_row_has_values(row: list[str]) -> bool:
    """Distinguish business rows from textual/group header rows."""
    for value in row:
        compact = _compact(value)
        if compact in {"--", "-"} or re.fullmatch(r"[-+]?\d[\d,./年月-]*", compact):
            return True
    return False


def _expanded_summary_headers(row: list[str], width: int) -> list[str]:
    values = [_clean(row[index] if index < len(row) else "") for index in range(width)]
    populated = [index for index, value in enumerate(values) if value]
    if not populated:
        return [""] * width
    if any(_compact(values[index]) not in _CANONICAL_SUMMARY_HEADER_LABELS for index in populated):
        return [""] * width
    expanded = [""] * width
    for position, start in enumerate(populated):
        end = populated[position + 1] if position + 1 < len(populated) else width
        for column in range(start, end):
            expanded[column] = values[start]
    return expanded


def _summary_business_rows(
    fragments: list[tuple[Any, Any, list[list[str]]]],
    *,
    title: str,
) -> tuple[
    list[tuple[Any, Any, int, list[str], list[str]]],
    list[tuple[Any, Any, int, list[str], str]],
]:
    width = max((len(row) for _page, _table, rows in fragments for row in rows), default=0)
    canonical_columns = _canonical_summary_columns(title, width)
    if canonical_columns is not None:
        output: list[tuple[Any, Any, int, list[str], list[str]]] = []
        rejected: list[tuple[Any, Any, int, list[str], str]] = []
        header_conflict = False
        for page, table, rows in fragments:
            for source_row_index, row in enumerate(rows):
                if _summary_row_has_values(row):
                    output.append((page, table, source_row_index, row, list(canonical_columns)))
                    continue
                for column, value in enumerate(row[:width]):
                    compact = _compact(value)
                    if not compact or compact in _CANONICAL_SUMMARY_GROUP_LABELS or "汇总" in compact:
                        continue
                    if compact not in _CANONICAL_SUMMARY_HEADER_LABELS:
                        continue
                    if compact != _compact(canonical_columns[column]):
                        header_conflict = True
                        rejected.append((page, table, source_row_index, row, "canonical_template_header_conflict"))
        if header_conflict:
            return [], rejected
        return output, rejected

    header_paths: list[list[str]] = [[] for _column in range(width)]
    output: list[tuple[Any, Any, int, list[str], list[str]]] = []
    rejected: list[tuple[Any, Any, int, list[str], str]] = []
    for page, table, rows in fragments:
        for source_row_index, row in enumerate(rows):
            nonempty = _nonempty(row)
            if len(nonempty) == 1 and "汇总" in _compact(nonempty[0]):
                continue
            if _summary_row_has_values(row):
                labels = ["/".join(path) for path in header_paths]
                missing_label_columns = [
                    column
                    for column, value in enumerate(row)
                    if _clean(value) and (column >= len(labels) or not labels[column])
                ]
                if missing_label_columns:
                    rejected.append((page, table, source_row_index, row, "value_without_exact_canonical_header"))
                    continue
                output.append((page, table, source_row_index, row, labels))
                continue
            expanded = _expanded_summary_headers(row, width)
            if nonempty and not any(expanded):
                rejected.append((page, table, source_row_index, row, "unknown_summary_header"))
                continue
            distinct = {value for value in expanded if value}
            if len(distinct) == 1:
                label = next(iter(distinct))
                header_paths = [[label] for _column in range(width)]
                continue
            for column, label in enumerate(expanded):
                if label and (not header_paths[column] or header_paths[column][-1] != label):
                    header_paths[column].append(label)
    return output, rejected


def _query_overview_signature(rows: list[list[str]]) -> bool:
    """Return whether a table contains the closed PBOC query-summary graph."""

    flattened = [_compact(cell) for row in rows for cell in row if _compact(cell)]
    if any(group in value for group in _QUERY_OVERVIEW_GROUPS for value in flattened):
        return True
    observed = Counter(value for value in flattened if value in _QUERY_OVERVIEW_LEAF_COUNTS)
    return sum(observed.values()) >= 3 and bool(observed.get("本人查询") or observed.get("贷后管理"))


def _query_overview_active_columns(
    table: Any,
    rows: list[list[str]],
) -> tuple[int, ...] | None:
    """Trim only source-empty terminal border bands from the PBOC lattice."""

    geometry = _native_table_geometry(table)
    if geometry is None:
        return None
    row_bands = _indexed_geometry_bands(
        geometry,
        "row_bands",
        lower_key="y0",
        upper_key="y1",
    )
    column_bands = _indexed_geometry_bands(
        geometry,
        "col_bands",
        lower_key="x0",
        upper_key="x1",
    )
    bboxes = geometry.get("cell_bboxes")
    statuses = geometry.get("cell_geometry_status")
    evidence_grid = geometry.get("cell_evidence_ids")
    metadata = getattr(table, "metadata", None) or {}
    token_grid = geometry.get("cell_token_ids") or (
        metadata.get("cell_token_ids") if isinstance(metadata, Mapping) else None
    )
    if (
        row_bands is None
        or set(row_bands) != set(range(len(rows)))
        or column_bands is None
        or set(column_bands) != set(range(len(column_bands)))
        or any(len(row) != len(column_bands) for row in rows)
        or any(not isinstance(grid, list) or len(grid) != len(rows) for grid in (bboxes, statuses, evidence_grid, token_grid))
    ):
        return None
    spans = geometry.get("cell_spans") or []
    if not isinstance(spans, list) or any(not isinstance(span, Mapping) for span in spans):
        return None
    normalized_spans: list[tuple[int, int, int, int]] = []
    for span in spans:
        try:
            normalized = (
                int(span.get("row")),
                int(span.get("col")),
                int(span.get("row_span")),
                int(span.get("col_span")),
            )
        except (TypeError, ValueError):
            return None
        if normalized[2] < 1 or normalized[3] < 1:
            return None
        normalized_spans.append(normalized)

    def empty_border(column: int) -> bool:
        for row in range(len(rows)):
            if any(
                not isinstance(grid[row], list) or len(grid[row]) != len(column_bands)
                for grid in (bboxes, statuses, evidence_grid, token_grid)
            ):
                return False
            if (
                _compact(rows[row][column])
                or evidence_grid[row][column] not in ([], None)
                or token_grid[row][column] not in ([], None)
            ):
                return False
            covering = [
                span
                for span in normalized_spans
                if span[0] <= row < span[0] + span[2]
                and span[1] <= column < span[1] + span[3]
            ]
            # A terminal band can contain a vertical border cell, but it can
            # never be the covered part of a horizontal business cell.
            if any(span[1] != column or span[3] != 1 for span in covering):
                return False
            status = str(statuses[row][column] or "")
            if status == "derived":
                if len(covering) != 1 or covering[0][0] >= row:
                    return False
                if bboxes[row][column] is not None:
                    return False
                continue
            if status != "exact":
                return False
            starts = [span for span in covering if span[0] == row]
            if len(starts) > 1 or (covering and len(starts) != 1):
                return False
            bbox = _exact_geometry_bbox(bboxes[row][column])
            if bbox is None:
                return False
            row_end = row + (starts[0][2] if starts else 1) - 1
            if row_end not in row_bands:
                return False
            expected = (
                column_bands[column][0],
                row_bands[row][0],
                column_bands[column][1],
                row_bands[row_end][1],
            )
            if any(abs(left - right) > 1.0 for left, right in zip(bbox, expected, strict=True)):
                return False
        return True

    expected_width = sum(len(leaves) for _group, leaves in _QUERY_OVERVIEW_SCHEMA)
    active = list(range(len(column_bands)))
    while len(active) > expected_width:
        if empty_border(active[0]):
            active.pop(0)
            continue
        if empty_border(active[-1]):
            active.pop()
            continue
        return None
    return tuple(active) if len(active) == expected_width else None


def _query_overview_row_atoms(
    parse_result: Any,
    table: Any,
    *,
    row: int,
    logical_page: int,
    columns: tuple[int, ...],
) -> tuple[tuple[str, tuple[float, float, float, float], str], ...] | None:
    """Resolve one complete exact table row without trusting merged-cell text order.

    OCR table reconstruction can put several values in one horizontally merged
    cell, and can attach a wide group title to the cell containing its centre.
    The immutable token boxes remain authoritative.  This helper validates the
    whole ruled row and returns those tokens; it never partitions a cell into
    equal-width synthetic columns.
    """

    geometry = _native_table_geometry(table)
    rows = _table_rows(table)
    if geometry is None or not (0 <= row < len(rows)):
        return None
    row_bands = _indexed_geometry_bands(
        geometry,
        "row_bands",
        lower_key="y0",
        upper_key="y1",
    )
    column_bands = _indexed_geometry_bands(
        geometry,
        "col_bands",
        lower_key="x0",
        upper_key="x1",
    )
    if (
        row_bands is None
        or row not in row_bands
        or column_bands is None
        or set(column_bands) != set(range(len(column_bands)))
        or not columns
        or any(column not in column_bands for column in columns)
        or len(rows[row]) != len(column_bands)
    ):
        return None
    bboxes = geometry.get("cell_bboxes")
    statuses = geometry.get("cell_geometry_status")
    evidence_grid = geometry.get("cell_evidence_ids")
    metadata = getattr(table, "metadata", None) or {}
    token_grid = geometry.get("cell_token_ids") or (
        metadata.get("cell_token_ids") if isinstance(metadata, Mapping) else None
    )
    if any(
        not isinstance(grid, list)
        or row >= len(grid)
        or not isinstance(grid[row], list)
        or len(grid[row]) != len(column_bands)
        for grid in (bboxes, statuses, evidence_grid, token_grid)
    ):
        return None
    spans = geometry.get("cell_spans") or []
    if not isinstance(spans, list) or any(not isinstance(span, Mapping) for span in spans):
        return None

    normalized_spans: list[tuple[int, int, int, int]] = []
    for span in spans:
        try:
            span_row = int(span.get("row"))
            span_column = int(span.get("col"))
            row_span = int(span.get("row_span"))
            column_span = int(span.get("col_span"))
        except (TypeError, ValueError):
            return None
        if row_span < 1 or column_span < 1:
            return None
        if span_row == row or (span_row < row < span_row + row_span):
            normalized_spans.append((span_row, span_column, row_span, column_span))

    all_tokens: list[tuple[str, tuple[float, float, float, float], str]] = []
    seen_ids: set[str] = set()
    row_y0, row_y1 = row_bands[row]
    table_x0 = column_bands[columns[0]][0]
    table_x1 = column_bands[columns[-1]][1]
    for column in columns:
        status = str(statuses[row][column] or "")
        raw = _compact(rows[row][column])
        raw_evidence = evidence_grid[row][column]
        raw_token_ids = token_grid[row][column]
        if not isinstance(raw_evidence, list) or not isinstance(raw_token_ids, list):
            return None
        evidence_ids = tuple(str(value) for value in raw_evidence if str(value or ""))
        token_ids = tuple(str(value) for value in raw_token_ids if str(value or ""))
        if len(evidence_ids) != len(set(evidence_ids)) or len(token_ids) != len(set(token_ids)):
            return None

        covering = [
            span
            for span in normalized_spans
            if span[0] <= row < span[0] + span[2]
            and span[1] <= column < span[1] + span[3]
        ]
        if status == "derived":
            if (
                raw
                or evidence_ids
                or token_ids
                or len(covering) != 1
                or covering[0][0] != row
                or covering[0][2] != 1
                or covering[0][1] >= column
            ):
                return None
            continue
        if status != "exact":
            return None
        starts = [span for span in covering if span[0] == row and span[1] == column]
        if len(starts) > 1 or (covering and len(starts) != 1):
            return None
        cell_bbox = _exact_geometry_bbox(bboxes[row][column])
        if cell_bbox is None:
            return None
        if starts:
            _span_row, _span_column, row_span, column_span = starts[0]
            if row_span != 1 or column + column_span - 1 not in column_bands:
                return None
            expected_bbox = (
                column_bands[column][0],
                row_y0,
                column_bands[column + column_span - 1][1],
                row_y1,
            )
        else:
            expected_bbox = (column_bands[column][0], row_y0, column_bands[column][1], row_y1)
        if any(abs(left - right) > 1.0 for left, right in zip(cell_bbox, expected_bbox, strict=True)):
            return None
        if not evidence_ids:
            if raw or token_ids:
                return None
            continue
        if set(evidence_ids) != set(token_ids) or seen_ids.intersection(evidence_ids):
            return None
        resolved = resolve_exact_page_token_atoms(
            parse_result,
            evidence_ids,
            logical_page=logical_page,
        )
        if resolved is None or {token[2] for token in resolved} != set(evidence_ids):
            return None
        if any(
            token_bbox[0] < table_x0 - 2.0
            or token_bbox[2] > table_x1 + 2.0
            or token_bbox[1] < row_y0 - 2.0
            or token_bbox[3] > row_y1 + 2.0
            for _text, token_bbox, _token_id in resolved
        ):
            return None
        # Raw cell strings are a lossy presentation.  Their character multiset
        # must nevertheless agree with the exact atoms, while atom geometry
        # determines semantic order.
        if Counter(raw) != Counter(_compact("".join(token[0] for token in resolved))):
            return None
        seen_ids.update(evidence_ids)
        all_tokens.extend(resolved)
    return tuple(sorted(all_tokens, key=lambda item: (item[1][0], item[1][1], item[2])))


def _query_overview_group_atoms(
    atoms: tuple[tuple[str, tuple[float, float, float, float], str], ...],
) -> tuple[
    dict[str, tuple[tuple[str, tuple[float, float, float, float], str], ...]],
    tuple[tuple[str, tuple[float, float, float, float], str], ...],
] | None:
    """Bind the three exact group labels and isolate harmless ASCII debris."""

    matches: dict[str, list[tuple[int, ...]]] = {}
    for label in _QUERY_OVERVIEW_GROUPS:
        candidates = _query_overview_label_matches(atoms, label)
        if not candidates:
            return None
        matches[label] = candidates

    assignments: list[tuple[tuple[int, ...], ...]] = []
    for selected in product(*(matches[label] for label in _QUERY_OVERVIEW_GROUPS)):
        flattened = [index for indexes in selected for index in indexes]
        if len(flattened) != len(set(flattened)):
            continue
        residue = [atoms[index] for index in range(len(atoms)) if index not in set(flattened)]
        if any(re.fullmatch(r"[A-Za-z]+", _compact(token[0])) is None for token in residue):
            continue
        assignments.append(selected)
    if len(assignments) != 1:
        return None
    selected = assignments[0]
    used = {index for indexes in selected for index in indexes}
    return (
        {
            label: tuple(atoms[index] for index in indexes)
            for label, indexes in zip(_QUERY_OVERVIEW_GROUPS, selected, strict=True)
        },
        tuple(atoms[index] for index in range(len(atoms)) if index not in used),
    )


def _query_overview_label_matches(
    atoms: tuple[tuple[str, tuple[float, float, float, float], str], ...],
    label: str,
) -> list[tuple[int, ...]]:
    """Return spatially contiguous exact atom runs spelling one role label."""

    candidates: set[tuple[int, ...]] = set()
    # A printed label is one spatially contiguous run.  Enumerating only
    # contiguous runs is both stricter and polynomial even when a damaged OCR
    # row contains many isolated flecks.
    for start in range(len(atoms)):
        for end in range(start + 1, len(atoms) + 1):
            indexes = tuple(range(start, end))
            selected = [atoms[index] for index in indexes]
            readings = {
                _compact("".join(token[0] for token in sorted(selected, key=lambda item: (item[1][0], item[1][1])))),
                _compact("".join(token[0] for token in sorted(selected, key=lambda item: (item[1][1], item[1][0])))),
            }
            if _compact(label) in readings:
                candidates.add(indexes)
    return sorted(candidates)


def _query_overview_leaf_header(
    atoms: tuple[tuple[str, tuple[float, float, float, float], str], ...],
    *,
    row_band: tuple[float, float],
    active_columns: tuple[int, ...],
    column_bands: Mapping[int, tuple[float, float]],
) -> tuple[
    list[str],
    list[tuple[float, float, float, float]],
    list[tuple[tuple[str, tuple[float, float, float, float], str], ...]],
    tuple[tuple[str, tuple[float, float, float, float], str], ...],
] | None:
    """Bind all eight exact leaf roles on one source-ruled header band."""

    requirements = [
        leaf
        for leaf, count in _QUERY_OVERVIEW_LEAF_COUNTS.items()
        for _occurrence in range(count)
    ]
    candidate_lists = {
        label: _query_overview_label_matches(atoms, label)
        for label in requirements
    }
    if any(not candidate_lists[label] for label in requirements):
        return None
    assignments: list[tuple[tuple[int, ...], ...]] = []

    def search(
        position: int,
        used: set[int],
        selected: list[tuple[int, ...]],
        last_choice: dict[str, int],
    ) -> None:
        if len(assignments) > 1:
            return
        if position == len(requirements):
            assignments.append(tuple(selected))
            return
        label = requirements[position]
        start = last_choice.get(label, -1) + 1
        for candidate_index in range(start, len(candidate_lists[label])):
            candidate = candidate_lists[label][candidate_index]
            if used.intersection(candidate):
                continue
            selected.append(candidate)
            prior = last_choice.get(label)
            last_choice[label] = candidate_index
            search(position + 1, {*used, *candidate}, selected, last_choice)
            if prior is None:
                last_choice.pop(label, None)
            else:
                last_choice[label] = prior
            selected.pop()

    search(0, set(), [], {})
    if len(assignments) != 1:
        return None
    selected = assignments[0]
    used = {index for indexes in selected for index in indexes}
    residue = tuple(atoms[index] for index in range(len(atoms)) if index not in used)
    if any(re.search(r"[\u3400-\u9fff]", _compact(token[0])) is not None for token in residue):
        return None
    by_position: dict[
        int,
        tuple[str, tuple[tuple[str, tuple[float, float, float, float], str], ...]],
    ] = {}
    for label, indexes in zip(requirements, selected, strict=True):
        owned = tuple(atoms[index] for index in indexes)
        owned_box = (
            min(token[1][0] for token in owned),
            min(token[1][1] for token in owned),
            max(token[1][2] for token in owned),
            max(token[1][3] for token in owned),
        )
        positions = [
            position
            for position, column in enumerate(active_columns)
            if owned_box[0] >= column_bands[column][0] - 2.0
            and owned_box[2] <= column_bands[column][1] + 2.0
        ]
        if len(positions) != 1 or positions[0] in by_position:
            return None
        by_position[positions[0]] = (label, owned)
    if set(by_position) != set(range(len(active_columns))):
        return None
    labels = [by_position[position][0] for position in range(len(active_columns))]
    if Counter(labels) != _QUERY_OVERVIEW_LEAF_COUNTS:
        return None
    boxes = [
        (
            column_bands[column][0],
            row_band[0],
            column_bands[column][1],
            row_band[1],
        )
        for column in active_columns
    ]
    tokens = [by_position[position][1] for position in range(len(active_columns))]
    return labels, boxes, tokens, residue


def _query_overview_collapsed_header(
    atoms: tuple[tuple[str, tuple[float, float, float, float], str], ...],
    *,
    row: int,
    row_band: tuple[float, float],
    active_columns: tuple[int, ...],
    column_bands: Mapping[int, tuple[float, float]],
) -> tuple[
    list[str],
    list[tuple[float, float, float, float]],
    list[tuple[tuple[str, tuple[float, float, float, float], str], ...]],
    dict[str, tuple[tuple[str, tuple[float, float, float, float], str], ...]],
    tuple[tuple[str, tuple[float, float, float, float], str], ...],
] | None:
    """Split one exact two-tier header row solely by immutable token boxes."""

    requirements: list[tuple[str, str]] = [
        *(('group', group) for group in _QUERY_OVERVIEW_GROUPS),
        *(
            ('leaf', leaf)
            for leaf, count in _QUERY_OVERVIEW_LEAF_COUNTS.items()
            for _occurrence in range(count)
        ),
    ]
    candidate_lists = {
        label: _query_overview_label_matches(atoms, label)
        for _kind, label in requirements
    }
    if any(not candidate_lists[label] for _kind, label in requirements):
        return None

    assignments: list[tuple[tuple[int, ...], ...]] = []

    def search(
        position: int,
        used: set[int],
        selected: list[tuple[int, ...]],
        last_choice: dict[tuple[str, str], int],
    ) -> None:
        if len(assignments) > 1:
            return
        if position == len(requirements):
            assignments.append(tuple(selected))
            return
        kind, label = requirements[position]
        key = (kind, label)
        start = last_choice.get(key, -1) + 1
        for candidate_index in range(start, len(candidate_lists[label])):
            candidate = candidate_lists[label][candidate_index]
            if used.intersection(candidate):
                continue
            selected.append(candidate)
            prior = last_choice.get(key)
            last_choice[key] = candidate_index
            search(position + 1, {*used, *candidate}, selected, last_choice)
            if prior is None:
                last_choice.pop(key, None)
            else:
                last_choice[key] = prior
            selected.pop()

    search(0, set(), [], {})
    if len(assignments) != 1:
        return None
    selected = assignments[0]
    used = {index for indexes in selected for index in indexes}
    residue = tuple(atoms[index] for index in range(len(atoms)) if index not in used)
    if any(re.search(r"[\u3400-\u9fff]", _compact(token[0])) is not None for token in residue):
        return None

    group_atoms: dict[str, tuple[tuple[str, tuple[float, float, float, float], str], ...]] = {}
    leaf_matches: list[tuple[str, tuple[tuple[str, tuple[float, float, float, float], str], ...]]] = []
    for (kind, label), indexes in zip(requirements, selected, strict=True):
        owned = tuple(atoms[index] for index in indexes)
        if kind == "group":
            group_atoms[label] = owned
        else:
            leaf_matches.append((label, owned))
    leaf_min_center = min((token[1][1] + token[1][3]) / 2.0 for _label, owned in leaf_matches for token in owned)
    if any(
        (token[1][1] + token[1][3]) / 2.0 >= leaf_min_center
        for owned in group_atoms.values()
        for token in owned
    ):
        return None

    by_position: dict[
        int,
        tuple[str, tuple[tuple[str, tuple[float, float, float, float], str], ...]],
    ] = {}
    for label, owned in leaf_matches:
        owned_box = (
            min(token[1][0] for token in owned),
            min(token[1][1] for token in owned),
            max(token[1][2] for token in owned),
            max(token[1][3] for token in owned),
        )
        positions = [
            position
            for position, column in enumerate(active_columns)
            if owned_box[0] >= column_bands[column][0] - 2.0
            and owned_box[2] <= column_bands[column][1] + 2.0
        ]
        if len(positions) != 1 or positions[0] in by_position:
            return None
        by_position[positions[0]] = (label, owned)
    if set(by_position) != set(range(len(active_columns))):
        return None
    labels = [by_position[position][0] for position in range(len(active_columns))]
    if Counter(labels) != _QUERY_OVERVIEW_LEAF_COUNTS:
        return None
    boxes = [
        (
            column_bands[column][0],
            row_band[0],
            column_bands[column][1],
            row_band[1],
        )
        for column in active_columns
    ]
    tokens = [by_position[position][1] for position in range(len(active_columns))]
    return labels, boxes, tokens, group_atoms, residue


def _query_overview_token_ref(
    page: Any,
    table: Any,
    token: tuple[str, tuple[float, float, float, float], str],
    *,
    row: int,
    column: int | None,
    field_name: str,
    binding: str,
) -> dict[str, Any]:
    ref = _source_ref(page, table)
    ref.update(
        {
            "source": "native_detail_summary_token",
            "row": row,
            "bbox": list(token[1]),
            "evidence_ids": [token[2]],
            "geometry_scope": "token",
            "field_name": field_name,
            "binding": binding,
            "binding_quality": "exact_pboc_query_overview_token",
        }
    )
    if column is not None:
        ref["column"] = column
    return ref


def _query_overview_integer_run(
    tokens: Iterable[tuple[str, tuple[float, float, float, float], str]],
) -> str | None:
    """Return one exact integer assembled from a connected OCR glyph run."""

    ordered = sorted(tokens, key=lambda item: (item[1][0], item[1][1], item[2]))
    if not ordered or any(re.fullmatch(r"\d+", _compact(token[0])) is None for token in ordered):
        return None
    for left, right in zip(ordered, ordered[1:]):
        left_box = left[1]
        right_box = right[1]
        left_height = left_box[3] - left_box[1]
        right_height = right_box[3] - right_box[1]
        vertical_overlap = min(left_box[3], right_box[3]) - max(left_box[1], right_box[1])
        left_glyph_width = (left_box[2] - left_box[0]) / len(_compact(left[0]))
        right_glyph_width = (right_box[2] - right_box[0]) / len(_compact(right[0]))
        if (
            right_box[0] < left_box[2]
            or vertical_overlap < 0.5 * min(left_height, right_height)
            or right_box[0] - left_box[2] > max(left_glyph_width, right_glyph_width)
        ):
            return None
    raw = "".join(_compact(token[0]) for token in ordered)
    return raw if _QUERY_OVERVIEW_INTEGER_RE.fullmatch(raw) is not None else None


def _bounded_query_overview_summary(
    parse_result: Any,
    page: Any,
    table: Any,
    rows: list[list[str]],
) -> tuple[dict[str, Any], list[dict[str, Any]]] | None:
    """Decode the closed PBOC query-overview graph from exact token geometry."""

    if not canonical_table_owned_by(parse_result, page, table, "information_summary"):
        return None
    geometry = _native_table_geometry(table)
    if geometry is None:
        return None
    row_bands = _indexed_geometry_bands(
        geometry,
        "row_bands",
        lower_key="y0",
        upper_key="y1",
    )
    column_bands = _indexed_geometry_bands(
        geometry,
        "col_bands",
        lower_key="x0",
        upper_key="x1",
    )
    expected_width = sum(len(leaves) for _group, leaves in _QUERY_OVERVIEW_SCHEMA)
    active_columns = _query_overview_active_columns(table, rows)
    if (
        row_bands is None
        or column_bands is None
        or active_columns is None
        or len(active_columns) != expected_width
    ):
        return None
    logical_page = int(getattr(page, "page_number", 0) or 0)
    source_page = int(getattr(page, "source_page_number", 0) or logical_page)
    if logical_page <= 0 or source_page <= 0:
        return None

    leaf_candidates: list[
        tuple[
            int,
            list[str],
            list[tuple[float, float, float, float]],
            list[tuple[tuple[str, tuple[float, float, float, float], str], ...]],
            tuple[tuple[str, tuple[float, float, float, float], str], ...],
        ]
    ] = []
    for row_index in sorted(row_bands):
        row_atoms = _query_overview_row_atoms(
            parse_result,
            table,
            row=row_index,
            logical_page=logical_page,
            columns=active_columns,
        )
        parsed_leaf = (
            _query_overview_leaf_header(
                row_atoms,
                row_band=row_bands[row_index],
                active_columns=active_columns,
                column_bands=column_bands,
            )
            if row_atoms is not None
            else None
        )
        if parsed_leaf is not None:
            labels, boxes, owned_tokens, leaf_residue = parsed_leaf
            leaf_candidates.append((row_index, labels, boxes, owned_tokens, leaf_residue))
    if len(leaf_candidates) > 1:
        return None
    header_graphs: list[
        tuple[
            int,
            int,
            int,
            list[str],
            list[tuple[float, float, float, float]],
            list[tuple[tuple[str, tuple[float, float, float, float], str], ...]],
            dict[str, tuple[tuple[str, tuple[float, float, float, float], str], ...]],
            tuple[tuple[str, tuple[float, float, float, float], str], ...],
        ]
    ] = []
    if leaf_candidates:
        leaf_row, leaf_labels, leaf_boxes, leaf_tokens, leaf_residue = leaf_candidates[0]
        group_row = leaf_row - 1
        value_row = leaf_row + 1
        if group_row in row_bands and value_row in row_bands:
            group_row_atoms = _query_overview_row_atoms(
                parse_result,
                table,
                row=group_row,
                logical_page=logical_page,
                columns=active_columns,
            )
            resolved_groups = (
                _query_overview_group_atoms(group_row_atoms)
                if group_row_atoms is not None
                else None
            )
            if resolved_groups is not None:
                group_atoms, group_residue = resolved_groups
                header_graphs.append(
                    (
                        group_row,
                        leaf_row,
                        value_row,
                        leaf_labels,
                        leaf_boxes,
                        leaf_tokens,
                        group_atoms,
                        (*group_residue, *leaf_residue),
                    )
                )

    for header_row in sorted(row_bands):
        value_row = header_row + 1
        if value_row not in row_bands:
            continue
        header_atoms = _query_overview_row_atoms(
            parse_result,
            table,
            row=header_row,
            logical_page=logical_page,
            columns=active_columns,
        )
        collapsed = (
            _query_overview_collapsed_header(
                header_atoms,
                row=header_row,
                row_band=row_bands[header_row],
                active_columns=active_columns,
                column_bands=column_bands,
            )
            if header_atoms is not None
            else None
        )
        if collapsed is None:
            continue
        labels, boxes, tokens, collapsed_groups, collapsed_residue = collapsed
        header_graphs.append(
            (
                header_row,
                header_row,
                value_row,
                labels,
                boxes,
                tokens,
                collapsed_groups,
                collapsed_residue,
            )
        )

    if len(header_graphs) != 1:
        return None
    (
        group_row,
        leaf_row,
        value_row,
        leaf_labels,
        leaf_boxes,
        leaf_tokens,
        group_atoms,
        residue_atoms,
    ) = header_graphs[0]
    value_atoms = _query_overview_row_atoms(
        parse_result,
        table,
        row=value_row,
        logical_page=logical_page,
        columns=active_columns,
    )
    if value_atoms is None:
        return None

    segment_assignments: list[dict[int, str]] = []
    for group_order in permutations(_QUERY_OVERVIEW_GROUPS):
        cursor = 0
        assignment: dict[int, str] = {}
        valid = True
        for group in group_order:
            expected_leaves = next(leaves for name, leaves in _QUERY_OVERVIEW_SCHEMA if name == group)
            end = cursor + len(expected_leaves)
            if Counter(leaf_labels[cursor:end]) != Counter(expected_leaves):
                valid = False
                break
            group_box = (
                min(token[1][0] for token in group_atoms[group]),
                min(token[1][1] for token in group_atoms[group]),
                max(token[1][2] for token in group_atoms[group]),
                max(token[1][3] for token in group_atoms[group]),
            )
            segment_left = leaf_boxes[cursor][0]
            segment_right = leaf_boxes[end - 1][2]
            if group_box[0] < segment_left - 2.0 or group_box[2] > segment_right + 2.0:
                valid = False
                break
            assignment.update({column: group for column in range(cursor, end)})
            cursor = end
        if valid and cursor == expected_width:
            segment_assignments.append(assignment)
    if len(segment_assignments) != 1:
        return None
    group_by_column = segment_assignments[0]

    value_by_column: dict[int, list[tuple[str, tuple[float, float, float, float], str]]] = defaultdict(list)
    for token in value_atoms:
        owners = [
            column
            for column, box in enumerate(leaf_boxes)
            if token[1][0] >= box[0] - 2.0 and token[1][2] <= box[2] + 2.0
        ]
        if len(owners) != 1:
            return None
        value_by_column[owners[0]].append(token)

    table_id = str(getattr(table, "table_id", "") or "")
    if not table_id:
        return None
    summary_id = stable_record_id(
        "personal_detail_summary",
        logical_page,
        table_id,
        "查询记录概要",
    )
    header_refs: list[dict[str, Any]] = []
    for column, tokens in enumerate(leaf_tokens):
        path = f"{group_by_column[column]}/{leaf_labels[column]}"
        header_refs.extend(
            _query_overview_token_ref(
                page,
                table,
                token,
                row=leaf_row,
                column=active_columns[column],
                field_name=path,
                binding="pboc_query_overview_header_role",
            )
            for token in tokens
        )
    record = {
        "record_id": summary_id,
        "summary_record_id": summary_id,
        "summary_type": "查询记录概要",
        "title": "查询记录概要",
        "source_table_id": table_id,
        "source_column_count": expected_width,
        "source_row_count": 1,
        "source": "native_pboc_query_overview_geometry",
        "source_refs": [_source_ref(page, table), *header_refs],
        "confidence": 1.0,
    }

    from docmirror.plugins.credit_report.personal_detail_scanned.extraction_issues import (
        make_issue,
        record_issue,
    )

    if residue_atoms:
        ascii_letters_only = all(
            re.fullmatch(r"[A-Za-z]+", _compact(token[0])) is not None
            for token in residue_atoms
        )
        residue_refs = [
            _query_overview_token_ref(
                page,
                table,
                token,
                row=group_row,
                column=None,
                field_name="header_structure",
                binding=(
                    "pboc_query_overview_ascii_header_residue"
                    if ascii_letters_only
                    else "pboc_query_overview_nonsemantic_header_residue"
                ),
            )
            for token in residue_atoms
        ]
        record_issue(
            parse_result,
            make_issue(
                category="ocr_structure_correction",
                issue_code=(
                    "candidate_b_query_overview_header_residue_ignored"
                    if ascii_letters_only
                    else "candidate_b_query_overview_header_residue_unresolved"
                ),
                message=(
                    "Non-semantic OCR residue was isolated from a complete exact PBOC query-overview header graph and was not used as field authority."
                ),
                severity="info" if ascii_letters_only else "warning",
                status="resolved" if ascii_letters_only else "requires_review",
                parser_stage="candidate_b_query_overview_geometry",
                target_dataset="personal_detail_summary_records",
                target_record_id=summary_id,
                field_name="header_structure",
                observed_value={"residue": [token[0] for token in residue_atoms]},
                source_refs=residue_refs,
                reason_codes=(
                    "complete_closed_pboc_query_overview_graph",
                    "ascii_only_residue" if ascii_letters_only else "non_han_header_residue",
                    "residue_not_used_as_business_authority",
                ),
            ),
        )

    cells: list[dict[str, Any]] = []
    for column, leaf in enumerate(leaf_labels):
        group = group_by_column[column]
        path = f"{group}/{leaf}"
        tokens = sorted(value_by_column.get(column, ()), key=lambda item: (item[1][0], item[1][1], item[2]))
        raw = _compact("".join(token[0] for token in tokens))
        normalized_integer = _query_overview_integer_run(tokens)
        valid = normalized_integer is not None
        cell_id = stable_record_id(
            "personal_detail_summary_cell",
            summary_id,
            1,
            column + 1,
            path,
        )
        value_refs = [
            _query_overview_token_ref(
                page,
                table,
                token,
                row=value_row,
                column=active_columns[column],
                field_name=path,
                binding="pboc_query_overview_value_token",
            )
            for token in tokens
        ]
        if not value_refs:
            slot_ref = _source_ref(page, table, row=value_row, column=active_columns[column])
            slot_ref.update(
                {
                    "field_name": path,
                    "binding": "pboc_query_overview_value_slot",
                    "binding_quality": "exact_ruled_slot_without_value_token",
                }
            )
            value_refs = [
                *[
                    _query_overview_token_ref(
                        page,
                        table,
                        token,
                        row=leaf_row,
                        column=active_columns[column],
                        field_name=path,
                        binding="pboc_query_overview_header_role",
                    )
                    for token in leaf_tokens[column]
                ],
                slot_ref,
            ]
        cell: dict[str, Any] = {
            "record_id": cell_id,
            "summary_cell_id": cell_id,
            "summary_record_id": summary_id,
            "summary_type": "查询记录概要",
            "title": "查询记录概要",
            "row_index": 1,
            "column_index": column + 1,
            "column_label": path,
            "value": normalized_integer if valid else (raw if tokens else None),
            "source": "native_pboc_query_overview_value_slot",
            "source_refs": value_refs,
            "confidence": 1.0,
        }
        if not valid:
            cell["value_status"] = "unreadable"
            record_issue(
                parse_result,
                make_issue(
                    category="ocr_cell_level_error",
                    issue_code="candidate_b_query_overview_value_unresolved",
                    message=(
                        "An exact PBOC query-overview metric slot lacked one connected strict integer glyph run; no value was invented."
                    ),
                    parser_stage="candidate_b_query_overview_geometry",
                    target_dataset="personal_detail_summary_cells",
                    target_record_id=cell_id,
                    field_name="value",
                    observed_value={
                        "metric": path,
                        "tokens": [token[0] for token in tokens],
                    },
                    source_refs=value_refs,
                    reason_codes=(
                        "complete_closed_pboc_query_overview_graph",
                        "exact_metric_slot",
                        "connected_strict_integer_glyph_run_required",
                        "normalized_value_withheld",
                    ),
                ),
            )
        cells.append(cell)
    return record, cells


_REGISTERED_SCALAR_SUMMARY_BLOCKS: tuple[tuple[str, tuple[str, ...]], ...] = (
    (
        "循环贷账户一信息汇总",
        ("管理机构数", "账户数", "授信总额", "余额", "最近6个月平均应还款"),
    ),
    (
        "循环贷账户二信息汇总",
        ("管理机构数", "账户数", "授信总额", "余额", "最近6个月平均应还款"),
    ),
    (
        "贷记卡账户信息汇总",
        (
            "发卡机构数",
            "账户数",
            "授信总额",
            "单家机构最高授信额",
            "单家机构最低授信额",
            "已用额度",
            "最近6个月平均使用额度",
        ),
    ),
)
_STRICT_REGISTERED_SUMMARY_NUMBER_RE = re.compile(r"(?:0|[1-9]\d{0,2}(?:,\d{3})*)")
_REGISTERED_SUMMARY_NUMBER_SHAPE_RE = re.compile(r"\d{1,3}(?:,\d{3})*")


def _bounded_registered_scalar_summaries(
    parse_result: Any,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]], set[tuple[int, str]]]:
    """Recover independently proved PBOC scalar-summary blocks.

    A registered title is presentation-independent semantic evidence, but it is
    never a page/template fingerprint.  Each block must own its title, complete
    header lattice, and complete value lattice on one logical page.  Other
    blocks may be absent, reordered, or added without granting authority to the
    block being decoded.
    """

    loader = getattr(parse_result, "corrected_evidence_pages", None)
    pages = loader() if callable(loader) else ()
    records: list[dict[str, Any]] = []
    cells: list[dict[str, Any]] = []
    owned: set[tuple[int, str]] = set()
    for page in pages or ():
        if not isinstance(page, Mapping):
            continue
        lines = [line for line in page.get("lines") or () if isinstance(line, Mapping)]
        texts = [_clean(line.get("text") or line.get("content") or "") for line in lines]
        title_indices: dict[str, list[int]] = {
            title: [index for index, text in enumerate(texts) if _compact(text) == _compact(title)]
            for title, _headers in _REGISTERED_SCALAR_SUMMARY_BLOCKS
        }
        logical_page = int(page.get("page") or 0)
        if logical_page <= 0:
            continue
        page_object = next(
            (
                candidate
                for candidate in getattr(parse_result, "pages", None) or ()
                if int(getattr(candidate, "page_number", 0) or 0) == logical_page
            ),
            None,
        )
        page_tables = [
            table
            for table in getattr(page_object, "tables", None) or ()
            if canonical_table_owned_by(
                parse_result,
                page_object,
                table,
                "information_summary",
            )
        ]
        line_atom_cache: dict[
            int,
            tuple[tuple[str, tuple[float, float, float, float], str], ...] | None,
        ] = {}

        def sealed_line_atoms(
            line_index: int,
        ) -> tuple[tuple[str, tuple[float, float, float, float], str], ...] | None:
            if line_index in line_atom_cache:
                return line_atom_cache[line_index]
            line_bbox = _exact_geometry_bbox(lines[line_index].get("bbox"))
            ref = _corrected_text_source_ref(page, lines[line_index], line_index)
            evidence_ids = tuple(str(value) for value in ref.get("evidence_ids") or () if value)
            if line_bbox is None or not evidence_ids or len(evidence_ids) != len(set(evidence_ids)):
                line_atom_cache[line_index] = None
                return None
            resolved = resolve_exact_page_token_atoms(
                parse_result,
                evidence_ids,
                logical_page=logical_page,
            )
            if resolved is None or any(
                token_bbox[0] < line_bbox[0]
                or token_bbox[1] < line_bbox[1]
                or token_bbox[2] > line_bbox[2]
                or token_bbox[3] > line_bbox[3]
                for _text, token_bbox, _token_id in resolved
            ):
                line_atom_cache[line_index] = None
                return None
            ordered = sorted(resolved, key=lambda token: (token[1][1], token[1][0], token[2]))
            if _compact("".join(token[0] for token in ordered)) != _compact(texts[line_index]):
                line_atom_cache[line_index] = None
                return None
            line_atom_cache[line_index] = resolved
            return resolved

        registered_sections = [
            (index, heading)
            for index, line in enumerate(lines)
            if (heading := _exact_registered_section_heading_line(line)) is not None
        ]

        def block_line_end(title_index: int) -> int:
            later_boundaries = [
                index
                for index in range(title_index + 1, len(lines))
                if (
                    re.fullmatch(
                        r"[\u3400-\u9fff（）()一二三四五六七八九十]+信息汇总",
                        _compact(texts[index]),
                    )
                    is not None
                    or _exact_registered_section_heading_line(lines[index]) is not None
                )
                and _exact_geometry_bbox(lines[index].get("bbox")) is not None
                and _corrected_text_source_ref(page, lines[index], index).get("evidence_ids")
            ]
            return min(later_boundaries) if later_boundaries else len(lines)

        def exact_token_rows(
            title_index: int,
            headers: tuple[str, ...],
            *,
            joined_header_index: int | None = None,
            joined_value_index: int | None = None,
        ) -> tuple[list[str], list[dict[str, Any]]] | None:
            title_bbox = _exact_geometry_bbox(lines[title_index].get("bbox"))
            title_atoms = sealed_line_atoms(title_index)
            if title_bbox is None or title_atoms is None:
                return None
            # Any exact ``...信息汇总`` title, including an unregistered future
            # PBOC family, closes this block.  A new block can never donate its
            # headers or values to a registered neighbour.
            line_end = block_line_end(title_index)

            # Re-OCR may preserve the first summary as ten individual lines
            # rather than a table.  Exact header text and x-banded numeric
            # lines still prove the same registered row without proximity-based
            # field shifting.
            exact_header_lines: dict[str, tuple[int, dict[str, Any]]] = {}
            for header in headers:
                matches = [
                    (index, lines[index])
                    for index in range(title_index + 1, line_end)
                    if _compact(texts[index]) == _compact(header)
                    and sealed_line_atoms(index) is not None
                ]
                if len(matches) != 1:
                    exact_header_lines = {}
                    break
                exact_header_lines[header] = matches[0]
            if len(exact_header_lines) == len(headers):
                header_centers = []
                header_boxes: list[tuple[float, float, float, float]] = []
                for header in headers:
                    bbox = _exact_geometry_bbox(exact_header_lines[header][1].get("bbox"))
                    if bbox is None:
                        return None
                    header_boxes.append(bbox)
                    header_centers.append((bbox[0] + bbox[2]) / 2.0)
                if (
                    header_centers != sorted(header_centers)
                    or max(bbox[1] for bbox in header_boxes) >= min(bbox[3] for bbox in header_boxes)
                    or any(left[2] > right[0] for left, right in zip(header_boxes, header_boxes[1:]))
                    or title_bbox[3] > min(bbox[1] for bbox in header_boxes)
                ):
                    return None
                header_bottom = max(bbox[3] for bbox in header_boxes)
                boundaries = [header_centers[0] - (header_centers[1] - header_centers[0]) / 2.0]
                boundaries.extend(
                    (left + right) / 2.0
                    for left, right in zip(header_centers, header_centers[1:])
                )
                boundaries.append(header_centers[-1] + (header_centers[-1] - header_centers[-2]) / 2.0)
                value_lines: list[list[tuple[int, dict[str, Any]]]] = [[] for _header in headers]
                for index in range(title_index + 1, line_end):
                    raw = _compact(texts[index])
                    bbox = _exact_geometry_bbox(lines[index].get("bbox"))
                    if (
                        bbox is None
                        or bbox[1] < header_bottom
                        or bbox[3] <= bbox[1]
                        or _REGISTERED_SUMMARY_NUMBER_SHAPE_RE.fullmatch(raw) is None
                        or sealed_line_atoms(index) is None
                    ):
                        continue
                    center = (bbox[0] + bbox[2]) / 2.0
                    owner = next(
                        (
                            column
                            for column in range(len(headers))
                            if boundaries[column] <= center < boundaries[column + 1]
                        ),
                        None,
                    )
                    if (
                        owner is not None
                        and bbox[0] >= boundaries[owner]
                        and bbox[2] <= boundaries[owner + 1]
                    ):
                        value_lines[owner].append((index, lines[index]))
                if all(len(values) == 1 for values in value_lines):
                    value_boxes = [
                        _exact_geometry_bbox(values[0][1].get("bbox"))
                        for values in value_lines
                    ]
                    if any(bbox is None for bbox in value_boxes) or max(
                        bbox[1] for bbox in value_boxes if bbox is not None
                    ) >= min(bbox[3] for bbox in value_boxes if bbox is not None):
                        return None
                    block_evidence_ids = [token[2] for token in title_atoms]
                    for header in headers:
                        atoms = sealed_line_atoms(exact_header_lines[header][0])
                        if atoms is None:
                            return None
                        block_evidence_ids.extend(token[2] for token in atoms)
                    for values in value_lines:
                        atoms = sealed_line_atoms(values[0][0])
                        if atoms is None:
                            return None
                        block_evidence_ids.extend(token[2] for token in atoms)
                    if len(block_evidence_ids) != len(set(block_evidence_ids)):
                        return None
                    raw_values = [_compact(texts[values[0][0]]) for values in value_lines]
                    value_refs = [
                        _corrected_text_source_ref(page, values[0][1], values[0][0])
                        for values in value_lines
                    ]
                    return raw_values, value_refs

            # Some OCR engines keep each printed row as one line. Split values
            # only when the immutable token plane independently owns every
            # numeric token and x geometry maps them one-to-one into the exact
            # printed header order. A whitespace split alone is never field
            # provenance.
            if joined_header_index is not None and joined_value_index is not None:
                header_ref = _corrected_text_source_ref(page, lines[joined_header_index], joined_header_index)
                value_ref = _corrected_text_source_ref(page, lines[joined_value_index], joined_value_index)
                header_ids = tuple(
                    dict.fromkeys(str(value) for value in header_ref.get("evidence_ids") or () if value)
                )
                value_ids = tuple(
                    dict.fromkeys(str(value) for value in value_ref.get("evidence_ids") or () if value)
                )
                title_ids = {token[2] for token in title_atoms}
                if (
                    header_ids
                    and value_ids
                    and set(header_ids).isdisjoint(value_ids)
                    and title_ids.isdisjoint(header_ids)
                    and title_ids.isdisjoint(value_ids)
                ):
                    header_tokens = sealed_line_atoms(joined_header_index)
                    value_tokens = sealed_line_atoms(joined_value_index)
                    if header_tokens is not None and value_tokens is not None:
                        ordered_headers = sorted(header_tokens, key=lambda token: (token[1][0], token[1][1], token[2]))
                        ordered_values = sorted(value_tokens, key=lambda token: (token[1][0], token[1][1], token[2]))
                        if (
                            len(ordered_headers) == len(headers)
                            and len(ordered_values) == len(headers)
                            and all(
                                _compact(token[0]) == _compact(header)
                                for token, header in zip(ordered_headers, headers, strict=True)
                            )
                            and all(
                                _REGISTERED_SUMMARY_NUMBER_SHAPE_RE.fullmatch(_compact(token[0]))
                                for token in ordered_values
                            )
                        ):
                            header_boxes = [token[1] for token in ordered_headers]
                            value_boxes = [token[1] for token in ordered_values]
                            if (
                                max(bbox[1] for bbox in header_boxes) >= min(bbox[3] for bbox in header_boxes)
                                or max(bbox[1] for bbox in value_boxes) >= min(bbox[3] for bbox in value_boxes)
                                or max(bbox[3] for bbox in header_boxes) > min(bbox[1] for bbox in value_boxes)
                                or title_bbox[3] > min(bbox[1] for bbox in header_boxes)
                                or any(left[2] > right[0] for left, right in zip(header_boxes, header_boxes[1:]))
                            ):
                                return None
                            header_centers = [(bbox[0] + bbox[2]) / 2.0 for bbox in header_boxes]
                            boundaries = [
                                header_centers[0] - (header_centers[1] - header_centers[0]) / 2.0
                            ]
                            boundaries.extend(
                                (left + right) / 2.0
                                for left, right in zip(header_centers, header_centers[1:])
                            )
                            boundaries.append(
                                header_centers[-1] + (header_centers[-1] - header_centers[-2]) / 2.0
                            )
                            owned_values: list[tuple[str, tuple[float, float, float, float], str]] = []
                            for column in range(len(headers)):
                                owned = [
                                    token
                                    for token in ordered_values
                                    if boundaries[column] <= token[1][0]
                                    and token[1][2] <= boundaries[column + 1]
                                ]
                                if len(owned) != 1:
                                    owned_values = []
                                    break
                                owned_values.append(owned[0])
                            if len(owned_values) == len(headers):
                                refs: list[dict[str, Any]] = []
                                for column, token in enumerate(owned_values):
                                    refs.append(
                                        {
                                            **value_ref,
                                            "source": "candidate_b_corrected_summary_token",
                                            "column": column,
                                            "bbox": list(token[1]),
                                            "evidence_ids": [token[2]],
                                            "geometry_scope": "token",
                                            "binding": "registered_summary_value_token",
                                            "binding_quality": "exact_token_below_registered_header",
                                        }
                                    )
                                return [_compact(token[0]) for token in owned_values], refs

            boundary_bbox = (
                _exact_geometry_bbox(lines[line_end].get("bbox"))
                if line_end < len(lines)
                else None
            )
            upper_bound = min(
                (bbox[1] for bbox in (boundary_bbox,) if bbox is not None),
                default=float("inf"),
            )
            candidates: list[
                tuple[Any, list[str], list[tuple[str, tuple[float, float, float, float], str]]]
            ] = []
            for table in page_tables:
                table_bbox = _exact_geometry_bbox(getattr(table, "bbox", None))
                if (
                    table_bbox is None
                    or table_bbox[1] < title_bbox[3]
                    or table_bbox[3] > upper_bound
                    or not table_bbox[0] <= (title_bbox[0] + title_bbox[2]) / 2.0 <= table_bbox[2]
                ):
                    continue
                token_ids: list[str] = []
                for native_row in getattr(table, "source_cell_objects", None) or ():
                    for cell in native_row or ():
                        if cell is not None:
                            token_ids.extend(str(value) for value in getattr(cell, "token_ids", None) or () if value)
                if not token_ids or len(token_ids) != len(set(token_ids)):
                    continue
                resolved = resolve_exact_page_token_atoms(
                    parse_result,
                    tuple(token_ids),
                    logical_page=logical_page,
                )
                if resolved is None:
                    continue
                tokens = list(resolved)
                geometry = _native_table_geometry(table)
                row_bands = (
                    _indexed_geometry_bands(geometry, "row_bands", lower_key="y0", upper_key="y1")
                    if geometry is not None
                    else None
                )
                column_bands = (
                    _indexed_geometry_bands(geometry, "col_bands", lower_key="x0", upper_key="x1")
                    if geometry is not None
                    else None
                )
                if row_bands is None or set(row_bands) != {0, 1}:
                    continue
                if row_bands[0][1] > row_bands[1][0]:
                    continue
                if column_bands is not None and (
                    set(column_bands) != set(range(len(column_bands)))
                    or any(
                        column_bands[index][1] > column_bands[index + 1][0]
                        for index in range(len(column_bands) - 1)
                    )
                ):
                    continue
                header_tokens = [
                    token
                    for token in tokens
                    if row_bands[0][0] <= token[1][1] and token[1][3] <= row_bands[0][1]
                ]
                value_tokens = [
                    token
                    for token in tokens
                    if row_bands[1][0] <= token[1][1] and token[1][3] <= row_bands[1][1]
                    and _REGISTERED_SUMMARY_NUMBER_SHAPE_RE.fullmatch(_compact(token[0]))
                ]
                if (
                    len(header_tokens) + len(value_tokens) != len(tokens)
                    or not {token[2] for token in title_atoms}.isdisjoint(token_ids)
                ):
                    continue
                ordered_values: list[tuple[str, tuple[float, float, float, float], str]] = []
                if column_bands is not None and set(column_bands) == set(range(len(headers))):
                    valid = True
                    for column, header in enumerate(headers):
                        band = column_bands[column]
                        owned_headers = [
                            token
                            for token in header_tokens
                            if band[0] <= token[1][0] and token[1][2] <= band[1]
                        ]
                        owned_values = [
                            token
                            for token in value_tokens
                            if band[0] <= token[1][0] and token[1][2] <= band[1]
                        ]
                        header_text = _compact(
                            "".join(
                                token[0]
                                for token in sorted(owned_headers, key=lambda token: (token[1][1], token[1][0]))
                            )
                        )
                        if header_text != _compact(header) or len(owned_values) != 1:
                            valid = False
                            break
                        ordered_values.append(owned_values[0])
                    if not valid:
                        continue
                else:
                    header_by_role: dict[
                        str,
                        list[tuple[str, tuple[float, float, float, float], str]],
                    ] = {}
                    remaining_headers = list(header_tokens)
                    for column, header in enumerate(headers):
                        compact_header = _compact(header)
                        matches: list[list[tuple[str, tuple[float, float, float, float], str]]] = []
                        for subset_size in range(1, min(3, len(remaining_headers)) + 1):
                            for subset in permutations(remaining_headers, subset_size):
                                ordered_subset = sorted(subset, key=lambda token: (token[1][1], token[1][0]))
                                if _compact("".join(token[0] for token in ordered_subset)) == compact_header:
                                    matches.append(ordered_subset)
                        if column_bands is not None and column in column_bands:
                            band = column_bands[column]
                            matches = [
                                match
                                for match in matches
                                if all(
                                    band[0] <= token[1][0] and token[1][2] <= band[1]
                                    for token in match
                                )
                            ]
                        unique_matches = {
                            tuple(token[2] for token in match): match for match in matches
                        }
                        if len(unique_matches) != 1:
                            header_by_role = {}
                            break
                        matched = next(iter(unique_matches.values()))
                        header_by_role[header] = matched
                        matched_ids = {token[2] for token in matched}
                        remaining_headers = [
                            token for token in remaining_headers if token[2] not in matched_ids
                        ]
                    if len(header_by_role) != len(headers) or remaining_headers:
                        continue
                    header_centers = [
                        sum((token[1][0] + token[1][2]) / 2.0 for token in header_by_role[header])
                        / len(header_by_role[header])
                        for header in headers
                    ]
                    if header_centers != sorted(header_centers):
                        continue
                    boundaries = [float("-inf")]
                    boundaries.extend(
                        (left + right) / 2.0 for left, right in zip(header_centers, header_centers[1:])
                    )
                    boundaries.append(float("inf"))
                    if any(
                        not all(
                            boundaries[column] <= token[1][0]
                            and token[1][2] <= boundaries[column + 1]
                            for token in header_by_role[header]
                        )
                        for column, header in enumerate(headers)
                    ):
                        continue
                    valid = True
                    for column in range(len(headers)):
                        owned = [
                            token
                            for token in value_tokens
                            if boundaries[column] <= token[1][0]
                            and token[1][2] <= boundaries[column + 1]
                        ]
                        if len(owned) != 1:
                            valid = False
                            break
                        ordered_values.append(owned[0])
                    if not valid:
                        continue
                candidates.append((table, [_compact(token[0]) for token in ordered_values], ordered_values))
            if len(candidates) != 1:
                return None
            table, raw_values, value_tokens = candidates[0]
            refs = []
            for column_index, token in enumerate(value_tokens):
                ref = _source_ref(page_object, table)
                ref.update(
                    {
                        "source": "native_detail_summary_token",
                        "logical_page": logical_page,
                        "source_page": int(page.get("source_page") or logical_page),
                        "table_id": str(getattr(table, "table_id", "") or ""),
                        "column": column_index,
                        "bbox": list(token[1]),
                        "evidence_ids": [token[2]],
                        "geometry_scope": "token",
                        "binding": "registered_summary_value_token",
                        "binding_quality": "exact_token_below_registered_header",
                    }
                )
                refs.append(ref)
            return raw_values, refs

        for title, headers in _REGISTERED_SCALAR_SUMMARY_BLOCKS:
            if len(title_indices[title]) != 1:
                continue
            title_index = title_indices[title][0]
            prior_sections = [entry for entry in registered_sections if entry[0] < title_index]
            if prior_sections and max(prior_sections, key=lambda entry: entry[0])[1] != "信息概要":
                continue
            header_index: int | None = None
            value_index: int | None = None
            joined_header_candidates: list[int] = []
            for candidate in range(title_index + 1, block_line_end(title_index)):
                residue = _compact(texts[candidate])
                complete_header = True
                for header in sorted(headers, key=len, reverse=True):
                    if residue.count(_compact(header)) != 1:
                        complete_header = False
                        break
                    residue = residue.replace(_compact(header), "", 1)
                if not complete_header or residue:
                    continue
                if not _corrected_text_source_ref(page, lines[candidate], candidate).get("evidence_ids"):
                    continue
                joined_header_candidates.append(candidate)
            if len(joined_header_candidates) == 1:
                header_index = joined_header_candidates[0]
                value_index = header_index + 1 if header_index + 1 < block_line_end(title_index) else None
            raw_values: list[str]
            value_refs: list[dict[str, Any]]
            if header_index is not None and value_index is not None:
                token_rows = exact_token_rows(
                    title_index,
                    headers,
                    joined_header_index=header_index,
                    joined_value_index=value_index,
                )
                if token_rows is None:
                    continue
                raw_values, value_refs = token_rows
            else:
                token_rows = exact_token_rows(title_index, headers)
                if token_rows is None:
                    continue
                raw_values, value_refs = token_rows

            summary_id = stable_record_id(
                "personal_detail_summary",
                logical_page,
                "corrected_registered_scalar_rows",
                title,
            )
            title_ref = _corrected_text_source_ref(page, lines[title_index], title_index)
            if not title_ref.get("evidence_ids") or "bbox" not in title_ref:
                continue
            header_refs = (
                [_corrected_text_source_ref(page, lines[header_index], header_index)]
                if header_index is not None
                else []
            )
            records.append(
                {
                    "record_id": summary_id,
                    "summary_record_id": summary_id,
                    "summary_type": re.sub(r"信息?汇总$", "", title),
                    "title": title,
                    "source_table_id": None,
                    "source_column_count": len(headers),
                    "source_row_count": 1,
                    "source": "candidate_b_corrected_registered_summary_rows",
                    "source_refs": [title_ref, *header_refs, *value_refs],
                    "confidence": 1.0,
                }
            )
            owned.add((logical_page, _compact(title)))
            for column_index, (header, raw, value_ref) in enumerate(
                zip(headers, raw_values, value_refs, strict=True),
                start=1,
            ):
                valid = _STRICT_REGISTERED_SUMMARY_NUMBER_RE.fullmatch(raw) is not None
                cell_id = stable_record_id(
                    "personal_detail_summary_cell",
                    summary_id,
                    1,
                    column_index,
                    raw,
                )
                cell = {
                    "record_id": cell_id,
                    "summary_cell_id": cell_id,
                    "summary_record_id": summary_id,
                    "summary_type": re.sub(r"信息?汇总$", "", title),
                    "title": title,
                    "row_index": 1,
                    "column_index": column_index,
                    "column_label": header,
                    "value": raw,
                    "source": "candidate_b_corrected_registered_summary_value_row",
                    "source_refs": [{**value_ref, "field_name": header}],
                    "confidence": 1.0,
                }
                if not valid:
                    cell["value_status"] = "unreadable"
                    from docmirror.plugins.credit_report.personal_detail_scanned.extraction_issues import (
                        make_issue,
                        record_issue,
                    )

                    record_issue(
                        parse_result,
                        make_issue(
                            category="ocr_cell_level_error",
                            issue_code="candidate_b_registered_summary_scalar_unreadable",
                            message=(
                                "An exact registered summary slot failed the strict grouped-number contract; "
                                "the observed OCR token was retained only as field-local evidence."
                            ),
                            parser_stage="candidate_b_summary_registered_rows",
                            target_dataset="personal_detail_summary_cells",
                            target_record_id=cell_id,
                            field_name="value",
                            observed_value=raw,
                            source_refs=cell["source_refs"],
                            reason_codes=(
                                "closed_registered_summary_block",
                                "exact_ordered_header_value_row",
                                "strict_grouped_number_contract_failed",
                                "normalized_value_withheld",
                            ),
                        ),
                    )
                cells.append(cell)
    return records, cells, owned


def _extract_summary_datasets(
    parse_result: Any,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """Project logical summary grids, including headerless cross-page fragments."""
    records, cells, registered_scalar_blocks = _bounded_registered_scalar_summaries(parse_result)
    physical: list[tuple[Any, Any, list[list[str]]]] = []
    for page in getattr(parse_result, "pages", None) or []:
        for table in getattr(page, "tables", None) or []:
            if not canonical_table_owned_by(
                parse_result,
                page,
                table,
                "information_summary",
            ):
                continue
            rows = _table_rows(table)
            if rows:
                physical.append((page, table, rows))

    # Query overview is a grouped semantic graph, not an ordinary rectangular
    # summary row.  Decode it before the generic header-fill path so merged
    # value cells can never shift a count into the neighbouring metric.
    query_consumed: set[int] = set()
    for physical_index, (page, table, rows) in enumerate(physical):
        if not _query_overview_signature(rows):
            continue
        query_consumed.add(physical_index)
        decoded_query = _bounded_query_overview_summary(
            parse_result,
            page,
            table,
            rows,
        )
        if decoded_query is not None:
            record, query_cells = decoded_query
            records.append(record)
            cells.extend(query_cells)
            continue
        from docmirror.plugins.credit_report.personal_detail_scanned.extraction_issues import (
            make_issue,
            record_issue,
        )

        record_issue(
            parse_result,
            make_issue(
                category="schema_incompleteness",
                issue_code="candidate_b_query_overview_layout_unresolved",
                message=(
                    "A PBOC query-overview signature lacked one complete exact semantic/geometry graph; all metric values were withheld."
                ),
                parser_stage="candidate_b_query_overview_geometry",
                target_dataset="personal_detail_summary_cells",
                observed_value={
                    "table_id": str(getattr(table, "table_id", "") or ""),
                    "observed_rows": len(rows),
                },
                source_refs=(_source_ref(page, table),),
                reason_codes=(
                    "pboc_query_overview_signature_observed",
                    "complete_exact_role_graph_required",
                    "positional_value_inference_forbidden",
                    "normalized_values_withheld",
                ),
            ),
        )

    continuation_check = getattr(parse_result, "tables_continue", None)
    reading_order = dict(getattr(parse_result, "reading_order_by_logical", {}) or {})
    text_evidence = _credit_overview_text_evidence(parse_result)
    consumed_text_pages: set[int] = set()
    consumed: set[int] = set()
    for index, (page, table, rows) in enumerate(physical):
        page_number = int(getattr(page, "page_number", 0) or 0)
        text_anchor = page_number in text_evidence and _is_headerless_credit_overview_fragment(rows)
        if index in query_consumed or index in consumed or (not _is_summary_anchor(rows) and not text_anchor):
            continue
        fragments = [(page, table, rows)]
        anchor_width = max((len(row) for row in rows), default=0)
        cursor = index + 1
        while cursor < len(physical):
            next_page, next_table, next_rows = physical[cursor]
            if _is_summary_anchor(next_rows):
                break
            previous_page, previous_table, _previous_rows = fragments[-1]
            previous_page_number = int(getattr(previous_page, "page_number", 0) or 0)
            next_page_number = int(getattr(next_page, "page_number", 0) or 0)
            next_width = max((len(row) for row in next_rows), default=0)
            previous_table_id = str(getattr(previous_table, "table_id", "") or "")
            next_table_id = str(getattr(next_table, "table_id", "") or "")
            previous_order = reading_order.get(previous_page_number, previous_page_number)
            next_order = reading_order.get(next_page_number, next_page_number)
            if (
                next_order != previous_order + 1
                or not callable(continuation_check)
                or continuation_check(previous_table_id, next_table_id) is not True
                or (anchor_width and next_width != anchor_width)
            ):
                break
            fragments.append((next_page, next_table, next_rows))
            consumed.add(cursor)
            cursor += 1

        title = "信用业务概要" if text_anchor else _summary_title(rows)
        if (page_number, _compact(title)) in registered_scalar_blocks:
            continue
        table_id = str(getattr(table, "table_id", "") or "")
        summary_id = stable_record_id("personal_detail_summary", page_number, table_id, title)
        business_rows, rejected_rows = _summary_business_rows(fragments, title=title)
        text_rows: list[tuple[dict[str, Any], dict[str, Any], str]] = []
        overview_evidence = text_evidence.get(page_number) if _compact(title) == "信用业务概要" else None
        if isinstance(overview_evidence, Mapping):
            remove_business_rows: set[int] = set()
            for decoded, ref, raw_text in overview_evidence.get("decoded") or ():
                if not isinstance(decoded, Mapping) or not isinstance(ref, Mapping):
                    continue
                count = decoded.get("account_count")
                month = str(decoded.get("first_business_issue_month") or "")
                business_type = str(decoded.get("business_type") or "")
                exact_matches: list[int] = []
                identity_matches: list[int] = []
                for row_index, (_row_page, _row_table, _source_index, source_row, _labels) in enumerate(business_rows):
                    if len(source_row) < 4:
                        continue
                    raw_count = _number(source_row[2])
                    raw_month = _compact(source_row[3])
                    month_match = re.fullmatch(r"((?:19|20)\d{2})[.:/-](\d{1,2})", raw_month)
                    normalized_month = (
                        f"{int(month_match.group(1)):04d}-{int(month_match.group(2)):02d}"
                        if month_match and 1 <= int(month_match.group(2)) <= 12
                        else ""
                    )
                    if raw_count is not None and raw_count == count and normalized_month == month:
                        identity_matches.append(row_index)
                        normalized_row = decode_credit_business_overview_text_line(
                            f"{source_row[1]} {source_row[2]} {source_row[3]}"
                        )
                        if normalized_row and str(normalized_row.get("business_type") or "") == business_type:
                            exact_matches.append(row_index)
                if exact_matches:
                    remove_business_rows.update(exact_matches[1:])
                    continue
                if len(identity_matches) == 1:
                    table_index = identity_matches[0]
                    source_row = business_rows[table_index][3]
                    normalized_table = decode_credit_business_overview_text_line(
                        f"{source_row[1]} {source_row[2]} {source_row[3]}"
                    )
                    table_category = str(normalized_table.get("business_type") or "") if normalized_table else ""
                    remove_business_rows.add(table_index)
                    if table_category and table_category != business_type:
                        from docmirror.plugins.credit_report.personal_detail_scanned.extraction_issues import (
                            make_issue,
                            record_issue,
                        )

                        ambiguous = dict(decoded)
                        ambiguous["business_type"] = None
                        text_rows.append((ambiguous, dict(ref), str(raw_text)))
                        record_issue(
                            parse_result,
                            make_issue(
                                category="ocr_structure_correction",
                                issue_code="candidate_b_summary_category_collision_unresolved",
                                message=(
                                    "Text and table observations shared one count/month identity but disagreed "
                                    "on the business category; the category was withheld."
                                ),
                                parser_stage="candidate_b_summary_text_table_reconciliation",
                                target_dataset="personal_detail_summary_cells",
                                target_record_id=summary_id,
                                field_name="business_type",
                                observed_value={
                                    "table_category": table_category,
                                    "text_category": business_type,
                                    "account_count": count,
                                    "first_business_issue_month": month,
                                },
                                source_refs=(ref,),
                                reason_codes=(
                                    "one_to_one_count_month_collision",
                                    "conflicting_finite_categories",
                                    "category_withheld",
                                    "duplicate_row_suppressed",
                                ),
                            ),
                        )
                    else:
                        text_rows.append((dict(decoded), dict(ref), str(raw_text)))
                    continue
                if len(identity_matches) > 1:
                    from docmirror.plugins.credit_report.personal_detail_scanned.extraction_issues import (
                        make_issue,
                        record_issue,
                    )

                    record_issue(
                        parse_result,
                        make_issue(
                            category="ocr_structure_correction",
                            issue_code="candidate_b_summary_category_collision_unresolved",
                            message=(
                                "A corrected text row matched multiple table rows by count and month but no "
                                "category matched exactly; the ambiguous text category was withheld."
                            ),
                            parser_stage="candidate_b_summary_text_table_reconciliation",
                            target_dataset="personal_detail_summary_cells",
                            target_record_id=summary_id,
                            field_name="business_type",
                            observed_value={
                                "text_category": business_type,
                                "account_count": count,
                                "first_business_issue_month": month,
                                "table_match_count": len(identity_matches),
                            },
                            source_refs=(ref,),
                            reason_codes=(
                                "one_to_many_count_month_collision",
                                "category_owner_ambiguous",
                                "text_row_withheld",
                                "duplicate_row_suppressed",
                            ),
                        ),
                    )
                    continue
                text_rows.append((dict(decoded), dict(ref), str(raw_text)))
            if remove_business_rows:
                business_rows = [
                    row for row_index, row in enumerate(business_rows) if row_index not in remove_business_rows
                ]
            consumed_text_pages.add(page_number)
        if rejected_rows:
            from docmirror.plugins.credit_report.personal_detail_scanned.extraction_issues import (
                make_issue,
                record_issue,
            )

            for rejected_page, rejected_table, rejected_row_index, rejected_row, reason in rejected_rows:
                record_issue(
                    parse_result,
                    make_issue(
                        category="ocr_structure_correction",
                        issue_code="candidate_b_summary_layout_unresolved",
                        message=(
                            "A canonical summary row could not be bound to the finite summary template; "
                            "its cells were withheld instead of inheriting positional labels."
                        ),
                        parser_stage="candidate_b_summary_canonical_slots",
                        target_dataset="personal_detail_summary_cells",
                        observed_value={"row": rejected_row, "reason": reason},
                        source_refs=(
                            _source_ref(
                                rejected_page,
                                rejected_table,
                                row=rejected_row_index,
                            ),
                        ),
                        reason_codes=(
                            "canonical_summary_table_observed",
                            reason,
                            "header_fill_inference_forbidden",
                            "normalized_cells_withheld",
                        ),
                    ),
                )
        if not business_rows and not text_rows:
            from docmirror.plugins.credit_report.personal_detail_scanned.extraction_issues import (
                make_issue,
                record_issue,
            )

            record_issue(
                parse_result,
                make_issue(
                    category="schema_incompleteness",
                    issue_code="candidate_b_summary_anchor_without_usable_rows",
                    message="A canonical summary anchor was observed but yielded zero usable business rows.",
                    parser_stage="candidate_b_summary_canonical_slots",
                    target_dataset="personal_detail_summary_cells",
                    target_record_id=summary_id,
                    observed_value={"title": title, "usable_row_count": 0},
                    source_refs=(
                        _source_ref(fragment_page, fragment_table)
                        for fragment_page, fragment_table, _fragment_rows in fragments
                    ),
                    reason_codes=(
                        "canonical_summary_anchor_observed",
                        "zero_usable_rows",
                        "silent_drop_prevented",
                    ),
                ),
            )
        records.append(
            {
                "record_id": summary_id,
                "summary_record_id": summary_id,
                "summary_type": re.sub(r"信息?汇总$", "", title) or title,
                "title": title,
                "source_table_id": table_id,
                "source_column_count": max(
                    (len(row) for _fragment_page, _fragment_table, fragment_rows in fragments for row in fragment_rows),
                    default=0,
                ),
                "source_row_count": len(text_rows) + len(business_rows),
                "source": "native_personal_detail_summary_table",
                "source_refs": [
                    *[_source_ref(fragment_page, fragment_table) for fragment_page, fragment_table, _ in fragments],
                    *[ref for _decoded, ref, _raw_text in text_rows],
                ],
                "confidence": 1.0,
            }
        )
        for logical_row_index, (decoded, ref, raw_text) in enumerate(text_rows, start=1):
            for column_index, (header, value) in enumerate(
                (
                    ("业务类型", decoded.get("business_type")),
                    ("账户数", decoded.get("account_count")),
                    ("首笔业务发放月份", decoded.get("first_business_issue_month")),
                ),
                start=2,
            ):
                if value in (None, ""):
                    continue
                cell_id = stable_record_id(
                    "personal_detail_summary_cell",
                    summary_id,
                    logical_row_index,
                    column_index,
                    value,
                )
                cells.append(
                    {
                        "record_id": cell_id,
                        "summary_cell_id": cell_id,
                        "summary_record_id": summary_id,
                        "summary_type": "信用业务概要",
                        "title": "信用业务概要",
                        "row_index": logical_row_index,
                        "column_index": column_index,
                        "column_label": header,
                        "value": str(value),
                        "canonical_raw": {"value": raw_text},
                        "source": "candidate_b_corrected_summary_text_row",
                        "source_refs": [ref],
                        "confidence": 1.0,
                    }
                )
        for logical_row_index, (source_page, source_table, source_row_index, row, labels) in enumerate(
            business_rows, start=len(text_rows) + 1
        ):
            for column_index, value in enumerate(row, start=1):
                value = _clean(value)
                if not value:
                    continue
                header = labels[column_index - 1] if column_index <= len(labels) else ""
                if _compact(title) == "信用业务概要" and header == "业务分组":
                    # 贷款/信用卡/其他 is a merged visual group label, not the
                    # row's individualized business category.
                    continue
                cell_id = stable_record_id(
                    "personal_detail_summary_cell",
                    summary_id,
                    logical_row_index,
                    column_index,
                    value,
                )
                cells.append(
                    {
                        "record_id": cell_id,
                        "summary_cell_id": cell_id,
                        "summary_record_id": summary_id,
                        "summary_type": re.sub(r"信息?汇总$", "", title) or title,
                        "title": title,
                        "row_index": logical_row_index,
                        "column_index": column_index,
                        "column_label": header or None,
                        "value": value,
                        "source": "native_personal_detail_summary_cell",
                        "source_refs": [
                            _source_ref(
                                source_page,
                                source_table,
                                row=source_row_index,
                                column=column_index - 1,
                            )
                        ],
                        "confidence": 1.0,
                    }
                )
        if isinstance(overview_evidence, Mapping):
            from docmirror.plugins.credit_report.personal_detail_scanned.extraction_issues import (
                make_issue,
                record_issue,
            )

            for raw_text, ref in overview_evidence.get("unresolved") or ():
                record_issue(
                    parse_result,
                    make_issue(
                        category="ocr_cell_level_error",
                        issue_code="candidate_b_summary_text_row_unresolved",
                        message=(
                            "A canonical credit-overview text row failed its finite category/count/month "
                            "contract and was withheld rather than guessed."
                        ),
                        parser_stage="candidate_b_summary_text_fallback",
                        target_dataset="personal_detail_summary_cells",
                        target_record_id=summary_id,
                        observed_value=raw_text,
                        source_refs=(ref,),
                        reason_codes=(
                            "canonical_credit_overview_text_header",
                            "typed_summary_row_contract_failed",
                            "normalized_cells_withheld",
                        ),
                    ),
                )
    for page_number, overview_evidence in text_evidence.items():
        if page_number in consumed_text_pages:
            continue
        decoded_rows = list(overview_evidence.get("decoded") or ())
        unresolved_rows = list(overview_evidence.get("unresolved") or ())
        summary_id = stable_record_id(
            "personal_detail_summary",
            page_number,
            "corrected_text",
            "信用业务概要",
        )
        source_refs = [dict(ref) for _decoded, ref, _raw_text in decoded_rows if isinstance(ref, Mapping)]
        source_refs.extend(
            dict(ref)
            for ref in overview_evidence.get("header_refs") or ()
            if isinstance(ref, Mapping) and dict(ref) not in source_refs
        )
        if not decoded_rows:
            from docmirror.plugins.credit_report.personal_detail_scanned.extraction_issues import (
                make_issue,
                record_issue,
            )

            record_issue(
                parse_result,
                make_issue(
                    category="schema_incompleteness",
                    issue_code="candidate_b_summary_anchor_without_usable_rows",
                    message="A canonical summary text anchor was observed but yielded zero usable business rows.",
                    parser_stage="candidate_b_summary_text_fallback",
                    target_dataset="personal_detail_summary_cells",
                    target_record_id=summary_id,
                    observed_value={"title": "信用业务概要", "usable_row_count": 0},
                    source_refs=source_refs,
                    reason_codes=(
                        "canonical_summary_anchor_observed",
                        "zero_usable_rows",
                        "silent_drop_prevented",
                    ),
                ),
            )
        records.append(
            {
                "record_id": summary_id,
                "summary_record_id": summary_id,
                "summary_type": "信用业务概要",
                "title": "信用业务概要",
                "source_table_id": None,
                "source_column_count": 4,
                "source_row_count": len(decoded_rows),
                "source": "candidate_b_corrected_summary_text",
                "source_refs": source_refs,
                "confidence": 1.0,
            }
        )
        for logical_row_index, (decoded, ref, raw_text) in enumerate(decoded_rows, start=1):
            for column_index, (header, value) in enumerate(
                (
                    ("业务类型", decoded.get("business_type")),
                    ("账户数", decoded.get("account_count")),
                    ("首笔业务发放月份", decoded.get("first_business_issue_month")),
                ),
                start=2,
            ):
                if value in (None, ""):
                    continue
                cell_id = stable_record_id(
                    "personal_detail_summary_cell",
                    summary_id,
                    logical_row_index,
                    column_index,
                    value,
                )
                cells.append(
                    {
                        "record_id": cell_id,
                        "summary_cell_id": cell_id,
                        "summary_record_id": summary_id,
                        "summary_type": "信用业务概要",
                        "title": "信用业务概要",
                        "row_index": logical_row_index,
                        "column_index": column_index,
                        "column_label": header,
                        "value": str(value),
                        "canonical_raw": {"value": raw_text},
                        "source": "candidate_b_corrected_summary_text_row",
                        "source_refs": [dict(ref)],
                        "confidence": 1.0,
                    }
                )
        if unresolved_rows:
            from docmirror.plugins.credit_report.personal_detail_scanned.extraction_issues import (
                make_issue,
                record_issue,
            )

            for raw_text, ref in unresolved_rows:
                record_issue(
                    parse_result,
                    make_issue(
                        category="ocr_cell_level_error",
                        issue_code="candidate_b_summary_text_row_unresolved",
                        message=(
                            "A canonical credit-overview text row failed its finite category/count/month "
                            "contract and was withheld rather than guessed."
                        ),
                        parser_stage="candidate_b_summary_text_fallback",
                        target_dataset="personal_detail_summary_cells",
                        target_record_id=summary_id,
                        observed_value=raw_text,
                        source_refs=(ref,),
                        reason_codes=(
                            "canonical_credit_overview_text_header",
                            "typed_summary_row_contract_failed",
                            "normalized_cells_withheld",
                        ),
                    ),
                )
    return records, cells


def _extract_recovery_records(parse_result: Any) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    for page in getattr(parse_result, "pages", None) or []:
        for table in getattr(page, "tables", None) or []:
            if not canonical_table_owned_by(
                parse_result,
                page,
                table,
                "credit_account_detail",
            ):
                continue
            rows = _table_rows(table)
            compact = _compact(" ".join(cell for row in rows[:3] for cell in row))
            if "债权接收日期" not in compact or "原债权人" not in compact:
                continue
            sequence = len(records) + 1
            provisional_id = stable_record_id(
                "recovery_unresolved",
                int(getattr(page, "page_number", 0) or 0),
                str(getattr(table, "table_id", "") or ""),
            )
            record = _decode_exact_label_card(
                parse_result,
                page=page,
                table=table,
                dataset="recovery_records",
                target_record_id=provisional_id,
                fields={
                    "institution": (("管理机构",), "text"),
                    "business_type": (("业务种类",), "text"),
                    "debt_received_date": (("债权接收日期",), "date"),
                    "original_creditor": (("原债权人",), "text"),
                    "original_business_type": (("原债务业务种类",), "text"),
                    "debt_amount": (("债权金额",), "number"),
                    "transfer_repayment_status": (("债权转移时的还款状态",), "text"),
                    "account_status": (("账户状态",), "text"),
                    "balance": (("余额",), "number"),
                    "last_repayment_date": (("最近一次还款日期",), "date"),
                    "close_date": (("账户关闭日期",), "date"),
                },
            )
            received_date = record.get("debt_received_date")
            institution = record.get("institution")
            recovery_id = (
                stable_record_id("recovery", institution, received_date, sequence)
                if institution and received_date
                else provisional_id
            )
            record.update(
                {
                    "recovery_record_id": recovery_id,
                    "sequence": sequence,
                    "snapshot_date": next(
                        (
                            _date("-".join(match.groups()))
                            for row in rows
                            if (match := _AS_OF_RE.search(_clean(" ".join(row))))
                        ),
                        None,
                    ),
                    "reporting_amount_currency": "CNY",
                    "reporting_amount_unit": "yuan",
                    "source": "native_detail_recovery_table",
                    "confidence": float(getattr(table, "confidence", None) or 0.9),
                }
            )
            if recovery_id != provisional_id:
                for issue in getattr(parse_result, "_personal_detail_extraction_issues", []) or []:
                    if isinstance(issue, dict) and issue.get("target_record_id") == provisional_id:
                        issue["target_record_id"] = recovery_id
            records.append(record)
    return records


def _iso_report_time(parts: tuple[str, str, str, str, str, str]) -> str | None:
    try:
        value = datetime(*(int(part) for part in parts))
    except ValueError:
        return None
    return value.isoformat(timespec="seconds") + "+08:00"


def _strict_report_time(compact: str, report_number: str | None) -> str | None:
    standard = re.search(
        r"报告时间[:：]?(20\d{2})[.年/-](\d{1,2})[.月/-](\d{1,2})日?(\d{1,2}):(\d{2}):(\d{2})",
        compact,
    )
    if standard:
        return _iso_report_time(tuple(standard.groups()))

    # One recurring scan form deletes a single date digit, e.g.
    # ``2023.01314:45:37``.  Recover it only when the report-number timestamp
    # is valid and deleting exactly one of its digits reproduces the complete
    # malformed timestamp evidence.  This is cross-field source agreement,
    # not a date guess.
    damaged = re.search(r"报告时间[:：]?((?:19|20)\d{2}[.年/-]\d{3,6}:\d{2}:\d{2})", compact)
    prefix = str(report_number or "")[:14]
    if damaged is None or not re.fullmatch(r"\d{14}", prefix):
        return None
    source_digits = re.sub(r"\D", "", damaged.group(1))
    if len(source_digits) != 13 or not any(
        prefix[:index] + prefix[index + 1 :] == source_digits for index in range(len(prefix))
    ):
        return None
    return _iso_report_time((prefix[0:4], prefix[4:6], prefix[6:8], prefix[8:10], prefix[10:12], prefix[12:14]))


def _strict_header_positive_int(value: Any) -> int | None:
    return value if isinstance(value, int) and not isinstance(value, bool) and value > 0 else None


def _strict_header_nonnegative_int(value: Any) -> int | None:
    return value if isinstance(value, int) and not isinstance(value, bool) and value >= 0 else None


def _strict_header_evidence_ids(value: Any) -> tuple[str, ...] | None:
    """Keep one immutable evidence-ID sequence without coercion or member loss."""

    if not isinstance(value, (list, tuple)) or not value:
        return None
    if any(
        not isinstance(item, str) or not item.strip() or item != item.strip()
        for item in value
    ):
        return None
    evidence_ids = tuple(value)
    return evidence_ids if len(evidence_ids) == len(set(evidence_ids)) else None


def _strict_header_page_identity(page: Any) -> tuple[int, int] | None:
    logical_page = _strict_header_positive_int(getattr(page, "page_number", None))
    source_page = _strict_header_positive_int(
        getattr(page, "source_page_number", None)
    )
    return (
        (logical_page, source_page)
        if logical_page is not None and source_page is not None
        else None
    )


def _header_native_evidence_occurrences(
    pages: Iterable[Any],
    evidence_ids: tuple[str, ...],
) -> tuple[
    tuple[
        tuple[int, int, str, int, int, tuple[float, float, float, float], tuple[str, ...], str],
        tuple[int, int, tuple[float, float, float, float], tuple[str, ...], str],
    ],
    ...,
] | None:
    """Inventory every physical native cell that reuses any requested ID."""

    requested = set(evidence_ids)
    occurrences: dict[
        tuple[int, int, str, int, int, tuple[float, float, float, float], tuple[str, ...], str],
        tuple[int, int, tuple[float, float, float, float], tuple[str, ...], str],
    ] = {}
    for page in pages:
        page_identity = _strict_header_page_identity(page)
        for table in getattr(page, "tables", None) or ():
            metadata = getattr(table, "metadata", None) or {}
            if not isinstance(metadata, Mapping):
                continue
            geometry = metadata.get("geometry")
            grids = [metadata.get("cell_evidence_ids")]
            if isinstance(geometry, Mapping):
                grids.append(geometry.get("cell_evidence_ids"))
            table_id = getattr(table, "table_id", None)
            for grid in grids:
                if not isinstance(grid, list):
                    continue
                for row, raw_row in enumerate(grid):
                    if not isinstance(raw_row, list):
                        continue
                    for column, raw_ids in enumerate(raw_row):
                        if not (
                            isinstance(raw_ids, (list, tuple))
                            and any(
                                isinstance(item, str) and item in requested
                                for item in raw_ids
                            )
                        ):
                            continue
                        strict_ids = _strict_header_evidence_ids(raw_ids)
                        if (
                            strict_ids is None
                            or page_identity is None
                            or not isinstance(table_id, str)
                            or not table_id.strip()
                        ):
                            return None
                        ref = _source_ref(page, table, row=row, column=column)
                        bbox = _exact_geometry_bbox(ref.get("bbox"))
                        rows = _table_rows(table)
                        if (
                            bbox is None
                            or row >= len(rows)
                            or column >= len(rows[row])
                        ):
                            return None
                        logical_page, source_page = page_identity
                        text = _compact(rows[row][column])
                        owner = (
                            logical_page,
                            source_page,
                            table_id,
                            row,
                            column,
                            bbox,
                            strict_ids,
                            text,
                        )
                        occurrences[owner] = (
                            logical_page,
                            source_page,
                            bbox,
                            strict_ids,
                            text,
                        )
    return tuple((owner, physical) for owner, physical in occurrences.items())


def _header_corrected_evidence_occurrences(
    pages: Iterable[Any],
    evidence_ids: tuple[str, ...],
) -> tuple[
    tuple[
        tuple[int, int, int, int, tuple[float, float, float, float], tuple[str, ...], str],
        tuple[int, int, tuple[float, float, float, float], tuple[str, ...], str],
    ],
    ...,
] | None:
    """Inventory every corrected line that reuses any requested evidence ID."""

    requested = set(evidence_ids)
    occurrences: list[
        tuple[
            tuple[int, int, int, int, tuple[float, float, float, float], tuple[str, ...], str],
            tuple[int, int, tuple[float, float, float, float], tuple[str, ...], str],
        ]
    ] = []
    for page_index, page in enumerate(pages):
        if not isinstance(page, Mapping):
            continue
        raw_logical_page = page.get("page")
        raw_source_page = page.get("source_page")
        for line_index, line in enumerate(page.get("lines") or ()):
            if not isinstance(line, Mapping):
                continue
            raw_ids = line.get("evidence_ids")
            if not (
                isinstance(raw_ids, (list, tuple))
                and any(
                    isinstance(item, str) and item in requested
                    for item in raw_ids
                )
            ):
                continue
            strict_ids = _strict_header_evidence_ids(raw_ids)
            logical_page = _strict_header_positive_int(
                line.get("source_logical_page", raw_logical_page)
            )
            source_page = _strict_header_positive_int(
                line.get("source_page", raw_source_page)
            )
            bbox = _exact_geometry_bbox(line.get("source_bbox") or line.get("bbox"))
            text = _compact(line.get("text") or line.get("content"))
            if (
                strict_ids is None
                or logical_page is None
                or source_page is None
                or bbox is None
                or not text
            ):
                return None
            physical = (logical_page, source_page, bbox, strict_ids, text)
            occurrences.append(
                (
                    (
                        logical_page,
                        source_page,
                        page_index,
                        line_index,
                        bbox,
                        strict_ids,
                        text,
                    ),
                    physical,
                )
            )
    return tuple(occurrences)


def _report_header_page_owned(page: Any, table: Any | None = None) -> bool:
    """Return whether canonical registration owns this PBOC header source."""

    if table is None:
        return (
            str(getattr(page, "canonical_template_id", "") or "")
            == "report_header_and_identity"
        )
    return canonical_table_owned_by(
        None,
        page,
        table,
        "report_header_and_identity",
    )


def _exact_report_header_cell_ref(
    page: Any,
    table: Any,
    *,
    row: int,
    column: int,
    field_name: str,
) -> dict[str, Any] | None:
    """Bind a semantic header field to one sealed, exact native source cell."""

    page_identity = _strict_header_page_identity(page)
    if (
        page_identity is None
        or _strict_header_nonnegative_int(row) is None
        or _strict_header_nonnegative_int(column) is None
        or not _report_header_page_owned(page, table)
    ):
        return None
    metadata = getattr(table, "metadata", None) or {}
    if not isinstance(metadata, Mapping):
        return None
    geometry = metadata.get("geometry")
    grids: list[Mapping[str, Any]] = [metadata]
    if isinstance(geometry, Mapping):
        grids.append(geometry)

    status = None
    for grid in grids:
        raw_status = grid.get("cell_geometry_status")
        if (
            isinstance(raw_status, list)
            and 0 <= row < len(raw_status)
            and isinstance(raw_status[row], list)
            and 0 <= column < len(raw_status[row])
        ):
            status = str(raw_status[row][column] or "")
            break
    if status != "exact":
        return None

    ref = _source_ref(page, table, row=row, column=column)
    bbox = _exact_geometry_bbox(ref.get("bbox"))
    normalized_ids = _strict_header_evidence_ids(ref.get("evidence_ids"))
    logical_page = _strict_header_positive_int(ref.get("logical_page"))
    source_page = _strict_header_positive_int(ref.get("source_page"))
    ref_row = _strict_header_nonnegative_int(ref.get("row"))
    ref_column = _strict_header_nonnegative_int(ref.get("column"))
    if (
        str(ref.get("source") or "") != "native_detail_table_cell"
        or str(ref.get("geometry_scope") or "") != "cell"
        or bbox is None
        or normalized_ids is None
        or logical_page != page_identity[0]
        or source_page != page_identity[1]
        or ref_row != row
        or ref_column != column
        or not str(ref.get("table_id") or "")
    ):
        return None
    occurrences = _header_native_evidence_occurrences((page,), normalized_ids)
    table_id = str(ref.get("table_id") or "")
    rows = _table_rows(table)
    if row >= len(rows) or column >= len(rows[row]):
        return None
    expected_owner = (
        logical_page,
        source_page,
        table_id,
        row,
        column,
        bbox,
        normalized_ids,
        _compact(rows[row][column]),
    )
    if occurrences is None or {owner for owner, _physical in occurrences} != {
        expected_owner
    }:
        return None
    ref.update(
        {
            "bbox": list(bbox),
            "evidence_ids": list(normalized_ids),
            "field_name": field_name,
            "canonical_template_id": "report_header_and_identity",
        }
    )
    return ref


def _exact_parser_report_header_field_ref(
    parse_result: Any,
    candidate: Any,
    *,
    label: str,
    field_name: str,
    value: str,
) -> dict[str, Any] | None:
    """Authorize one parser value only through its unique physical header cell."""

    if str(getattr(candidate, "dataset_name", "") or "") != "report_header":
        return None
    observed_labels = getattr(candidate, "observed_labels", frozenset()) or frozenset()
    unresolved_labels = getattr(candidate, "unresolved_labels", frozenset()) or frozenset()
    if label not in observed_labels or label in unresolved_labels:
        return None
    fields = getattr(candidate, "fields", None)
    refs_by_field = getattr(candidate, "source_refs_by_field", None)
    bindings_by_field = getattr(candidate, "binding_quality_by_field", None)
    if not (
        isinstance(fields, Mapping)
        and _compact(fields.get(label)) == _compact(value)
        and isinstance(refs_by_field, Mapping)
        and isinstance(bindings_by_field, Mapping)
    ):
        return None
    raw_refs = refs_by_field.get(label)
    if not isinstance(raw_refs, (list, tuple)) or len(raw_refs) != 1:
        return None
    raw_ref = raw_refs[0]
    if not isinstance(raw_ref, Mapping):
        return None

    bbox = _exact_geometry_bbox(raw_ref.get("bbox"))
    normalized_ids = _strict_header_evidence_ids(raw_ref.get("evidence_ids"))
    logical_page = _strict_header_positive_int(raw_ref.get("logical_page"))
    source_page = _strict_header_positive_int(raw_ref.get("source_page"))
    if (
        bbox is None
        or normalized_ids is None
        or logical_page is None
        or source_page is None
        or str(raw_ref.get("geometry_scope") or "") != "cell"
        or str(raw_ref.get("field_name") or "") != label
    ):
        return None

    source = str(raw_ref.get("source") or "")
    binding = str(raw_ref.get("binding") or "")
    binding_quality = str(bindings_by_field.get(label) or "")
    if source == "native_detail_tolerant_table_cell":
        if binding != "label_column" or binding_quality != "native_label_column":
            return None
        table_id = str(raw_ref.get("table_id") or "")
        row = _strict_header_nonnegative_int(raw_ref.get("row"))
        column = _strict_header_nonnegative_int(raw_ref.get("column"))
        if not table_id or row is None or column is None:
            return None
        owners: list[tuple[Any, Any]] = []
        for page in getattr(parse_result, "pages", None) or ():
            if _strict_header_page_identity(page) != (logical_page, source_page):
                continue
            for table in getattr(page, "tables", None) or ():
                if (
                    str(getattr(table, "table_id", "") or "") != table_id
                    or not _report_header_page_owned(page, table)
                ):
                    continue
                rows = _table_rows(table)
                if (
                    0 <= row < len(rows)
                    and 0 <= column < len(rows[row])
                    and _compact(rows[row][column]) == _compact(value)
                ):
                    owners.append((page, table))
        if len(owners) != 1:
            return None
        page, table = owners[0]
        exact_ref = _exact_report_header_cell_ref(
            page,
            table,
            row=row,
            column=column,
            field_name=field_name,
        )
        if exact_ref is None:
            return None
        exact_bbox = _exact_geometry_bbox(exact_ref.get("bbox"))
        exact_ids = _strict_header_evidence_ids(exact_ref.get("evidence_ids"))
        exact_logical_page = _strict_header_positive_int(
            exact_ref.get("logical_page")
        )
        exact_source_page = _strict_header_positive_int(exact_ref.get("source_page"))
        if (
            exact_bbox != bbox
            or exact_ids != normalized_ids
            or exact_logical_page != logical_page
            or exact_source_page != source_page
            or str(exact_ref.get("table_id") or "") != table_id
        ):
            return None
        all_pages = tuple(getattr(parse_result, "pages", None) or ())
        native_occurrences = _header_native_evidence_occurrences(
            all_pages,
            normalized_ids,
        )
        expected_physical = (
            logical_page,
            source_page,
            bbox,
            normalized_ids,
            _compact(value),
        )
        if (
            native_occurrences is None
            or len(native_occurrences) != 1
            or native_occurrences[0][1] != expected_physical
        ):
            return None
        evidence_loader = getattr(parse_result, "corrected_evidence_pages", None)
        if callable(evidence_loader):
            corrected_occurrences = _header_corrected_evidence_occurrences(
                tuple(evidence_loader() or ()),
                normalized_ids,
            )
            if corrected_occurrences is None or any(
                physical != expected_physical
                for _owner, physical in corrected_occurrences
            ):
                return None
        return exact_ref

    if source != "personal_detail_corrected_page_cell":
        return None
    if binding != "canonical_label_slot" or binding_quality != "canonical_cell_slot":
        return None
    registered_owners = [
        page
        for page in getattr(parse_result, "pages", None) or ()
        if _strict_header_page_identity(page) == (logical_page, source_page)
        and _report_header_page_owned(page)
    ]
    if len(registered_owners) != 1:
        return None
    loader = getattr(parse_result, "corrected_evidence_pages", None)
    if not callable(loader):
        return None
    all_evidence_pages = tuple(loader() or ())
    evidence_pages = [
        page
        for page in all_evidence_pages
        if isinstance(page, Mapping)
        and _strict_header_positive_int(page.get("page")) == logical_page
        and _strict_header_positive_int(page.get("source_page")) == source_page
        and str(page.get("canonical_template_id") or "")
        == "report_header_and_identity"
    ]
    if len(evidence_pages) != 1:
        return None
    matching_lines: list[Mapping[str, Any]] = []
    for line in evidence_pages[0].get("lines") or ():
        if not isinstance(line, Mapping):
            continue
        line_bbox = _exact_geometry_bbox(line.get("source_bbox") or line.get("bbox"))
        line_ids = _strict_header_evidence_ids(line.get("evidence_ids"))
        if (
            line_bbox == bbox
            and line_ids == normalized_ids
            and _compact(line.get("text") or line.get("content")) == _compact(value)
            and _strict_header_positive_int(
                line.get("source_logical_page", logical_page)
            )
            == logical_page
            and _strict_header_positive_int(line.get("source_page", source_page))
            == source_page
        ):
            matching_lines.append(line)
    if len(matching_lines) != 1:
        return None
    expected_physical = (
        logical_page,
        source_page,
        bbox,
        normalized_ids,
        _compact(value),
    )
    corrected_occurrences = _header_corrected_evidence_occurrences(
        all_evidence_pages,
        normalized_ids,
    )
    native_occurrences = _header_native_evidence_occurrences(
        tuple(getattr(parse_result, "pages", None) or ()),
        normalized_ids,
    )
    if (
        corrected_occurrences is None
        or len(corrected_occurrences) != 1
        or corrected_occurrences[0][1] != expected_physical
        or native_occurrences is None
        or any(
            physical != expected_physical
            for _owner, physical in native_occurrences
        )
    ):
        return None
    return {
        **dict(raw_ref),
        "bbox": list(bbox),
        "evidence_ids": list(normalized_ids),
        "field_name": field_name,
        "binding": "canonical_field_slot",
        "binding_quality": "canonical_cell_slot",
        "canonical_template_id": "report_header_and_identity",
    }


def _bounded_other_identity_documents(
    pages: Iterable[Any],
) -> list[dict[str, Any]]:
    """Decode source-owned PBOC ``其他证件信息`` rows without spouse leakage."""

    owners: list[tuple[Any, Any, list[list[str]], int]] = []
    for page in pages:
        for table in getattr(page, "tables", None) or ():
            if not _report_header_page_owned(page, table):
                continue
            rows = _table_rows(table)
            title_rows = [
                index
                for index, row in enumerate(rows)
                if [_compact(cell) for cell in row if _compact(cell)]
                == ["其他证件信息"]
            ]
            for title_row in title_rows:
                if _exact_report_header_cell_ref(
                    page,
                    table,
                    row=title_row,
                    column=next(
                        column
                        for column, cell in enumerate(rows[title_row])
                        if _compact(cell) == "其他证件信息"
                    ),
                    field_name="identity_document_section",
                ) is not None:
                    owners.append((page, table, rows, title_row))
    # A duplicated title is not authority for choosing one physical owner.
    if len(owners) != 1:
        return []

    page, table, rows, title_row = owners[0]
    header_row = title_row + 1
    if header_row >= len(rows):
        return []
    slots = _canonical_header_slots(
        tuple(rows[header_row]),
        {
            "document_type": ("证件类型",),
            "document_number": ("证件号码",),
        },
    )
    if set(slots) != {"document_type", "document_number"} or len(set(slots.values())) != 2:
        return []
    if any(
        _exact_report_header_cell_ref(
            page,
            table,
            row=header_row,
            column=column,
            field_name=field_name,
        )
        is None
        for field_name, column in slots.items()
    ):
        return []

    documents: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    for row_index in range(header_row + 1, len(rows)):
        row = rows[row_index]
        nonempty_columns = {
            column for column, cell in enumerate(row) if _compact(cell)
        }
        if not nonempty_columns:
            continue
        if not nonempty_columns <= set(slots.values()):
            return []
        document_type = _clean(
            row[slots["document_type"]]
            if slots["document_type"] < len(row)
            else ""
        )
        document_number = _compact(
            row[slots["document_number"]]
            if slots["document_number"] < len(row)
            else ""
        )
        refs: list[dict[str, Any]] = []
        for field_name, value in (
            ("document_type", document_type),
            ("document_number", document_number),
        ):
            column = slots[field_name]
            ref = _exact_report_header_cell_ref(
                page,
                table,
                row=row_index,
                column=column,
                field_name=field_name,
            )
            if ref is None or not header_field_valid(
                field_name,
                value,
                id_type=document_type,
            ):
                return []
            refs.append(ref)
        identity = (document_type, document_number)
        if identity in seen:
            return []
        seen.add(identity)
        documents.append(
            {
                "identity_document_id": stable_record_id(
                    "identity_document",
                    "additional",
                    document_type,
                    document_number,
                ),
                "sequence": len(documents) + 2,
                "holder_name": None,
                "document_type": document_type,
                "document_number": document_number,
                "is_primary": False,
                "source": "native_detail_header",
                "source_refs": refs,
                "confidence": 1.0,
            }
        )
    return documents


def _bounded_header_subject_name(
    parse_result: Any,
    page: Any,
    table: Any,
    rows: list[list[str]],
) -> str | None:
    """Recover a name only when an exact page-one cell separates one watermark token.

    Some scans place a one-character bank/watermark mark in the subject-name
    value cell.  Treating the whole cell as a name correctly fails the ordinary
    header contract, but losing the independently owned name token is equally
    wrong.  This helper accepts only the complete canonical identity header,
    exact token ownership, one valid Chinese-name token, and at most one tiny
    non-CJK residue token.  It never edits a glyph inside the name.
    """

    if not _report_header_page_owned(page, table):
        return None
    matches: list[tuple[int, int]] = []
    for row_index, row in enumerate(rows[:-1]):
        compact_cells = [_compact(cell) for cell in row]
        if (
            compact_cells.count("被查询者姓名") == 1
            and compact_cells.count("被查询者证件类型") == 1
            and compact_cells.count("被查询者证件号码") == 1
            and sum("查询机构" in cell and "查询原因" in cell for cell in compact_cells) == 1
        ):
            matches.append((row_index, compact_cells.index("被查询者姓名")))
    if len(matches) != 1:
        return None
    header_row, column = matches[0]
    value_row = header_row + 1
    if column >= len(rows[value_row]):
        return None
    header_tokens = _exact_native_table_cell_tokens(
        parse_result,
        table,
        row=header_row,
        column=column,
        logical_page=int(getattr(page, "page_number", 0) or 0),
    )
    value_tokens = _exact_native_table_cell_tokens(
        parse_result,
        table,
        row=value_row,
        column=column,
        logical_page=int(getattr(page, "page_number", 0) or 0),
    )
    if (
        header_tokens is None
        or value_tokens is None
        or _compact("".join(token[0] for token in header_tokens)) != "被查询者姓名"
        or not 1 <= len(value_tokens) <= 2
    ):
        return None
    names = [
        token
        for token in value_tokens
        if header_field_valid("subject_name", _compact(token[0]))
    ]
    if len(names) != 1:
        return None
    name = names[0]
    residue = [token for token in value_tokens if token is not name]
    if residue and (
        len(residue) != 1
        or re.fullmatch(r"[A-Za-z0-9]{1,2}", _compact(residue[0][0])) is None
        or (residue[0][1][2] - residue[0][1][0]) >= (name[1][2] - name[1][0])
    ):
        return None
    observed = _compact(rows[value_row][column])
    possible_token_texts = {
        _compact("".join(token[0] for token in value_tokens)),
        _compact("".join(token[0] for token in reversed(value_tokens))),
    }
    if not observed or observed not in possible_token_texts:
        return None
    return _compact(name[0])


def _extract_header_datasets(parse_result: Any, full_text: str) -> dict[str, list[dict[str, Any]]]:
    # A document-wide string has no section or cell ownership. Header values
    # are admitted only from registered native tables or registered corrected
    # page evidence below, irrespective of physical/logical page position.
    _ = full_text
    field_candidates: dict[str, list[str]] = defaultdict(list)
    observed_field_candidates: defaultdict[str, list[str]] = defaultdict(list)
    field_candidate_refs: defaultdict[
        str,
        list[tuple[str, dict[str, Any]]],
    ] = defaultdict(list)
    header_pages = [
        page
        for page in list(getattr(parse_result, "pages", None) or [])
        if _report_header_page_owned(page)
    ]
    scan_pages = header_pages
    for page in scan_pages:
        for table in getattr(page, "tables", None) or []:
            if not _report_header_page_owned(page, table):
                continue
            rows = _table_rows(table)
            for row_index, row in enumerate(rows):
                for column, raw_cell in enumerate(row):
                    cell = _clean(raw_cell)
                    compact_cell = _compact(cell)
                    number_match = re.fullmatch(
                        r"报告编号[:：]?(\d{18,30})",
                        compact_cell,
                    )
                    if number_match is not None:
                        value = number_match.group(1)
                        observed_field_candidates["report_number"].append(value)
                        ref = _exact_report_header_cell_ref(
                            page,
                            table,
                            row=row_index,
                            column=column,
                            field_name="report_number",
                        )
                        if ref is not None:
                            field_candidates["report_number"].append(value)
                            field_candidate_refs["report_number"].append((value, ref))
                    if compact_cell.startswith("报告时间"):
                        value = _strict_report_time(compact_cell, None)
                        if value is not None:
                            observed_field_candidates["report_time"].append(value)
                            ref = _exact_report_header_cell_ref(
                                page,
                                table,
                                row=row_index,
                                column=column,
                                field_name="report_time",
                            )
                            if ref is not None:
                                field_candidates["report_time"].append(value)
                                field_candidate_refs["report_time"].append((value, ref))
            bounded_name = _bounded_header_subject_name(parse_result, page, table, rows)
            if bounded_name is not None:
                observed_field_candidates["subject_name"].append(bounded_name)
                field_candidates["subject_name"].append(bounded_name)
            for row_index, row in enumerate(rows[:-1]):
                header_slots = _canonical_header_slots(
                    tuple(row),
                    {
                        "subject_name": ("被查询者姓名",),
                        "primary_id_type": ("被查询者证件类型",),
                        "primary_id_number": ("被查询者证件号码",),
                        "query_institution": ("查询机构",),
                        "query_reason": ("查询原因",),
                    },
                )
                if set(header_slots) != {
                    "subject_name",
                    "primary_id_type",
                    "primary_id_number",
                    "query_institution",
                    "query_reason",
                }:
                    continue
                value_row = tuple(rows[row_index + 1])
                for key, column in header_slots.items():
                    value = _clean(value_row[column] if column < len(value_row) else "")
                    if value:
                        observed_field_candidates[key].append(value)
                        ref = _exact_report_header_cell_ref(
                            page,
                            table,
                            row=row_index + 1,
                            column=column,
                            field_name=key,
                        )
                        if ref is not None:
                            field_candidates[key].append(value)
                            field_candidate_refs[key].append((value, ref))
    from docmirror.plugins.credit_report.personal_detail_scanned.extraction_issues import (
        make_issue,
        record_issue,
        retarget_issue_record,
    )
    from docmirror.plugins.credit_report.personal_detail_scanned.native_parser import PBOCPersonalDetailNativeParser

    parser = PBOCPersonalDetailNativeParser(parse_result)
    authorized_parser_candidates: defaultdict[
        str,
        list[tuple[str, dict[str, Any]]],
    ] = defaultdict(list)
    rejected_parser_candidates: defaultdict[str, list[str]] = defaultdict(list)
    rejected_parser_refs: defaultdict[str, list[dict[str, Any]]] = defaultdict(list)
    label_to_key = {
        "被查询者姓名": "subject_name",
        "被查询者证件类型": "primary_id_type",
        "被查询者证件号码": "primary_id_number",
        "查询机构": "query_institution",
        "查询原因": "query_reason",
        "报告编号": "report_number",
        "报告时间": "report_time",
    }
    for candidate in parser.records("report_header"):
        for label, key in label_to_key.items():
            value = candidate.fields.get(label)
            if value not in (None, ""):
                observed_value = str(value)
                observed_field_candidates[key].append(observed_value)
                ref = _exact_parser_report_header_field_ref(
                    parse_result,
                    candidate,
                    label=label,
                    field_name=key,
                    value=observed_value,
                )
                if ref is not None:
                    authorized_parser_candidates[key].append((observed_value, ref))
                    continue
                rejected_parser_candidates[key].append(observed_value)
                refs_by_field = getattr(candidate, "source_refs_by_field", None)
                raw_refs = refs_by_field.get(label) if isinstance(refs_by_field, Mapping) else ()
                rejected_parser_refs[key].extend(
                    dict(raw_ref)
                    for raw_ref in raw_refs or ()
                    if isinstance(raw_ref, Mapping)
                )
    for key, candidates in authorized_parser_candidates.items():
        semantic_values = {
            (
                normalize_pboc_field(value, "inquiry_reason")
                if key == "query_reason"
                else value.strip()
            )
            for value, _ref in candidates
        }
        if len(candidates) > 1 and len(semantic_values) == 1:
            # Repeated parser records would leave more than one candidate
            # owner for the same semantic field.  None of those parser
            # observations can choose which physical cell is authoritative.
            rejected_parser_candidates[key].extend(value for value, _ref in candidates)
            rejected_parser_refs[key].extend(dict(ref) for _value, ref in candidates)
            continue
        for value, ref in candidates:
            field_candidates[key].append(value)
            field_candidate_refs[key].append((value, ref))

    def candidate_valid(key: str, value: str, selected_id_type: str | None = None) -> bool:
        if key == "query_reason":
            return validate_pboc_field(value, "inquiry_reason").valid
        return header_field_valid(key, value, id_type=selected_id_type)

    def select(key: str, selected_type: str | None = None) -> str | None:
        observed = tuple(
            dict.fromkeys(
                value.strip()
                for value in observed_field_candidates.get(key, [])
                if value.strip()
            )
        )
        authorized = tuple(
            dict.fromkeys(
                value.strip()
                for value in field_candidates.get(key, [])
                if value.strip()
            )
        )
        valid = tuple(
            dict.fromkeys(
                normalize_pboc_field(value, "inquiry_reason") if key == "query_reason" else value
                for value in authorized
                if candidate_valid(key, value, selected_type)
            )
        )
        if len(valid) == 1:
            if rejected_parser_candidates.get(key):
                target_dataset = (
                    "report_query"
                    if key in {"query_institution", "query_reason"}
                    else "report_metadata"
                )
                record_issue(
                    parse_result,
                    make_issue(
                        category="ocr_cell_level_error",
                        issue_code="report_header_candidate_source_ownership_unresolved",
                        message=(
                            "A parser-observed PBOC report-header value lacked one unique exact "
                            "field-cell owner and was not admitted as normalized authority."
                        ),
                        parser_stage="report_header_source_ownership",
                        target_dataset=target_dataset,
                        target_record_id="personal_report_metadata:primary",
                        field_name=key,
                        observed_value=list(observed),
                        source_refs=(
                            rejected_parser_refs[key]
                            if rejected_parser_refs.get(key)
                            else (
                                {
                                    "source": "candidate_b_report_header_parser_observation",
                                    "geometry_scope": "canonical_template",
                                    "canonical_template_id": "report_header_and_identity",
                                },
                            )
                        ),
                        reason_codes=(
                            "report_header_and_identity_owner_required",
                            "unique_exact_field_cell_required",
                            "parser_observation_not_promoted",
                        ),
                    ),
                )
            return valid[0]
        target_dataset = "report_query" if key in {"query_institution", "query_reason"} else "report_metadata"
        exact_observed_refs = [
            ref
            for value, ref in field_candidate_refs.get(key, ())
            if value.strip() in observed
        ]
        location_ref: dict[str, Any] = {
            "source": "candidate_b_report_header_business_fields",
            "geometry_scope": "canonical_template",
            "canonical_template_id": "report_header_and_identity",
        }
        if scan_pages:
            logical_page = int(getattr(scan_pages[0], "page_number", 0) or 0)
            source_page = int(
                getattr(scan_pages[0], "source_page_number", 0)
                or logical_page
            )
            if logical_page > 0:
                location_ref["logical_page"] = logical_page
            if source_page > 0:
                location_ref["source_page"] = source_page
        record_issue(
            parse_result,
            make_issue(
                category="ocr_cell_level_error",
                issue_code="page_one_consensus_unresolved",
                message="PBOC report-header evidence was missing, invalid, or conflicting; the normalized value was withheld.",
                parser_stage="report_header_consensus",
                target_dataset=target_dataset,
                target_record_id="personal_report_metadata:primary",
                field_name=key,
                observed_value=list(observed),
                source_refs=(
                    exact_observed_refs
                    if exact_observed_refs
                    else (location_ref,)
                ),
                reason_codes=(
                    "report_header_consensus",
                    "schema_field_validation",
                    "normalized_value_withheld",
                    *(
                        ("parser_candidate_exact_source_ownership_unresolved",)
                        if rejected_parser_candidates.get(key)
                        else ()
                    ),
                ),
            ),
        )
        return None

    subject_name = select("subject_name")
    id_type = select("primary_id_type")
    id_number = select("primary_id_number", id_type or "身份证")
    observed_primary_numbers = tuple(
        dict.fromkeys(value.strip() for value in field_candidates.get("primary_id_number", []) if value.strip())
    )
    source_primary_id_number = id_number or (
        observed_primary_numbers[0] if len(observed_primary_numbers) == 1 else None
    )
    if id_type is None and cn_identity_number_valid(id_number):
        id_type = "身份证"
        for issue in getattr(parse_result, "_personal_detail_extraction_issues", []) or []:
            if (
                isinstance(issue, dict)
                and issue.get("issue_code") == "page_one_consensus_unresolved"
                and issue.get("field_name") == "primary_id_type"
            ):
                issue["status"] = "resolved"
                issue["severity"] = "info"
                issue["reason_codes"] = [
                    *issue.get("reason_codes", []),
                    "checksum_valid_resident_identity_implies_document_type",
                ]
    query_institution = select("query_institution")
    query_reason = select("query_reason")
    report_number = select("report_number")
    report_time = select("report_time")
    metadata_id = stable_record_id("personal_report_metadata", report_number, report_time, subject_name)
    page_one_targets = {
        "report_metadata": metadata_id,
        "report_query": f"report_query:{metadata_id}",
    }
    issues = getattr(parse_result, "_personal_detail_extraction_issues", None)
    if isinstance(issues, list):
        for index, issue in enumerate(issues):
            if not isinstance(issue, Mapping):
                continue
            target_dataset = str(issue.get("target_dataset") or "")
            if (
                issue.get("issue_code")
                in {
                    "page_one_consensus_unresolved",
                    "report_header_candidate_source_ownership_unresolved",
                }
                and issue.get("target_record_id") == "personal_report_metadata:primary"
                and target_dataset in page_one_targets
            ):
                issues[index] = retarget_issue_record(
                    issue,
                    page_one_targets[target_dataset],
                )
    selected_values = {
        "report_number": report_number,
        "report_time": report_time,
        "subject_name": subject_name,
        "primary_id_type": id_type,
        "primary_id_number": id_number,
        "query_institution": query_institution,
        "query_reason": query_reason,
    }
    metadata_source_refs: list[dict[str, Any]] = []
    for key, selected_value in selected_values.items():
        if selected_value is None:
            continue
        matching = [
            ref
            for raw_value, ref in field_candidate_refs.get(key, ())
            if (
                normalize_pboc_field(raw_value, "inquiry_reason")
                if key == "query_reason"
                else raw_value
            )
            == selected_value
        ]
        unique_slots = {
            (
                int(ref.get("logical_page") or 0),
                int(ref.get("source_page") or 0),
                str(ref.get("table_id") or ""),
                int(ref.get("row") or 0),
                int(ref.get("column") or 0),
            )
            for ref in matching
        }
        if len(unique_slots) == 1:
            metadata_source_refs.extend(matching[:1])
    metadata = [
        {
            "personal_report_metadata_id": metadata_id,
            "report_number": report_number,
            "report_time": report_time,
            "subject_name": subject_name,
            "primary_id_type": id_type,
            "primary_id_number": id_number,
            "query_institution": query_institution,
            "query_reason": query_reason,
            "reporting_currency": "CNY",
            "reporting_amount_unit": "yuan",
            "reporting_amount_precision": 0,
            "amount_policy_source": "personal_detailed_report_notes",
            "source": "native_detail_header",
            "source_refs": metadata_source_refs,
            "confidence": 1.0,
        }
    ]
    identities: list[dict[str, Any]] = []
    if id_type and source_primary_id_number:
        primary_refs: list[dict[str, Any]] = []
        for key, value in (
            ("document_type", id_type),
            ("document_number", source_primary_id_number),
        ):
            source_key = "primary_id_type" if key == "document_type" else "primary_id_number"
            candidates = [
                {**ref, "field_name": key}
                for raw_value, ref in field_candidate_refs.get(source_key, ())
                if raw_value == value
            ]
            slots = {
                (
                    ref.get("logical_page"),
                    ref.get("source_page"),
                    ref.get("table_id"),
                    ref.get("row"),
                    ref.get("column"),
                )
                for ref in candidates
            }
            if len(slots) == 1:
                primary_refs.extend(candidates[:1])
        identities.append(
            {
                "identity_document_id": stable_record_id(
                    "identity_document", "primary", id_type, source_primary_id_number
                ),
                "sequence": 1,
                "holder_name": subject_name,
                "document_type": id_type,
                # Preserve the source-visible row even when its displayed
                # number fails a checksum/type contract.  The v2 quality gate
                # withholds the normalized field and publishes the linked
                # uncertainty instead of silently deleting the identity row.
                "document_number": source_primary_id_number,
                "is_primary": True,
                "source": "native_detail_header",
                "source_refs": primary_refs,
                "confidence": 1.0,
            }
        )
    additional_documents = _bounded_other_identity_documents(header_pages)
    for document in additional_documents:
        document["holder_name"] = subject_name
    identities.extend(additional_documents)
    return {"personal_report_metadata": metadata, "identity_documents": identities}


def extract_personal_detail_native_business(parse_result: Any, full_text: str) -> dict[str, Any]:
    """Return the business slice of the authoritative Candidate B result."""
    from copy import deepcopy

    from docmirror.plugins.credit_report.personal_detail_scanned.context import (
        build_personal_detail_extraction_context,
    )

    context = build_personal_detail_extraction_context(parse_result)
    return deepcopy(context.candidate_b_extraction(full_text).business)


def extract_personal_detail_section_content(parse_result: Any, full_text: str) -> dict[str, Any]:
    """Return the supplemental slice of the authoritative Candidate B result."""
    from copy import deepcopy

    from docmirror.plugins.credit_report.personal_detail_scanned.context import (
        build_personal_detail_extraction_context,
    )

    context = build_personal_detail_extraction_context(parse_result)
    return deepcopy(context.candidate_b_extraction(full_text).section_content)


def extract_personal_detail_common_datasets(
    parse_result: Any,
    full_text: str,
) -> dict[str, list[dict[str, Any]]]:
    """Return report metadata datasets for any content mode."""
    return _extract_header_datasets(parse_result, full_text)


__all__ = [
    "extract_personal_detail_common_datasets",
    "extract_personal_detail_native_business",
    "extract_personal_detail_section_content",
]
